-- 2. Questions ------------------------------------------------------------
-- Rangées APRÈS celles du quiz : position = dernière position + rang.
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, qz.id, v.question, v.kind, v.options, v.correct_index, v.explanation,
       COALESCE((SELECT max(x.position) FROM public.quiz_questions x WHERE x.quiz_id = qz.id), 0) + v.rang
  FROM (VALUES
    ('6c73eea9-f236-5262-ba5c-387b077e7369'::uuid, 'histoire-geo', 'Tle', 'Les caractéristiques du capitalisme des années 1920', 'Qu’apporte le taylorisme à l’industrie ?', 'mcq', '["La hausse des salaires ouvriers","La décomposition du travail en tâches simples, qui fait bondir la productivité","Le crédit à la consommation","La publicité de masse"]'::jsonb, 1, 'Le taylorisme découpe le travail en gestes simples et chronométrés ; le fordisme y ajoute la chaîne de montage et les hauts salaires.', 1),
    ('d2a71f98-f65e-5853-8963-35be9189bc32'::uuid, 'histoire-geo', 'Tle', 'Les caractéristiques du capitalisme des années 1920', 'Dans le circuit financier des années 1920, à qui l’Allemagne verse-t-elle ses réparations ?', 'mcq', '["Aux États-Unis directement","À la Société des Nations","Aux Alliés, qui remboursent ensuite Washington","À l’URSS"]'::jsonb, 2, 'Les capitaux américains prêtés à l’Allemagne reviennent aux États-Unis via les réparations versées aux Alliés : un circuit unique qui casse en 1929.', 2),
    ('5c961cb7-622d-5259-bf39-e9689283f78f'::uuid, 'histoire-geo', 'Tle', 'Les caractéristiques du capitalisme des années 1920', 'Depuis quand l’agriculture américaine est-elle en surproduction ?', 'mcq', '["Depuis le krach de 1929","Depuis le New Deal","Depuis la fin des années 1930","Dès le début des années 1920"]'::jsonb, 3, 'Une partie du pays, les campagnes, est déjà en crise pendant la prospérité : c’est l’un des déséquilibres qui annoncent 1929.', 3),
    ('1aa58868-87f4-59d2-b14a-74c85d1b2a77'::uuid, 'histoire-geo', 'Tle', 'Les caractéristiques du capitalisme des années 1920', 'Quels groupes restent à l’écart de la prospérité des années 1920 ?', 'mcq', '["Les ouvriers agricoles, les Noirs du Sud et les immigrés récents","Les ouvriers de l’automobile","Les banquiers de Wall Street","Les classes moyennes urbaines"]'::jsonb, 0, 'Derrière l’image des « années folles », une partie des Américains ne connaît jamais la prospérité.', 4),
    ('7f397db4-117e-5de5-99b5-5bbb88ffcfc3'::uuid, 'histoire-geo', 'Tle', 'La crise de 1929 : de la crise financière américaine à la crise économique mondiale', 'Comment appelle-t-on le 29 octobre 1929 ?', 'mcq', '["Le jeudi noir","Le vendredi rouge","Le mardi noir","Le lundi de Pâques"]'::jsonb, 2, 'Après le jeudi noir du 24 octobre, le mardi 29 octobre prolonge l’effondrement des cours de Wall Street.', 1),
    ('b70f6217-22da-58b7-8c16-212c411334dc'::uuid, 'histoire-geo', 'Tle', 'La crise de 1929 : de la crise financière américaine à la crise économique mondiale', 'De combien l’indice boursier américain chute-t-il entre 1929 et 1932 ?', 'mcq', '["Près de 90 %","Environ 10 %","Environ 30 %","Près de 50 %"]'::jsonb, 0, 'En trois ans, les actions perdent presque toute leur valeur : la baisse s’auto-entretient par les ventes forcées.', 2),
    ('e7bf77ee-8932-5758-bb68-bb5c4088e6f9'::uuid, 'histoire-geo', 'Tle', 'La crise de 1929 : de la crise financière américaine à la crise économique mondiale', 'Qu’appelle-t-on la spirale déflationniste ?', 'mcq', '["Une hausse continue des prix","L’enchaînement crédit fermé, licenciements, effondrement de la consommation, qui se répète","Une dévaluation volontaire de la monnaie","Le retour de la croissance après la crise"]'::jsonb, 1, 'Chaque fermeture d’entreprise réduit la consommation, ce qui provoque de nouvelles fermetures : la crise se nourrit d’elle-même.', 3),
    ('30f89e4e-eaa8-5ec2-9b11-1e881e433d62'::uuid, 'histoire-geo', 'Tle', 'La crise de 1929 : de la crise financière américaine à la crise économique mondiale', 'Pourquoi la crise américaine devient-elle mondiale ?', 'mcq', '["Parce que l’Europe exporte trop vers les États-Unis","Parce que le dollar est dévalué dès 1929","Parce que l’URSS cesse de commercer","Parce que les banques américaines rapatrient les capitaux prêtés à l’Europe"]'::jsonb, 3, 'Le monde vivait du crédit américain : quand les prêteurs rappellent leur argent, l’Europe, et d’abord l’Allemagne, est asphyxiée.', 4),
    ('6d9b87f9-1a9d-5bf9-a35c-45e89a9c5420'::uuid, 'histoire-geo', 'Tle', 'Les politiques des États face à la crise mondiale', 'Que fait le Glass-Steagall Act ?', 'mcq', '["Il crée la Sécurité sociale","Il sépare banques de dépôt et banques d’affaires","Il dévalue le dollar","Il reconnaît les syndicats"]'::jsonb, 1, 'Pour que les dépôts des épargnants ne soient plus exposés à la spéculation, le New Deal sépare les deux métiers bancaires.', 1),
    ('e34daf80-eb12-5f9f-90cc-c0f468b3c4f5'::uuid, 'histoire-geo', 'Tle', 'Les politiques des États face à la crise mondiale', 'Que reconnaît le Wagner Act de 1935 ?', 'mcq', '["Les syndicats","Le droit de vote des femmes","La semaine de 40 heures","Le salaire minimum européen"]'::jsonb, 0, 'Le Wagner Act donne aux syndicats une place reconnue dans les relations de travail américaines.', 2),
    ('d2b499d5-042a-5e41-898d-c412509e9858'::uuid, 'histoire-geo', 'Tle', 'Les politiques des États face à la crise mondiale', 'Sur quels accords débouchent les grèves de 1936 en France ?', 'mcq', '["Les accords de Grenelle","Les accords de Munich","Les accords du Latran","Les accords Matignon"]'::jsonb, 3, 'Les accords Matignon (juin 1936) accordent hausses de salaires et conventions collectives ; les lois suivantes instaurent congés payés et 40 heures.', 3),
    ('8dd4d5fc-ecef-5249-a59f-8039bb3f5aca'::uuid, 'histoire-geo', 'Tle', 'Les politiques des États face à la crise mondiale', 'Combien de semaines de congés payés le Front populaire accorde-t-il ?', 'mcq', '["Une","Deux","Trois","Cinq"]'::jsonb, 1, 'Deux semaines de congés payés : un acquis durable, même si la relance économique échoue en partie.', 4),
    ('7d91cc79-2529-5497-b9f0-30d5415f9372'::uuid, 'histoire-geo', 'Tle', 'Le modèle nazi : en Allemagne, Hitler et la montée du nazisme', 'Quel score le parti nazi obtient-il aux élections de juillet 1932 ?', 'mcq', '["2,6 %","18 %","37 %","52 %"]'::jsonb, 2, 'De 2,6 % en 1928 à 37 % en juillet 1932 : la crise donne au NSDAP son public, sans lui donner la majorité absolue.', 1),
    ('3fec8047-4326-516f-a633-9e58e3a9be0a'::uuid, 'histoire-geo', 'Tle', 'Le modèle nazi : en Allemagne, Hitler et la montée du nazisme', 'Qui nomme Hitler chancelier en janvier 1933 ?', 'mcq', '["Le président Hindenburg","Le Reichstag par un vote","Mussolini","Le peuple par référendum"]'::jsonb, 0, 'Hitler est nommé légalement par le président Hindenburg : le nazisme reçoit le pouvoir avant de détruire les règles qui le lui ont donné.', 2),
    ('a136feec-f63b-552c-9786-6c705c90f23d'::uuid, 'histoire-geo', 'Tle', 'Le modèle nazi : en Allemagne, Hitler et la montée du nazisme', 'Quelle crise ruine les classes moyennes allemandes en 1923 ?', 'mcq', '["Le krach de Wall Street","L’hyperinflation","La guerre civile","La famine"]'::jsonb, 1, 'En 1923, le mark perd toute valeur : l’épargne des classes moyennes disparaît, et avec elle leur confiance dans Weimar.', 3),
    ('161c6ce8-6263-5205-8808-350f6c88f92f'::uuid, 'histoire-geo', 'Tle', 'Le modèle nazi : en Allemagne, Hitler et la montée du nazisme', 'Quelle organisation embrigade la jeunesse allemande ?', 'mcq', '["Les Balilla","Les Komsomols","Le Dopolavoro","Les Jeunesses hitlériennes"]'::jsonb, 3, 'Les Jeunesses hitlériennes encadrent les jeunes Allemands ; les Balilla sont leur équivalent italien, les Komsomols soviétiques.', 4),
    ('63fbc1ec-2326-582e-b452-5b89cca84ffc'::uuid, 'histoire-geo', 'Tle', 'Le fascisme italien : un modèle spécifique', 'Que désigne la « victoire mutilée » ?', 'mcq', '["La défaite italienne de 1943","La frustration de l’Italie, sortie de la Grande Guerre sans les gains espérés","La conquête de l’Éthiopie","La perte de la Libye"]'::jsonb, 1, 'Vainqueur en 1918 mais déçue par les traités, l’Italie nourrit un ressentiment que Mussolini exploite dès 1919.', 1),
    ('b21ca1bb-06cd-5444-be2d-14a1d8abd0ed'::uuid, 'histoire-geo', 'Tle', 'Le fascisme italien : un modèle spécifique', 'Qu’est-ce que l’OVRA ?', 'mcq', '["La police politique fasciste","L’organisation des loisirs","Le parti fasciste","L’armée coloniale"]'::jsonb, 0, 'Créée avec les lois « fascistissimes » de 1925-1926, l’OVRA traque les opposants, avec le tribunal spécial.', 2),
    ('a1ce35a7-6f95-5e3e-a4b9-006a6b4c318b'::uuid, 'histoire-geo', 'Tle', 'Le fascisme italien : un modèle spécifique', 'Quelle organisation encadre la jeunesse italienne sous le fascisme ?', 'mcq', '["Le Dopolavoro","Les Jeunesses hitlériennes","Les Komsomols","Les Balilla"]'::jsonb, 3, 'Les Balilla encadrent la jeunesse ; le Dopolavoro, lui, organise les loisirs des travailleurs.', 3),
    ('efbc5a43-8c4e-5175-819c-643e3825b82c'::uuid, 'histoire-geo', 'Tle', 'Le fascisme italien : un modèle spécifique', 'Qui destitue Mussolini en 1943 ?', 'mcq', '["Hitler","Le pape","Le roi Victor-Emmanuel III","Les Alliés par un vote de l’ONU"]'::jsonb, 2, 'La monarchie, jamais supprimée, reste un pouvoir distinct : c’est le roi qui écarte le Duce, preuve que le fascisme n’a pas tout contrôlé.', 4),
    ('e6a59b36-3bd1-5eb3-aae8-6fff5c3cfbed'::uuid, 'histoire-geo', 'Tle', 'La mise en place du système socialiste soviétique en URSS de Lénine à Staline', 'En quelle année l’URSS est-elle fondée ?', 'mcq', '["1917","1922","1924","1928"]'::jsonb, 1, 'L’Union des républiques socialistes soviétiques naît en 1922, après la guerre civile ; Lénine meurt en 1924.', 1),
    ('2e2f18ad-fc75-5af0-82e4-cbda69aa0904'::uuid, 'histoire-geo', 'Tle', 'La mise en place du système socialiste soviétique en URSS de Lénine à Staline', 'Quel rival Staline écarte-t-il après la mort de Lénine ?', 'mcq', '["Trotski","Kerenski","Nicolas II","Khrouchtchev"]'::jsonb, 0, 'À partir de 1924, Staline élimine ses concurrents, dont Trotski, et s’assure seul le pouvoir.', 2),
    ('3ed589f9-316a-5da9-9b46-8c56320f7d44'::uuid, 'histoire-geo', 'Tle', 'La mise en place du système socialiste soviétique en URSS de Lénine à Staline', 'Quelle police politique mène la terreur des grandes purges de 1936-1938 ?', 'mcq', '["La Gestapo","L’OVRA","La Stasi","Le NKVD"]'::jsonb, 3, 'Le NKVD organise arrestations, exécutions et déportations vers le Goulag.', 3),
    ('4735b235-d0c9-593c-894e-89019fcc1dd0'::uuid, 'histoire-geo', 'Tle', 'La mise en place du système socialiste soviétique en URSS de Lénine à Staline', 'Quel est l’objectif des plans quinquennaux ?', 'mcq', '["Rendre les terres aux paysans","Développer le commerce avec l’Occident","Industrialiser le pays à marche forcée","Réduire l’armée"]'::jsonb, 2, 'Lancés à partir de 1928, les plans quinquennaux fixent des objectifs de production, surtout à l’industrie lourde, au prix d’une contrainte extrême.', 4),
    ('3669b1f5-dfc8-5be1-b39c-546c49bcc33e'::uuid, 'histoire-geo', 'Tle', 'Les caractéristiques des régimes totalitaires européens', 'Sur quelle idéologie repose le fascisme italien ?', 'mcq', '["Une idéologie raciale","Une idéologie de classe","Une idéologie nationaliste, celle de la grandeur romaine","Une idéologie religieuse"]'::jsonb, 2, 'Le nazisme est racial, le stalinisme de classe, le fascisme italien nationaliste : c’est ce qui les sépare.', 1),
    ('8bcb9d8d-6454-549b-ab80-37e0d63992ca'::uuid, 'histoire-geo', 'Tle', 'Les caractéristiques des régimes totalitaires européens', 'Quel accord de 1938 illustre la politique d’apaisement ?', 'mcq', '["Les accords de Munich","Le pacte germano-soviétique","Le pacte d’Acier","Le traité de Versailles"]'::jsonb, 0, 'À Munich, la France et le Royaume-Uni cèdent les Sudètes à Hitler ; ils comprendront que les totalitarismes ne se satisfont d’aucune concession.', 2),
    ('23e56e0b-137f-5dac-b354-874307fe1ef0'::uuid, 'histoire-geo', 'Tle', 'Les caractéristiques des régimes totalitaires européens', 'Quel but affiche le stalinisme ?', 'mcq', '["L’espace vital","La restauration de la grandeur romaine","La hiérarchie des races","La révolution mondiale"]'::jsonb, 3, 'L’idéologie soviétique se veut universaliste : elle vise la révolution mondiale, là où le nazisme vise l’espace vital.', 3),
    ('6ac25ead-aa74-55ed-9299-fb92c57b888c'::uuid, 'histoire-geo', 'Tle', 'Les caractéristiques des régimes totalitaires européens', 'Dans un régime totalitaire, quelle place a l’économie ?', 'mcq', '["Elle est dirigée : l’État commande la production","Elle est laissée entièrement au marché","Elle est confiée à l’Église","Elle est gérée par des syndicats libres"]'::jsonb, 0, 'L’économie dirigée fait partie des traits communs : comme la société, elle doit servir le projet du régime.', 4),
    ('6e76d759-b6ab-5076-8648-a8da70b21ccf'::uuid, 'histoire-geo', 'Tle', 'La Seconde Guerre mondiale', 'Que désigne l’opération Barbarossa ?', 'mcq', '["Le débarquement en Sicile","L’invasion de l’URSS par l’Allemagne en juin 1941","L’attaque de Pearl Harbor","L’invasion de la Pologne"]'::jsonb, 1, 'En juin 1941, Hitler rompt le pacte germano-soviétique et envahit l’URSS : la guerre devient une guerre d’anéantissement à l’Est.', 1),
    ('e11998ab-e8c3-5ba5-a3d8-cd91f6a351f6'::uuid, 'histoire-geo', 'Tle', 'La Seconde Guerre mondiale', 'Quel est le premier échec de l’Allemagne, en 1940 ?', 'mcq', '["La bataille d’Angleterre","Stalingrad","El-Alamein","Midway"]'::jsonb, 0, 'Faute de maîtriser le ciel britannique, Hitler renonce à envahir le Royaume-Uni.', 2),
    ('a5d54ca0-e6a7-5b28-9831-02b103761f6c'::uuid, 'histoire-geo', 'Tle', 'La Seconde Guerre mondiale', 'Quelle bataille marque le tournant dans le Pacifique, en juin 1942 ?', 'mcq', '["Stalingrad","El-Alamein","Koursk","Midway"]'::jsonb, 3, 'Stalingrad à l’Est, El-Alamein en Afrique du Nord, Midway dans le Pacifique : l’Axe est arrêté sur les trois théâtres.', 3),
    ('44d8942d-7e76-5ec0-a2a8-c76a28f7cef5'::uuid, 'histoire-geo', 'Tle', 'La Seconde Guerre mondiale', 'Où les Alliés débarquent-ils en août 1944 ?', 'mcq', '["En Normandie","En Sicile","En Provence","En Afrique du Nord"]'::jsonb, 2, 'Après la Normandie le 6 juin, le débarquement de Provence d’août 1944 ouvre un second front en France.', 4),
    ('e213935d-0a1e-51a1-85a5-91d55c8067b4'::uuid, 'histoire-geo', 'Tle', 'La France défaite et occupée', 'Que vote l’Assemblée le 10 juillet 1940 ?', 'mcq', '["L’armistice","Les pleins pouvoirs à Pétain","Le statut des Juifs","La création de la Milice"]'::jsonb, 1, 'Par ce vote, la République laisse place à l’État français dirigé par Pétain.', 1),
    ('7bb053d5-f75e-51e4-9c1b-a5e35f87cea5'::uuid, 'histoire-geo', 'Tle', 'La France défaite et occupée', 'D’où de Gaulle lance-t-il son appel du 18 juin 1940 ?', 'mcq', '["De Londres","D’Alger","De Vichy","De Bordeaux"]'::jsonb, 0, 'Depuis Londres, à la BBC, de Gaulle appelle à poursuivre le combat : c’est l’acte fondateur de la France libre.', 2),
    ('b4f336ea-03aa-5dcb-b991-5a3574089682'::uuid, 'histoire-geo', 'Tle', 'La France défaite et occupée', 'Que marque la création de la Milice en 1943 ?', 'mcq', '["La fin de la collaboration","L’unification de la Résistance","Le début de l’Occupation","Une répression désormais menée par des Français"]'::jsonb, 3, 'La Milice traque résistants et Juifs aux côtés de l’occupant : la répression devient française.', 3),
    ('7825b38e-9eff-5b79-acc3-89a90c410f7f'::uuid, 'histoire-geo', 'Tle', 'La France défaite et occupée', 'En quelle année un président reconnaît-il officiellement la responsabilité de l’État français dans la déportation ?', 'mcq', '["1945","1981","1995","2005"]'::jsonb, 2, 'Le discours de Jacques Chirac en 1995 reconnaît que Vichy a devancé certaines demandes de l’occupant.', 4),
    ('422d42a1-481c-514a-8e58-884116171d7f'::uuid, 'histoire-geo', 'Tle', 'L’Europe et le monde face aux crimes de la Seconde Guerre mondiale', 'Que désigne le Porajmos ?', 'mcq', '["Le génocide des Tsiganes","Le programme d’assassinat des handicapés","Le massacre de Nankin","La déportation des résistants"]'::jsonb, 0, 'Le Porajmos est le génocide des Tsiganes d’Europe par les nazis.', 1),
    ('f2b7c11c-8815-5a94-ae3d-7b1da94e0c26'::uuid, 'histoire-geo', 'Tle', 'L’Europe et le monde face aux crimes de la Seconde Guerre mondiale', 'Qui sont les victimes du programme T4 ?', 'mcq', '["Les prisonniers soviétiques","Les handicapés","Les résistants français","Les Tsiganes"]'::jsonb, 1, 'Le programme T4 organise l’assassinat de personnes handicapées, avant même la mise à mort industrielle des Juifs.', 2),
    ('273569a5-08a5-5a0b-8f75-44407d509cc7'::uuid, 'histoire-geo', 'Tle', 'L’Europe et le monde face aux crimes de la Seconde Guerre mondiale', 'Que représente le massacre d’Oradour-sur-Glane ?', 'mcq', '["Une fusillade des Einsatzgruppen","Un centre de mise à mort","Un crime japonais en Asie","Des représailles nazies contre des civils"]'::jsonb, 3, 'En juin 1944, la population d’Oradour-sur-Glane est massacrée : un crime contre des civils, pas un dommage de guerre.', 3),
    ('0687d78c-16db-5b55-ba61-d01657e5dd2c'::uuid, 'histoire-geo', 'Tle', 'L’Europe et le monde face aux crimes de la Seconde Guerre mondiale', 'Quel procès se tient en France en 1987 ?', 'mcq', '["Le procès Papon","Le procès Touvier","Le procès Barbie","Le procès de Nuremberg"]'::jsonb, 2, 'Klaus Barbie est jugé en 1987, Paul Touvier en 1994, Maurice Papon en 1998 : l’imprescriptibilité permet ces procès tardifs.', 4),
    ('80c0cf24-85f8-5b78-beca-95a2febfda1b'::uuid, 'histoire-geo', 'Tle', 'Le bilan de la Seconde Guerre mondiale : le règlement du conflit et ses conséquences', 'Que décide la conférence de Potsdam (juillet-août 1945) pour l’Allemagne ?', 'mcq', '["Sa réunification immédiate","Son entrée à l’ONU","La dénazification et la démilitarisation","L’annulation des réparations"]'::jsonb, 2, 'À Potsdam, l’Allemagne et Berlin sont découpés en quatre zones, dénazifiés et démilitarisés ; les désaccords entre Alliés sont déjà visibles.', 1),
    ('24081b06-44b9-5b56-9298-a56e74dc3a13'::uuid, 'histoire-geo', 'Tle', 'Le bilan de la Seconde Guerre mondiale : le règlement du conflit et ses conséquences', 'Quel est le rôle du GATT, créé en 1947 ?', 'mcq', '["Libéraliser les échanges commerciaux","Maintenir la paix","Stabiliser les monnaies","Financer la reconstruction de l’URSS"]'::jsonb, 0, 'Le GATT organise la baisse des droits de douane, mais ses règles restent non contraignantes.', 2),
    ('a2b97a81-9ab6-5e63-8013-6e576ee8ffe7'::uuid, 'histoire-geo', 'Tle', 'Le bilan de la Seconde Guerre mondiale : le règlement du conflit et ses conséquences', 'Jusqu’en quelle année les États-Unis sont-ils seuls à détenir l’arme atomique ?', 'mcq', '["1945","1962","1953","1949"]'::jsonb, 3, 'L’URSS obtient la bombe en 1949 : le monopole atomique américain n’a duré que quatre ans.', 3),
    ('69fd31f3-0d86-58d3-bed1-878f191012d2'::uuid, 'histoire-geo', 'Tle', 'Le bilan de la Seconde Guerre mondiale : le règlement du conflit et ses conséquences', 'Sur quelle monnaie repose le système de Bretton Woods ?', 'mcq', '["La livre sterling","Le dollar","Le mark","L’or seul, sans monnaie de référence"]'::jsonb, 1, 'Le système monétaire de 1944 fait du dollar la monnaie pivot : c’est aussi sa faiblesse, il dépend des États-Unis.', 4),
    ('0a5f549a-5aed-5d2f-bf1c-7513974dc396'::uuid, 'histoire-geo', 'Tle', 'La naissance d’un nouvel ordre mondial bipolaire après la Seconde Guerre mondiale', 'En quelle année naît le pacte de Varsovie ?', 'mcq', '["1947","1949","1955","1961"]'::jsonb, 2, 'Le pacte de Varsovie (1955) répond à l’OTAN (1949) : il structure militairement le bloc de l’Est.', 1),
    ('6409ab67-c645-56b6-a61f-7f69bcfde31f'::uuid, 'histoire-geo', 'Tle', 'La naissance d’un nouvel ordre mondial bipolaire après la Seconde Guerre mondiale', 'Comment l’URSS réagit-elle au plan Marshall ?', 'mcq', '["Elle le refuse et l’interdit à ses satellites","Elle l’accepte pour la Pologne seulement","Elle en demande une part plus grande","Elle le soutient à l’ONU"]'::jsonb, 0, 'Été 1947 : Moscou refuse l’aide américaine et l’interdit aux pays qu’elle contrôle ; chaque camp organise le sien.', 2),
    ('0847efaa-535a-5c64-8048-72ae08d5ea6c'::uuid, 'histoire-geo', 'Tle', 'La naissance d’un nouvel ordre mondial bipolaire après la Seconde Guerre mondiale', 'Comment les Alliés répondent-ils au blocus de Berlin ?', 'mcq', '["Par une offensive militaire","Par la construction d’un mur","Par un embargo sur l’URSS","Par un pont aérien"]'::jsonb, 3, 'De juin 1948 à mai 1949, les Occidentaux ravitaillent Berlin-Ouest par avion, jusqu’à la levée du blocus.', 3),
    ('381c3b35-0933-553e-a9eb-51986d3d219a'::uuid, 'histoire-geo', 'Tle', 'La naissance d’un nouvel ordre mondial bipolaire après la Seconde Guerre mondiale', 'Sur quoi repose l’économie du modèle soviétique ?', 'mcq', '["La liberté d’entreprendre","La planification et la collectivisation","La consommation de masse","Le libre-échange"]'::jsonb, 1, 'Au marché américain s’oppose la planification soviétique : chacun des deux modèles se présente comme la seule voie du progrès.', 4),
    ('4fffa288-3220-51f9-afd6-4b43a4b78510'::uuid, 'histoire-geo', 'Tle', '1945-1949 : Un monde bipolaire', 'Que réclame l’URSS pour l’Allemagne vaincue ?', 'mcq', '["Sa reconstruction rapide","Des réparations et le démantèlement de son industrie","Son entrée dans l’OTAN","Sa neutralité armée"]'::jsonb, 1, 'Moscou veut faire payer l’Allemagne et l’affaiblir durablement ; Washington veut la reconstruire : c’est l’un des premiers désaccords.', 1),
    ('afa539be-b9b6-5e46-bbb9-921d0d3006d7'::uuid, 'histoire-geo', 'Tle', '1945-1949 : Un monde bipolaire', 'Que réclament les Américains pour la Pologne ?', 'mcq', '["Un gouvernement communiste","Son rattachement à l’URSS","Des élections libres","Son partage entre les deux blocs"]'::jsonb, 2, 'Staline veut un gouvernement ami à sa frontière, les États-Unis des élections libres : la Pologne cristallise la méfiance.', 2),
    ('b66c5464-688d-5591-a46d-8a041e5ee6c7'::uuid, 'histoire-geo', 'Tle', '1945-1949 : Un monde bipolaire', 'Comment Staline installe-t-il des régimes communistes en Europe orientale ?', 'mcq', '["À mesure que l’Armée rouge occupe le terrain","Par des élections libres gagnées partout","À la demande de l’ONU","Après un accord avec Washington"]'::jsonb, 0, 'C’est ce lien entre présence militaire et régime politique qui alarme Washington.', 3),
    ('d86ebae1-1a35-511d-8079-1d2d8943d1af'::uuid, 'histoire-geo', 'Tle', '1945-1949 : Un monde bipolaire', 'Qu’est-ce qui tient d’abord le bloc de l’Est ?', 'mcq', '["L’aide économique américaine","Les bases de l’OTAN","Le plan Marshall","La présence de l’Armée rouge"]'::jsonb, 3, 'À l’Ouest, l’OTAN et l’aide économique ; à l’Est, l’Armée rouge et le CAEM.', 4),
    ('74b54559-1911-57ed-a5d3-6fe7726a79a9'::uuid, 'histoire-geo', 'Tle', 'La guerre froide : affrontements et crises politiques dans un monde bipolaire', 'Quel conflit symbolise l’enlisement soviétique ?', 'mcq', '["La guerre du Vietnam","La guerre de Corée","L’intervention en Afghanistan (1979-1989)","La crise de Cuba"]'::jsonb, 2, 'Comme les États-Unis au Vietnam, l’URSS s’enlise dix ans en Afghanistan, ce qui l’épuise à la veille de sa chute.', 1),
    ('4ab34338-86f2-571c-bcd6-0111050d3264'::uuid, 'histoire-geo', 'Tle', 'La guerre froide : affrontements et crises politiques dans un monde bipolaire', 'Que met-on en place après la crise de Cuba pour éviter un accident nucléaire ?', 'mcq', '["Le « téléphone rouge »","Le pacte de Varsovie","Le mur de Berlin","Le plan Marshall"]'::jsonb, 0, 'Une ligne directe entre Washington et Moscou permet de se parler en cas de crise.', 2),
    ('57253381-3f9d-5546-b8e3-02856f2cb3f6'::uuid, 'histoire-geo', 'Tle', 'La guerre froide : affrontements et crises politiques dans un monde bipolaire', 'Quels événements sportifs sont boycottés pendant la guerre froide ?', 'mcq', '["Les Coupes du monde de 1962 et 1966","Le Tour de France","Les championnats d’Europe d’athlétisme","Les Jeux olympiques de 1980 et 1984"]'::jsonb, 3, 'L’Ouest boycotte les Jeux de Moscou (1980), le bloc de l’Est ceux de Los Angeles (1984) : le sport devient un terrain d’affrontement.', 3),
    ('95f0865b-90ca-5307-a9e2-e098b85ca155'::uuid, 'histoire-geo', 'Tle', 'La guerre froide : affrontements et crises politiques dans un monde bipolaire', 'Comment appelle-t-on la phase de 1963 à 1975, marquée par les accords d’Helsinki ?', 'mcq', '["La guerre fraîche","La Détente","La coexistence pacifique","La guerre froide « chaude »"]'::jsonb, 1, 'Après Cuba, les deux Grands multiplient les accords ; la « guerre fraîche » (1979-1985) viendra ensuite avec l’Afghanistan et les euromissiles.', 4),
    ('bb7e59a8-960a-52c9-af36-baa23cfacc50'::uuid, 'histoire-geo', 'Tle', 'Le Proche et le Moyen-Orient pendant la guerre froide : un enjeu stratégique pour les deux superpuissances', 'Comment se termine la crise de Suez de 1956 ?', 'mcq', '["Par l’annexion du canal par Israël","Par la victoire franco-britannique","Par l’intervention de l’OTAN","Par le retrait franco-britannique imposé par les deux Grands"]'::jsonb, 3, 'Américains et Soviétiques obligent Paris et Londres à se retirer : les anciennes puissances coloniales ne décident plus seules.', 1),
    ('7ba8eb29-1427-5cf1-ac35-b02b5e1553be'::uuid, 'histoire-geo', 'Tle', 'Le Proche et le Moyen-Orient pendant la guerre froide : un enjeu stratégique pour les deux superpuissances', 'Quel État est un appui de l’URSS dans la région ?', 'mcq', '["L’Égypte de Nasser","L’Arabie saoudite","L’Iran du chah","Israël"]'::jsonb, 0, 'L’URSS soutient l’Égypte de Nasser, la Syrie et l’Irak ; les États-Unis s’appuient sur l’Arabie saoudite et l’Iran du chah.', 2),
    ('79139302-9ab1-583b-98fb-9749881fed08'::uuid, 'histoire-geo', 'Tle', 'Le Proche et le Moyen-Orient pendant la guerre froide : un enjeu stratégique pour les deux superpuissances', 'Quelle guerre fait environ un million de morts entre 1980 et 1988 ?', 'mcq', '["La guerre des Six Jours","La guerre du Kippour","La guerre Iran-Irak","La guerre du Liban"]'::jsonb, 2, 'La guerre Iran-Irak éclate juste après la révolution iranienne et devient l’un des conflits les plus meurtriers de la période.', 3),
    ('43bf1eac-04b9-565f-90fd-e98177d38894'::uuid, 'histoire-geo', 'Tle', 'Le Proche et le Moyen-Orient pendant la guerre froide : un enjeu stratégique pour les deux superpuissances', 'Quel est l’enjeu stratégique de la région ?', 'mcq', '["Ses mines de charbon","Le canal de Suez, les détroits et les routes aériennes","Ses forêts","Ses ports de pêche"]'::jsonb, 1, 'Charnière entre trois continents, la région est un passage obligé, en plus d’abriter les deux tiers des réserves de pétrole.', 4),
    ('24a96449-603a-53d1-84be-c32308188591'::uuid, 'histoire-geo', 'Tle', 'Indépendance et nouveaux États pendant la guerre froide', 'Où naît le mouvement des non-alignés en 1961 ?', 'mcq', '["À Bandung","À Belgrade","Au Caire","À New Delhi"]'::jsonb, 1, 'À Belgrade, Nehru, Nasser, Tito et Soekarno fondent le mouvement, six ans après la conférence de Bandung.', 1),
    ('230fb52e-5dc3-5e98-ae47-d80b0d21687c'::uuid, 'histoire-geo', 'Tle', 'Indépendance et nouveaux États pendant la guerre froide', 'Que montre la partition de l’Inde en 1947 ?', 'mcq', '["Qu’une indépendance négociée peut aussi coûter très cher","Que la décolonisation s’est faite sans violence","Que le Royaume-Uni a refusé toute négociation","Que l’Inde est restée une colonie"]'::jsonb, 0, 'L’indépendance est négociée, mais la partition entre l’Inde et le Pakistan fait des centaines de milliers de morts.', 2),
    ('adaf3953-ccb9-517a-ae09-5e90a0fe06c7'::uuid, 'histoire-geo', 'Tle', 'Indépendance et nouveaux États pendant la guerre froide', 'En quelle année l’Angola et le Mozambique deviennent-ils indépendants ?', 'mcq', '["1947","1960","1962","1975"]'::jsonb, 3, 'Ces colonies portugaises arrachent leur indépendance tardivement, en 1975, après de longues guerres.', 3),
    ('b62a14cb-4b9c-5332-a81d-c11e5428ea2b'::uuid, 'histoire-geo', 'Tle', 'Indépendance et nouveaux États pendant la guerre froide', 'Quel texte affirme le droit des peuples à disposer d’eux-mêmes ?', 'mcq', '["Le traité de Versailles","Le pacte de Varsovie","La charte de l’ONU","Le plan Marshall"]'::jsonb, 2, 'La charte de l’ONU (1945) donne aux mouvements nationalistes un argument juridique contre l’ordre colonial.', 4),
    ('c47a6074-15b9-571b-8439-fa261b65cb3a'::uuid, 'histoire-geo', 'Tle', 'L’ère maoïste : retrouver la puissance par la révolution (1949-1976)', 'Combien de morts fait la famine de 1959-1961 ?', 'mcq', '["Environ 1 million","Environ 5 millions","20 à 40 millions","Plus de 100 millions"]'::jsonb, 2, 'Le Grand Bond en avant, appliqué sans contradiction possible, tourne à la catastrophe démographique.', 1),
    ('c7649cb8-cfec-53d5-92d4-5305fb561b09'::uuid, 'histoire-geo', 'Tle', 'L’ère maoïste : retrouver la puissance par la révolution (1949-1976)', 'Que produisent les « hauts fourneaux de jardin » ?', 'mcq', '["Un acier inutilisable","L’essentiel de l’acier chinois","Des armes pour l’Armée populaire","Des outils exportés vers l’URSS"]'::jsonb, 0, 'Fondre des ustensiles dans des fourneaux de fortune gonfle les chiffres, pas la production réelle.', 2),
    ('cdfef6e4-7ea0-546e-b20e-1fadcd09a246'::uuid, 'histoire-geo', 'Tle', 'L’ère maoïste : retrouver la puissance par la révolution (1949-1976)', 'En quelle année Mao lance-t-il la Révolution culturelle ?', 'mcq', '["1949","1958","1972","1966"]'::jsonb, 3, 'En 1966, pour reprendre la main après l’échec du Grand Bond, Mao lance les gardes rouges contre le parti, l’école et la culture.', 3),
    ('1de14980-c6da-52c7-b1a4-f8f37123a263'::uuid, 'histoire-geo', 'Tle', 'L’ère maoïste : retrouver la puissance par la révolution (1949-1976)', 'Sur quel modèle le premier plan quinquennal chinois de 1953 est-il bâti ?', 'mcq', '["Le modèle américain","Le modèle soviétique","Le modèle japonais","Le modèle yougoslave"]'::jsonb, 1, 'Alliée de l’URSS depuis le traité de 1950, la Chine copie d’abord la planification soviétique, avant la rupture des années 1960.', 4),
    ('f0ab7ff2-3ddf-5b7b-8cb9-ccf9401a5cd5'::uuid, 'histoire-geo', 'Tle', '1968 : la remise en question des modèles', 'Quels accords sont conclus en France en mai 1968 ?', 'mcq', '["Les accords Matignon","Les accords d’Évian","Les accords de Grenelle","Les accords d’Helsinki"]'::jsonb, 2, 'Les accords de Grenelle accordent des hausses de salaires ; les accords Matignon, eux, datent du Front populaire (1936).', 1),
    ('d4b105fd-71d4-5d72-9ce2-38922c39efd8'::uuid, 'histoire-geo', 'Tle', '1968 : la remise en question des modèles', 'Comment s’achève la crise de Mai 68 en France ?', 'mcq', '["Par la démission immédiate de De Gaulle","Par une dissolution et une large victoire gaulliste aux élections","Par un changement de Constitution","Par la victoire de la gauche"]'::jsonb, 1, 'La contestation ne se transforme pas en majorité : les législatives de juin 1968 donnent une large victoire aux gaullistes.', 2),
    ('3bf1aed4-dc6a-5bfa-b96b-cf964239c9a8'::uuid, 'histoire-geo', 'Tle', '1968 : la remise en question des modèles', 'Où les manifestations de 1968 sont-elles réprimées à Tlatelolco ?', 'mcq', '["Au Mexique, avant les Jeux olympiques","Au Japon","En Pologne","Aux États-Unis"]'::jsonb, 0, 'À Mexico, peu avant les Jeux, la répression de Tlatelolco écrase le mouvement étudiant.', 3),
    ('6447c426-9669-52b5-a607-fee98e207c6e'::uuid, 'histoire-geo', 'Tle', '1968 : la remise en question des modèles', 'Quel projet porte le Printemps de Prague ?', 'mcq', '["La sortie immédiate du communisme","Le rattachement à l’Allemagne de l’Ouest","L’adhésion à l’OTAN","Un « socialisme à visage humain »"]'::jsonb, 3, 'Dubcek veut réformer le socialisme de l’intérieur ; la doctrine Brejnev interdit même cela.', 4),
    ('df41c05c-f405-5226-beaf-777fd32cfe05'::uuid, 'histoire-geo', 'Tle', 'La IVe République : entre décolonisation et construction européenne', 'Combien de gouvernements se succèdent sous la IVe République ?', 'mcq', '["24 en douze ans","5 en douze ans","12 en douze ans","40 en douze ans"]'::jsonb, 0, 'Scrutin proportionnel et coalitions fragiles rendent les gouvernements très éphémères.', 1),
    ('b516f647-0961-5dc5-942c-9ec529ba8164'::uuid, 'histoire-geo', 'Tle', 'La IVe République : entre décolonisation et construction européenne', 'Quel est le sort de la Communauté européenne de défense (CED) en 1954 ?', 'mcq', '["Elle est adoptée par six pays","Elle devient l’OTAN","Elle est rejetée par l’Assemblée française","Elle est remplacée par la CECA"]'::jsonb, 2, 'L’Assemblée nationale refuse l’armée européenne : la construction européenne repart par l’économie, avec le traité de Rome (1957).', 2),
    ('92f5d0bd-de55-595c-ad0f-8a80e67c1154'::uuid, 'histoire-geo', 'Tle', 'La IVe République : entre décolonisation et construction européenne', 'Quelle entreprise est nationalisée à la Libération ?', 'mcq', '["Peugeot","Michelin","Citroën","Renault"]'::jsonb, 3, 'EDF, Renault et les grandes banques passent sous le contrôle de l’État au sortir de la guerre.', 3),
    ('b08598b0-340f-59e3-8f18-6a3ef97095ad'::uuid, 'histoire-geo', 'Tle', 'La IVe République : entre décolonisation et construction européenne', 'En quelle année la Tunisie et le Maroc deviennent-ils indépendants ?', 'mcq', '["1954","1956","1960","1962"]'::jsonb, 1, 'Les deux protectorats obtiennent leur indépendance en 1956, alors que la guerre d’Algérie s’intensifie.', 4),
    ('da77e86e-8bca-5877-ae5b-d7c7774afd1a'::uuid, 'histoire-geo', 'Tle', 'La Ve République de De Gaulle', 'Que permet l’article 16 de la Constitution de 1958 ?', 'mcq', '["Le référendum","L’exercice de pouvoirs exceptionnels par le président","La dissolution de l’Assemblée","La nomination du Premier ministre"]'::jsonb, 1, 'En cas de menace grave, le président peut concentrer les pouvoirs : c’est l’un des instruments d’un exécutif fort.', 1),
    ('a1ce166d-6cd9-5934-b534-f203eb3d30db'::uuid, 'histoire-geo', 'Tle', 'La Ve République de De Gaulle', 'Quand a lieu le putsch des généraux à Alger ?', 'mcq', '["En avril 1961","En mai 1958","En mars 1962","En juillet 1962"]'::jsonb, 0, 'Des généraux hostiles à l’autodétermination tentent de prendre le pouvoir à Alger ; le putsch échoue en quelques jours.', 2),
    ('100262c6-624c-5ac3-ba99-4bfe8dd84148'::uuid, 'histoire-geo', 'Tle', 'La Ve République de De Gaulle', 'En quelle année la France reconnaît-elle la Chine populaire ?', 'mcq', '["1949","1971","1958","1964"]'::jsonb, 3, 'En 1964, de Gaulle reconnaît Pékin avant les États-Unis : un geste d’indépendance diplomatique.', 3),
    ('37f7225e-4ef5-55f7-a265-05daf31a598c'::uuid, 'histoire-geo', 'Tle', 'La Ve République de De Gaulle', 'Que marque le discours de Phnom Penh en 1966 ?', 'mcq', '["Le retrait de l’OTAN","La fin de la guerre d’Algérie","L’opposition de la France à la guerre du Vietnam","La reconnaissance de la Chine"]'::jsonb, 2, 'À Phnom Penh, de Gaulle critique l’intervention américaine au Vietnam : l’indépendance nationale vaut aussi face aux alliés.', 4),
    ('be241709-bd81-5c0e-9457-f20d877bfc98'::uuid, 'histoire-geo', 'Tle', 'L’influence de la chute de l’URSS sur l’Europe', 'Qu’entraîne l’abandon de la doctrine Brejnev par Gorbatchev ?', 'mcq', '["Le renforcement du pacte de Varsovie","Moscou n’interviendra plus pour sauver les régimes frères","L’invasion de la Pologne","Le retour du stalinisme"]'::jsonb, 1, 'Privés du filet soviétique, les régimes d’Europe centrale tombent en quelques mois, comme des dominos.', 1),
    ('87326fbd-c80e-5185-8737-a8d1a7ffbc9b'::uuid, 'histoire-geo', 'Tle', 'L’influence de la chute de l’URSS sur l’Europe', 'Que désigne la « thérapie de choc » ?', 'mcq', '["Le passage brutal à l’économie de marché","Une réforme de la santé publique","La réunification allemande","Une intervention militaire de l’OTAN"]'::jsonb, 0, 'Privatisations massives et fin des prix administrés provoquent inflation, effondrement de la production et chômage de masse.', 2),
    ('db56a244-1566-505b-ba54-0ac9a941b4ee'::uuid, 'histoire-geo', 'Tle', 'L’influence de la chute de l’URSS sur l’Europe', 'Quand l’Allemagne est-elle réunifiée ?', 'mcq', '["Le 9 novembre 1989","Le 25 décembre 1991","Le 1er mai 2004","Le 3 octobre 1990"]'::jsonb, 3, 'Moins d’un an après l’ouverture du Mur, la RDA rejoint la RFA ; l’Allemagne devient la première puissance économique du continent.', 3),
    ('6961df9b-09ad-580b-9406-667ca3d9ad1d'::uuid, 'histoire-geo', 'Tle', 'L’influence de la chute de l’URSS sur l’Europe', 'En quelle année la Pologne, la Hongrie et la République tchèque entrent-elles dans l’OTAN ?', 'mcq', '["1991","2004","1999","2007"]'::jsonb, 2, 'Elles rejoignent l’OTAN dès 1999, avant les pays baltes (2004) et avant leur entrée dans l’Union européenne (2004).', 4),
    ('4e4ce1a0-565c-5512-9883-8c16c8eef8f3'::uuid, 'histoire-geo', 'Tle', 'Le Proche-Orient au cœur de la nouvelle géopolitique mondiale', 'En quelle année Yitzhak Rabin est-il assassiné ?', 'mcq', '["1993","1995","2000","1987"]'::jsonb, 1, 'L’assassinat de Rabin en 1995 enraye le processus d’Oslo, qui s’effondre avec la seconde Intifada (2000).', 1),
    ('1006e029-e67a-53e5-9414-6fce277b6fc8'::uuid, 'histoire-geo', 'Tle', 'Le Proche-Orient au cœur de la nouvelle géopolitique mondiale', 'Quel est le motif de la guerre du Golfe de 1991 ?', 'mcq', '["L’invasion du Koweït par l’Irak de Saddam Hussein","Des armes de destruction massive","Les attentats du 11 septembre","La révolution iranienne"]'::jsonb, 0, 'L’invasion du Koweït justifie une intervention sous mandat de l’ONU ; les armes de destruction massive seront le motif de 2003.', 2),
    ('e1566f4e-cfb2-5584-834a-9df904a61d5d'::uuid, 'histoire-geo', 'Tle', 'Le Proche-Orient au cœur de la nouvelle géopolitique mondiale', 'Quelle est la position de la France face à l’invasion de l’Irak en 2003 ?', 'mcq', '["Elle y participe","Elle la finance","Elle s’abstient sans prendre position","Elle s’y oppose, avec le discours de Villepin à l’ONU"]'::jsonb, 3, 'La France participe à la guerre de 1991 mais s’oppose à celle de 2003, lancée sans mandat de l’ONU.', 3),
    ('7de0a75c-ea27-56db-ba46-f61edf6025cf'::uuid, 'histoire-geo', 'Tle', 'Le Proche-Orient au cœur de la nouvelle géopolitique mondiale', 'Qu’oppose la rivalité entre l’Arabie saoudite et l’Iran ?', 'mcq', '["Deux alliés des États-Unis","Deux monarchies laïques","Sunnisme et chiisme, deux puissances régionales","Deux membres de l’Union européenne"]'::jsonb, 2, 'La rivalité entre Riyad, sunnite, et Téhéran, chiite, structure une grande partie des conflits de la région.', 4),
    ('d767b810-e034-5489-9f66-74869cb4e8e2'::uuid, 'histoire-geo', 'Tle', 'La montée de la puissance économique chinoise de 1978 à 2001', 'Combien de zones économiques spéciales sont créées en 1980 ?', 'mcq', '["Deux","Dix","Quatre","Cinquante"]'::jsonb, 2, 'Quatre zones, dont Shenzhen, expérimentent l’ouverture aux capitaux étrangers sans toucher au reste du pays.', 1),
    ('9c734ca6-6850-527c-9064-e71e71c97108'::uuid, 'histoire-geo', 'Tle', 'La montée de la puissance économique chinoise de 1978 à 2001', 'Que devient la terre avec le démantèlement des communes populaires ?', 'mcq', '["Elle est vendue à des firmes étrangères","Elle revient aux familles par contrat","Elle est nationalisée","Elle est mise en jachère"]'::jsonb, 1, 'Les familles cultivent sous contrat et peuvent vendre leurs surplus : la production agricole bondit.', 2),
    ('d1d2114f-9bff-5af0-b350-701726b2eb54'::uuid, 'histoire-geo', 'Tle', 'La montée de la puissance économique chinoise de 1978 à 2001', 'Quand Deng Xiaoping fait-il sa « tournée dans le Sud » qui relance les réformes ?', 'mcq', '["En 1992","En 1978","En 1989","En 2001"]'::jsonb, 0, 'Après Tian’anmen, la tournée de 1992 relance la croissance sous le nom d’« économie socialiste de marché ».', 3),
