    ('21ae2296-9718-51e3-86b1-106ac8c2dfa2'::uuid, 'histoire-geo', 'Tle', 'Des enjeux géostratégiques qui se déplacent vers les mers et les océans', 'Quels archipels la Chine militarise-t-elle en mer de Chine méridionale ?', 'mcq', '["Les Kouriles et les Aléoutiennes","Les Maldives et les Seychelles","Les Açores et les Canaries","Les Spratleys et les Paracels"]'::jsonb, 3, 'Pékin y construit des îlots artificiels militarisés pour appuyer sa « ligne en neuf traits ».', 3),
    ('dde493ba-d53a-5eb8-b9b0-53de454d8001'::uuid, 'histoire-geo', 'Tle', 'Des enjeux géostratégiques qui se déplacent vers les mers et les océans', 'Sur quel critère un État peut-il demander l’extension de son plateau continental au-delà de 200 milles ?', 'mcq', '["La population de ses côtes","Un critère géologique","La taille de sa flotte","L’ancienneté de sa présence"]'::jsonb, 1, 'Les demandes déposées auprès de l’ONU reposent sur le prolongement naturel des fonds marins : la mer se territorialise.', 4),
    ('da305a4a-8b25-54ff-8f3e-ca8e0d9a3888'::uuid, 'histoire-geo', 'Tle', 'Le détroit de Malacca et le golfe arabo-persique : des points de passage au cœur de la mondialisation', 'Quelle part du pétrole consommé dans le monde transite par le détroit d’Ormuz ?', 'mcq', '["Environ un cinquième","Environ la moitié","Environ 2 %","Presque la totalité"]'::jsonb, 0, 'Environ 20 millions de barils par jour franchissent Ormuz : c’est à la fois une artère et un levier de pression.', 1),
    ('b992ff39-95a7-56ed-ab49-71a3f3b3aef7'::uuid, 'histoire-geo', 'Tle', 'Le détroit de Malacca et le golfe arabo-persique : des points de passage au cœur de la mondialisation', 'Quelle part du commerce maritime mondial passe par le détroit de Malacca ?', 'mcq', '["Environ 5 %","Environ 80 %","Environ la moitié","Environ un quart"]'::jsonb, 3, 'Entre 90 000 et 100 000 navires par an empruntent ce goulet de 900 km entre la Malaisie et Sumatra.', 2),
    ('2708ebfe-3528-54ba-a9cb-5660a31e4d73'::uuid, 'histoire-geo', 'Tle', 'Le détroit de Malacca et le golfe arabo-persique : des points de passage au cœur de la mondialisation', 'Où est basée la Ve flotte américaine ?', 'mcq', '["À Djibouti","À Singapour","À Bahreïn","À Abou Dabi"]'::jsonb, 2, 'La Ve flotte à Bahreïn surveille le golfe ; la France dispose, elle, d’une base à Abou Dabi.', 3),
    ('4203423d-a933-5b32-9a24-410615c2da3e'::uuid, 'histoire-geo', 'Tle', 'Le détroit de Malacca et le golfe arabo-persique : des points de passage au cœur de la mondialisation', 'Où serait creusé le canal de Kra, projet pour contourner Malacca ?', 'mcq', '["En Malaisie","En Thaïlande","En Indonésie","Au Vietnam"]'::jsonb, 1, 'Le canal de Kra à travers la Thaïlande n’a jamais été engagé ; seuls des oléoducs vers la Birmanie et le Pakistan fonctionnent.', 4),
    ('a17d958c-c20b-505e-8f3c-00d59e257307'::uuid, 'histoire-geo', 'Tle', 'Mers et océans en devenir', 'Qu’est-ce qui provoque l’eutrophisation des eaux côtières ?', 'mcq', '["Les plastiques","Les engrais agricoles","Le réchauffement","Le trafic des porte-conteneurs"]'::jsonb, 1, 'Les engrais nourrissent la prolifération d’algues : marées vertes et zones mortes privées d’oxygène.', 1),
    ('084dfb4b-9ea7-5387-a5b7-e46dea0e58b5'::uuid, 'histoire-geo', 'Tle', 'Mers et océans en devenir', 'Quel est le rôle de l’AIFM ?', 'mcq', '["Délivrer les permis d’exploration des fonds marins au-delà des ZEE","Surveiller la pêche illégale","Fixer les quotas de pêche européens","Protéger les coraux"]'::jsonb, 0, 'L’Autorité internationale des fonds marins gère les ressources minérales des grands fonds qui n’appartiennent à aucun État.', 2),
    ('c465f66b-dd94-59d2-a6d9-3f452d61e326'::uuid, 'histoire-geo', 'Tle', 'Mers et océans en devenir', 'Quelle part de l’océan n’appartenait à personne avant le traité BBNJ ?', 'mcq', '["10 %","30 %","90 %","60 %"]'::jsonb, 3, 'La haute mer, environ 60 % de l’océan, échappait à toute juridiction : personne ne pouvait y interdire quoi que ce soit.', 3),
    ('caa0f598-ce99-572c-bb3b-266bfbfc6d2c'::uuid, 'histoire-geo', 'Tle', 'Mers et océans en devenir', 'Quelle part du CO₂ émis l’océan absorbe-t-il ?', 'mcq', '["Environ la moitié","Presque rien","Environ un quart","La totalité"]'::jsonb, 2, 'Ce CO₂ absorbé fait baisser le pH de l’eau et fragilise coraux et coquillages.', 4),
    ('36751300-9b6c-5c31-b8d4-6b9484a7ccf9'::uuid, 'histoire-geo', 'Tle', 'La France : une puissance maritime ?', 'Quelle est la superficie approximative de la ZEE française ?', 'mcq', '["1 million de km²","10,2 millions de km²","3,5 millions de km²","25 millions de km²"]'::jsonb, 1, 'Environ 10,2 millions de km², derrière les États-Unis ; les demandes d’extension la portent au-delà de 11 millions.', 1),
    ('f0a680bc-a3d6-5fc4-9007-795d01e98fbe'::uuid, 'histoire-geo', 'Tle', 'La France : une puissance maritime ?', 'Quel territoire donne à la France un espace maritime dans l’océan Indien ?', 'mcq', '["La Polynésie française","La Guyane","Saint-Pierre-et-Miquelon","Mayotte"]'::jsonb, 3, 'Mayotte, La Réunion et les Terres australes placent la France dans l’océan Indien ; la Polynésie est dans le Pacifique.', 2),
    ('fc27bb5b-ab3a-5032-9ff7-5d292c2de252'::uuid, 'histoire-geo', 'Tle', 'La France : une puissance maritime ?', 'Quelle ville est un grand pôle de construction navale française ?', 'mcq', '["Saint-Nazaire","Lyon","Clermont-Ferrand","Toulouse"]'::jsonb, 0, 'Les chantiers de Saint-Nazaire construisent parmi les plus grands navires du monde.', 3),
    ('87bd5caa-b691-57b6-8034-cd1dc385848e'::uuid, 'histoire-geo', 'Tle', 'La France : une puissance maritime ?', 'Pourquoi les ports français décrochent-ils face à Rotterdam et Anvers ?', 'mcq', '["Parce qu’ils sont trop petits pour accueillir des navires","Parce que la France n’a pas de façade maritime","Parce que leur arrière-pays est mal connecté et leur fiabilité insuffisante","Parce que le commerce maritime diminue"]'::jsonb, 2, 'La France est puissante par son domaine et sa marine, pas par son économie portuaire.', 4),
    ('f8cd149f-c7a1-5bf3-a9c0-c74aa79a7d58'::uuid, 'histoire-geo', 'Tle', 'Des territoires inégalement intégrés dans la mondialisation', 'Quels espaces forment les centres d’impulsion de la mondialisation ?', 'mcq', '["L’Afrique subsaharienne et l’Asie centrale","L’Amérique du Nord, l’Europe occidentale et l’Asie orientale","Le Moyen-Orient seul","L’Amérique latine et l’Océanie"]'::jsonb, 1, 'Ces trois pôles concentrent capitaux, décisions et innovation.', 1),
    ('c69491dc-3445-53b4-a5f3-4143203eddfe'::uuid, 'histoire-geo', 'Tle', 'Des territoires inégalement intégrés dans la mondialisation', 'Quel pays, premier exportateur mondial, montre que la grille Nord / Sud ne suffit plus ?', 'mcq', '["L’Inde","Le Brésil","La Chine","Le Nigeria"]'::jsonb, 2, 'Un pays longtemps classé au « Sud » est devenu le premier exportateur mondial.', 2),
    ('48d258c9-7582-586c-9e7a-313f15dd51f9'::uuid, 'histoire-geo', 'Tle', 'Des territoires inégalement intégrés dans la mondialisation', 'Quelle est la limite du PIB par habitant comme indicateur ?', 'mcq', '["Il ignore la répartition des richesses","Il ne mesure pas la richesse produite","Il n’existe que pour les pays riches","Il ne tient compte que de l’agriculture"]'::jsonb, 0, 'Une moyenne élevée peut cacher de très fortes inégalités.', 3),
    ('bbbbc500-2db0-5169-9b4b-170a947b058e'::uuid, 'histoire-geo', 'Tle', 'Des territoires inégalement intégrés dans la mondialisation', 'Pourquoi un stock d’IDE élevé ne prouve-t-il pas toujours l’attractivité ?', 'mcq', '["Parce qu’il ne concerne que l’agriculture","Parce qu’il est toujours faible","Parce qu’il mesure le tourisme","Parce qu’il peut refléter un statut fiscal avantageux"]'::jsonb, 3, 'Des capitaux peuvent transiter par un territoire pour des raisons fiscales, sans y créer d’activité réelle.', 4),
    ('1bf32232-cd94-531d-9960-6a8da735eec9'::uuid, 'histoire-geo', 'Tle', 'La hiérarchie des centres de décision mondiaux', 'Quel réseau de chercheurs classe les villes mondiales ?', 'mcq', '["L’OCDE","Le GaWC","L’ONU-Habitat","Le FMI"]'::jsonb, 1, 'Le classement du GaWC place New York et Londres au sommet, suivies de Tokyo, Paris, Hong Kong, Singapour, Shanghai et Dubaï.', 1),
    ('7ed41ac1-f4bb-5c25-9f64-a65fd1191737'::uuid, 'histoire-geo', 'Tle', 'La hiérarchie des centres de décision mondiaux', 'Quel quartier d’affaires (CBD) appartient à Shanghai ?', 'mcq', '["La City","Canary Wharf","La Défense","Pudong"]'::jsonb, 3, 'Pudong est le CBD de Shanghai, comme Manhattan pour New York ou La Défense pour Paris.', 2),
    ('85481a46-307a-5d94-a98b-38bfc3169306'::uuid, 'histoire-geo', 'Tle', 'La hiérarchie des centres de décision mondiaux', 'Où siègent l’OMC et l’OMS ?', 'mcq', '["À Genève","À New York","À Washington","À Bruxelles"]'::jsonb, 0, 'Genève accueille l’OMC et l’OMS ; l’ONU siège à New York, le FMI et la Banque mondiale à Washington.', 3),
    ('7d5a4d91-7803-5133-83d1-1ff836ad1066'::uuid, 'histoire-geo', 'Tle', 'La hiérarchie des centres de décision mondiaux', 'Que désigne le réseau, par opposition à la hiérarchie ?', 'mcq', '["Qui commande à qui","Le nombre d’habitants","Qui est relié à qui","La superficie des villes"]'::jsonb, 2, 'La hiérarchie dit qui commande, le réseau qui est connecté : une mégapole peut être très peuplée et faiblement reliée.', 4),
    ('dc7d749d-7a64-5abf-947c-c97324627b28'::uuid, 'histoire-geo', 'Tle', 'La France : un rayonnement international différencié et une inégale attractivité dans la mondialisation', 'Quelle part de la population mondiale la France représente-t-elle ?', 'mcq', '["Environ 1 %","Environ 5 %","Environ 0,1 %","Environ 10 %"]'::jsonb, 0, 'Environ 1 % de la population mondiale, mais une influence bien supérieure à ce poids.', 1),
    ('551a1b44-932f-5142-9dde-d559809b56f3'::uuid, 'histoire-geo', 'Tle', 'La France : un rayonnement international différencié et une inégale attractivité dans la mondialisation', 'Pourquoi la France, première destination touristique, n’a-t-elle pas les premières recettes ?', 'mcq', '["Parce que ses hôtels sont gratuits","Parce que les touristes y viennent surtout l’hiver","Parce que le tourisme y est interdit aux étrangers","Parce que les séjours y sont plus courts"]'::jsonb, 3, 'L’Espagne et les États-Unis encaissent davantage : un record de fréquentation n’est pas un record de puissance.', 2),
    ('9a2c0ef4-ff88-591c-bb1b-aafee56c3e19'::uuid, 'histoire-geo', 'Tle', 'La France : un rayonnement international différencié et une inégale attractivité dans la mondialisation', 'Combien de visiteurs internationaux la France reçoit-elle chaque année ?', 'mcq', '["10 à 20 millions","300 millions","90 à 100 millions","40 millions"]'::jsonb, 2, 'Entre 90 et 100 millions de visiteurs par an en font la première destination mondiale.', 3),
    ('822663e6-2413-5d62-b959-63f53265194a'::uuid, 'histoire-geo', 'Tle', 'La France : un rayonnement international différencié et une inégale attractivité dans la mondialisation', 'Depuis quand la part de l’industrie dans le PIB français recule-t-elle ?', 'mcq', '["Depuis les années 2020","Depuis les années 1980","Depuis 1945","Elle ne recule pas"]'::jsonb, 1, 'La désindustrialisation, visible depuis les années 1980, explique en partie le déficit commercial structurel.', 4),
    ('bc542ebb-faab-5c3f-8cd3-ff4ac1fc121e'::uuid, 'histoire-geo', 'Tle', 'Coopérations économiques et tentatives de régulation', 'Quel est le rôle du FMI ?', 'mcq', '["Arbitrer les litiges commerciaux","Prêter aux États en crise, sous conditions","Financer les ONG","Fixer le prix du pétrole"]'::jsonb, 1, 'Créé en 1944, le FMI prête aux États en difficulté ; ses conditionnalités sont contestées.', 1),
    ('995af583-86ab-570b-8c7b-cd2667ec6c2b'::uuid, 'histoire-geo', 'Tle', 'Coopérations économiques et tentatives de régulation', 'Quel est le degré d’intégration du Mercosur ?', 'mcq', '["Une union douanière imparfaite","Une monnaie unique","Une union politique","Un marché unique complet"]'::jsonb, 0, 'En Amérique du Sud, le Mercosur a un tarif extérieur commun appliqué avec de nombreuses exceptions.', 2),
    ('7f952351-91d4-5bfd-b6ca-6409a12cb925'::uuid, 'histoire-geo', 'Tle', 'Coopérations économiques et tentatives de régulation', 'Quel ensemble a remplacé l’ALENA en Amérique du Nord ?', 'mcq', '["Le RCEP","La ZLECAf","L’ASEAN","L’ACEUM"]'::jsonb, 3, 'L’ACEUM associe États-Unis, Mexique et Canada dans une zone de libre-échange.', 3),
    ('420b16d6-1ea4-5a33-b190-5f07c4853ac8'::uuid, 'histoire-geo', 'Tle', 'Coopérations économiques et tentatives de régulation', 'Quelle organisation adopte des conventions sur le travail ?', 'mcq', '["L’OMC","L’OCDE","L’OIT","Le G7"]'::jsonb, 2, 'Les conventions de l’Organisation internationale du travail ont une force contraignante faible.', 4),
    ('b8bdeab4-529b-53d0-bcdd-ac8fc2877236'::uuid, 'histoire-geo', 'Tle', 'La mondialisation et ses limites', 'Qu’a révélé la crise de 2008 ?', 'mcq', '["La contagion financière : un défaut américain devient une crise mondiale","La fin du commerce maritime","La dépendance énergétique à la Russie","La pénurie de masques"]'::jsonb, 0, 'Parti des crédits immobiliers américains, le choc s’est propagé à tout le système financier mondial.', 1),
    ('1173274e-bf4d-55bc-a48f-38eddc9e5052'::uuid, 'histoire-geo', 'Tle', 'La mondialisation et ses limites', 'Que désigne le « dumping social et environnemental » ?', 'mcq', '["La hausse des normes","La relocalisation des usines","La taxation des importations","Produire là où le droit du travail et les normes sont les plus faibles"]'::jsonb, 3, 'C’est l’un des principaux reproches adressés à la mondialisation.', 2),
    ('6ce409e3-e195-539c-8251-d5e8e92bb58d'::uuid, 'histoire-geo', 'Tle', 'La mondialisation et ses limites', 'Quel plan américain illustre la politique de relocalisation ?', 'mcq', '["Le plan Marshall","L’Inflation Reduction Act","Le consensus de Washington","Le New Deal"]'::jsonb, 1, 'L’Inflation Reduction Act subventionne massivement la production sur le sol américain.', 3),
    ('325369ea-3710-51ff-b1f2-3c700644b320'::uuid, 'histoire-geo', 'Tle', 'La mondialisation et ses limites', 'Quel mot le cours préfère-t-il à « démondialisation » ?', 'mcq', '["Effondrement","Isolement","Recomposition","Autarcie"]'::jsonb, 2, 'Le commerce mondial ne s’effondre pas : il se régionalise et se politise.', 4),
    ('39dc3931-7095-5a5b-a17b-32ef8cbc92d9'::uuid, 'histoire-geo', 'Tle', 'La Russie et l’Asie du Sud-Est : entre inégale intégration dans la mondialisation, coopérations et tensions', 'Combien d’États compte l’ASEAN ?', 'mcq', '["6","27","15","10"]'::jsonb, 3, 'Fondée en 1967, l’ASEAN réunit dix États d’Asie du Sud-Est, sur les grandes routes maritimes.', 1),
    ('42d29d9b-78d2-5f68-82d5-e212b331baed'::uuid, 'histoire-geo', 'Tle', 'La Russie et l’Asie du Sud-Est : entre inégale intégration dans la mondialisation, coopérations et tensions', 'Combien d’habitants compte l’ASEAN ?', 'mcq', '["Plus de 650 millions","Environ 100 millions","Plus de 2 milliards","Environ 300 millions"]'::jsonb, 0, 'Une main-d’œuvre nombreuse, qui attire la sous-traitance et les relocalisations hors de Chine.', 2),
    ('0e721ac5-e97c-5413-a71a-0d89f3ecb599'::uuid, 'histoire-geo', 'Tle', 'La Russie et l’Asie du Sud-Est : entre inégale intégration dans la mondialisation, coopérations et tensions', 'Quels États de l’ASEAN comptent parmi les plus pauvres du monde ?', 'mcq', '["Singapour et la Malaisie","Le Laos et le Cambodge","L’Indonésie et la Thaïlande","Le Vietnam et les Philippines"]'::jsonb, 1, 'Singapour est parmi les plus riches du monde, le Laos et le Cambodge parmi les plus pauvres : l’ensemble est très inégal.', 3),
    ('9781200c-4b85-52ef-ba2e-71ca7f480bce'::uuid, 'histoire-geo', 'Tle', 'La Russie et l’Asie du Sud-Est : entre inégale intégration dans la mondialisation, coopérations et tensions', 'À quoi le PIB de la Russie est-il comparable ?', 'mcq', '["À celui des États-Unis","À celui de la Chine","À celui d’un grand pays européen","À celui d’un petit État africain"]'::jsonb, 2, 'Premier pays du monde par la superficie, la Russie a une économie peu diversifiée, fondée sur la rente.', 4),
    ('59478984-b5f0-52c8-9d92-e203315a078a'::uuid, 'histoire-geo', 'Tle', 'L’Union européenne : la puissance dans la diversité', 'Combien d’habitants compte l’Union européenne ?', 'mcq', '["Environ 200 millions","Environ 450 millions","Environ 800 millions","Plus d’un milliard"]'::jsonb, 1, 'Environ 450 millions d’habitants dans 27 États : le plus vaste marché intégré du monde.', 1),
    ('d6338755-966f-57d8-8eab-309b5786f208'::uuid, 'histoire-geo', 'Tle', 'L’Union européenne : la puissance dans la diversité', 'Quel rang l’euro occupe-t-il parmi les monnaies de réserve ?', 'mcq', '["Le premier","Le cinquième","Le dixième","Le deuxième"]'::jsonb, 3, 'L’euro est la deuxième monnaie de réserve mondiale, derrière le dollar.', 2),
    ('928307f4-c676-5e71-b0b7-c23b71324c76'::uuid, 'histoire-geo', 'Tle', 'L’Union européenne : la puissance dans la diversité', 'Sur quoi repose largement la défense des États de l’UE ?', 'mcq', '["Sur l’OTAN","Sur une armée européenne","Sur l’ONU","Sur la PAC"]'::jsonb, 0, 'Sans armée commune, l’Union compte sur l’OTAN, donc en grande partie sur les États-Unis.', 3),
    ('7d1a398b-83c8-5aa5-bbcc-b2112b4ab2f6'::uuid, 'histoire-geo', 'Tle', 'L’Union européenne : la puissance dans la diversité', 'Quelle formule classique résume la puissance européenne ?', 'mcq', '["« Nain économique, géant politique »","« Hyperpuissance »","« Géant économique, nain politique »","« Gendarme du monde »"]'::jsonb, 2, 'La formule est à discuter : la relance de 2020 et le soutien à l’Ukraine ont montré une capacité d’action nouvelle.', 4),
    ('2f6356a9-965f-557f-8739-2069e080f062'::uuid, 'histoire-geo', 'Tle', 'Des défis à relever qui fragilisent l’UE', 'Quel score obtient la sortie de l’UE au référendum britannique de 2016 ?', 'mcq', '["48,1 %","51,9 %","54,7 %","60 %"]'::jsonb, 1, 'Une courte majorité de 51,9 % décide du premier retrait de l’histoire de la construction européenne.', 1),
    ('5ab959f2-dfff-54c6-bb29-8c7aabde0ac5'::uuid, 'histoire-geo', 'Tle', 'Des défis à relever qui fragilisent l’UE', 'Que révèle la crise de la dette de 2010-2015 ?', 'mcq', '["Qu’une monnaie unique sans budget commun est instable","Que l’euro est trop faible face au dollar","Que l’Union a trop de membres","Que la PAC coûte trop cher"]'::jsonb, 0, 'Il en sort le MES, l’intervention de la BCE et des règles budgétaires renforcées.', 2),
    ('2620d9b8-4dba-53a0-a41a-587829cbee42'::uuid, 'histoire-geo', 'Tle', 'Des défis à relever qui fragilisent l’UE', 'Quel outil l’Union utilise-t-elle, en plus de l’article 7, face aux atteintes à l’État de droit ?', 'mcq', '["L’exclusion de l’euro","La fermeture de Schengen","L’article 50","La conditionnalité budgétaire"]'::jsonb, 3, 'Les fonds européens peuvent être suspendus à un État qui s’éloigne des valeurs qu’il a signées.', 3),
    ('873a174b-3459-5723-be89-5aa984e4ebc3'::uuid, 'histoire-geo', 'Tle', 'Des défis à relever qui fragilisent l’UE', 'Sur quels pays le règlement de Dublin fait-il peser la crise migratoire de 2015 ?', 'mcq', '["L’Allemagne et la Suède","La France et la Belgique","La Grèce et l’Italie","La Pologne et la Hongrie"]'::jsonb, 2, 'Le pays d’entrée traite la demande d’asile : les pays de la Méditerranée supportent donc l’essentiel des arrivées.', 4),
    ('4fad8034-91fe-53a7-9dd9-c8dc2329331a'::uuid, 'histoire-geo', 'Tle', 'L’Union européenne : entre inégalités territoriales et concurrence mondiale', 'Quel fonds finance la politique de cohésion ?', 'mcq', '["Le MES","Le FEDER","Frontex","La BCE"]'::jsonb, 1, 'Le FEDER, le FSE+ et le Fonds de cohésion financent infrastructures, formation et innovation dans les régions en retard.', 1),
    ('af0f07e9-accd-5dcb-870d-148ebb2d6556'::uuid, 'histoire-geo', 'Tle', 'L’Union européenne : entre inégalités territoriales et concurrence mondiale', 'Quel pays a un PIB par habitant plusieurs fois supérieur à celui de la Bulgarie ?', 'mcq', '["Le Luxembourg","La Grèce","La Roumanie","La Pologne"]'::jsonb, 0, 'Les écarts entre États membres sont considérables, du Luxembourg à la Bulgarie.', 2),
    ('ad14bb85-85b6-54c2-80d1-597238162271'::uuid, 'histoire-geo', 'Tle', 'L’Union européenne : entre inégalités territoriales et concurrence mondiale', 'Comment s’étend la dorsale de la mégalopole européenne ?', 'mcq', '["De Lisbonne à Varsovie","De Brest à Vienne","De la Scandinavie à la Grèce","Du sud de l’Angleterre à l’Italie du Nord"]'::jsonb, 3, 'Par le Benelux, la vallée du Rhin et la Suisse, elle rassemble métropoles, ports et industrie productive.', 3),
    ('77426a7b-92fc-5ea4-95f8-9d4b2ef25b7c'::uuid, 'histoire-geo', 'Tle', 'L’Union européenne : entre inégalités territoriales et concurrence mondiale', 'Lequel relève de la concurrence INTERNE entre membres de l’UE ?', 'mcq', '["L’Inflation Reduction Act","Les véhicules électriques chinois","Le recours aux travailleurs détachés","Les panneaux solaires importés"]'::jsonb, 2, 'Dumping fiscal, travailleurs détachés et course aux sièges sociaux : le marché unique organise aussi la concurrence entre ses membres.', 4),
    ('5e4b1241-ad36-5554-94d2-bdaa138b0278'::uuid, 'histoire-geo', 'Tle', 'Les transports, outils d’ouverture, de cohésion et de compétitivité de l’UE', 'Depuis quand le projet Lyon-Turin est-il débattu ?', 'mcq', '["Les années 2020","Les années 1950","Les années 1990","Les années 2010"]'::jsonb, 2, 'Le Lyon-Turin illustre des projets lents et coûteux, encore en chantier trente ans plus tard.', 1),
    ('5118fed5-22c4-5977-a0a8-61b878f5dd91'::uuid, 'histoire-geo', 'Tle', 'Les transports, outils d’ouverture, de cohésion et de compétitivité de l’UE', 'Quel port appartient au Northern Range ?', 'mcq', '["Marseille","Hambourg","Gênes","Barcelone"]'::jsonb, 1, 'Rotterdam, Anvers, Hambourg et Le Havre forment la façade maritime majeure de l’Europe du Nord-Ouest.', 2),
    ('0de1a09c-02f1-5463-ae59-e150a52b79e1'::uuid, 'histoire-geo', 'Tle', 'Les transports, outils d’ouverture, de cohésion et de compétitivité de l’UE', 'En quelles années des crises ont-elles rétabli des frontières intérieures ?', 'mcq', '["2015 et 2020","1995 et 2004","2008 et 2012","1989 et 1991"]'::jsonb, 0, 'La crise migratoire de 2015 et la pandémie de 2020 ont montré que la libre circulation se perd vite.', 3),
    ('372d222a-268f-5ada-bf0b-a1d28720ea46'::uuid, 'histoire-geo', 'Tle', 'Les transports, outils d’ouverture, de cohésion et de compétitivité de l’UE', 'Avec quel objectif la recherche de fluidité des transports entre-t-elle en tension ?', 'mcq', '["La compétitivité","L’ouverture","La cohésion","L’objectif climatique"]'::jsonb, 3, 'Plus de transport, c’est plus d’émissions : le report modal vers le rail reste un objectif, pas un fait.', 4),
    ('77f7b0ed-369f-54d1-a21b-aab290391050'::uuid, 'histoire-geo', 'Tle', 'La France et ses territoires transfrontaliers', 'Avec quels pays la France a-t-elle une frontière terrestre en Guyane ?', 'mcq', '["Le Brésil et le Suriname","Le Venezuela et la Colombie","Le Guyana et le Brésil","Le Pérou et le Suriname"]'::jsonb, 0, 'En plus de ses huit voisins européens, la France touche le Brésil et le Suriname par la Guyane.', 1),
    ('bd54a72d-e358-595a-a2c1-cf038c358744'::uuid, 'histoire-geo', 'Tle', 'La France et ses territoires transfrontaliers', 'Vers quel pays se rend une grande partie des travailleurs frontaliers ?', 'mcq', '["L’Espagne","L’Andorre","La Suisse","Le Royaume-Uni"]'::jsonb, 2, 'Genève et Bâle en Suisse, le Luxembourg, la Belgique, l’Allemagne et Monaco sont les principales destinations.', 2),
    ('7aa3fd19-de7a-501e-971c-f1a9af9d193c'::uuid, 'histoire-geo', 'Tle', 'La France et ses territoires transfrontaliers', 'Quel effet négatif le travail frontalier a-t-il côté français ?', 'mcq', '["Une baisse des prix du logement","Une hausse du chômage","Un déclin démographique","Une pénurie de main-d’œuvre, dans les hôpitaux par exemple"]'::jsonb, 3, 'Attirés par les salaires voisins, soignants et salariés quittent les employeurs français.', 3),
    ('4be6e6bb-93c8-5a2f-8966-a1178aa65d2e'::uuid, 'histoire-geo', 'Tle', 'La France et ses territoires transfrontaliers', 'Avec quelle ville allemande Strasbourg forme-t-elle une eurométropole ?', 'mcq', '["Fribourg","Kehl","Sarrebruck","Karlsruhe"]'::jsonb, 1, 'Strasbourg et Kehl, reliées par un tramway qui traverse le Rhin, gèrent ensemble une agglomération à cheval sur la frontière.', 4),
    ('464696d1-8432-5ceb-a4f9-71524d6c8057'::uuid, 'histoire-geo', 'Tle', 'Les lignes de force du territoire français', 'Quelle part de la population française vit en Île-de-France ?', 'mcq', '["Environ 31 %","Environ 10 %","Environ 19 %","Environ 40 %"]'::jsonb, 2, 'Environ 19 % de la population pour près de 31 % du PIB : c’est la macrocéphalie parisienne.', 1),
    ('f6877740-8726-508b-b06c-c1e49103471d'::uuid, 'histoire-geo', 'Tle', 'Les lignes de force du territoire français', 'Pourquoi le terme de « diagonale du vide » est-il trompeur ?', 'mcq', '["Parce que ces espaces sont peu denses, pas vides","Parce qu’ils sont très peuplés","Parce qu’ils ne forment pas une diagonale","Parce qu’ils sont en pleine croissance"]'::jsonb, 0, 'On y vit, mais l’accès aux services y est difficile : peu dense ne veut pas dire vide.', 2),
    ('998fed43-8db0-5cc6-bf30-c1e78a8324f0'::uuid, 'histoire-geo', 'Tle', 'Les lignes de force du territoire français', 'Quel risque la littoralisation accroît-elle ?', 'mcq', '["La sécheresse des montagnes","L’exposition au risque de submersion","Le dépeuplement des côtes","La baisse du prix du foncier"]'::jsonb, 1, 'Concentrer habitants et activités sur les côtes augmente aussi l’artificialisation et la flambée du foncier.', 3),
    ('803dd4c5-690e-529d-81e6-3f62a96b4215'::uuid, 'histoire-geo', 'Tle', 'Les lignes de force du territoire français', 'Qu’est-ce qui rend la macrocéphalie parisienne singulière en Europe ?', 'mcq', '["Paris est la plus grande ville du monde","Aucun autre pays n’a de capitale","Toutes les capitales européennes sont petites","L’Allemagne et l’Italie ont plusieurs pôles de rang comparable"]'::jsonb, 3, 'Le poids écrasant d’une seule ville est une singularité française, pas une norme.', 4),
    ('2b66d711-f06c-5492-b5fc-1f56121a3a30'::uuid, 'histoire-geo', 'Tle', 'Les recompositions territoriales en France', 'Combien de métropoles compte aujourd’hui la France ?', 'mcq', '["22","13","5","101"]'::jsonb, 0, 'La loi MAPTAM (2014) crée le statut ; on en compte 21, plus la Métropole de Lyon, collectivité à part ; Grand Paris, Lyon et Aix-Marseille ont un statut particulier.', 1),
    ('e17e10e8-dab6-55c2-9384-c8cbd7f5556d'::uuid, 'histoire-geo', 'Tle', 'Les recompositions territoriales en France', 'Qui exerce l’essentiel des compétences d’aménagement du quotidien ?', 'mcq', '["Les régions","L’État","Les intercommunalités","Les préfets"]'::jsonb, 2, 'La montée continue des intercommunalités en fait l’échelon clé de la vie quotidienne.', 2),
    ('908b0ca4-8c44-571b-9919-a5648e5480a1'::uuid, 'histoire-geo', 'Tle', 'Les recompositions territoriales en France', 'Quelle formule résume la doctrine d’aménagement des années 1960 ?', 'mcq', '["« Paris et le désert français »","« Zéro artificialisation nette »","« Action cœur de ville »","« La France d’en bas »"]'::jsonb, 0, 'Le titre du livre de Jean-François Gravier (1947) a inspiré le rééquilibrage volontariste des décennies suivantes.', 3),
    ('1fd927a6-ed1c-5079-8ad7-a1ee6d6b68ca'::uuid, 'histoire-geo', 'Tle', 'Les recompositions territoriales en France', 'Que reproche-t-on à la fusion des régions de 2015-2016 ?', 'mcq', '["D’avoir créé trop de régions","Des ensembles très vastes et des centres de décision éloignés","D’avoir supprimé les départements","D’avoir augmenté le nombre de communes"]'::jsonb, 1, 'Identités mal reconnues et éloignement des décisions nourrissent la contestation.', 4),
    ('4fd6a6dc-0ac2-50a5-81b5-7bb92ced1323'::uuid, 'histoire-geo', 'Tle', 'L’intégration de la France en Europe et dans le monde', 'Quel est le premier partenaire commercial de la France ?', 'mcq', '["Les États-Unis","La Chine","Le Royaume-Uni","L’Allemagne"]'::jsonb, 3, 'L’Allemagne est de très loin le premier partenaire : 60 % du commerce extérieur français se fait dans l’UE.', 1),
    ('ab977838-ac0f-5a37-8523-d7d420d5970f'::uuid, 'histoire-geo', 'Tle', 'L’intégration de la France en Europe et dans le monde', 'De quelle communauté la France est-elle membre fondateur dès 1951 ?', 'mcq', '["La CECA","L’OTAN","La CED","L’AELE"]'::jsonb, 0, 'La CECA (1951) précède la CEE (1957) : la France est fondatrice des deux.', 2),
    ('97707c8d-8fdd-57cc-8fdb-c90f4c37aa9e'::uuid, 'histoire-geo', 'Tle', 'L’intégration de la France en Europe et dans le monde', 'Quelle interface est une liaison fixe ?', 'mcq', '["Roissy-CDG","Le port du Havre","Le tunnel sous la Manche","La gare de Lille-Europe"]'::jsonb, 2, 'Le tunnel relie la France au Royaume-Uni ; Roissy est un hub aérien, Le Havre un port, Lille-Europe une gare LGV.', 3),
    ('1709b57b-f64f-50de-8c5d-df2399d4072e'::uuid, 'histoire-geo', 'Tle', 'L’intégration de la France en Europe et dans le monde', 'Qu’a révélé la période ouverte en 2020 sur l’intégration française ?', 'mcq', '["L’autonomie totale de l’industrie française","Une dépendance à des chaînes extérieures pour l’électronique et les médicaments","La fin du déficit commercial","La disparition des échanges européens"]'::jsonb, 1, 'La pandémie a montré que certaines productions essentielles dépendent de fournisseurs lointains.', 4),
    ('5e86c3e9-dddd-54ac-a59f-bc67b68b2b5f'::uuid, 'histoire-geo', 'Tle', 'La région Occitanie, entre attractivité, concurrence et inégalité', 'Combien d’habitants compte l’Occitanie ?', 'mcq', '["Environ 12 millions","Environ 2 millions","Environ 6 millions","Environ 9 millions"]'::jsonb, 2, 'Environ 6 millions d’habitants, et de l’ordre de 50 000 de plus chaque année.', 1),
    ('5d04f593-098f-51d5-afc6-8afc11783dd2'::uuid, 'histoire-geo', 'Tle', 'La région Occitanie, entre attractivité, concurrence et inégalité', 'Combien de départements compte l’Occitanie ?', 'mcq', '["13","5","8","22"]'::jsonb, 0, 'Treize départements, des Pyrénées au Massif central et de la Méditerranée à la Garonne.', 2),
    ('e1888ab2-6193-5f14-b0bb-0137144d39f8'::uuid, 'histoire-geo', 'Tle', 'La région Occitanie, entre attractivité, concurrence et inégalité', 'Quel organisme spatial est implanté à Toulouse ?', 'mcq', '["L’Ifremer","Météo-France","Le CEA","Le CNES"]'::jsonb, 3, 'Avec Airbus et ses sous-traitants, le CNES fait de Toulouse le premier pôle industriel de la région.', 3),
    ('38fa5074-abf8-5225-9868-592eff57b299'::uuid, 'histoire-geo', 'Tle', 'La région Occitanie, entre attractivité, concurrence et inégalité', 'Quel équipement de transport la région attend-elle de longue date ?', 'mcq', '["Un aéroport international","La LGV vers Toulouse","Un port en eau profonde","Un tunnel sous les Pyrénées"]'::jsonb, 1, 'Les liaisons ferroviaires restent lentes, notamment d’est en ouest : l’accessibilité reste une faiblesse.', 4),
    ('9a8529bc-7caa-5979-ba6d-618056279f06'::uuid, 'hggsp', 'Tle', 'Les spécificités de l’espace et des océans', 'Quelle part de la surface du globe les océans couvrent-ils ?', 'mcq', '["Environ 50 %","Environ 60 %","Environ 71 %","Environ 85 %"]'::jsonb, 2, 'Les océans couvrent 71 % du globe et abritent l’essentiel de la biodiversité, mais moins d’un quart de leurs fonds est cartographié avec précision.', 1),
    ('5093c023-4d9b-50ea-a4ef-c7032ea56ffb'::uuid, 'hggsp', 'Tle', 'Les spécificités de l’espace et des océans', 'À quelle altitude se trouve l’orbite géostationnaire, la plus convoitée ?', 'mcq', '["400 km","2 000 km","100 km","36 000 km"]'::jsonb, 3, 'À 36 000 km, un satellite tourne à la vitesse de la Terre et reste au-dessus du même point : les places y sont rares, donc disputées.', 2),
    ('6b7f7eae-db96-5cdf-ab1b-69e847835245'::uuid, 'hggsp', 'Tle', 'Les spécificités de l’espace et des océans', 'Quelle institution gère les grands fonds marins, « patrimoine commun de l’humanité » ?', 'mcq', '["L’Autorité internationale des fonds marins","L’Organisation maritime internationale","L’UNESCO","La Cour permanente d’arbitrage"]'::jsonb, 0, 'Au-delà des zones nationales, les grands fonds relèvent de l’Autorité internationale des fonds marins, qui encadre leur exploitation.', 3),
    ('1a59cf61-4492-5c4a-95b3-6514b985bbeb'::uuid, 'hggsp', 'Tle', 'Les spécificités de l’espace et des océans', 'Quel organisme attribue les fréquences radio utilisées par les satellites ?', 'mcq', '["L’Agence spatiale européenne","L’Union internationale des télécommunications","La NASA","L’ICANN"]'::jsonb, 1, 'Les fréquences sont une ressource rare de l’espace : l’Union internationale des télécommunications les répartit entre les États.', 4),
    ('523fe3b7-2154-526b-af99-264f6c51796c'::uuid, 'hggsp', 'Tle', 'Les enjeux géopolitiques de la conquête spatiale', 'D’où viennent les premières fusées des deux Grands ?', 'mcq', '["Des lanceurs britanniques","Des fusées françaises","Des V2 allemands récupérés en 1945","Des missiles japonais"]'::jsonb, 2, 'Américains et Soviétiques récupèrent en 1945 les ingénieurs et les plans des V2 allemands : la conquête spatiale naît d’une arme.', 1),
    ('4663d189-8dab-5be0-a837-99b972f32153'::uuid, 'hggsp', 'Tle', 'Les enjeux géopolitiques de la conquête spatiale', 'Qui devient en 1961 le premier homme dans l’espace ?', 'mcq', '["Neil Armstrong","Iouri Gagarine","John Glenn","Buzz Aldrin"]'::jsonb, 1, 'Gagarine, en 1961, offre à l’URSS un deuxième succès après Spoutnik (1957) ; les États-Unis répondent par le programme lunaire.', 2),
    ('7afa8f06-9efd-5a8e-8062-b6088ec7d223'::uuid, 'hggsp', 'Tle', 'Les enjeux géopolitiques de la conquête spatiale', 'Quel pays réussit en 2023 un alunissage près du pôle Sud de la Lune ?', 'mcq', '["L’Inde","La Chine","Le Japon","Israël"]'::jsonb, 0, 'L’alunissage indien près du pôle Sud, en 2023, montre que la rivalité spatiale n’est plus un duel mais une compétition à plusieurs puissances.', 3),
    ('4cb208ff-1845-5f41-aa59-f1a010c6a4be'::uuid, 'hggsp', 'Tle', 'Les enjeux géopolitiques de la conquête spatiale', 'Comment s’appelle le programme américain de retour sur la Lune ?', 'mcq', '["Gemini","Mercury","Skylab","Artemis"]'::jsonb, 3, 'Artemis marque le retour de la rivalité lunaire, face à la Chine ; les États-Unis se sont aussi dotés d’une Space Force en 2019.', 4),
    ('2c143ac5-46bc-5161-b908-67820407eaca'::uuid, 'hggsp', 'Tle', 'L’affirmation de la puissance des États à partir des espaces maritimes', 'À qui attribue-t-on la formule « Qui tient la mer tient le commerce du monde » ?', 'mcq', '["Alfred Mahan","Napoléon","Walter Raleigh","Francis Drake"]'::jsonb, 2, 'La formule attribuée à Walter Raleigh résume une idée toujours actuelle : la maîtrise des mers est un attribut de puissance.', 1),
    ('12be9d60-f401-53f1-a8fd-1c3db247ea99'::uuid, 'hggsp', 'Tle', 'L’affirmation de la puissance des États à partir des espaces maritimes', 'Combien de porte-avions compte la marine américaine ?', 'mcq', '["Onze","Trois","Vingt-cinq","Six"]'::jsonb, 0, 'Onze porte-avions et des bases sur toutes les mers font des États-Unis la seule puissance maritime vraiment globale.', 2),
    ('09f9bd3b-b3ff-5f99-8d60-b40356f73304'::uuid, 'hggsp', 'Tle', 'L’affirmation de la puissance des États à partir des espaces maritimes', 'Quels États revendiquent l’extension de leur plateau continental en Arctique ?', 'mcq', '["La Chine, le Japon et l’Inde","Le Brésil, l’Argentine et le Chili","La France, l’Italie et l’Espagne","La Russie, le Canada et le Danemark"]'::jsonb, 3, 'La fonte de la banquise ouvre des routes et des gisements : les États riverains cherchent à étendre leurs droits sur les fonds.', 3),
    ('76cb728c-7498-537c-9c4c-2577668ad5d2'::uuid, 'hggsp', 'Tle', 'L’affirmation de la puissance des États à partir des espaces maritimes', 'Qu’est-ce qui donne à la France une voix dans l’Indo-Pacifique ?', 'mcq', '["Sa flotte de commerce, la première du monde","Ses outre-mer, qui ouvrent chacun une ZEE","Le contrôle du détroit de Malacca","Un mandat de l’ONU sur la région"]'::jsonb, 1, 'Polynésie, Nouvelle-Calédonie, la Réunion, Clipperton… Ses territoires donnent à la France une ZEE et une présence qu’aucun autre pays européen ne possède.', 4),
    ('a264e265-2b8a-5508-b373-7bc2c40440ed'::uuid, 'hggsp', 'Tle', 'La Chine à la conquête de l’espace, des mers et des océans', 'Qu’appelle-t-on le « siècle des humiliations » ?', 'mcq', '["La Révolution culturelle","La période où la Chine a été forcée d’ouvrir ses ports aux puissances étrangères","La famine du Grand Bond en avant","L’occupation soviétique de la Mandchourie"]'::jsonb, 1, 'Le rêve chinois veut effacer ce souvenir : devenir puissante sur mer, c’est ne plus jamais subir l’ouverture forcée des ports.', 1),
    ('4a442b20-27f5-5e19-9ea6-b51bd8b97096'::uuid, 'hggsp', 'Tle', 'La Chine à la conquête de l’espace, des mers et des océans', 'Quelle mission chinoise ramène des échantillons lunaires en 2020 ?', 'mcq', '["Tianwen 1","Shenzhou 5","Chang’e 5","Beidou 3"]'::jsonb, 2, 'Chang’e 5 rapporte des échantillons de la Lune en 2020, un an après la sonde posée sur la face cachée.', 2),
    ('59ccf693-9cf4-5095-a661-be5f1ab71720'::uuid, 'hggsp', 'Tle', 'La Chine à la conquête de l’espace, des mers et des océans', 'En quelle année la Chine pose-t-elle un rover sur Mars ?', 'mcq', '["2003","2013","2019","2021"]'::jsonb, 3, 'En 2021, la Chine pose un rover sur Mars ; fin 2022, sa station Tiangong est occupée en permanence : elle dispose d’une chaîne spatiale complète.', 3),
    ('3ef8b1ea-3bd1-504a-b80c-865965f379c1'::uuid, 'hggsp', 'Tle', 'La Chine à la conquête de l’espace, des mers et des océans', 'Combien des dix premiers ports à conteneurs du monde sont chinois ?', 'mcq', '["Sept","Deux","Quatre","Dix"]'::jsonb, 0, 'Shanghai, Ningbo, Shenzhen… Sept des dix premiers ports à conteneurs sont chinois : la puissance maritime passe aussi par le commerce.', 4),
    ('273716db-5c52-5633-bd36-d70d30ac3ffa'::uuid, 'hggsp', 'Tle', 'Conflits et tentatives de paix dans le monde contemporain', 'Dans le modèle « trinitaire » classique, comment une guerre se termine-t-elle ?', 'mcq', '["Par un simple cessez-le-feu","Par une résolution de l’ONU","Par un traité","Par la disparition d’un des États"]'::jsonb, 2, 'Le modèle classique suppose des États, des armées régulières, une déclaration au début et un traité à la fin — ce que les conflits récents n’ont plus.', 1),
    ('78c9fe41-10df-5147-9fa9-64cab7669e8f'::uuid, 'hggsp', 'Tle', 'Conflits et tentatives de paix dans le monde contemporain', 'Qui parle de « nouvelles guerres » pour qualifier les conflits récents ?', 'mcq', '["Johan Galtung","Mary Kaldor","Clausewitz","Kant"]'::jsonb, 1, 'Mary Kaldor désigne ainsi des guerres intra-étatiques, non déclarées, asymétriques, dont les civils sont les premières victimes.', 2),
    ('e867237d-d98e-542d-8f00-34ea7e2dfb67'::uuid, 'hggsp', 'Tle', 'Conflits et tentatives de paix dans le monde contemporain', 'Lequel de ces conflits est un exemple de conflit gelé ?', 'mcq', '["La guerre du Golfe de 1991","La guerre de Trente Ans","La guerre des Six Jours","Le Cachemire"]'::jsonb, 3, 'Au Cachemire, comme à Chypre ou en Corée, les armes se sont tues mais le différend n’est pas réglé : une paix négative qui dure.', 3),
    ('252f82f7-6311-5f04-b76c-221b582ac6b1'::uuid, 'hggsp', 'Tle', 'Conflits et tentatives de paix dans le monde contemporain', 'Quel rôle jouent les ONG et les médiateurs privés dans la paix ?', 'mcq', '["Garder le contact quand les États ne se parlent plus","Autoriser le recours à la force","Déployer les Casques bleus","Juger les criminels de guerre"]'::jsonb, 0, 'Quand la diplomatie officielle est bloquée, ces acteurs maintiennent un canal de discussion entre les belligérants.', 4),
    ('a8d01157-0c3e-55a6-9701-40d3f9328eaa'::uuid, 'hggsp', 'Tle', 'De la guerre entre États à de nouvelles formes de conflits', 'Quelle innovation de la Révolution et de l’Empire ouvre l’âge de la guerre totale ?', 'mcq', '["Le bombardement stratégique","La guerre sous-marine","La levée en masse","Les chars d’assaut"]'::jsonb, 2, 'La levée en masse mobilise la nation entière ; les guerres mondiales y ajouteront l’industrie, puis le bombardement des villes.', 1),
    ('ef3a73f3-44cc-514c-b095-12df38dfa9a1'::uuid, 'hggsp', 'Tle', 'De la guerre entre États à de nouvelles formes de conflits', 'Quel pays subit en 2007 une vague de cyberattaques restée emblématique ?', 'mcq', '["La Finlande","La Géorgie","La Pologne","L’Estonie"]'::jsonb, 3, 'L’Estonie, paralysée en 2007, montre qu’un État peut être attaqué sans un seul coup de feu : c’est la cyberconflictualité.', 2),
    ('f5a0461f-c65c-54ba-b348-ec751c89c596'::uuid, 'hggsp', 'Tle', 'De la guerre entre États à de nouvelles formes de conflits', 'Quel événement de 2014 illustre la guerre hybride ?', 'mcq', '["L’annexion de la Crimée","L’invasion de l’Irak","L’intervention au Mali","La guerre des Malouines"]'::jsonb, 0, 'En Crimée, soldats sans insignes, milices et désinformation remplacent la déclaration de guerre : c’est le propre de la guerre hybride.', 3),
    ('6f60a351-ac6d-55e1-bc90-7e3d499fb323'::uuid, 'hggsp', 'Tle', 'De la guerre entre États à de nouvelles formes de conflits', 'Quel mot décrit le mieux la place actuelle de la guerre classique face aux nouveaux conflits ?', 'mcq', '["Disparition","Superposition","Remplacement","Oubli"]'::jsonb, 1, 'L’invasion de l’Ukraine en 2022 montre que la guerre de haute intensité coexiste avec les drones et la guerre informationnelle.', 4),
    ('68736dbe-b034-5622-8a9a-b63cfea3d50c'::uuid, 'hggsp', 'Tle', 'Construire la paix par la diplomatie', 'Quelle limite majeure présente le congrès de Vienne ?', 'mcq', '["Il ignore les nationalités","Il exclut la France des négociations","Il crée une armée européenne","Il ne tient que cinq ans"]'::jsonb, 0, 'Le congrès stabilise l’Europe pendant un demi-siècle, mais il nie les aspirations nationales, qui feront éclater les crises suivantes.', 1),
    ('a2c6f07e-a86e-5715-9960-68b1af42a058'::uuid, 'hggsp', 'Tle', 'Construire la paix par la diplomatie', 'Quelle invasion de 1935 démontre publiquement l’impuissance de la SDN ?', 'mcq', '["L’annexion de l’Autriche","L’invasion de l’Éthiopie par l’Italie","L’invasion de la Pologne","L’occupation de la Ruhr"]'::jsonb, 1, 'Face à l’invasion de l’Éthiopie, la SDN, sans armée ni sanction crédible, se montre incapable de défendre un de ses membres.', 2),
    ('753616b5-4d38-59b2-8bfd-9d2b0026c1f7'::uuid, 'hggsp', 'Tle', 'Construire la paix par la diplomatie', 'Quelle règle de vote paralyse la SDN ?', 'mcq', '["La majorité simple","La majorité des deux tiers","Le tirage au sort","L’unanimité"]'::jsonb, 3, 'Exiger l’accord de tous revient à donner un veto à chacun : la SDN ne peut presque jamais décider.', 3),
    ('1cd744cb-d980-5dc1-aea1-23ef65feaba5'::uuid, 'hggsp', 'Tle', 'Construire la paix par la diplomatie', 'Quelle différence sépare la Cour internationale de justice de la Cour pénale internationale ?', 'mcq', '["La CIJ juge les individus, la CPI les États","Les deux ne jugent que les États","La CIJ juge les États, la CPI les individus","La CIJ est une juridiction européenne"]'::jsonb, 2, 'La CIJ (1945) tranche les différends entre États consentants ; la CPI (2002) juge des personnes pour génocide, crimes de guerre et crimes contre l’humanité.', 4),
    ('ffef2034-d8dc-5a4b-bbf6-5fe3cf7989a8'::uuid, 'hggsp', 'Tle', 'Guerres et paix au Moyen-Orient', 'En quelle année l’ONU adopte-t-elle un plan de partage de la Palestine ?', 'mcq', '["1917","1947","1956","1967"]'::jsonb, 1, 'Le plan de partage de 1947 précède la création d’Israël en 1948 et la première guerre israélo-arabe.', 1),
    ('9388d862-3646-5b07-9b6b-70ff7f2a0f93'::uuid, 'hggsp', 'Tle', 'Guerres et paix au Moyen-Orient', 'Quelle guerre de 1973 oppose Israël à ses voisins arabes ?', 'mcq', '["La guerre des Six Jours","La guerre de Suez","La première Intifada","La guerre du Kippour"]'::jsonb, 3, 'La guerre du Kippour, en 1973, suit de six ans la guerre des Six Jours (1967) qui avait conduit Israël à occuper plusieurs territoires.', 2),
    ('348e0765-96af-57fb-9dbe-25339d06a19f'::uuid, 'hggsp', 'Tle', 'Guerres et paix au Moyen-Orient', 'À partir de quand la Russie revient-elle au Moyen-Orient par la Syrie ?', 'mcq', '["1991","2003","2015","2022"]'::jsonb, 2, 'En intervenant en Syrie en 2015, la Russie redevient un acteur majeur de la région, longtemps dominée par les États-Unis.', 3),
    ('b5fe6c8b-8861-5e87-a4b8-ae3f8c85434c'::uuid, 'hggsp', 'Tle', 'Guerres et paix au Moyen-Orient', 'Qu’est-ce qui enraye le processus d’Oslo ?', 'mcq', '["La colonisation et la seconde Intifada","La guerre Iran-Irak","La chute de l’URSS","La création de l’OPEP"]'::jsonb, 0, 'Colonisation et violences bloquent durablement le processus : la tentative de paix la plus aboutie débouche sur un échec.', 4),
    ('27c76ee3-fa69-53dc-af78-feab3f1fc7cf'::uuid, 'hggsp', 'Tle', 'Histoire et mémoires : l’exemple de la guerre d’Algérie', 'Comment la France désigne-t-elle officiellement le conflit pendant qu’il se déroule ?', 'mcq', '["La guerre d’indépendance","Les « événements »","La révolution algérienne","La guerre coloniale"]'::jsonb, 1, 'De 1954 à 1962, on parle d’« événements » et d’« opérations de maintien de l’ordre » : ne pas nommer la guerre est déjà un choix politique.', 1),
    ('aebb037e-ca24-5020-b92d-729458e0584f'::uuid, 'hggsp', 'Tle', 'Histoire et mémoires : l’exemple de la guerre d’Algérie', 'Quel nom est associé aux révélations de 2000 sur la torture en Algérie ?', 'mcq', '["Salan","Mendès France","Aussaresses","Mollet"]'::jsonb, 2, 'Les aveux du général Aussaresses, en 2000, relancent le débat public ; l’ouverture des archives permet aux historiens d’établir les faits.', 2),
    ('4e232d02-a8ab-50f2-9701-f0c281084c8c'::uuid, 'hggsp', 'Tle', 'Histoire et mémoires : l’exemple de la guerre d’Algérie', 'Que propose le rapport remis par Benjamin Stora en 2021 ?', 'mcq', '["La fermeture des archives","Des réparations financières","Une loi mémorielle unique","Des gestes de réconciliation mémorielle"]'::jsonb, 3, 'Le rapport Stora ne prétend pas écrire une histoire officielle : il propose des gestes pour apaiser des mémoires concurrentes.', 3),
    ('750e67f8-501d-533a-848d-2aae3bf67c48'::uuid, 'hggsp', 'Tle', 'Histoire et mémoires : l’exemple de la guerre d’Algérie', 'Quelle mémoire portent les pieds-noirs rapatriés en 1962 ?', 'mcq', '["Une mémoire de l’arrachement","Une mémoire d’État centrée sur le FLN","La mémoire de la répression du 17 octobre 1961","La mémoire des supplétifs abandonnés"]'::jsonb, 0, 'Chaque groupe garde son souvenir : arrachement pour les pieds-noirs, abandon pour les harkis, répression pour les immigrés algériens.', 4),
    ('49dcb134-3f26-5dfa-a5ac-2161d04e59c2'::uuid, 'hggsp', 'Tle', 'Les responsabilités des États dans le déclenchement de la Première Guerre mondiale', 'Comment l’historien Christopher Clark qualifie-t-il les dirigeants de 1914 ?', 'mcq', '["Des « criminels »","Des « bellicistes »","Des « somnambules »","Des « apprentis sorciers »"]'::jsonb, 2, 'Pour Clark, les dirigeants avancent vers la guerre sans en mesurer les conséquences : la responsabilité devient partagée.', 1),
    ('1ca76f02-77ec-5318-a3b0-81afa73c604a'::uuid, 'hggsp', 'Tle', 'Les responsabilités des États dans le déclenchement de la Première Guerre mondiale', 'Que justifie la « clause de culpabilité » de l’article 231 ?', 'mcq', '["Les réparations","La création de la SDN","Le partage de l’Empire ottoman","Le retour de l’Alsace-Moselle"]'::jsonb, 0, 'Si l’Allemagne est responsable, elle doit payer : la clause fonde juridiquement les réparations exigées par les vainqueurs.', 2),
    ('18e0b05f-1957-5c90-9e08-72ee4b6eb3f7'::uuid, 'hggsp', 'Tle', 'Les responsabilités des États dans le déclenchement de la Première Guerre mondiale', 'Pourquoi la thèse de Fritz Fischer fait-elle scandale en 1961 ?', 'mcq', '["Elle accuse la France d’avoir voulu la guerre","Un historien allemand accuse l’Allemagne, archives à l’appui","Elle nie toute responsabilité allemande","Elle repose sur des documents falsifiés"]'::jsonb, 1, 'Ce n’est plus le vainqueur qui accuse : la question de la responsabilité est rouverte de l’intérieur même de l’Allemagne.', 3),
    ('2b6ffc90-5429-532f-8ead-47a9a30dbc80'::uuid, 'hggsp', 'Tle', 'Les responsabilités des États dans le déclenchement de la Première Guerre mondiale', 'Selon les lectures actuelles, quel facteur explique le consentement des opinions en 1914 ?', 'mcq', '["Les plans de mobilisation","La course aux armements","L’article 231","Les nationalismes"]'::jsonb, 3, 'Les nationalismes font accepter la guerre aux populations ; les alliances l’étendent, les plans rigides l’accélèrent.', 4),
    ('b3757bf0-2149-5460-9894-8f6f5cd3ae21'::uuid, 'hggsp', 'Tle', 'Juger un crime de masse à l’échelle locale et internationale : les exemples du Rwanda et des Balkans', 'Combien de morts fait le génocide des Tutsi, en cent jours ?', 'mcq', '["Environ 80 000","Environ 800 000","Environ 2 millions","Environ 8 000"]'::jsonb, 1, 'En cent jours de 1994, environ 800 000 personnes sont tuées, sans que la communauté internationale intervienne.', 1),
    ('26fabd68-4657-5d84-b745-3b37b4ece6f5'::uuid, 'hggsp', 'Tle', 'Juger un crime de masse à l’échelle locale et internationale : les exemples du Rwanda et des Balkans', 'Quel dirigeant serbe meurt avant le verdict du TPIY ?', 'mcq', '["Radovan Karadžić","Ratko Mladić","Slobodan Milošević","Ante Gotovina"]'::jsonb, 2, 'Milošević meurt en détention avant d’être jugé ; Karadžić et Mladić, eux, sont condamnés à la perpétuité.', 2),
    ('fef33f17-724d-5e36-b2ae-1e62e709e385'::uuid, 'hggsp', 'Tle', 'Juger un crime de masse à l’échelle locale et internationale : les exemples du Rwanda et des Balkans', 'Combien de dossiers les gacaca ont-elles jugés entre 2002 et 2012 ?', 'mcq', '["Environ 10 000","Environ 100 000","Près de dix millions","Près de deux millions"]'::jsonb, 3, 'Face à plus de cent mille détenus, les gacaca traitent la masse des dossiers, au prix de garanties procédurales insuffisantes.', 3),
    ('3934a018-25a0-5c05-9107-665821c24258'::uuid, 'hggsp', 'Tle', 'Juger un crime de masse à l’échelle locale et internationale : les exemples du Rwanda et des Balkans', 'Comment s’appellent les milices qui participent au génocide des Tutsi ?', 'mcq', '["Les interahamwe","Les gacaca","Les Casques bleus","Les harkis"]'::jsonb, 0, 'Planifié par le pouvoir hutu, le génocide est exécuté par l’armée, les milices interahamwe et une partie de la population.', 4),
    ('3bd6f681-9f4c-53be-bda6-f618c0134754'::uuid, 'hggsp', 'Tle', 'L’histoire et les mémoires du génocide des Juifs et des Tsiganes', 'Combien de Tsiganes ont été victimes du Porajmos selon les estimations ?', 'mcq', '["Entre 20 000 et 50 000","Entre 200 000 et 500 000","Environ deux millions","Environ six millions"]'::jsonb, 1, 'Internés, déportés, exécutés : entre 200 000 et 500 000 Tsiganes sont tués ; la France reconnaît ce génocide en 2016.', 1),
    ('db7c2b72-519f-51aa-b9d5-6113987860e1'::uuid, 'hggsp', 'Tle', 'L’histoire et les mémoires du génocide des Juifs et des Tsiganes', 'Quel film de 1971 fissure le récit rassurant d’une France résistante ?', 'mcq', '["Shoah","Nuit et brouillard","Le Chagrin et la Pitié","La Liste de Schindler"]'::jsonb, 2, 'Le Chagrin et la Pitié montre une société française faite d’attentisme et de collaboration, loin du mythe résistancialiste.', 2),
    ('670e70b0-27e0-5dcb-8f87-0b005bd27be8'::uuid, 'hggsp', 'Tle', 'L’histoire et les mémoires du génocide des Juifs et des Tsiganes', 'En quelle année les crimes contre l’humanité sont-ils déclarés imprescriptibles en France ?', 'mcq', '["1964","1945","1987","1995"]'::jsonb, 0, 'L’imprescriptibilité, votée en 1964, rend possibles les procès tardifs de Barbie (1987), Touvier (1994) et Papon (1998).', 3),
    ('71e72f2b-74a0-54d3-9587-ecc1b8c858c8'::uuid, 'hggsp', 'Tle', 'L’histoire et les mémoires du génocide des Juifs et des Tsiganes', 'Quel risque nouveau le « devoir de mémoire » fait-il apparaître ?', 'mcq', '["L’oubli total","L’ouverture des archives","La fin des procès","La commémoration sans connaissance"]'::jsonb, 3, 'Le danger n’est plus le silence mais un rituel vidé de savoir : se souvenir suppose de connaître les faits.', 4),
    ('1aaddc2c-a58c-5f38-bafe-7a00ec05b9e4'::uuid, 'hggsp', 'Tle', 'Du patrimoine individuel au patrimoine mondial', 'Que signifie le mot latin patrimonium ?', 'mcq', '["Le monument de la cité","Le trésor du temple","Le bien hérité du père","La terre des ancêtres"]'::jsonb, 2, 'D’abord bien privé transmis en famille, le patrimoine devient l’héritage d’une nation, puis celui de l’humanité.', 1),
    ('2de7bd66-ff90-5df2-93a2-8e916395cca0'::uuid, 'hggsp', 'Tle', 'Du patrimoine individuel au patrimoine mondial', 'Quel critère permet d’inscrire un site sur la liste du patrimoine mondial ?', 'mcq', '["Une « valeur universelle exceptionnelle »","Une ancienneté de plus de mille ans","Une forte fréquentation touristique","L’appartenance à un État fondateur de l’UNESCO"]'::jsonb, 0, 'Plus de 1 200 biens sont inscrits pour leur « valeur universelle exceptionnelle » : ils n’appartiennent plus seulement à l’État qui les abrite.', 2),
    ('b8e8b1e4-fe13-5cac-a627-4a0614525883'::uuid, 'hggsp', 'Tle', 'Du patrimoine individuel au patrimoine mondial', 'Quelle part des inscriptions au patrimoine mondial revient à l’Afrique ?', 'mcq', '["Près de la moitié","Moins d’un dixième","Environ un quart","Environ un tiers"]'::jsonb, 1, 'L’Europe détient près de la moitié des inscriptions : la liste reflète aussi les capacités administratives et diplomatiques des États.', 3),
    ('0ff1bc4a-9a28-579e-8cea-530289056315'::uuid, 'hggsp', 'Tle', 'Du patrimoine individuel au patrimoine mondial', 'Quel type de patrimoine regroupe mines, usines et cités ouvrières ?', 'mcq', '["Le patrimoine immatériel","Le patrimoine rural","Le patrimoine maritime","Le patrimoine industriel"]'::jsonb, 3, 'Le patrimoine s’est élargi : industriel, rural, du XXe siècle, puis immatériel depuis 2003.', 4),
    ('f484241d-a266-598d-87b7-17330727b2f5'::uuid, 'hggsp', 'Tle', 'Les usages sociaux et politiques du patrimoine', 'Quel pont est détruit en 1993 pendant la guerre de Bosnie ?', 'mcq', '["Le pont de Remagen","Le pont de Mostar","Le pont d’Avignon","Le pont Charles"]'::jsonb, 1, 'Détruire le pont de Mostar, symbole d’une ville mêlée, c’est nier l’existence de l’autre : destruction patrimoniale et nettoyage ethnique vont ensemble.', 1),
    ('39c77f44-f247-5d80-bbd7-d7af0a0b2806'::uuid, 'hggsp', 'Tle', 'Les usages sociaux et politiques du patrimoine', 'Quel site antique syrien est détruit en 2015 ?', 'mcq', '["Pétra","Babylone","Palmyre","Persépolis"]'::jsonb, 2, 'Après les bouddhas de Bamiyan (2001), la destruction de Palmyre (2015) montre le patrimoine utilisé comme cible politique.', 2),
    ('fd2c45da-e492-589d-acd0-5a90383e0cbc'::uuid, 'hggsp', 'Tle', 'Les usages sociaux et politiques du patrimoine', 'À quel pays la France restitue-t-elle des objets en 2021 ?', 'mcq', '["L’Égypte","Le Maroc","Le Vietnam","Le Bénin"]'::jsonb, 3, 'Ces restitutions suivent le rapport Sarr-Savoy (2018) : le patrimoine engage des rapports de domination hérités de la colonisation.', 3),
    ('a57b3e52-910d-5689-907f-9d7d2060a407'::uuid, 'hggsp', 'Tle', 'Les usages sociaux et politiques du patrimoine', 'Quel monument français est un exemple de patrimoine au service du récit national ?', 'mcq', '["Le Panthéon","La tour Eiffel","Le château de Chambord","Le pont du Gard"]'::jsonb, 0, 'Le Panthéon accueille les « grands hommes » choisis par la nation : il dit ce qu’un pays veut honorer et transmettre.', 4),
    ('866e15d9-c357-5195-99f5-8b0c0018fa5e'::uuid, 'hggsp', 'Tle', 'La préservation du patrimoine', 'Que demande la charte de Venise (1964) pour toute intervention nouvelle sur un monument ?', 'mcq', '["Qu’elle imite le style d’origine","Qu’elle soit visible","Qu’elle soit invisible","Qu’elle utilise des matériaux modernes"]'::jsonb, 1, 'La charte tranche entre Viollet-le-Duc et Ruskin : respecter l’authenticité des matériaux et ne jamais faire passer un ajout pour d’origine.', 1),
    ('999dc738-6dac-5c95-8310-ff15fb144aab'::uuid, 'hggsp', 'Tle', 'La préservation du patrimoine', 'Quelle ville a été retirée de la liste du patrimoine mondial en 2021 ?', 'mcq', '["Venise","Dresde","Liverpool","Bath"]'::jsonb, 2, 'Liverpool en 2021, après Dresde en 2009 : l’inscription n’est pas définitive, la sanction existe.', 2),
    ('07424a6b-5030-5e99-9e2d-5bc73bd1148f'::uuid, 'hggsp', 'Tle', 'La préservation du patrimoine', 'Quel site Viollet-le-Duc a-t-il restauré ?', 'mcq', '["Versailles","Le pont du Gard","Le château de Chambord","Carcassonne"]'::jsonb, 3, 'À Carcassonne, Viollet-le-Duc rend à la cité un état complet « qui peut n’avoir jamais existé » : c’est sa doctrine.', 3),
    ('e9259fcc-aa5a-5c6c-87f1-7c69a7a9fb2a'::uuid, 'hggsp', 'Tle', 'La préservation du patrimoine', 'Pourquoi la préservation du patrimoine est-elle aussi un enjeu de sécurité ?', 'mcq', '["Le trafic illicite d’antiquités finance des groupes armés","Les monuments servent de bases militaires","L’UNESCO dispose d’une armée","Les sites classés sont fermés au public"]'::jsonb, 0, 'Le pillage des sites alimente un trafic qui arme des groupes : protéger le patrimoine, c’est aussi couper une source de financement.', 4),
    ('83e7b4b5-606e-5ff1-82d6-5f71d074021d'::uuid, 'hggsp', 'Tle', 'La France et le patrimoine', 'Combien d’immeubles sont protégés en France au titre des monuments historiques ?', 'mcq', '["Environ 4 500","Plus de 45 000","Plus de 450 000","Environ 1 200"]'::jsonb, 1, 'Plus de 45 000 immeubles protégés : la France est l’un des pays où l’État prend le plus en charge le patrimoine.', 1),
    ('1ceac528-bad7-59e9-85fb-23c4ef70a007'::uuid, 'hggsp', 'Tle', 'La France et le patrimoine', 'Avec quel pays la France a-t-elle créé le fonds ALIPH en 2017 ?', 'mcq', '["L’Arabie saoudite","Le Qatar","Les Émirats arabes unis","L’Égypte"]'::jsonb, 2, 'Le fonds ALIPH, créé avec les Émirats, protège le patrimoine en zone de conflit : un levier de la diplomatie patrimoniale française.', 2),
    ('724bb809-ad39-5578-be45-dde414715a3a'::uuid, 'hggsp', 'Tle', 'La France et le patrimoine', 'Lesquels de ces paysages culturels français sont inscrits au patrimoine mondial ?', 'mcq', '["La Beauce et la Brie","Les Landes et la Sologne","La Champagne pouilleuse et le Berry","Le Val de Loire et les Causses et Cévennes"]'::jsonb, 3, 'Le patrimoine ne se limite plus aux monuments : des paysages façonnés par les hommes sont aussi protégés.', 3),
    ('e5a84c55-72d0-5f68-83ed-90bbb12f5302'::uuid, 'hggsp', 'Tle', 'La France et le patrimoine', 'Quel débat oppose l’inaliénabilité des collections publiques à la réparation historique ?', 'mcq', '["Les restitutions aux anciennes colonies","L’entretien des églises rurales","L’isolation des bâtiments anciens","L’implantation des éoliennes"]'::jsonb, 0, 'Les collections publiques ne peuvent en principe être cédées : restituer suppose donc une loi, et oppose deux principes légitimes.', 4),
    ('428febcf-d95b-59fa-a394-3c4218516610'::uuid, 'hggsp', 'Tle', 'Qu’est-ce que l’environnement ?', 'Quel organisme est créé à la suite de la conférence de Stockholm de 1972 ?', 'mcq', '["Le PNUE","Le GIEC","L’IPBES","L’UNESCO"]'::jsonb, 0, 'Stockholm crée le Programme des Nations unies pour l’environnement : l’environnement devient un objet de coopération internationale.', 1),
    ('0d128e60-25e9-5843-ae15-9b492d31a131'::uuid, 'hggsp', 'Tle', 'Qu’est-ce que l’environnement ?', 'Selon le rapport Brundtland, le développement durable répond aux besoins du présent…', 'mcq', '["en limitant la croissance à zéro","sans compromettre la capacité des générations futures à répondre aux leurs","en priorité pour les pays du Sud","grâce au seul progrès technique"]'::jsonb, 1, 'La définition de 1987 introduit la solidarité entre générations : ce que nous consommons ne doit pas priver nos descendants.', 2),
    ('9baead57-edda-5527-b086-241066d2ac36'::uuid, 'hggsp', 'Tle', 'Qu’est-ce que l’environnement ?', 'Quelle date de départ de l’anthropocène fait peser la responsabilité d’abord sur les pays industrialisés ?', 'mcq', '["Le Néolithique","La « grande accélération » de 1950","La Révolution industrielle","La découverte de l’Amérique"]'::jsonb, 2, 'Choisir une date, c’est désigner des responsables : le débat sur l’anthropocène est aussi politique.', 3),
    ('42e62603-d3e9-5cbb-b33d-7f75e6e4066f'::uuid, 'hggsp', 'Tle', 'Qu’est-ce que l’environnement ?', 'Quelle conception de la nature est associée à la tradition occidentale issue de la Genèse ?', 'mcq', '["Une nature-milieu dont on fait partie","Une nature sacrée et intouchable","Une nature sans limites","Une nature à dominer"]'::jsonb, 3, 'D’autres cosmologies voient l’homme comme une partie du milieu : l’environnement est une construction culturelle, pas une évidence.', 4),
    ('6e8e7ced-6e38-5729-a771-9cb535917f76'::uuid, 'hggsp', 'Tle', 'Exploiter, préserver et protéger l’environnement', 'Quelle part des stocks de poissons est exploitée au-delà de son renouvellement ?', 'mcq', '["Un dixième","Un tiers","La moitié","Les trois quarts"]'::jsonb, 1, 'Un tiers des stocks est surexploité : une ressource renouvelable peut s’épuiser si on la prélève plus vite qu’elle ne se reconstitue.', 1),
    ('8f52f7aa-22b1-5cc9-bd14-56821537090a'::uuid, 'hggsp', 'Tle', 'Exploiter, préserver et protéger l’environnement', 'Pourquoi l’accord sur la couche d’ozone a-t-il fonctionné ?', 'mcq', '["Substances identifiées, alternatives disponibles, industriels peu nombreux","Tous les pays y étaient déjà en règle","Une taxe mondiale a été créée","Seuls les pays du Sud étaient concernés"]'::jsonb, 0, 'Le climat réunit rarement ces trois conditions : c’est pourquoi il est bien plus difficile à négocier que l’ozone.', 2),
    ('a5cfd336-f3ce-50a0-abd3-734e4f8f5dad'::uuid, 'hggsp', 'Tle', 'Exploiter, préserver et protéger l’environnement', 'Laquelle de ces ressources est non renouvelable ?', 'mcq', '["Les forêts","L’eau douce","Les poissons","Les minerais"]'::jsonb, 3, 'Pétrole, gaz et minerais ne se reconstituent pas à l’échelle humaine ; forêts, eau et poissons se renouvellent, mais peuvent être surexploités.', 3),
    ('debb2f86-3dda-5f16-ba7b-379dc2512613'::uuid, 'hggsp', 'Tle', 'Exploiter, préserver et protéger l’environnement', 'En quelle année est adoptée la convention sur la diversité biologique ?', 'mcq', '["1973","1987","1992","2022"]'::jsonb, 2, 'Adoptée en 1992, au sommet de Rio, elle vise la protection du vivant ; la CITES date de 1973, le protocole de Montréal de 1987.', 4),
    ('c6ecd84a-143b-547e-b7e5-678a6f87bb81'::uuid, 'hggsp', 'Tle', 'Le changement climatique : approches historique et géopolitique', 'Quel historien étudie le climat passé à partir des dates de vendanges ?', 'mcq', '["Fernand Braudel","Emmanuel Le Roy Ladurie","Marc Bloch","Georges Duby"]'::jsonb, 1, 'Vendanges, registres paroissiaux, glaciers : Le Roy Ladurie fait du climat un objet d’histoire.', 1),
    ('658074c7-2b05-5e87-be77-f0311f30f4e1'::uuid, 'hggsp', 'Tle', 'Le changement climatique : approches historique et géopolitique', 'Quel savant du XIXe siècle figure parmi les découvreurs de l’effet de serre ?', 'mcq', '["Keeling","Crutzen","Lavoisier","Arrhenius"]'::jsonb, 3, 'Fourier, Tyndall et Arrhenius établissent l’effet de serre au XIXe siècle, bien avant les mesures continues de CO₂.', 2),
    ('28c60d85-3f60-555f-be88-d5576d37c768'::uuid, 'hggsp', 'Tle', 'Le changement climatique : approches historique et géopolitique', 'Qui lance en 1958 la mesure continue du CO₂ atmosphérique à Mauna Loa ?', 'mcq', '["Svante Arrhenius","Paul Crutzen","Charles Keeling","Rachel Carson"]'::jsonb, 2, 'La « courbe de Keeling » montre, année après année, la hausse de la concentration de CO₂ dans l’atmosphère.', 3),
    ('0e9a69a0-36eb-5597-9c5f-1e49a89dfaab'::uuid, 'hggsp', 'Tle', 'Le changement climatique : approches historique et géopolitique', 'Quelle est la principale faiblesse de l’accord de Paris ?', 'mcq', '["Il repose sur des engagements volontaires","Il ne concerne que les pays développés","Il ne vise que le méthane","Il n’a été signé par aucun pays émergent"]'::jsonb, 0, 'Universel, l’accord de Paris l’est au prix de la contrainte : chaque État fixe lui-même ses objectifs.', 4),
    ('f57666cd-8380-5154-8006-17315b548a99'::uuid, 'hggsp', 'Tle', 'Les États-Unis et la question environnementale', 'Quel naturaliste est associé à la fondation du Sierra Club ?', 'mcq', '["Henry Thoreau","John Muir","Aldo Leopold","Al Gore"]'::jsonb, 1, 'John Muir, à la fin du XIXe siècle, défend une nature sauvage à préserver : c’est l’idée de wilderness.', 1),
    ('3887cd18-21d5-553e-9293-8b34de0c3e42'::uuid, 'hggsp', 'Tle', 'Les États-Unis et la question environnementale', 'Sous quel président l’EPA est-elle créée en 1970 ?', 'mcq', '["Kennedy","Johnson","Nixon","Carter"]'::jsonb, 2, 'L’EPA naît sous Nixon, l’année du premier Jour de la Terre, qui rassemble vingt millions d’Américains.', 2),
    ('13d5e051-a685-5ddd-8f67-41aa099874fe'::uuid, 'hggsp', 'Tle', 'Les États-Unis et la question environnementale', 'Quel rang occupent les États-Unis pour les émissions annuelles de CO₂ ?', 'mcq', '["Premier","Troisième, derrière la Chine et l’Inde","Cinquième","Deuxième, derrière la Chine"]'::jsonb, 3, 'Deuxièmes en émissions annuelles, ils restent premiers en émissions cumulées depuis 1850.', 3),
    ('72f8e35a-1694-59d4-8b5f-4648520a4bbf'::uuid, 'hggsp', 'Tle', 'Les États-Unis et la question environnementale', 'Quel État fédéré est connu pour ses normes environnementales propres ?', 'mcq', '["La Californie","Le Texas","L’Alaska","La Floride"]'::jsonb, 0, 'Grâce au fédéralisme, la Californie mène sa propre politique : le pays agit même quand Washington recule.', 4),
    ('14a0e379-357a-5934-a82d-a3fb183c8a8c'::uuid, 'hggsp', 'Tle', 'Vers une société de la connaissance', 'Quelle part des adultes du monde est alphabétisée ?', 'mcq', '["Environ 50 %","Environ 70 %","Plus de 86 %","Plus de 99 %"]'::jsonb, 2, 'L’alphabétisation dépasse 86 % des adultes, mais l’accès au savoir reste inégal : fracture numérique, sous-financement de la recherche au Sud.', 1),
    ('8943b70f-f305-5823-b79a-1194fc7dd421'::uuid, 'hggsp', 'Tle', 'Vers une société de la connaissance', 'Par combien le nombre d’étudiants dans le monde a-t-il été multiplié depuis 1970 ?', 'mcq', '["Par deux","Par plus de cinq","Par vingt","Par cent"]'::jsonb, 1, 'La massification de l’enseignement supérieur est réelle : le nombre d’étudiants a été multiplié par plus de cinq.', 2),
    ('85b01829-db48-5e0c-beae-5009fa191c51'::uuid, 'hggsp', 'Tle', 'Vers une société de la connaissance', 'Comment appelle-t-on le réseau des savants qui correspondent aux XVIIe et XVIIIe siècles ?', 'mcq', '["L’Académie européenne","La Ligue des savants","L’Internationale savante","La République des Lettres"]'::jsonb, 3, 'Par lettres et voyages, les savants font circuler les idées par-delà les frontières : une étape de la société de la connaissance.', 3),
    ('fe4588da-9764-5fc1-bf2e-a46d6bf4eee3'::uuid, 'hggsp', 'Tle', 'Vers une société de la connaissance', 'Que désigne la fracture numérique ?', 'mcq', '["Un accès très inégal aux outils et aux réseaux numériques","Une panne mondiale d’Internet","La séparation entre logiciels libres et payants","Le piratage de données personnelles"]'::jsonb, 0, 'Détenir un savoir ne suffit plus : il faut les moyens d’y accéder et d’en produire, très inégalement répartis.', 4),
    ('a2cc0ea8-dc9f-5152-9f61-dd6a66cfcbcb'::uuid, 'hggsp', 'Tle', 'Produire et diffuser des connaissances', 'Quel grand équipement est, avec le CERN, un exemple de coopération scientifique internationale ?', 'mcq', '["Le CNRS","ITER","Le MIT","La Sorbonne"]'::jsonb, 1, 'Accélérateurs, réacteurs expérimentaux, stations spatiales : aucun État ne finance seul ces équipements.', 1),
    ('cedc01ee-d0bf-5b1c-aef3-eac410d3a6a0'::uuid, 'hggsp', 'Tle', 'Produire et diffuser des connaissances', 'Quel pays est le premier déposant de brevets au monde ?', 'mcq', '["Les États-Unis","Le Japon","La Chine","L’Allemagne"]'::jsonb, 2, 'La Chine est aussi le premier producteur d’articles en volume : la géographie du savoir s’est déplacée vers l’Asie.', 2),
    ('01177687-98d9-5da5-843c-60c95ae23420'::uuid, 'hggsp', 'Tle', 'Produire et diffuser des connaissances', 'Quel est l’inconvénient des brevets pour la diffusion du savoir ?', 'mcq', '["Ils rendent les résultats gratuits","Ils suppriment l’évaluation par les pairs","Ils imposent la publication immédiate","Ils réservent l’usage de l’innovation"]'::jsonb, 3, 'Le brevet protège l’inventeur mais limite l’usage par les autres : toute politique de recherche arbitre entre protection et ouverture.', 3),
    ('95a6fe25-06e6-5a6d-bdef-57517e46a52e'::uuid, 'hggsp', 'Tle', 'Produire et diffuser des connaissances', 'Qu’arrive-t-il à un savoir qui n’est pas publié ?', 'mcq', '["Il n’existe pas pour la communauté scientifique","Il est protégé par un brevet automatique","Il est versé aux archives ouvertes","Il devient un secret d’État"]'::jsonb, 0, 'Publier fait exister un résultat, mais le fait échapper à son auteur : c’est la tension au cœur de la diffusion du savoir.', 4),
    ('2efa4855-c37c-5c13-a3ac-c467a510b3c0'::uuid, 'hggsp', 'Tle', 'La connaissance, enjeu politique et géopolitique', 'Pendant combien de temps le lyssenkisme a-t-il ruiné la génétique soviétique ?', 'mcq', '["Deux ans","Cinquante ans","Vingt ans","Un siècle"]'::jsonb, 2, 'Quand un régime décide de ce qui est vrai, la science recule : la génétique soviétique a perdu vingt ans.', 1),
    ('0d11c503-14a2-5897-8bd2-9c8a09e84652'::uuid, 'hggsp', 'Tle', 'La connaissance, enjeu politique et géopolitique', 'Quelle loi américaine soutient la production de semi-conducteurs ?', 'mcq', '["L’Inflation Reduction Act","Le CHIPS Act","Le Patriot Act","Le Cloud Act"]'::jsonb, 1, 'Semi-conducteurs, IA, quantique : la rivalité sino-américaine se joue sur les technologies, à coups de lois et de contrôles à l’exportation.', 2),
    ('2df617a4-136b-5056-bb72-f1320f5ec7e7'::uuid, 'hggsp', 'Tle', 'La connaissance, enjeu politique et géopolitique', 'Quelle entreprise chinoise est visée par des restrictions liées à la 5G ?', 'mcq', '["Alibaba","Tencent","Huawei","Baidu"]'::jsonb, 2, 'Les restrictions contre Huawei montrent que la maîtrise d’une technologie est aussi une question de sécurité nationale.', 3),
    ('7df49d65-e278-5b8f-a67a-780cc1ded20c'::uuid, 'hggsp', 'Tle', 'La connaissance, enjeu politique et géopolitique', 'Quelle politique du régime nazi chasse les savants juifs ?', 'mcq', '["Le lyssenkisme","L’opération Paperclip","Le projet Manhattan","La « science aryenne »"]'::jsonb, 3, 'En chassant ses savants juifs, l’Allemagne nazie a perdu des chercheurs de premier plan, dont beaucoup ont rejoint les États-Unis.', 4),
    ('42a0c6ad-5b9d-5abc-8670-725fd600d0d7'::uuid, 'hggsp', 'Tle', 'Le cyberespace : conflictualité et coopération entre les acteurs', 'Dans quelle couche du cyberespace se trouvent les câbles sous-marins et les data centers ?', 'mcq', '["La couche logicielle","La couche matérielle","La couche sémantique","La couche normative"]'::jsonb, 1, 'La couche matérielle est localisée : elle est donc vulnérable et soumise à la souveraineté des États.', 1),
    ('dc737f25-e6cb-5b46-8f56-9666aa39c122'::uuid, 'hggsp', 'Tle', 'Le cyberespace : conflictualité et coopération entre les acteurs', 'Comment appelle-t-on le système chinois de contrôle d’Internet ?', 'mcq', '["Le splinternet","Le Cloud Act","La « Grande Muraille numérique »","Le réseau ARPANET"]'::jsonb, 2, 'La Chine filtre et contrôle l’accès : le cyberespace n’efface pas les frontières, il les déplace.', 2),
    ('bd8efa3a-efaa-5d33-85ea-6230313c3e69'::uuid, 'hggsp', 'Tle', 'Le cyberespace : conflictualité et coopération entre les acteurs', 'Que désigne le terme splinternet ?', 'mcq', '["Un réseau militaire secret","Un virus informatique","Un câble transatlantique","La fragmentation d’Internet en espaces nationaux"]'::jsonb, 3, 'Chine, Russie, Union européenne : chacun impose ses règles, et l’Internet mondial se fragmente.', 3),
    ('2ba33fa5-cef6-5480-94e2-e23901b9e4a9'::uuid, 'hggsp', 'Tle', 'Le cyberespace : conflictualité et coopération entre les acteurs', 'Quel organisme illustre le poids des États-Unis dans la gouvernance technique d’Internet ?', 'mcq', '["L’ICANN","L’UNESCO","Le CERN","L’OTAN"]'::jsonb, 0, 'L’origine américaine d’Internet explique ce poids durable : ICANN, standards et entreprises dominantes.', 4),
    ('49aae52c-d84c-5411-8a3d-c75279f00f62'::uuid, 'hlp', 'Tle', 'La recherche de soi', 'Que montre le roman d’apprentissage à propos de son héros ?', 'mcq', '["Il découvre ce qu’il était déjà","Il se construit en se heurtant au monde","Il reste identique du début à la fin","Il est entièrement façonné par son précepteur"]'::jsonb, 1, 'Le héros du roman d’apprentissage ne se découvre pas : il se forme au contact des obstacles que le monde lui oppose.', 1),
    ('6f89dbbb-a9fd-5b35-bb6f-6c4b26f9410a'::uuid, 'hlp', 'Tle', 'La recherche de soi', 'Selon le cours, que fait l’objection freudienne à la connaissance de soi ?', 'mcq', '["Elle la rend impossible","Elle la réserve aux médecins","Elle en déplace la méthode : passer par ce que le moi produit","Elle confirme l’introspection classique"]'::jsonb, 2, 'Si le moi ne se voit pas en se regardant, on l’approche par ses productions : actes manqués, rêves, récits.', 2),
    ('73453684-ff69-54bc-a678-2559a062b88a'::uuid, 'hlp', 'Tle', 'La recherche de soi', 'Qu’inaugurent les *Confessions* de Rousseau, par rapport à celles d’Augustin ?', 'mcq', '["L’aveu comme chemin vers Dieu","Le journal écrit au présent","Le roman d’apprentissage","L’autobiographie moderne, adressée aux hommes"]'::jsonb, 3, 'Augustin se confesse devant Dieu ; Rousseau, s’il invoque l’« Être éternel » dans son préambule, se raconte devant ses semblables, et fonde l’autobiographie moderne.', 3),
    ('093927cd-35df-5f1d-a93e-02934ec61abd'::uuid, 'hlp', 'Tle', 'La recherche de soi', 'Que retenir de Hegel et de Sartre sur la nature du moi ?', 'mcq', '["Le moi est un rapport : il n’existe pas avant la relation qui le constitue","Le moi est une substance fixe","Le moi se forme sans autrui","Le moi est une illusion sans réalité"]'::jsonb, 0, 'Reconnaissance chez Hegel, regard qui fige chez Sartre : dans les deux cas, le moi naît de la relation à l’autre.', 4),
    ('86eddc15-dc1f-584a-a57d-1a58abc11628'::uuid, 'hlp', 'Tle', 'Le renouveau de l’éducation', 'Dans *Gargantua*, quel précepteur forme l’élève par le corps, l’observation et la conversation ?', 'mcq', '["Thubal Holopherne","Ponocrates","Émile","Pantagruel"]'::jsonb, 1, 'Rabelais oppose Ponocrates, qui forme, à Thubal Holopherne, dont la récitation par cœur abrutit.', 1),
    ('ecb165a2-17b6-5a0b-b804-4e64557518c7'::uuid, 'hlp', 'Tle', 'Le renouveau de l’éducation', 'Selon Condorcet (1792), que devient l’égalité politique sans égalité des lumières ?', 'mcq', '["Elle reste fictive","Elle se renforce","Elle devient inutile","Elle se transforme en monarchie"]'::jsonb, 0, 'Pour Condorcet, l’instruction est une condition de la citoyenneté : sans elle, l’égalité des droits reste sur le papier.', 2),
    ('b03d5a96-f41a-513a-a660-85cadcec769e'::uuid, 'hlp', 'Tle', 'Le renouveau de l’éducation', '« Le plus utile de toute l’éducation, c’est de ne pas gagner du temps, c’est d’en perdre » : qui l’écrit ?', 'mcq', '["Montaigne","Kant","Rousseau","Condorcet"]'::jsonb, 2, 'C’est Rousseau dans *Émile* : l’enfant n’est pas un adulte incomplet qu’il faudrait presser.', 3),
    ('0ff1365b-0b30-5fce-bf61-52ba39c67306'::uuid, 'hlp', 'Tle', 'Le renouveau de l’éducation', 'Quelle formule de Kant résume la tension de toute éducation ?', 'mcq', '["« Une tête bien faite plutôt que bien pleine »","« Connais-toi toi-même »","« Il faut perdre du temps »","« Comment cultiver la liberté par la contrainte ? »"]'::jsonb, 3, 'Kant voit le paradoxe : on veut former un être libre, mais on ne peut le faire qu’en lui imposant une discipline.', 4),
    ('d86dca83-e196-5093-9cb0-cb0f7ab042f9'::uuid, 'hlp', 'Tle', 'La transmission des savoirs', 'Dans le mythe du *Phèdre*, que voit Theuth, l’inventeur, dans l’écriture ?', 'mcq', '["Un poison pour la mémoire","Un remède à la mémoire","Un danger pour la cité","Un jeu sans utilité"]'::jsonb, 1, 'Theuth y voit un remède ; c’est le roi Thamous qui y voit un poison : d’où le *pharmakon*, remède et poison à la fois.', 1),
    ('111d5e8c-5e67-54e7-b075-4c017403ec46'::uuid, 'hlp', 'Tle', 'La transmission des savoirs', 'Quels bouleversements le cours juge-t-il indissociables de l’imprimerie ?', 'mcq', '["Les croisades et la féodalité","La révolution industrielle et le romantisme","La Réforme, la révolution scientifique et les Lumières","La décolonisation et la mondialisation"]'::jsonb, 2, 'Le livre devenu reproductible, vérifiable et discutable a rendu possibles la Réforme, la science moderne et les Lumières.', 2),
    ('b8ff67dc-17f1-5321-abc0-5e23b2643cc6'::uuid, 'hlp', 'Tle', 'La transmission des savoirs', 'Par quel canal se transmettent surtout les gestes et les manières d’être ?', 'mcq', '["Les commémorations","Le manuel scolaire","Les monuments","L’imitation et l’apprentissage, à l’atelier ou dans le compagnonnage"]'::jsonb, 3, 'Un geste ne s’apprend pas dans un livre : il se transmet en regardant faire et en refaisant.', 3),
    ('09a78a8a-eac1-5bdf-9105-ae06ca0bb108'::uuid, 'hlp', 'Tle', 'La transmission des savoirs', 'Que transmet aussi une société, en creux, à travers ce qu’elle commémore ?', 'mcq', '["Ce qu’elle choisit d’oublier","Uniquement la vérité historique","Des savoir-faire techniques","Des règles grammaticales"]'::jsonb, 0, 'Choisir ce qu’on commémore, c’est aussi décider de ce qu’on laisse tomber dans l’oubli.', 4),
    ('7d03c72c-f880-5596-954e-ff32b597d887'::uuid, 'hlp', 'Tle', 'L’Humanité en question', 'Que désigne la « banalité du mal » chez Hannah Arendt ?', 'mcq', '["Le mal rare, commis par des monstres","Le crime commis par des hommes ordinaires, dans un système obéissant","Les catastrophes naturelles","Les petites fautes de la vie quotidienne"]'::jsonb, 1, 'Arendt montre que le crime de masse n’exige pas des monstres : des hommes ordinaires qui obéissent y suffisent.', 1),
    ('419b6703-a850-5cc7-ac84-93129089ac5a'::uuid, 'hlp', 'Tle', 'L’Humanité en question', 'Dans le débat sur le transhumanisme, quelles deux définitions de l’humain s’opposent ?', 'mcq', '["La raison et la passion","Le corps et l’esprit","La perfectibilité et la finitude","La nature et la grâce"]'::jsonb, 2, 'L’humain est-il l’être qui se transforme, ou l’être qui sait qu’il meurt ? Augmenter l’humain l’accomplit-il ou le supprime-t-il ?', 2),
    ('28e84327-8e8c-569f-b6bc-f1054968ec85'::uuid, 'hlp', 'Tle', 'L’Humanité en question', 'Quelle figure le cours place-t-il au point de départ de la technique qui augmente le pouvoir de l’homme ?', 'mcq', '["Narcisse","Orphée","Icare","Prométhée"]'::jsonb, 3, '« De Prométhée aux biotechnologies » : le voleur du feu symbolise la technique donnée aux hommes.', 3),
    ('b204e104-e750-5d66-ab18-c282854090ec'::uuid, 'hlp', 'Tle', 'L’Humanité en question', 'Que demande le principe responsabilité de Hans Jonas ?', 'mcq', '["Que les effets de l’action restent compatibles avec la permanence d’une vie humaine authentique sur terre","Que le progrès technique soit accéléré","Que toute technique nouvelle soit interdite","Que chacun agisse selon son intérêt"]'::jsonb, 0, 'Jonas répond au pouvoir de la technique sur l’homme lui-même par une responsabilité envers l’avenir.', 4),
    ('1abea0fc-f3c4-5cf3-a2fe-c4e7c9085a2d'::uuid, 'hlp', 'Tle', 'L’émancipation pour tous ?', 'Que signifie la devise des Lumières *Sapere aude* ?', 'mcq', '["Ose savoir","Sache obéir","Connais-toi toi-même","Doute de tout"]'::jsonb, 0, 'C’est le mot d’ordre que Kant tire de sa définition : oser se servir de son propre entendement.', 1),
    ('f84891bf-91bb-5ed4-8ef6-30fbb9244f20'::uuid, 'hlp', 'Tle', 'L’émancipation pour tous ?', 'Selon le cours, que fait un maître qui explique, dans la perspective de Rancière ?', 'mcq', '["Il supprime toute inégalité","Il installe la dépendance qu’il prétend guérir","Il pose l’égalité des intelligences","Il rend l’école inutile"]'::jsonb, 1, 'L’explication suppose que l’élève ne peut comprendre seul : elle fabrique la minorité qu’elle veut abolir.', 2),
    ('42c3ffc2-e659-565c-9107-042e862c9204'::uuid, 'hlp', 'Tle', 'L’émancipation pour tous ?', 'En quelle année les femmes obtiennent-elles en France la pleine capacité juridique ?', 'mcq', '["1944","1936","1965","1981"]'::jsonb, 2, 'Le droit de vote arrive en 1944, mais la capacité juridique pleine (travailler, ouvrir un compte sans l’accord du mari) seulement en 1965.', 3),
    ('971f8677-7d40-5cef-8cb6-f3f93ed9631c'::uuid, 'hlp', 'Tle', 'L’émancipation pour tous ?', 'Rétabli en 1802, l’esclavage est aboli définitivement en France en…', 'mcq', '["1791","1794","1802","1848"]'::jsonb, 3, 'La première abolition de 1794 est défaite par Bonaparte en 1802 : preuve de la fragilité des émancipations.', 4),
    ('d9b28c9b-9ef7-53fd-9478-e28a0e87f4ad'::uuid, 'hlp', 'Tle', '« Un seul être vous manque et tout est dépeuplé » : le sentiment romantique', 'Dans quel recueil de Lamartine se trouve « L’Isolement » ?', 'mcq', '["*Les Contemplations*","*Méditations poétiques* (1820)","*Les Fleurs du mal*","*Les Nuits*"]'::jsonb, 1, '« L’Isolement » ouvre les *Méditations poétiques* de 1820, acte de naissance du romantisme poétique français.', 1),
    ('d86f7e04-9335-55ba-a969-31eb4b7e5686'::uuid, 'hlp', 'Tle', '« Un seul être vous manque et tout est dépeuplé » : le sentiment romantique', 'Chez Chateaubriand, que désigne le « vague des passions » ?', 'mcq', '["Une passion amoureuse précise","Une explication historique du malaise","Une mélancolie sans objet, où le désir devance l’expérience","Une crise de la foi religieuse"]'::jsonb, 2, 'Dans *René* (1802), le héros désire avant d’avoir vécu : sa mélancolie n’a pas d’objet déterminé.', 2),
    ('970b664a-80f5-56de-9717-10fff4cc6657'::uuid, 'hlp', 'Tle', '« Un seul être vous manque et tout est dépeuplé » : le sentiment romantique', 'Quel poème de Hugo demande à la nature de garder la mémoire d’un amour ?', 'mcq', '["« Tristesse d’Olympio »","« Le Lac »","« Demain, dès l’aube »","« L’Isolement »"]'::jsonb, 0, '« Tristesse d’Olympio » est de Hugo ; « Le Lac », sur le même motif, est de Lamartine.', 3),
    ('b16ebf02-1e83-513a-8889-b29f3c371756'::uuid, 'hlp', 'Tle', '« Un seul être vous manque et tout est dépeuplé » : le sentiment romantique', 'Quel héritage le sentiment romantique a-t-il durablement installé ?', 'mcq', '["Le culte de la règle classique","La méfiance envers toute émotion","Le refus de parler de soi","L’idée que la sincérité de l’émotion vaut caution"]'::jsonb, 3, 'Cet héritage se retrouve dans la chanson, le cinéma et une bonne part des réseaux sociaux.', 4),
    ('58180115-b458-53ac-8be8-f170c1895076'::uuid, 'hlp', 'Tle', 'Les sentiments et la raison', 'Que désigne l’*apatheia* stoïcienne selon le cours ?', 'mcq', '["L’insensibilité totale","La soumission aux passions","L’affranchissement des jugements précipités","La pitié envers autrui"]'::jsonb, 2, 'L’*apatheia* n’est pas l’absence de sensibilité : c’est ne plus être troublé par des opinions fausses sur les choses.', 1),
    ('65000075-4880-5ba1-880d-b11bf5a6be77'::uuid, 'hlp', 'Tle', 'Les sentiments et la raison', 'Chez Descartes, quel est le remède aux passions ?', 'mcq', '["L’ascèse et le jeûne","La générosité, sentiment de sa propre liberté","La pitié","La fuite du monde"]'::jsonb, 1, 'Dans *Les Passions de l’âme*, la générosité permet de ne pas se soumettre aux passions, qui restent bonnes par nature.', 2),
    ('da54d003-2074-5077-8c4f-d49c8d202ace'::uuid, 'hlp', 'Tle', 'Les sentiments et la raison', 'Quel ouvrage d’Antonio Damasio (1994) montre que l’émotion est une condition du raisonnement ?', 'mcq', '["*Les Passions de l’âme*","*Traité de la nature humaine*","*Discours de la méthode*","*L’Erreur de Descartes*"]'::jsonb, 3, 'Le titre vise le partage cartésien entre esprit et corps, que les observations cliniques de Damasio remettent en cause.', 3),
    ('99738343-d392-5e27-a760-b1704d86e458'::uuid, 'hlp', 'Tle', 'Les sentiments et la raison', 'Pourquoi les algorithmes de recommandation exploitent-ils l’indignation, selon le cours ?', 'mcq', '["Parce qu’elle retient l’attention","Parce qu’elle apaise les utilisateurs","Parce qu’elle est rationnelle","Parce que la loi l’impose"]'::jsonb, 0, 'Les émotions renseignent mais se manipulent : l’indignation capte l’attention, ce que la rhétorique du *pathos* savait déjà.', 4),
    ('50fd70d2-e027-5bae-9ed4-eeffd1d59daf'::uuid, 'hlp', 'Tle', 'Musique et sensibilité artistique', 'Selon le cours, quel problème unique pose la musique ?', 'mcq', '["Elle est réservée aux savants","Elle ne touche personne","Elle imite trop fidèlement la nature","Elle émeut sans représenter"]'::jsonb, 3, 'Elle ne raconte ni ne montre rien, et agit pourtant plus directement que les autres arts.', 1),
    ('e8086e01-235e-5c1a-b029-dbb26034f87f'::uuid, 'hlp', 'Tle', 'Musique et sensibilité artistique', 'Pourquoi le sublime commence-t-il par un déplaisir, selon Kant ?', 'mcq', '["Parce que l’objet est laid","Parce que l’imagination échoue là où la raison conçoit","Parce que la forme est à notre mesure","Parce qu’il est vulgaire"]'::jsonb, 1, 'Devant l’infini ou l’océan démonté, l’imagination est dépassée ; la raison, qui conçoit ce qu’elle ne peut figurer, en tire ensuite une grandeur.', 2),
    ('a2020aad-5a9f-5643-afb2-db012fb842cd'::uuid, 'hlp', 'Tle', 'Musique et sensibilité artistique', 'Qu’appelle-t-on le « paradoxe de la fiction » ?', 'mcq', '["Pleurer devant une fiction sans croire à sa réalité","Préférer la fiction à la réalité","Écrire une fiction vraie","Imiter la nature sans la représenter"]'::jsonb, 0, 'Comment une émotion réelle peut-elle naître d’un objet qu’on sait imaginaire ? Aristote y répondait par la catharsis.', 3),
    ('cde97645-aa03-50f7-a107-820bcacd3ba0'::uuid, 'hlp', 'Tle', 'Musique et sensibilité artistique', 'Lequel de ces exemples le cours range-t-il du côté du sublime ?', 'mcq', '["Une mélodie harmonieuse","Un portrait bien proportionné","L’océan démonté","Un jardin à la française"]'::jsonb, 2, 'Le sublime excède nos facultés, comme l’océan démonté, la montagne ou l’infini ; le beau s’accorde à elles.', 4),
    ('42a426f2-2da7-5f01-8bfe-12b402987034'::uuid, 'hlp', 'Tle', 'Les transformations historiques de l’ego', '« Je ne peins pas l’être, je peins le passage » : de qui est cette phrase ?', 'mcq', '["Descartes","Montaigne","Saint Augustin","Sartre"]'::jsonb, 1, 'Montaigne fait pour la première fois du caractère mouvant et contradictoire du moi une qualité.', 1),
    ('f6a88dc8-2319-575f-80eb-a30be04e2b6e'::uuid, 'hlp', 'Tle', 'Les transformations historiques de l’ego', 'Quand paraît le *Discours de la méthode*, où Descartes fait du moi un fondement ?', 'mcq', '["1580","1662","1637","1543"]'::jsonb, 2, 'En 1637, le *cogito* fait du moi le point d’appui de toute certitude ; 1580 est la date des *Essais*.', 2),
    ('63f1c4a5-76ba-50d3-a370-4d77a0ce2ff2'::uuid, 'hlp', 'Tle', 'Les transformations historiques de l’ego', 'Quelle humiliation la « blessure » darwinienne inflige-t-elle à l’homme ?', 'mcq', '["La Terre n’est pas au centre du monde","Le moi n’est pas maître dans sa maison","La conscience dépend de l’économie","L’homme n’est pas d’une autre nature que l’animal"]'::jsonb, 3, 'Après Copernic et avant la psychanalyse, Darwin retire à l’homme sa place à part dans le vivant.', 3),
    ('09e2dbe1-7f7f-5463-994b-c9c7e3fa9d31'::uuid, 'hlp', 'Tle', 'Les transformations historiques de l’ego', 'Selon le cours, que devient le moi contemporain ?', 'mcq', '["Une image à administrer, mise en scène sur les profils","Un secret de plus en plus caché","Une substance transparente","Une pure fiction grammaticale"]'::jsonb, 0, 'Profils, avatars, récits de soi : l’examen intérieur devient exposition.', 4),
    ('8217afe9-22f7-54e4-aa98-2e0d37bbde8c'::uuid, 'hlp', 'Tle', 'Identité et genre', 'Chez Ricœur, qu’est-ce que l’ipséité (*ipse*) ?', 'mcq', '["Rester physiquement le même","Se tenir à ses promesses","Être un faisceau de perceptions","Être défini par le regard d’autrui"]'::jsonb, 1, 'On peut changer entièrement et rester fidèle à sa parole : c’est ce que Ricœur appelle l’identité narrative.', 1),
    ('84a32dfb-a59e-53bc-929a-e0e6f50830dd'::uuid, 'hlp', 'Tle', 'Identité et genre', 'Quelle difficulté rencontre la théorie de l’identité personnelle de Locke ?', 'mcq', '["Elle nie l’existence de la conscience","Elle fait tout dépendre du corps","Que devient l’identité quand la mémoire manque ?","Elle ignore le récit de soi"]'::jsonb, 2, 'Si c’est la mémoire qui relie les moments du moi, l’oubli semble menacer l’identité elle-même.', 2),
    ('760d51b6-a45d-5292-9c2e-fbc9f6b5898c'::uuid, 'hlp', 'Tle', 'Identité et genre', 'Quel ouvrage Judith Butler publie-t-elle en 1990 ?', 'mcq', '["*Trouble dans le genre*","*Le Deuxième Sexe*","*Une femme*","*Les Identités meurtrières*"]'::jsonb, 0, 'Dans *Trouble dans le genre*, le genre est ce que l’on fait, non ce que l’on est.', 3),
    ('0a1bd124-c00c-5bea-9fde-ecf5ec3915f8'::uuid, 'hlp', 'Tle', 'Identité et genre', 'Que désigne le genre, par distinction avec le sexe ?', 'mcq', '["Les caractères biologiques","Le nom propre","L’âge","Les rôles, conduites et attentes qu’une société associe au sexe"]'::jsonb, 3, 'Le sexe renvoie au biologique ; le genre, à ce que la société y attache.', 4),
    ('36a0a367-81ba-5b23-8061-3a0e71e93b91'::uuid, 'hlp', 'Tle', 'Mutilations de la guerre et détention', 'Pourquoi la mutilation faciale des « gueules cassées » attaque-t-elle l’identité elle-même ?', 'mcq', '["Parce qu’elle empêche de travailler","Parce qu’elle est invisible","Parce que le visage est ce par quoi on est reconnu","Parce qu’elle est toujours mortelle"]'::jsonb, 2, 'Le visage est le lieu de la reconnaissance par les autres : le détruire, c’est plus que blesser un corps.', 1),
    ('68942d47-644e-58e4-b565-c351dafb724d'::uuid, 'hlp', 'Tle', 'Mutilations de la guerre et détention', 'Qui est l’auteur du *Feu* (1916) ?', 'mcq', '["Erich Maria Remarque","Henri Barbusse","Pierre Lemaitre","Roland Dorgelès"]'::jsonb, 1, 'Barbusse raconte la guerre depuis la tranchée ; Dorgelès a écrit *Les Croix de bois*.', 2),
    ('b1bc3ff6-1fa1-53e3-93be-e77400e662ea'::uuid, 'hlp', 'Tle', 'Mutilations de la guerre et détention', 'Que se fabrique le héros défiguré d’*Au revoir là-haut* ?', 'mcq', '["Une nouvelle identité administrative","Une prothèse de métal","Un journal intime","Des masques"]'::jsonb, 3, 'Faute de redevenir un visage, il devient une image : ses masques disent la perte de l’identité.', 3),
    ('e1fc90f5-09f7-59ee-8a33-13c0e0cd04ed'::uuid, 'hlp', 'Tle', 'Mutilations de la guerre et détention', 'Quel roman de Remarque (1929) évoque la génération sacrifiée ?', 'mcq', '["*À l’Ouest, rien de nouveau*","*Le Feu*","*Si c’est un homme*","*L’Espèce humaine*"]'::jsonb, 0, 'Écrit du côté allemand, le roman de Remarque montre une jeunesse broyée par la guerre.', 4),
    ('d1162c25-ad54-549f-8021-de382c02a8a2'::uuid, 'hlp', 'Tle', 'La science en question', 'Quelle exigence Weber tire-t-il de l’écart entre les faits et les devoirs ?', 'mcq', '["L’engagement politique du savant","La neutralité axiologique du savant","Le refus de toute expérience","La soumission de la science à l’État"]'::jsonb, 1, 'Le savant ne doit pas confondre sa chaire et sa tribune : la science dit ce qui est, pas ce qui doit être.', 1),
    ('d747d5d6-0fc2-5e77-8d7c-4b22648f7cd4'::uuid, 'hlp', 'Tle', 'La science en question', 'Selon Kuhn, que se passe-t-il quand les anomalies s’accumulent ?', 'mcq', '["La science s’arrête","Les savants les ignorent toujours","Le paradigme est prouvé","Le paradigme finit par basculer"]'::jsonb, 3, 'La science ordinaire travaille dans un paradigme ; quand trop d’anomalies résistent, il est remplacé.', 2),
    ('ddf95131-d8c2-5bd8-a99f-4fd6e30dc824'::uuid, 'hlp', 'Tle', 'La science en question', 'Que dire d’une théorie qui explique tout, quel que soit le fait observé ?', 'mcq', '["Elle est hors du champ scientifique","Elle est la plus solide","Elle est prouvée par induction","Elle forme un paradigme"]'::jsonb, 0, 'Faute de pouvoir être démentie par un fait, elle n’est pas réfutable, donc pas scientifique au sens de Popper.', 3),
    ('3fbff6cc-3bae-5101-8dff-d787943dbb8c'::uuid, 'hlp', 'Tle', 'La science en question', 'Selon le cours, comment répondre à la crise de confiance envers la science ?', 'mcq', '["Renforcer l’autorité des experts","Cesser de publier","Exposer la méthode, ce qui pourrait démentir la théorie","Suivre l’opinion majoritaire"]'::jsonb, 2, 'Ce qui distingue une science, c’est qu’elle montre ce qui pourrait la réfuter, non qu’elle exige d’être crue.', 4),
    ('5eab73f5-dee8-5d41-9b28-1443a3d52a17'::uuid, 'hlp', 'Tle', 'Les arts contemporains : héritages et reniements', 'En quelle année Duchamp présente-t-il *Fountain* ?', 'mcq', '["1839","1917","1964","1905"]'::jsonb, 1, 'En 1917, l’urinoir renversé et signé fait du choix et du contexte, non du savoir-faire, ce qui fait l’œuvre.', 1),
    ('3a7b510e-70de-5956-8084-1c891a3aaa8e'::uuid, 'hlp', 'Tle', 'Les arts contemporains : héritages et reniements', 'Quel mouvement abandonne le point de vue unique ?', 'mcq', '["L’impressionnisme","L’abstraction","Le cubisme","Le réalisme"]'::jsonb, 2, 'L’impressionnisme abandonne la ligne et le fini, l’abstraction le sujet, le cubisme le point de vue unique.', 2),
    ('e5f43cc9-34ba-5e73-8989-ad5664dc73a4'::uuid, 'hlp', 'Tle', 'Les arts contemporains : héritages et reniements', 'Pour Benjamin, que permet aussi la perte de l’aura ?', 'mcq', '["Une hausse du prix des œuvres","Un retour au culte","La fin de toute reproduction","Une chance politique : l’art sort du culte pour entrer dans l’usage"]'::jsonb, 3, 'La reproduction retire l’unicité de l’œuvre mais la rend accessible à tous.', 3),
    ('cd701459-18f5-501e-b645-7f9312d5da7e'::uuid, 'hlp', 'Tle', 'Les arts contemporains : héritages et reniements', 'Selon Adorno, comment l’art résiste-t-il à la standardisation ?', 'mcq', '["En n’étant pas immédiatement consommable","En se vendant massivement","En imitant la nature","En s’exposant au musée"]'::jsonb, 0, 'Face à l’industrie culturelle, l’art authentique résiste par sa difficulté.', 4),
    ('a0851500-80ef-5b4b-8309-bfd6e314cb32'::uuid, 'hlp', 'Tle', 'La question de la pop culture', 'Dans quel ouvrage Adorno et Horkheimer forgent-ils la notion d’« industrie culturelle » ?', 'mcq', '["*La Distinction*","*La Dialectique de la raison* (1944)","*Mythologies*","*Pédagogie des opprimés*"]'::jsonb, 1, 'Écrite en 1944, *La Dialectique de la raison* voit dans la culture de masse une production industrielle reçue par les masses.', 1),
    ('662120cc-c069-5a30-bf3c-9587b2bfbe34'::uuid, 'hlp', 'Tle', 'La question de la pop culture', 'Quel exemple Umberto Eco propose-t-il d’analyser avec les mêmes outils que le reste ?', 'mcq', '["James Bond","La Joconde","L’*Iliade*","Le catch"]'::jsonb, 0, 'Eco refuse le mépris comme la complaisance : un roman de James Bond mérite une analyse sérieuse. Le catch, lui, est un exemple de Barthes.', 2),
    ('eefaa5ad-089a-5438-b195-36f3c3d7906b'::uuid, 'hlp', 'Tle', 'La question de la pop culture', 'Pourquoi une série très regardée relève-t-elle d’un examen sérieux, selon le cours ?', 'mcq', '["Parce qu’elle est coûteuse","Parce qu’elle est récente","Parce qu’elle façonne des représentations de la justice, du travail, de la famille","Parce qu’elle est toujours de l’art"]'::jsonb, 2, 'Vue par des dizaines de millions de personnes, elle produit des mythologies communes.', 3),
    ('91803cb4-ace7-5932-9789-54bc8b1ddda8'::uuid, 'hlp', 'Tle', 'La question de la pop culture', 'Selon Adorno et Horkheimer, que fait la distraction ?', 'mcq', '["Elle éveille l’esprit critique","Elle libère du travail","Elle rend chaque œuvre unique","Elle neutralise la critique : le divertissement prolonge le travail"]'::jsonb, 3, 'Le divertissement repose pour mieux faire retourner au travail, sans rien remettre en cause.', 4),
    ('0e52468f-8b2b-57bb-a9d8-c8e6e57980b6'::uuid, 'hlp', 'Tle', 'La dystopie : la fin de l’utopie', 'Que signifie *ou-topos*, d’où vient le mot « utopie » ?', 'mcq', '["Le lieu du bonheur","Le lieu de nulle part","La cité idéale","L’île lointaine"]'::jsonb, 1, '*Ou-topos* est le lieu de nulle part ; Thomas More joue aussi sur *eu-topos*, le lieu du bonheur.', 1),
    ('d2098a93-1384-5cb4-bf65-f31d57822706'::uuid, 'hlp', 'Tle', 'La dystopie : la fin de l’utopie', 'Qu’est-ce que la double-pensée dans *1984* ?', 'mcq', '["Faire tenir ensemble deux propositions contradictoires","Parler deux langues","Surveiller deux fois","Obéir à deux chefs"]'::jsonb, 0, 'Avec la novlangue, elle rend le pouvoir maître non seulement des actes, mais de la pensée elle-même.', 2),
    ('b5e98088-35ee-5ca0-ba41-0c0a6b25b6f5'::uuid, 'hlp', 'Tle', 'La dystopie : la fin de l’utopie', 'Selon le cours, que font vraiment les dystopies ?', 'mcq', '["Elles prédisent l’avenir avec exactitude","Elles décrivent des sociétés idéales","Elles décrivent des mécanismes réels : contrôle de l’information, réécriture du passé","Elles refusent de parler de politique"]'::jsonb, 2, 'Écrites pendant ou après les totalitarismes, elles sont un détour pour parler du présent.', 3),
    ('6757ab03-0326-5c79-91c3-89304428572d'::uuid, 'hlp', 'Tle', 'La dystopie : la fin de l’utopie', 'Dans *Le Meilleur des mondes*, comment s’appelle la drogue qui maintient la docilité ?', 'mcq', '["La novlangue","Le Big Brother","La double-pensée","Le *soma*"]'::jsonb, 3, 'Chez Huxley, la servitude passe par le plaisir : conditionnement, castes fabriquées et *soma*.', 4),
    ('1a59a4ea-00dc-50f0-b7a2-b9dfc677236d'::uuid, 'hlp', 'Tle', 'Violence et société', 'Que désigne la violence structurelle selon Galtung ?', 'mcq', '["Les violences policières","Des inégalités qui tuent sans qu’aucun coup soit porté","La guerre civile","Une domination acceptée par ceux qui la subissent"]'::jsonb, 1, 'Galtung élargit la notion aux effets meurtriers des structures sociales ; la domination acceptée est la violence symbolique de Bourdieu.', 1),
    ('58f37bf3-7711-5897-8d29-b5e1cf1984ae'::uuid, 'hlp', 'Tle', 'Violence et société', 'Chez Rousseau, qu’est-ce qui produit la violence ?', 'mcq', '["La société, la propriété, la comparaison","L’absence d’État","La nature humaine","La pitié"]'::jsonb, 0, 'Pour Rousseau, l’homme naturel est pacifique : c’est la vie en société qui le rend violent. L’absence d’État est la cause chez Hobbes.', 2),
    ('d90eeba7-d99c-53e8-a347-d158a22e39e5'::uuid, 'hlp', 'Tle', 'Violence et société', 'Pourquoi manier avec précaution les notions de violence symbolique ou structurelle ?', 'mcq', '["Elles sont interdites par la loi","Elles sont trop récentes","Si tout est violence, le mot ne distingue plus rien","Elles ne concernent que l’économie"]'::jsonb, 2, 'Élargir un mot le rend utile pour voir l’invisible, mais un mot qui désigne tout perd son pouvoir de distinguer.', 3),
    ('71170023-4fdf-5e68-a0c5-da3b74fa324e'::uuid, 'hlp', 'Tle', 'Violence et société', 'Que distingue Walter Benjamin ?', 'mcq', '["La violence juste et la violence injuste","La violence physique et la violence verbale","La violence privée et la violence publique","La violence qui fonde le droit et celle qui le conserve"]'::jsonb, 3, 'Toute fondation d’un ordre juridique passe par une violence, que le droit établi prolonge ensuite pour se maintenir.', 4),
    ('706b05de-e72c-519a-97f4-d1af4ad82eca'::uuid, 'hlp', 'Tle', 'L’histoire de la psychiatrie (Foucault)', 'Selon Foucault, que fait la raison classique face à la folie ?', 'mcq', '["Elle la réfute par des arguments","Elle l’exclut, en la réduisant au silence","Elle la célèbre","Elle la soigne par la parole"]'::jsonb, 1, 'Le silence de l’interné est la condition du monologue de la raison sur lui.', 1),
    ('39433483-c38d-58d6-81f1-d0bc8e3d86fa'::uuid, 'hlp', 'Tle', 'L’histoire de la psychiatrie (Foucault)', 'Qu’ajoute *Naissance de la clinique* (1963) à l’œuvre de Foucault ?', 'mcq', '["Le biopouvoir","Le panoptique","Le regard médical comme savoir-pouvoir","L’histoire de la sexualité"]'::jsonb, 2, 'Le panoptique vient avec *Surveiller et punir* (1975), le biopouvoir avec *La Volonté de savoir* (1976).', 2),
    ('0db76ff0-51a4-5228-a99e-1a555d4d0e31'::uuid, 'hlp', 'Tle', 'L’histoire de la psychiatrie (Foucault)', 'Selon Foucault, comment s’exerce principalement le pouvoir moderne ?', 'mcq', '["Par la norme : il classe, mesure, corrige","Par l’interdiction et le supplice","Par la seule force armée","Par la religion"]'::jsonb, 0, 'Le pouvoir moderne produit des savoirs sur les individus et les ramène à la norme plutôt que de simplement interdire.', 3),
    ('33ef59bf-fd73-537e-8188-84236f1aa79b'::uuid, 'hlp', 'Tle', 'L’histoire de la psychiatrie (Foucault)', 'Quelle objection portent Gauchet et Swain à l’*Histoire de la folie* ?', 'mcq', '["On ne peut écrire l’histoire de la folie dans le langage de la raison","La folie n’existe pas","Pinel n’a jamais existé","La chronologie du « grand renfermement » est contestable"]'::jsonb, 3, 'L’objection du langage de la raison est celle de Derrida ; Gauchet et Swain discutent la chronologie.', 4),
    ('86405f4b-575c-561d-81a9-27545fb3d602'::uuid, 'hlp', 'Tle', 'Le fantasme de la toute-puissance humaine', 'En quelle année paraît *Frankenstein* de Mary Shelley ?', 'mcq', '["1818","1789","1859","1886"]'::jsonb, 0, 'Le roman, sous-titré *Le Prométhée moderne*, paraît en 1818.', 1),
    ('8b0fea7e-4fa8-50de-95e4-8726aa68575d'::uuid, 'hlp', 'Tle', 'Le fantasme de la toute-puissance humaine', 'Pourquoi le « comme » de « comme maîtres et possesseurs de la nature » compte-t-il ?', 'mcq', '["Il atténue la science","Descartes ne divinise pas l’homme : il l’assigne à une tâche","Il renvoie à Dieu seul","Il est une erreur de traduction"]'::jsonb, 1, 'L’homme n’est pas maître absolu ; la science pratique doit le rendre capable d’agir sur la nature.', 2),
    ('83b57162-a967-5f16-aef8-937dc514ffec'::uuid, 'hlp', 'Tle', 'Le fantasme de la toute-puissance humaine', 'Quel mythe raconte une tour, une langue unique et la dispersion ?', 'mcq', '["Prométhée","Icare","Babel","Faust"]'::jsonb, 2, 'La tour de Babel punit la démesure humaine par la confusion des langues et la dispersion.', 3),
    ('67b44af7-a7b2-5751-9a80-47b4f391a66b'::uuid, 'hlp', 'Tle', 'Le fantasme de la toute-puissance humaine', 'Chez Heidegger, que devient le fleuve sous le regard de la technique moderne ?', 'mcq', '["Un paysage à contempler","Une divinité","Une frontière naturelle","Une réserve d’énergie"]'::jsonb, 3, 'C’est l’arraisonnement (*Gestell*) : le monde devient un fonds disponible.', 4),
    ('153404b8-b317-5df8-b2e8-76923b3e15ed'::uuid, 'hlp', 'Tle', 'La conscience écologique', 'Qui a popularisé en 2000 le concept d’Anthropocène ?', 'mcq', '["Bruno Latour","Paul Crutzen","Philippe Descola","Arne Næss"]'::jsonb, 1, 'Le chimiste Paul Crutzen propose le terme pour dire que l’humanité est devenue une force géologique.', 1),
    ('89fddf74-2ab5-5c49-af22-892e5a7dda7b'::uuid, 'hlp', 'Tle', 'La conscience écologique', 'Que met en cause Lynn White dans la généalogie de la crise écologique ?', 'mcq', '["L’économie extractive","La modernité cartésienne","Le partage nature / culture","Le récit biblique de la domination : « soumettez la terre »"]'::jsonb, 3, 'Lynn White accuse une lecture du récit biblique qui place l’homme en maître de la nature.', 2),
    ('bf8bd945-e76f-57f1-a065-d5685d6fc069'::uuid, 'hlp', 'Tle', 'La conscience écologique', 'Quelle objection juridique vise l’idée de droits de la nature ?', 'mcq', '["On ne peut accorder des droits à des entités incapables de devoirs","La nature appartient à l’État","Les droits ne concernent que les citoyens français","La loi ne peut pas changer"]'::jsonb, 0, 'Dans la tradition juridique, droits et devoirs vont ensemble : d’où la difficulté à reconnaître des droits à un fleuve ou à une forêt.', 3),
    ('ff25e45b-f099-5eb7-94e2-c10e45670e94'::uuid, 'hlp', 'Tle', 'La conscience écologique', 'Qui a écrit *Walden* ?', 'mcq', '["Jean Giono","Italo Calvino","Henry David Thoreau","Aldo Leopold"]'::jsonb, 2, 'Giono a écrit *L’Homme qui plantait des arbres* et Calvino *Le Baron perché* ; *Walden* est de Thoreau.', 4),
    ('0eaa861a-e658-5c1c-b1f0-7e310bd8db02'::uuid, 'hlp', 'Tle', 'La bioéthique', 'Entre quels principes le débat bioéthique arbitre-t-il le plus souvent ?', 'mcq', '["L’autonomie du patient et la bienfaisance du soignant","La justice et la gratuité","Le secret et la transparence","La liberté de la recherche et le profit"]'::jsonb, 0, 'Les quatre principes entrent en conflit : respecter la décision du patient peut s’opposer à ce que le soignant juge être son bien.', 1),
    ('37ca7ea4-b8bf-5e54-9739-eb8c7eb91a00'::uuid, 'hlp', 'Tle', 'La bioéthique', 'Que signifie *Primum non nocere* ?', 'mcq', '["D’abord soigner","D’abord ne pas nuire","D’abord informer","D’abord consentir"]'::jsonb, 1, 'C’est le principe de non-malfaisance, l’un des quatre de Beauchamp et Childress.', 2),
    ('fc0091ee-c7e5-51f0-ac56-c66b0143820b'::uuid, 'hlp', 'Tle', 'La bioéthique', 'Qu’apporte la déclaration d’Helsinki (1964) ?', 'mcq', '["Elle autorise l’euthanasie","Elle interdit la PMA","Elle étend l’exigence de consentement à toute la recherche médicale","Elle crée le CCNE"]'::jsonb, 2, 'Elle prolonge le code de Nuremberg de 1947, rédigé après le procès des médecins nazis.', 3),
    ('5c1994ab-ec03-5614-8f1d-c0354fe10f2a'::uuid, 'hlp', 'Tle', 'La bioéthique', 'En quelle année est créé le Comité consultatif national d’éthique (CCNE) ?', 'mcq', '["1947","1964","2005","1983"]'::jsonb, 3, 'Créé en 1983, il incarne la méthode française : une éthique délibérative et révisable.', 4),
    ('712f4811-831d-5c04-a9fa-abc4b8d57264'::uuid, 'hlp', 'Tle', 'Méthode de l’épreuve', 'Sur combien de points chaque exercice de l’épreuve est-il noté ?', 'mcq', '["12 et 8","Sur 20 chacun","Sur 10 chacun","Sur 5 chacun"]'::jsonb, 2, 'L’interprétation littéraire et l’essai philosophique comptent à parts égales, sur 10 chacun.', 1),
    ('722480c0-df83-558b-aa6d-552dd5ed3e89'::uuid, 'hlp', 'Tle', 'Méthode de l’épreuve', 'Qu’attend-on à chaque étape de l’interprétation littéraire ?', 'mcq', '["Un résumé du passage","L’articulation entre le procédé relevé et l’effet produit","Une liste de figures de style","Une biographie de l’auteur"]'::jsonb, 1, 'Un procédé nommé sans effet analysé ne rapporte rien.', 2),
    ('14fef91b-33f2-5cbc-840e-e87bdef1526b'::uuid, 'hlp', 'Tle', 'Méthode de l’épreuve', 'Quelle est la première étape de l’essai philosophique ?', 'mcq', '["Problématiser : montrer que la question n’a pas de réponse évidente","Citer un maximum d’auteurs","Résumer le texte","Donner tout de suite sa conclusion"]'::jsonb, 0, 'Sans problème posé, le développement n’a rien à résoudre et tourne à la récitation.', 3),
    ('d4840fbe-23f8-56c9-8b62-836dfbf93e1d'::uuid, 'hlp', 'Tle', 'Méthode de l’épreuve', 'Combien de temps garder pour la relecture finale ?', 'mcq', '["30 minutes","1 heure","5 minutes","10 minutes"]'::jsonb, 3, 'Dix minutes pour la syntaxe et l’exactitude des citations : elles rapportent plus que les dix premières.', 4),
    ('e950d80c-fa27-56a1-a872-520956da4b14'::uuid, 'ses', 'Tle', 'Les sources de la croissance économique', 'Pourquoi la croissance extensive n’est-elle pas soutenable à long terme ?', 'mcq', '["Parce qu’elle provoque toujours de l’inflation","Parce qu’elle réduit la productivité à zéro","Parce que la population active et le stock de capital ne peuvent pas croître indéfiniment","Parce qu’elle est interdite par les traités européens"]'::jsonb, 2, 'La croissance extensive repose sur plus de facteurs ; or leurs quantités sont bornées. Seuls les gains de productivité (croissance intensive) tiennent sur la durée.', 1),
    ('bc3f2330-2136-5338-8953-4519eaa26af0'::uuid, 'ses', 'Tle', 'Les sources de la croissance économique', 'Lequel de ces économistes n’est PAS associé aux théories de la croissance endogène ?', 'mcq', '["Romer","Lucas","Barro","Ricardo"]'::jsonb, 3, 'Romer, Lucas et Barro montrent que le progrès technique est produit par l’investissement ; Ricardo est l’auteur de l’avantage comparatif.', 2),
    ('5e050b61-13c3-5b78-960f-58d1fc71a12c'::uuid, 'ses', 'Tle', 'Les sources de la croissance économique', 'Dans la croissance endogène, quel investissement alimente le capital technologique ?', 'mcq', '["L’éducation et la formation","La recherche-développement","Les infrastructures publiques","L’achat de machines neuves"]'::jsonb, 1, 'La R&D alimente le capital technologique ; l’éducation nourrit le capital humain, les infrastructures le capital public.', 3),
    ('7bd20f86-1669-5dba-a1d1-71f6f44f9c2f'::uuid, 'ses', 'Tle', 'Les sources de la croissance économique', 'Que prend en compte l’IDH en plus du revenu ?', 'mcq', '["Les inégalités et l’état de l’environnement","L’espérance de vie et l’éducation","Le taux de chômage et l’inflation","La balance commerciale"]'::jsonb, 1, 'L’IDH combine revenu, espérance de vie et éducation ; il ignore encore les inégalités et l’environnement.', 4),
    ('2861fa2f-251c-5030-95a5-1793dec575ad'::uuid, 'ses', 'Tle', 'Entretenir la croissance économique : le rôle des institutions et des innovations', 'Quelle est en général la durée du monopole accordé par un brevet ?', 'mcq', '["5 ans","10 ans","20 ans","99 ans"]'::jsonb, 2, 'Le brevet protège l’invention environ 20 ans, en échange de sa publication : un compromis entre inciter à innover et diffuser la connaissance.', 1),
    ('f1b396b3-213b-594d-8cf9-4f6a2d5d3165'::uuid, 'ses', 'Tle', 'Entretenir la croissance économique : le rôle des institutions et des innovations', 'Selon Acemoglu et Robinson, comment le pouvoir est-il réparti dans des institutions inclusives ?', 'mcq', '["Il est largement réparti","Il est concentré sur une élite","Il est confié aux entreprises étrangères","Il est détenu par la banque centrale"]'::jsonb, 0, 'Les institutions inclusives répartissent le pouvoir et sécurisent les droits du plus grand nombre : la destruction créatrice y est acceptée.', 2),
    ('103f54b5-fd58-5cd3-a963-a341a6a087b5'::uuid, 'ses', 'Tle', 'Entretenir la croissance économique : le rôle des institutions et des innovations', 'Le toyotisme est un exemple d’innovation…', 'mcq', '["de produit","de débouché","de procédé","d’organisation"]'::jsonb, 3, 'Taylorisme et toyotisme sont des innovations d’organisation : ils changent la façon d’agencer le travail, pas le bien produit.', 3),
    ('72df39e5-aae0-5992-a4e6-b8b40c00b27b'::uuid, 'ses', 'Tle', 'Entretenir la croissance économique : le rôle des institutions et des innovations', 'Pourquoi le lien entre institutions et croissance n’est-il pas mécanique ?', 'mcq', '["Parce que les institutions n’ont aucun effet sur l’économie","Parce qu’il joue dans les deux sens : les pays riches ont aussi les moyens de se doter de bonnes institutions","Parce que seul le capital physique compte","Parce que les institutions changent chaque année"]'::jsonb, 1, 'La causalité est réciproque : de bonnes institutions favorisent la croissance, et la richesse aide à bâtir de bonnes institutions.', 4),
    ('60552877-8ff4-5f59-a7b2-7ea85625aa17'::uuid, 'ses', 'Tle', 'Développement et écologie : les limites de la croissance', 'Selon la soutenabilité faible, la perte de capital naturel…', 'mcq', '["est toujours irréversible","doit être interdite par la loi","peut être compensée par du capital technologique","n’a aucun lien avec la croissance"]'::jsonb, 2, 'La soutenabilité faible suppose les capitaux substituables : innover compense ce que l’on prélève sur la nature.', 1),
    ('e52ff2d9-d62c-5b43-b690-7969361e82bc'::uuid, 'ses', 'Tle', 'Développement et écologie : les limites de la croissance', 'Les émissions d’un pays augmentent de 1 % quand son PIB augmente de 3 %. De quoi s’agit-il ?', 'mcq', '["D’un découplage absolu","D’un découplage relatif","D’une décroissance","D’une empreinte carbone négative"]'::jsonb, 1, 'Le découplage est relatif quand les émissions croissent moins vite que le PIB ; il n’est absolu que si elles baissent.', 2),
    ('4d848983-c60e-5378-a2e1-c3f75dd9cc63'::uuid, 'ses', 'Tle', 'Développement et écologie : les limites de la croissance', 'Que recouvre le capital social parmi les quatre capitaux ?', 'mcq', '["Les machines et infrastructures","Les fonds propres d’une société","Les cotisations sociales","La qualité des relations et de la confiance"]'::jsonb, 3, 'Le capital social désigne la qualité des relations et de la confiance ; physique, humain et naturel complètent la liste.', 3),
    ('f041cb02-dcab-516d-8fe5-0f120eb10600'::uuid, 'ses', 'Tle', 'Développement et écologie : les limites de la croissance', 'Quel argument avancent les partisans de la décroissance ?', 'mcq', '["Le découplage est trop lent et trop partiel","Le signal-prix suffira à verdir la production","Les capitaux sont parfaitement substituables","Le PIB mesure bien le bien-être"]'::jsonb, 0, 'La décroissance juge le découplage insuffisant et veut réduire la production elle-même ; la croissance verte parie sur l’innovation et le prix.', 4),
    ('94ca5b38-42ef-5ffd-858d-169348c52337'::uuid, 'ses', 'Tle', 'Les fondements du commerce international', 'Quelle est la principale limite du modèle HOS ?', 'mcq', '["Il suppose un avantage absolu","Il explique mal le commerce entre pays semblables","Il ignore les dotations en facteurs","Il ne s’applique qu’aux services"]'::jsonb, 1, 'HOS raisonne sur des dotations factorielles différentes : il éclaire mal les échanges entre pays développés comparables.', 1),
    ('ced9cfdc-a4c0-5a52-b2f1-8401a1d90c81'::uuid, 'ses', 'Tle', 'Les fondements du commerce international', 'Quelle hypothèse du modèle de Ricardo constitue une limite ?', 'mcq', '["Des produits différenciés","Des économies d’échelle","Des facteurs de production immobiles entre pays","Des coûts de transport élevés"]'::jsonb, 2, 'Ricardo suppose que travail et capital ne franchissent pas les frontières, ce que la mondialisation dément en partie.', 2),
    ('b8d0d2e9-e22a-5c37-b812-98f8b1400484'::uuid, 'ses', 'Tle', 'Les fondements du commerce international', 'Quel exemple montre que les avantages comparatifs se construisent ?', 'mcq', '["L’Arabie saoudite et le pétrole","Le Chili et le cuivre","L’Australie et le minerai de fer","La Corée du Sud et l’électronique"]'::jsonb, 3, 'La Corée du Sud n’avait aucun avantage dans l’électronique en 1960 : formation, recherche et protection temporaire l’ont fabriqué.', 3),
    ('a841d13b-df73-534f-bbfe-53507ad8d3cd'::uuid, 'ses', 'Tle', 'Les fondements du commerce international', 'Un échange de voitures contre du textile relève du commerce…', 'mcq', '["interbranche","intrabranche","intra-firme","de services"]'::jsonb, 0, 'Le commerce interbranche échange des produits de branches différentes ; c’est celui qu’expliquent Smith, Ricardo et HOS.', 4),
    ('6e44d04e-2049-5647-872b-22f601ba6303'::uuid, 'ses', 'Tle', 'Échanger : pourquoi, comment ?', 'En quelle année le GATT a-t-il été créé ?', 'mcq', '["1919","1947","1971","1995"]'::jsonb, 1, 'Le GATT (1947) organise la baisse des barrières douanières ; l’OMC lui succède en 1995.', 1),
    ('a40468c8-2a1b-5e5e-bc8b-8c0fb085d2e0'::uuid, 'ses', 'Tle', 'Échanger : pourquoi, comment ?', 'Par quel organe l’OMC arbitre-t-elle les conflits commerciaux ?', 'mcq', '["Le Conseil de sécurité","La Banque mondiale","L’organe de règlement des différends","Le Fonds monétaire international"]'::jsonb, 2, 'L’organe de règlement des différends est la grande nouveauté de l’OMC par rapport au GATT.', 2),
    ('a4326fad-447a-502c-86e4-676e96e3cb35'::uuid, 'ses', 'Tle', 'Échanger : pourquoi, comment ?', 'Quel coût le protectionnisme fait-il peser sur le pays qui l’applique ?', 'mcq', '["Une baisse des prix intérieurs","Une hausse automatique de ses exportations","La disparition des normes sanitaires","Des intrants renchéris et des représailles"]'::jsonb, 3, 'Protéger renchérit les biens importés utilisés par les entreprises, expose aux représailles et retarde l’adaptation.', 3),
    ('ec698204-35c3-5f72-842c-b5842643d926'::uuid, 'ses', 'Tle', 'Échanger : pourquoi, comment ?', 'Quels instruments protectionnistes sont aujourd’hui les plus utilisés ?', 'mcq', '["Les instruments non tarifaires : normes, quotas, subventions","Les droits de douane","Les embargos","Les dévaluations monétaires"]'::jsonb, 0, 'Les droits de douane étant encadrés par l’OMC, la protection passe surtout par des normes, quotas, subventions et marchés publics réservés.', 4),
    ('d3310aad-b6e0-5442-a1ca-d8fcbb0ff36d'::uuid, 'ses', 'Tle', 'Entreprises et internationalisation de la production', 'Au sens strict, une délocalisation est un IDE motivé par…', 'mcq', '["la conquête d’un marché","la réduction des coûts de production","l’accès aux matières premières","la proximité d’un pôle technologique"]'::jsonb, 1, 'Délocaliser, c’est produire ailleurs pour produire moins cher ; la plupart des IDE visent au contraire à vendre sur place.', 1),
    ('b1c248c1-9658-5813-a3b4-3012ae40d23a'::uuid, 'ses', 'Tle', 'Entreprises et internationalisation de la production', 'Qu’est-ce qui définit une firme multinationale ?', 'mcq', '["Exporter plus de la moitié de sa production","Être cotée dans plusieurs bourses","Posséder au moins une unité de production hors de son pays d’origine","Employer des salariés étrangers"]'::jsonb, 2, 'Une FMN possède au moins une unité de production à l’étranger, grâce à des investissements directs.', 2),
    ('5fa4de32-0eb6-5fc4-bfeb-e81e6a361854'::uuid, 'ses', 'Tle', 'Entreprises et internationalisation de la production', 'Comment une firme garde-t-elle la main sur un sous-traitant indépendant ?', 'mcq', '["En détenant son capital","Par une subvention publique","Par une fusion","Par le contrat et la marque"]'::jsonb, 3, 'Externaliser permet de contrôler la production par le contrat et la marque, sans porter l’investissement ni le risque social.', 3),
    ('f1f4603d-6349-5c22-bfce-2d455ce64b1c'::uuid, 'ses', 'Tle', 'Entreprises et internationalisation de la production', 'Que gagne en général le pays d’accueil d’un IDE ?', 'mcq', '["Les fonctions de conception à forte valeur ajoutée","Des emplois et des transferts de technologie","Des recettes fiscales garanties","Une indépendance économique accrue"]'::jsonb, 1, 'Le pays d’accueil gagne emplois et technologie, mais devient dépendant et entre en concurrence fiscale.', 4),
    ('11ef1b57-dd3f-5055-ad72-21263ab37c4b'::uuid, 'ses', 'Tle', 'Définir et mesurer le chômage', 'Une personne a travaillé une heure pendant la semaine de référence. Au sens du BIT, elle est…', 'mcq', '["chômeuse","active occupée","inactive","dans le halo du chômage"]'::jsonb, 1, 'Le BIT exige de n’avoir travaillé aucune heure : une seule heure suffit à être compté comme actif occupé.', 1),
    ('3e845159-a896-5f28-ae38-ff2e0fba2af2'::uuid, 'ses', 'Tle', 'Définir et mesurer le chômage', 'Dans quel délai un chômeur au sens du BIT doit-il être disponible pour travailler ?', 'mcq', '["24 heures","Trois mois","Deux semaines","Un an"]'::jsonb, 2, 'Il doit être disponible dans les deux semaines et avoir cherché activement un emploi dans le mois précédent.', 2),
    ('0edd96b5-5f51-5ad3-a965-5958ead9bf77'::uuid, 'ses', 'Tle', 'Définir et mesurer le chômage', 'Comment se compose la population active ?', 'mcq', '["De la population en âge de travailler","Des seuls actifs occupés","Des chômeurs et des inactifs","Des actifs occupés et des chômeurs"]'::jsonb, 3, 'Population active = actifs occupés + chômeurs : c’est à elle qu’on rapporte le nombre de chômeurs.', 3),
    ('8d8d446b-db01-5bdc-a55a-cc2ec9a9d4fe'::uuid, 'ses', 'Tle', 'Définir et mesurer le chômage', 'Quel avantage a le chiffre des chômeurs BIT sur celui des inscrits à France Travail ?', 'mcq', '["Il est le seul comparable au niveau international","Il est publié chaque mois","Il vient d’une démarche administrative","Il se découpe en catégories A, B, C"]'::jsonb, 0, 'Mesuré par l’enquête Emploi selon des critères communs, le chômage BIT permet les comparaisons entre pays.', 4),
    ('ac3c8e12-1041-5c52-aa13-f97c8dd8f18e'::uuid, 'ses', 'Tle', 'Comment expliquer le chômage ?', 'Pourquoi, selon l’analyse néoclassique, le salaire minimum peut-il créer du chômage ?', 'mcq', '["Il réduit la demande globale","Il accroît le temps de recherche","Il exclut ceux dont la productivité lui est inférieure","Il décourage la formation"]'::jsonb, 2, 'Si le salaire minimum dépasse la productivité de certains travailleurs, les employeurs ne les embauchent pas.', 1),
    ('9ada6ebf-f265-57e0-a44f-62fdf2a78ad5'::uuid, 'ses', 'Tle', 'Comment expliquer le chômage ?', 'Pourquoi la théorie du salaire d’efficience compte-t-elle dans le débat ?', 'mcq', '["Elle montre que le chômage est volontaire","Elle explique un chômage durable sans aucune rigidité imposée","Elle justifie la suppression du salaire minimum","Elle est d’inspiration keynésienne"]'::jsonb, 1, 'L’employeur paie volontairement au-dessus du marché : le chômage persiste sans contrainte extérieure, une objection interne au raisonnement néoclassique.', 2),
    ('6ec8607f-303a-5cd9-8d10-71447cc73bfa'::uuid, 'ses', 'Tle', 'Comment expliquer le chômage ?', 'Des emplois vacants loin des lieux où vivent les chômeurs illustrent…', 'mcq', '["le chômage keynésien","le coin fiscalo-social","l’hystérésis","une inadéquation géographique"]'::jsonb, 3, 'Quand bassins d’emploi et lieux de résidence sont disjoints, le chômage est structurel et géographique.', 3),
    ('acebcedf-41da-57bd-899c-b0e25e7e9606'::uuid, 'ses', 'Tle', 'Comment expliquer le chômage ?', 'Pourquoi l’hystérésis plaide-t-elle pour une réaction rapide aux récessions ?', 'mcq', '["Parce que le coût d’attendre devient permanent","Parce que les récessions s’aggravent toujours","Parce que la dette publique baisse en récession","Parce que les salaires augmentent en récession"]'::jsonb, 0, 'Un chômage conjoncturel long dégrade compétences et réseaux et devient structurel : ce qu’on laisse durer ne se rattrape pas.', 4),
    ('04e5048c-4c49-56f7-aff2-126fff133e23'::uuid, 'ses', 'Tle', 'Les politiques de lutte contre le chômage', 'Quelle est la principale limite des politiques de formation ?', 'mcq', '["Leurs effets d’aubaine","Les fuites vers les importations","Des effets lents","La trappe à bas salaires"]'::jsonb, 2, 'La formation a les effets les plus durables selon les évaluations, mais aussi les plus lents.', 1),
    ('412e8e0c-c3f6-53b1-bf02-d4b749c0156b'::uuid, 'ses', 'Tle', 'Les politiques de lutte contre le chômage', 'Qu’ont établi les évaluations sur la flexibilisation du marché du travail ?', 'mcq', '["Une hausse certaine du niveau d’emploi","Un effet établi sur la rotation de l’emploi, discuté sur son niveau","Une baisse de la rotation des emplois","Aucun effet d’aucune sorte"]'::jsonb, 1, 'Assouplir accélère les entrées et sorties d’emploi ; l’effet sur le nombre total d’emplois reste débattu.', 2),
    ('1ad40c17-a5db-5c07-9937-eb090a02ef32'::uuid, 'ses', 'Tle', 'Les politiques de lutte contre le chômage', 'Laquelle de ces mesures est une politique passive de l’emploi ?', 'mcq', '["Un emploi aidé","Une formation","Une aide à la mobilité","L’assurance chômage"]'::jsonb, 3, 'Les politiques passives indemnisent (assurance chômage, préretraites) ; les actives agissent sur l’emploi lui-même.', 3),
    ('c83a02e3-4833-5b9d-ab74-20c50eac59cf'::uuid, 'ses', 'Tle', 'Les politiques de lutte contre le chômage', 'Selon les évaluations, qu’est-ce qui raccourcit le plus le retour à l’emploi ?', 'mcq', '["Un accompagnement intensif","La suppression des indemnités","La baisse du salaire minimum","La hausse des taux directeurs"]'::jsonb, 0, 'L’indemnisation est un arbitrage ; ce que les évaluations montrent surtout, c’est l’efficacité d’un suivi intensif des chômeurs.', 4),
    ('8989d340-3522-5075-947a-1050e7dcf928'::uuid, 'ses', 'Tle', 'Les caractéristiques de la crise financière des années 1930 et de celle de 2008', 'En 2008, sur quel marché la bulle s’était-elle formée ?', 'mcq', '["La Bourse de New York","L’immobilier américain","Le marché du pétrole","Les dettes souveraines européennes"]'::jsonb, 1, 'En 1929, la bulle était boursière ; en 2008, immobilière, alimentée par les crédits subprimes.', 1),
    ('00b66a4d-7426-53fa-a243-7c66a25216a8'::uuid, 'ses', 'Tle', 'Les caractéristiques de la crise financière des années 1930 et de celle de 2008', 'Quel taux de chômage les États-Unis ont-ils atteint après 1929 ?', 'mcq', '["Environ 5 %","Environ 10 %","Environ 25 %","Environ 50 %"]'::jsonb, 2, 'Le chômage a touché un actif américain sur quatre, contre environ 10 % après 2008.', 2),
    ('86070e68-5dba-59d2-b9b2-5d52fea7814b'::uuid, 'ses', 'Tle', 'Les caractéristiques de la crise financière des années 1930 et de celle de 2008', 'Pourquoi les stabilisateurs automatiques n’ont-ils pas amorti la crise de 1929 ?', 'mcq', '["Ils ont été suspendus","Ils étaient jugés trop coûteux","Ils ne jouent qu’en période d’inflation","Ils n’existaient pas encore"]'::jsonb, 3, 'Allocations chômage et impôts progressifs, qui soutiennent les revenus en récession, n’existaient pas à cette échelle en 1929.', 3),
    ('37acb36c-ece8-5be1-97b5-990a8c4656ee'::uuid, 'ses', 'Tle', 'Les caractéristiques de la crise financière des années 1930 et de celle de 2008', 'Comment le sauvetage des banques a-t-il nourri la crise des dettes souveraines ?', 'mcq', '["En transférant la dette privée vers les États","En faisant baisser les impôts","En relevant les taux de la BCE","En supprimant l’euro"]'::jsonb, 0, 'En sauvant les banques, les États ont repris leurs pertes : la dette privée est devenue publique, d’où la crise de 2010-2012.', 4),
    ('e4fc03d5-a26f-574b-bb74-8c1a78b714c2'::uuid, 'ses', 'Tle', 'Bulles spéculatives et faillites bancaires', 'Qu’est-ce que la valeur fondamentale d’un actif ?', 'mcq', '["Son prix de marché du jour","La somme actualisée des revenus qu’il rapportera","Son prix d’achat initial","Le prix que les autres anticipent"]'::jsonb, 1, 'La bulle est un écart durable entre le prix et cette valeur fondamentale : on achète pour revendre plus cher.', 1),
    ('76e08325-bed3-5d9b-9ed1-b11830afc2a0'::uuid, 'ses', 'Tle', 'Bulles spéculatives et faillites bancaires', 'Un investisseur apporte 10 et emprunte 90 pour acheter un actif de 100. Le prix baisse de 10 %. Que se passe-t-il ?', 'mcq', '["Il perd 1 % de son apport","Il perd 10 % de son apport","Son apport est entièrement perdu","Il gagne grâce au levier"]'::jsonb, 2, 'L’actif ne vaut plus que 90, juste de quoi rembourser la dette : l’apport de 10 a disparu. Le levier amplifie les pertes.', 2),
    ('783d1652-6298-59c9-9e46-c5b7dbb34e35'::uuid, 'ses', 'Tle', 'Bulles spéculatives et faillites bancaires', 'Pourquoi une banque solvable peut-elle tomber lors d’un retrait de panique ?', 'mcq', '["Parce qu’elle a perdu tous ses fonds propres","Parce qu’elle a prêté à l’État","Parce qu’elle est surveillée par la BCE","Parce qu’elle a transformé des dépôts courts en crédits longs"]'::jsonb, 3, 'Solvable à long terme, la banque est illiquide à court terme : elle ne peut pas rendre d’un coup des dépôts prêtés sur des années.', 3),
    ('db0d5636-acc0-5c36-a342-81d78bf7bc2e'::uuid, 'ses', 'Tle', 'Bulles spéculatives et faillites bancaires', 'Quel canal de propagation vient de ce que les banques se prêtent entre elles ?', 'mcq', '["Le risque de contrepartie","La sélection adverse","Le canal du crédit","Le concours de beauté"]'::jsonb, 0, 'Les banques se détiennent mutuellement : la faillite de l’une menace celles qui lui ont prêté.', 4),
    ('dad9986b-f407-5295-a15a-d97bef606b3a'::uuid, 'ses', 'Tle', 'Les instruments de régulation monétaire', 'Quel mandat distingue la Réserve fédérale de la BCE ?', 'mcq', '["La seule stabilité des prix","L’équilibre budgétaire","Un double mandat : prix stables et plein emploi","Un taux de change fixe"]'::jsonb, 2, 'La Fed vise à la fois les prix et l’emploi ; la BCE a pour objectif principal la stabilité des prix.', 1),
    ('37f1f94d-a510-5b83-ae31-25bd3106019b'::uuid, 'ses', 'Tle', 'Les instruments de régulation monétaire', 'Que fait une banque centrale avec la forward guidance ?', 'mcq', '["Elle achète des actions d’entreprises","Elle annonce à l’avance la trajectoire de ses taux","Elle fixe les salaires","Elle garantit les dépôts"]'::jsonb, 1, 'Annoncer la trajectoire future des taux ancre les anticipations : un instrument non conventionnel quand les taux sont à zéro.', 2),
    ('2a1fdc79-2605-55be-bb7a-b2c14808e581'::uuid, 'ses', 'Tle', 'Les instruments de régulation monétaire', 'Selon la règle de Bagehot, le prêteur en dernier ressort doit prêter…', 'mcq', '["sans condition à toutes les banques","à taux nul, sans garantie","uniquement aux banques insolvables","largement, à un taux de pénalité, contre de bonnes garanties"]'::jsonb, 3, 'Ces trois conditions évitent que le sauvetage devienne une prime à l’imprudence.', 3),
    ('2ad71836-4853-53c2-97d2-3d7ea2254484'::uuid, 'ses', 'Tle', 'Les instruments de régulation monétaire', 'Quand les banques doivent-elles constituer le coussin contracyclique ?', 'mcq', '["En haut de cycle","En pleine récession","Pendant un retrait de panique","Seulement en cas de déflation"]'::jsonb, 0, 'Le coussin se constitue quand tout va bien, pour être mobilisé quand le cycle se retourne.', 4),
    ('4799a01b-3854-53e2-b235-778986c58854'::uuid, 'ses', 'Tle', 'Le processus d’intégration européenne', 'Selon Balassa, quel degré d’intégration suit immédiatement l’union douanière ?', 'mcq', '["La zone de libre-échange","Le marché commun","L’union monétaire","L’union économique"]'::jsonb, 1, 'L’ordre est : zone de libre-échange, union douanière, marché commun, union économique, union monétaire.', 1),
    ('44a5a9ec-b463-5144-8df2-65f745695fa3'::uuid, 'ses', 'Tle', 'Le processus d’intégration européenne', 'En quelle année la CEE a-t-elle été créée ?', 'mcq', '["1945","1968","1957","1992"]'::jsonb, 2, 'La CEE naît en 1957 ; suivent l’union douanière (1968), le marché unique, Maastricht (1992) et l’euro.', 2),
    ('97e6ffd3-6848-59f4-b7cc-207328369a2a'::uuid, 'ses', 'Tle', 'Le processus d’intégration européenne', 'Quel est le rôle de la politique de cohésion européenne ?', 'mcq', '["Interdire les fusions","Fixer les taux directeurs","Harmoniser les salaires","Redistribuer vers les régions les moins riches"]'::jsonb, 3, 'La cohésion redistribue vers les régions moins riches ; la politique de concurrence, elle, peut interdire une fusion.', 3),
    ('856a77ae-1ac6-5eeb-819c-ebe9aaa24282'::uuid, 'ses', 'Tle', 'Le processus d’intégration européenne', 'Quelle condition de Mundell la zone euro remplit-elle mal, pour des raisons de langue, de diplômes et de logement ?', 'mcq', '["La mobilité du travail","La stabilité des prix","La transparence des prix","La fin du risque de change"]'::jsonb, 0, 'La mobilité du travail reste faible en Europe : un pays touché par un choc ne peut guère compter sur le départ de ses chômeurs.', 4),
    ('de2bc708-48e1-59dd-b06c-69af819a5a91'::uuid, 'ses', 'Tle', 'La gestion de la politique économique européenne : une coordination difficile', 'Pour un pays en récession, le taux directeur unique de la BCE est souvent…', 'mcq', '["trop bas","parfaitement adapté","trop élevé","fixé par son gouvernement"]'::jsonb, 2, 'Adapté à la moyenne de la zone, le taux unique est trop élevé pour le pays en récession et trop bas pour celui en surchauffe.', 1),
    ('716e98fc-82a1-56e8-a942-8f386f31192d'::uuid, 'ses', 'Tle', 'La gestion de la politique économique européenne : une coordination difficile', 'Pourquoi chaque État peut-il attendre que son voisin relance ?', 'mcq', '["Parce que la BCE interdit les relances","Parce qu’une relance profite aux voisins par les importations","Parce que les traités imposent un ordre de relance","Parce qu’une relance fait baisser les exportations des voisins"]'::jsonb, 1, 'Une partie de la relance fuit vers les importations : chacun a intérêt à laisser l’autre payer, c’est le passager clandestin.', 2),
    ('c9dfa185-4bf2-5e96-99ea-88f93c20a5d5'::uuid, 'ses', 'Tle', 'La gestion de la politique économique européenne : une coordination difficile', 'À quoi renvoie le « whatever it takes » de 2012 ?', 'mcq', '["Au plan de relance européen","À la suspension du pacte de stabilité","À la création de l’euro","À l’engagement de la BCE à tout faire pour préserver l’euro"]'::jsonb, 3, 'Cette déclaration de la BCE a calmé la crise des dettes souveraines : son action a été de fait décisive dans la coordination.', 3),
    ('982ef2c0-0354-5dfb-bcf1-c3f5dd1373b2'::uuid, 'ses', 'Tle', 'La gestion de la politique économique européenne : une coordination difficile', 'Quel diagnostic relève de la lecture « défaut d’architecture » ?', 'mcq', '["L’absence de budget fédéral et de transferts automatiques","Certains États n’ont pas tenu leurs engagements","Des salaires trop élevés partout","Une inflation trop forte"]'::jsonb, 0, 'La lecture « architecture » met en cause la construction : pas de budget fédéral, ni de mutualisation, ni de transferts automatiques.', 4),
    ('8690b105-1c95-584c-bf6b-4d5705eadf65'::uuid, 'ses', 'Tle', 'Structuration de l’espace social', 'Qu’est-ce qui distingue le revenu du patrimoine ?', 'mcq', '["Le revenu est un stock, le patrimoine un flux","Le revenu est un flux, le patrimoine un stock","Les deux sont des flux","Le patrimoine ne comprend que l’immobilier"]'::jsonb, 1, 'Le revenu arrive sur une période (flux) ; le patrimoine est ce que l’on possède à un moment donné (stock).', 1),
    ('602570ca-05ec-5bb8-85c4-eeb3e8dfd78b'::uuid, 'ses', 'Tle', 'Structuration de l’espace social', 'Lequel de ces groupes fait partie des six grands groupes de PCS ?', 'mcq', '["Les classes moyennes","Les travailleurs précaires","Les professions intermédiaires","Les dirigeants du public"]'::jsonb, 2, 'Les six groupes : agriculteurs ; artisans, commerçants, chefs d’entreprise ; cadres ; professions intermédiaires ; employés ; ouvriers.', 2),
    ('3038da14-ff50-5ed0-b899-6b6016f4cd3c'::uuid, 'ses', 'Tle', 'Structuration de l’espace social', 'Quelle limite de la nomenclature des PCS concerne les femmes ?', 'mcq', '["Elle les excluait de la population active","Elle leur réservait un groupe à part","Elle ne comptait pas les employées","Elle les a longtemps classées d’après la profession de leur conjoint"]'::jsonb, 3, 'Classer une femme d’après son conjoint masquait sa propre position professionnelle.', 3),
    ('4f69e2b1-1724-5a2a-a867-2178a746d236'::uuid, 'ses', 'Tle', 'Structuration de l’espace social', 'Chez Weber, à quel ordre correspondent les partis ?', 'mcq', '["À l’ordre politique","À l’ordre économique","À l’ordre social","À l’ordre religieux"]'::jsonb, 0, 'Classes (économique), groupes de statut (social) et partis (politique) : trois hiérarchies qui ne se recouvrent pas.', 4),
    ('70f98b22-9eeb-59fc-bb5d-c738825584a7'::uuid, 'ses', 'Tle', 'L’évolution de la structure sociale en France depuis la seconde moitié du XXe siècle', 'Vers 1950, quelle part d’une génération obtenait le baccalauréat ?', 'mcq', '["Environ 30 %","Moins de 10 %","Environ 50 %","Environ 80 %"]'::jsonb, 1, 'Moins de 10 % d’une génération était bachelière en 1950, contre environ 80 % aujourd’hui.', 1),
    ('eebe34bf-9355-5d2c-a4fa-e5bc61159d35'::uuid, 'ses', 'Tle', 'L’évolution de la structure sociale en France depuis la seconde moitié du XXe siècle', 'Quelle part des actifs les ouvriers représentent-ils encore aujourd’hui ?', 'mcq', '["Environ un sur deux","Moins d’un sur vingt","Environ un sur cinq","Environ deux sur cinq"]'::jsonb, 2, 'Le groupe ouvrier est passé d’environ 40 % à environ 20 % des actifs : moins visible, mais toujours un actif sur cinq.', 2),
    ('110579ca-4a81-5cb5-8fa9-ffcf0b80e72c'::uuid, 'ses', 'Tle', 'L’évolution de la structure sociale en France depuis la seconde moitié du XXe siècle', 'À quel sociologue la thèse de la moyennisation est-elle associée ?', 'mcq', '["Bourdieu","Marx","Boudon","Mendras"]'::jsonb, 3, 'Henri Mendras décrit, pour les années 1960-1970, une vaste classe moyenne qui absorbe les extrêmes.', 3),
    ('a161bb19-b8a8-5e1a-aa63-1776a2f861c0'::uuid, 'ses', 'Tle', 'L’évolution de la structure sociale en France depuis la seconde moitié du XXe siècle', 'Comment a évolué le taux d’activité des femmes de 25 à 49 ans depuis les années 1960 ?', 'mcq', '["D’environ 40 % à plus de 80 %","D’environ 10 % à 30 %","Il est resté stable autour de 60 %","Il a diminué"]'::jsonb, 0, 'L’activité féminine a doublé, mais l’emploi des femmes reste concentré dans certains secteurs et plus souvent à temps partiel.', 4),
    ('f6fc8cd1-dafc-5e03-bb48-1d281a009a27'::uuid, 'ses', 'Tle', 'Les théories des classes sociales', 'Chez Marx, quelles sont les deux classes en conflit ?', 'mcq', '["Les cadres et les employés","La noblesse et le clergé","La bourgeoisie et le prolétariat","Les urbains et les ruraux"]'::jsonb, 2, 'La bourgeoisie possède les moyens de production, le prolétariat ne dispose que de sa force de travail.', 1),
    ('2a175121-44a8-5e90-a235-15722f8b63c1'::uuid, 'ses', 'Tle', 'Les théories des classes sociales', 'Selon le cours, le passage de la classe en soi à la classe pour soi est…', 'mcq', '["automatique","le produit d’un travail politique","impossible par définition","décidé par l’État"]'::jsonb, 1, 'Une position objective partagée ne devient conscience commune et action collective que par un travail politique.', 2),
    ('60378f4f-2761-560c-aff2-1e21b307c1db'::uuid, 'ses', 'Tle', 'Les théories des classes sociales', 'Chez Bourdieu, qu’est-ce que la distinction ?', 'mcq', '["La réussite scolaire","L’écart de revenu entre classes","Le prestige d’un métier","Le travail permanent de démarcation par les pratiques culturelles"]'::jsonb, 3, 'Les classes se distinguent par leurs goûts et pratiques culturelles, qui marquent leur position.', 3),
    ('f3b43d14-7421-5b53-88bd-0d8cb7635b49'::uuid, 'ses', 'Tle', 'Les théories des classes sociales', 'Un professeur au prestige élevé mais au revenu modeste illustre, chez Weber…', 'mcq', '["le non-recouvrement des ordres économique et social","la lutte des classes","l’habitus","la classe pour soi"]'::jsonb, 0, 'Chez Weber, la position économique et le prestige social sont deux hiérarchies distinctes qui peuvent diverger.', 4),
    ('892b7894-ca53-54e4-9bd2-004e73e05148'::uuid, 'ses', 'Tle', 'La massification scolaire depuis les années 1950', 'Que prévoit la réforme Berthoin de 1959 ?', 'mcq', '["Le collège unique","La scolarité obligatoire jusqu’à 16 ans","La création du bac professionnel","L’objectif de 80 % d’une génération au niveau du bac"]'::jsonb, 1, 'Berthoin (1959) porte l’obligation scolaire à 16 ans ; Haby crée le collège unique en 1975.', 1),
    ('612894b6-90d1-57ca-b20a-5da01e1eff78'::uuid, 'ses', 'Tle', 'La massification scolaire depuis les années 1950', 'Quelle mesure date de 1985 ?', 'mcq', '["Le collège unique","La scolarité obligatoire à 16 ans","La création du bac professionnel et l’objectif de 80 % au niveau du bac","La création des zones d’éducation prioritaire"]'::jsonb, 2, 'En 1985 sont lancés le bac professionnel et l’objectif de 80 % d’une génération au niveau du bac.', 2),
    ('18ee9236-a893-5d5b-ae07-d357cd189e73'::uuid, 'ses', 'Tle', 'La massification scolaire depuis les années 1950', 'Tertiarisation et hausse des qualifications requises relèvent de quel moteur de la massification ?', 'mcq', '["La demande sociale","L’offre publique","La démocratisation","La demande économique"]'::jsonb, 3, 'L’économie réclame plus de qualifications : c’est la demande économique, à côté de la demande sociale et de l’offre publique.', 3),
    ('88328816-034d-52ee-a69b-04f9e9dffd35'::uuid, 'ses', 'Tle', 'La massification scolaire depuis les années 1950', 'Pourquoi dit-on que la dévaluation des diplômes est relative ?', 'mcq', '["Parce que le chômage des non-diplômés reste plusieurs fois supérieur à celui des diplômés du supérieur","Parce que les diplômes ont gardé toute leur valeur","Parce que tous les diplômés gagnent la même chose","Parce que le bac vaut plus qu’en 1950"]'::jsonb, 0, 'Le diplôme rapporte moins qu’avant, mais son absence pénalise toujours fortement : la dévaluation est relative, pas absolue.', 4),
    ('959b6d29-9720-5ab7-8391-542b306d7ded'::uuid, 'ses', 'Tle', 'Une inégalité des chances persistante', 'Sous quelle forme le capital culturel existe-t-il quand il s’agit de diplômes ?', 'mcq', '["Incorporée","Objectivée","Institutionnalisée","Symbolique"]'::jsonb, 2, 'Incorporé (dispositions, langage), objectivé (livres, œuvres), institutionnalisé (diplômes) : trois formes du capital culturel.', 1),
    ('90dacad3-ca07-558c-8779-7eac5f038a0e'::uuid, 'ses', 'Tle', 'Une inégalité des chances persistante', 'Selon Boudon, pourquoi une famille favorisée pousse-t-elle vers les études longues ?', 'mcq', '["Parce qu’elles sont gratuites","Parce qu’il faut ces études pour ne pas déchoir","Parce que le risque d’échec y est nul","Parce que l’École l’impose"]'::jsonb, 1, 'Pour un milieu favorisé, les études longues évitent un déclassement ; pour un milieu modeste, elles représentent un gain, mais coûteux et risqué.', 2),
    ('03969ce0-ffc5-5d8e-8315-4aa88164abe6'::uuid, 'ses', 'Tle', 'Une inégalité des chances persistante', 'Qu’appelle-t-on stratégies d’évitement scolaire ?', 'mcq', '["Le refus de passer le bac","L’absentéisme","Le redoublement volontaire","Le recours aux options rares, au privé ou aux dérogations pour éviter l’établissement de secteur"]'::jsonb, 3, 'Ces stratégies sont mieux maîtrisées par les familles informées, ce qui renforce les inégalités.', 3),
    ('b9f9cefe-0604-5417-a38b-7ebd8ad23c11'::uuid, 'ses', 'Tle', 'Une inégalité des chances persistante', 'En quelle année l’éducation prioritaire (ZEP) a-t-elle été créée ?', 'mcq', '["1981","1975","1959","2002"]'::jsonb, 0, 'Les ZEP datent de 1981 ; elles sont devenues REP et REP+, avec des effets réels mais modestes.', 4),
    ('c3e070e2-ece9-509d-9838-0e5e74a83e24'::uuid, 'ses', 'Tle', 'Qu’est-ce que la mobilité sociale ?', 'Quelle question pose une table de recrutement ?', 'mcq', '["Que deviennent les fils d’ouvriers ?","D’où viennent les cadres ?","Combien y a-t-il de cadres ?","Quel est le salaire moyen des cadres ?"]'::jsonb, 1, 'La table de recrutement part de la position d’arrivée et se lit en colonne : « d’où viennent-ils ? ».', 1),
    ('dabba2bd-45da-57ae-817f-1da6ed502201'::uuid, 'ses', 'Tle', 'Qu’est-ce que la mobilité sociale ?', 'Qu’est-ce que la mobilité intragénérationnelle ?', 'mcq', '["La comparaison entre la position d’un enfant et celle de ses parents","Un changement de groupe sans changement de niveau","La comparaison de deux moments de la carrière d’une même personne","L’absence de mobilité"]'::jsonb, 2, 'L’intragénérationnelle suit une même personne ; l’INSEE mesure surtout l’intergénérationnelle, parent contre enfant.', 2),
    ('9e47a2cc-8c41-551e-a02b-a393e9d232a8'::uuid, 'ses', 'Tle', 'Qu’est-ce que la mobilité sociale ?', 'Quel était le cas de la France des Trente Glorieuses ?', 'mcq', '["Une forte fluidité mais peu de mobilité observée","Aucune mobilité","Une mobilité surtout descendante","Beaucoup de mobilité observée et très peu de fluidité"]'::jsonb, 3, 'La transformation des emplois imposait beaucoup de mobilité structurelle, sans que la fluidité réelle soit forte.', 3),
    ('6b3d60d4-f666-506e-8b61-d5e1eba8f1e2'::uuid, 'ses', 'Tle', 'Qu’est-ce que la mobilité sociale ?', 'Pourquoi un ouvrier qualifié devenu non qualifié n’apparaît-il pas dans une table de mobilité ?', 'mcq', '["Parce que la mobilité à l’intérieur d’un même groupe est invisible","Parce que les ouvriers ne sont pas comptés","Parce qu’il devient inactif","Parce qu’il est compté comme employé"]'::jsonb, 0, 'Les tables reposent sur les grands groupes de PCS : un mouvement au sein du même groupe n’y figure pas.', 4),
    ('890ca0aa-4d91-5c7b-b0df-4dc12d287879'::uuid, 'ses', 'Tle', 'L’évolution de la mobilité sociale', 'Quelles enquêtes de l’INSEE suivent la mobilité sociale depuis les années 1970 ?', 'mcq', '["Les enquêtes Emploi","Le recensement","Les enquêtes FQP","Les enquêtes Budget de famille"]'::jsonb, 2, 'Les enquêtes Formation et qualification professionnelle (FQP) comparent la position des individus à celle de leurs parents.', 1),
    ('e2f4541d-485c-5db5-a5ca-8e44e8222235'::uuid, 'ses', 'Tle', 'L’évolution de la mobilité sociale', 'Quel est l’effet d’une entrée sur le marché du travail en pleine récession ?', 'mcq', '["Aucun effet durable","Une promotion plus rapide","Une protection contre le déclassement","Une trace sur toute la carrière"]'::jsonb, 3, 'La conjoncture à l’entrée dans la vie active pèse durablement sur les trajectoires : c’est l’un des cinq facteurs de la mobilité.', 2),
    ('37e99fd9-6bbc-550d-a094-c4c69a6b71c2'::uuid, 'ses', 'Tle', 'L’évolution de la mobilité sociale', 'Le déclassement intergénérationnel augmente surtout pour les enfants…', 'mcq', '["des agriculteurs","des classes moyennes","des ouvriers","des indépendants"]'::jsonb, 1, 'Faute d’une expansion suffisante des places qualifiées, les enfants des classes moyennes descendent plus souvent qu’avant.', 3),
    ('a399e624-ea47-53ed-a98a-5b07ac4125e7'::uuid, 'ses', 'Tle', 'L’évolution de la mobilité sociale', 'Pourquoi la mobilité des femmes paraît-elle plus forte que celle des hommes ?', 'mcq', '["La structure des emplois féminins s’est transformée plus vite","Le plafond de verre a disparu","Les tables ne comptent pas les femmes","Les femmes changent plus souvent d’entreprise"]'::jsonb, 0, 'La mutation rapide des emplois féminins crée de la mobilité, mais le plafond de verre limite toujours l’accès aux postes dirigeants.', 4),
    ('418ef622-76d5-5d60-8f9f-062b9805ee6c'::uuid, 'ses', 'Tle', 'L’évolution des formes de l’emploi', 'Qu’est-ce qui distingue l’emploi du travail ?', 'mcq', '["Ce sont deux synonymes","Le travail est toujours salarié","L’emploi est le cadre juridique et social dans lequel s’exerce le travail","L’emploi désigne seulement le CDI"]'::jsonb, 2, 'Le travail est une activité de production ; l’emploi en est le cadre, et c’est lui qui a le plus changé.', 1),
    ('ba374fbc-b183-559c-b9c2-62123a23495a'::uuid, 'ses', 'Tle', 'L’évolution des formes de l’emploi', 'Environ quelle part des actifs occupés sont des travailleurs pauvres ?', 'mcq', '["Un sur deux","Un sur vingt","Un sur cinq","Un sur cent"]'::jsonb, 1, 'Occupés mais sous le seuil de pauvreté, les travailleurs pauvres représentent environ un actif occupé sur vingt.', 2),
    ('fa15ff02-8ed4-5139-aa5e-29ee29c43a94'::uuid, 'ses', 'Tle', 'L’évolution des formes de l’emploi', 'Quels publics sont surreprésentés sur le marché secondaire du travail ?', 'mcq', '["Les cadres supérieurs","Les fonctionnaires titulaires","Les chefs d’entreprise","Les jeunes, les femmes et les peu diplômés"]'::jsonb, 3, 'Le marché secondaire concentre les emplois instables et peu qualifiés, où ces publics sont surreprésentés.', 3),
    ('976dd1fc-dc43-5a58-8004-3b7fe32f74c9'::uuid, 'ses', 'Tle', 'L’évolution des formes de l’emploi', 'Pourquoi les services peu qualifiés (aide à domicile, nettoyage) progressent-ils ?', 'mcq', '["Ils sont difficilement automatisables","Ils sont très bien rémunérés","Ils se délocalisent facilement","Ils exigent un diplôme élevé"]'::jsonb, 0, 'C’est le bas de la polarisation : ces tâches résistent à l’automatisation et à la délocalisation, contrairement aux emplois intermédiaires.', 4),
    ('9c1e4e58-d2b8-5e14-9603-2add207956a0'::uuid, 'ses', 'Tle', 'L’organisation du travail : quels modèles ?', 'Que désigne la division horizontale du travail chez Taylor ?', 'mcq', '["La séparation entre conception et exécution","La décomposition du travail en tâches élémentaires, répétitives et chronométrées","La hiérarchie des salaires","La polyvalence des opérateurs"]'::jsonb, 1, 'La division verticale sépare concevoir et exécuter ; l’horizontale découpe l’exécution en tâches simples.', 1),
    ('f890a0ff-cfa6-530f-b73a-cf64522c5615'::uuid, 'ses', 'Tle', 'L’organisation du travail : quels modèles ?', 'Pourquoi Ford verse-t-il le « five dollars day » ?', 'mcq', '["Pour réduire la productivité","Pour obéir à une loi","Pour retenir la main-d’œuvre et solvabiliser la demande","Pour financer la chaîne de montage"]'::jsonb, 2, 'Un salaire élevé limite le turnover et permet aux ouvriers d’acheter les voitures produites en série.', 2),
    ('a094ef82-8c2d-5827-9016-baf454cb411e'::uuid, 'ses', 'Tle', 'L’organisation du travail : quels modèles ?', 'Quelle est la première maladie professionnelle reconnue ?', 'mcq', '["Le burn-out","Les accidents de trajet","Les allergies","Les troubles musculo-squelettiques"]'::jsonb, 3, 'Les TMS restent la première maladie professionnelle, tandis que les risques psychosociaux progressent.', 3),
    ('af7103aa-7a53-562e-b5ac-b6bdaf488eb6'::uuid, 'ses', 'Tle', 'L’organisation du travail : quels modèles ?', 'Avec l’ubérisation, qui exerce le contrôle du travail ?', 'mcq', '["L’algorithme et la note du client","Le bureau des méthodes","Le contremaître","Le syndicat"]'::jsonb, 0, 'Le contrôle est externalisé : l’application et l’évaluation du client remplacent la hiérarchie directe.', 4),
    ('926b53f6-90fa-5e0d-8a7f-51add4419b3d'::uuid, 'ses', 'Tle', 'L’évolution du lien social dans le monde du travail', 'Chez Durkheim, sur quoi repose la solidarité mécanique ?', 'mcq', '["La ressemblance entre individus","La complémentarité des fonctions","Le contrat de travail","La redistribution par l’État"]'::jsonb, 0, 'La solidarité mécanique, propre aux sociétés traditionnelles, naît de la ressemblance ; l’organique, de la complémentarité.', 1),
    ('9624f961-217e-5e42-bdd1-7d9cbb303bee'::uuid, 'ses', 'Tle', 'L’évolution du lien social dans le monde du travail', 'Qui a montré que le chômage désorganise le rapport au temps et l’identité ?', 'mcq', '["Castel","Schnapper","Durkheim","Gaxie"]'::jsonb, 1, 'Dominique Schnapper a montré que le chômage de longue durée attaque à la fois le revenu, le collectif et l’identité.', 2),
    ('906fbd91-6c54-5aaa-9ffa-1e1511d1f121'::uuid, 'ses', 'Tle', 'L’évolution du lien social dans le monde du travail', 'Quel canal d’intégration le sous-emploi et le déclassement laissent-ils de côté ?', 'mcq', '["Le canal économique (le revenu)","Le canal juridique","Le canal symbolique (la reconnaissance)","Aucun canal"]'::jsonb, 2, 'Le sous-emploi procure un revenu, mais sans la reconnaissance et le statut qui font l’intégration symbolique.', 3),
    ('3ac17cc3-98ee-5912-9693-18b296d18305'::uuid, 'ses', 'Tle', 'L’évolution du lien social dans le monde du travail', 'À quelle condition la division du travail produit-elle la solidarité organique ?', 'mcq', '["Si elle est imposée par l’État","Si tous exercent le même métier","Si les salaires sont égaux","Si elle est non anomique, encadrée par des règles reconnues"]'::jsonb, 3, 'Pour Durkheim, une division du travail sans règles (anomique) ne crée pas de solidarité.', 4),
    ('6f9694c2-f9f5-5496-b2c9-1a3904a596b1'::uuid, 'ses', 'Tle', 'Diverses formes d’engagement citoyen', 'Quel est environ le taux de syndicalisation en France ?', 'mcq', '["Environ 30 %","Environ 10 %","Environ 50 %","Environ 70 %"]'::jsonb, 1, 'Avec environ 10 %, la France a l’un des taux de syndicalisation les plus faibles de l’OCDE.', 1),
    ('d09fbb06-e74d-5ab7-ac49-9e5d0067c904'::uuid, 'ses', 'Tle', 'Diverses formes d’engagement citoyen', 'À quel auteur doit-on l’analyse des rétributions symboliques du militantisme ?', 'mcq', '["Olson","Ion","Gaxie","Inglehart"]'::jsonb, 2, 'Daniel Gaxie montre qu’on gagne à militer autre chose que la cause : sociabilité, reconnaissance, apprentissage.', 2),
    ('2c13e0f9-d1f3-573f-9d38-c2ab56ca8494'::uuid, 'ses', 'Tle', 'Diverses formes d’engagement citoyen', 'Pourquoi un petit groupe se mobilise-t-il plus facilement qu’un grand, selon Olson ?', 'mcq', '["Ses membres sont plus riches","Il reçoit des subventions","Il est protégé par la loi","L’abstention de chacun s’y voit"]'::jsonb, 3, 'Dans un petit groupe, le passager clandestin est repéré : la pression des autres limite la défection.', 3),
    ('3d797bc9-2767-5d6d-af56-dce3b51a3849'::uuid, 'ses', 'Tle', 'Diverses formes d’engagement citoyen', 'Le recul des partis et des syndicats signifie-t-il un recul de l’engagement ?', 'mcq', '["Non : l’engagement se transforme, plus ponctuel et centré sur des causes","Oui : les Français ne s’engagent plus","Oui : seul le vote subsiste","Non : les partis n’ont jamais eu d’adhérents"]'::jsonb, 0, 'Le recul des organisations n’est pas celui de l’engagement : le confondre est l’erreur d’interprétation la plus fréquente.', 4),
    ('563393f0-adfb-54f6-bc92-93c928ae3e6c'::uuid, 'ses', 'Tle', 'L’évolution des formes de l’action collective', 'Quel trait partagent souvent les acteurs des nouveaux mouvements sociaux ?', 'mcq', '["Ils sont plus diplômés, souvent issus des classes moyennes","Ce sont surtout des ouvriers d’industrie","Ce sont des chefs d’entreprise","Ils sont majoritairement retraités"]'::jsonb, 0, 'Ces mouvements recrutent des acteurs diplômés, dans des organisations souples, avec un rapport privilégié aux médias.', 1),
    ('6b2aced5-178e-5586-9b28-a07535d272f7'::uuid, 'ses', 'Tle', 'L’évolution des formes de l’action collective', 'Pourquoi les Gilets jaunes brouillent-ils l’opposition entre anciens et nouveaux mouvements sociaux ?', 'mcq', '["Ils sont exclusivement syndicaux","Ils conjuguent pouvoir d’achat et demande de reconnaissance","Ils portent sur les seuls droits des minorités","Ils n’ont formulé aucune revendication"]'::jsonb, 1, 'Ils mêlent un enjeu de répartition et un enjeu d’identité : les deux objets ne s’excluent pas.', 2),
    ('5aeedcae-477f-54bc-9476-047818f8da81'::uuid, 'ses', 'Tle', 'L’évolution des formes de l’action collective', 'Comment se sont transformés les conflits du travail ?', 'mcq', '["Ils ont disparu","Ils se limitent aux grèves générales","Ils se sont individualisés et diversifiés : prud’hommes, débrayages courts","Ils sont devenus illégaux"]'::jsonb, 2, 'Les journées de grève ont reculé, mais le conflit passe par les recours prud’homaux, les débrayages, le refus d’heures supplémentaires.', 3),
    ('65b1f021-4ffb-5860-822c-94b907ab7482'::uuid, 'ses', 'Tle', 'L’évolution des formes de l’action collective', 'Dans le modèle classique du conflit du travail, qui est l’adversaire ?', 'mcq', '["L’État","Les médias","Les consommateurs","L’employeur"]'::jsonb, 3, 'Syndicats structurés face à un employeur identifié, autour de la répartition : c’est la forme dominante jusqu’aux années 1970.', 4),
    ('accee579-8cad-53f1-886b-b43c88cb20cd'::uuid, 'ses', 'Tle', 'Des inégalités multiformes et cumulatives', 'Quelle part du patrimoine les 10 % les mieux dotés détiennent-ils environ en France ?', 'mcq', '["Environ 10 %","Environ un quart","Environ la moitié","La quasi-totalité"]'::jsonb, 2, 'Les 10 % les mieux dotés détiennent environ la moitié du patrimoine, les 50 % les moins dotés moins de 10 %.', 1),
    ('e5c41146-2a9a-5ea3-a8c7-1a3422eabc15'::uuid, 'ses', 'Tle', 'Des inégalités multiformes et cumulatives', 'Pourquoi préfère-t-on la médiane à la moyenne pour décrire le milieu d’une distribution ?', 'mcq', '["La médiane inclut le patrimoine","La moyenne est tirée par les valeurs extrêmes","La moyenne ignore les pauvres","La médiane se calcule plus vite"]'::jsonb, 1, 'Quelques très hauts revenus suffisent à gonfler la moyenne ; la médiane partage la population en deux moitiés.', 2),
    ('3862a1df-e12c-5197-a64c-391240a000fd'::uuid, 'ses', 'Tle', 'Des inégalités multiformes et cumulatives', 'Quelle mesure de la pauvreté est retenue en Europe ?', 'mcq', '["La pauvreté absolue","Le nombre de bénéficiaires du RSA","La pauvreté relative","Le taux de chômage"]'::jsonb, 2, 'L’Europe mesure la distance au niveau de vie habituel de la société : la pauvreté relative.', 3),
    ('9f58e6d6-49c4-544d-86ef-0c9736ea39f5'::uuid, 'ses', 'Tle', 'Des inégalités multiformes et cumulatives', 'Avec quoi juge-t-on qu’une inégalité est juste ou injuste ?', 'mcq', '["Avec l’indice de Gini","Avec le seuil de pauvreté","Avec la moyenne des revenus","Avec une conception de la justice"]'::jsonb, 3, 'Une inégalité se constate avec des données et se juge avec une conception de la justice, dans cet ordre.', 4),
    ('e2119052-93bf-5cb3-9f35-ef24c45cc427'::uuid, 'ses', 'Tle', 'La mesure des inégalités économiques : une diversité d’outils', 'Quelle est environ la valeur du rapport D9/D1 en France après redistribution ?', 'mcq', '["Environ 1,2","Environ 3,4","Environ 10","Environ 22"]'::jsonb, 1, 'La redistribution fait passer le rapport interdécile d’environ 22 à environ 3,4.', 1),
    ('3ce88a2e-e43f-5e52-b033-29af1a8900ed'::uuid, 'ses', 'Tle', 'La mesure des inégalités économiques : une diversité d’outils', 'Combien de seuils séparent les déciles d’une distribution ?', 'mcq', '["Dix","Cent","Neuf, de D1 à D9","Quatre"]'::jsonb, 2, 'Dix parts égales sont séparées par neuf seuils, notés D1 à D9.', 2),
    ('e332963a-fbb4-5ff5-ad97-217d186a4526'::uuid, 'ses', 'Tle', 'La mesure des inégalités économiques : une diversité d’outils', 'Que signifie un indice de Gini égal à 1 ?', 'mcq', '["L’égalité parfaite","La moitié de la population est pauvre","Le revenu moyen a doublé","Une seule personne détient tout"]'::jsonb, 3, 'Le Gini va de 0 (égalité parfaite) à 1 (concentration totale).', 3),
    ('b3026d88-e945-52c2-9724-28269a015482'::uuid, 'ses', 'Tle', 'La mesure des inégalités économiques : une diversité d’outils', 'Sur un graphique de Lorenz, que représente la diagonale ?', 'mcq', '["L’égalité parfaite","L’inégalité maximale","Le seuil de pauvreté","La médiane"]'::jsonb, 0, 'Plus la courbe de Lorenz s’écarte de la diagonale, plus la distribution est inégalitaire.', 4),
    ('53a94d35-b021-5158-89de-952b6d20fe22'::uuid, 'ses', 'Tle', 'Pouvoirs publics et justice sociale', 'Quelle conception de l’égalité vise à réduire les écarts eux-mêmes ?', 'mcq', '["L’égalité des droits","L’égalité des chances","L’égalité des situations","L’égalité devant la loi"]'::jsonb, 2, 'L’égalité des situations agit sur les écarts, pas seulement sur les règles ou les conditions d’accès.', 1),
    ('ed668905-c09a-594b-a6f5-bacbf8150501'::uuid, 'ses', 'Tle', 'Pouvoirs publics et justice sociale', 'Chez Rawls, sous quel dispositif les principes de justice sont-ils choisis ?', 'mcq', '["La main invisible","Le voile d’ignorance","Le calcul d’utilité","Le contrat de travail"]'::jsonb, 1, 'Sans savoir quelle place on occupera, on choisit l’égale liberté puis le principe de différence.', 2),
    ('217ca917-60e1-57cd-b5f3-89fb61a5157b'::uuid, 'ses', 'Tle', 'Pouvoirs publics et justice sociale', 'Lequel de ces dispositifs relève de l’assistance ?', 'mcq', '["L’assurance chômage","La retraite","L’assurance maladie","Le RSA"]'::jsonb, 3, 'L’assurance couvre un risque en échange de cotisations ; l’assistance (RSA, minima sociaux) aide sans contrepartie de cotisation.', 3),
    ('062030db-9d5a-59f5-8ffb-1e6f89accf38'::uuid, 'ses', 'Tle', 'Pouvoirs publics et justice sociale', 'Quel débat renvoie aux effets désincitatifs supposés de la redistribution ?', 'mcq', '["La trappe à inactivité","Le non-recours","Le voile d’ignorance","L’intersectionnalité"]'::jsonb, 0, 'On soupçonne certaines prestations de rendre la reprise d’emploi peu rentable : c’est le débat sur la trappe à inactivité.', 4),
    ('65f2577f-5d77-5c63-b3de-4c2d7e1ab2ec'::uuid, 'ses', 'Tle', 'Coopération et conflit dans la conduite de l’action publique pour l’environnement', 'Pourquoi dit-on que le climat est « rival dans sa dégradation » ?', 'mcq', '["Chaque émission réduit la capacité d’absorption disponible pour les autres","On peut en exclure les pays pauvres","Il appartient au plus offrant","Il se renouvelle sans limite"]'::jsonb, 0, 'Non excluable et rival dans sa dégradation : c’est la définition d’un bien commun.', 1),
    ('45fc3dfd-46f0-590d-bbbc-db8d72bc7691'::uuid, 'ses', 'Tle', 'Coopération et conflit dans la conduite de l’action publique pour l’environnement', 'À quel auteur doit-on la « tragédie des communs » ?', 'mcq', '["Ostrom","Hardin","Pigou","Keynes"]'::jsonb, 1, 'Hardin décrit la surexploitation d’une ressource commune ; Ostrom a ensuite nuancé ce pessimisme.', 2),
    ('1f2fdfaa-3561-5b1b-9765-895cee4c66e3'::uuid, 'ses', 'Tle', 'Coopération et conflit dans la conduite de l’action publique pour l’environnement', 'Quel objectif de température fixe l’accord de Paris (2015) ?', 'mcq', '["Moins de 4 °C","Zéro émission dès 2020","Bien en dessous de 2 °C, en visant 1,5 °C","Une stabilisation à 3 °C"]'::jsonb, 2, 'Paris vise bien en dessous de 2 °C, avec des engagements nationaux volontaires et universels.', 3),
    ('578d4c9f-3fc2-5f95-9dbc-c633cde8f810'::uuid, 'ses', 'Tle', 'Coopération et conflit dans la conduite de l’action publique pour l’environnement', 'Pourquoi l’action climatique oppose-t-elle les générations ?', 'mcq', '["Les jeunes polluent davantage","Les retraités paient seuls la taxe carbone","Le GIEC l’a décidé","Le coût est immédiat, le bénéfice lointain"]'::jsonb, 3, 'Ceux qui paient aujourd’hui ne sont pas ceux qui profiteront des effets : c’est le conflit entre générations.', 4),
    ('7ab26004-f38f-509b-bd12-939ecd75fbb2'::uuid, 'ses', 'Tle', 'Les principaux instruments des politiques climatiques', 'Depuis quand le marché européen de quotas (SEQE-UE) existe-t-il ?', 'mcq', '["1997","2015","2005","2021"]'::jsonb, 2, 'Le SEQE-UE fonctionne depuis 2005 ; son prix s’est longtemps effondré avant la réserve de stabilité.', 1),
    ('1bdd3199-81f6-536f-8f50-88c4bc61782b'::uuid, 'ses', 'Tle', 'Les principaux instruments des politiques climatiques', 'À quel niveau une taxe pigouvienne doit-elle être fixée ?', 'mcq', '["Au bénéfice de l’entreprise","Au dommage marginal causé","Au prix du pétrole","À zéro"]'::jsonb, 1, 'La taxe pigouvienne fait payer au pollueur le dommage marginal, pour internaliser l’externalité.', 2),
    ('6e60c528-d870-5c90-b638-4042d6c0cc54'::uuid, 'ses', 'Tle', 'Les principaux instruments des politiques climatiques', 'Qu’appelle-t-on le « dividende carbone » ?', 'mcq', '["Le bénéfice des entreprises polluantes","Le prix d’un quota","Une subvention aux voitures","La redistribution des recettes d’une taxe carbone"]'::jsonb, 3, 'Reverser les recettes aux ménages corrige le caractère régressif de la taxe carbone.', 3),
    ('a60da1c1-b8f0-50e1-bb0f-18243e39b96e'::uuid, 'ses', 'Tle', 'Les principaux instruments des politiques climatiques', 'Quel avantage l’échange de quotas procure-t-il ?', 'mcq', '["La réduction est réalisée par ceux qui la font au moindre coût","Le prix du carbone est stable","Il ne coûte rien aux entreprises","Il rend toute réglementation inutile"]'::jsonb, 0, 'Ceux qui réduisent à bas coût vendent leurs quotas à ceux pour qui c’est cher : l’objectif est atteint au moindre coût total.', 4),
    ('3ef62586-659b-5785-8949-3dc2a54dd322'::uuid, 'philosophie', 'Tle', 'La conscience', '« Je vois, je marche, j’ai froid » illustre quel degré de conscience ?', 'mcq', '["La conscience réfléchie","La conscience immédiate","La conscience morale","L’inconscient"]'::jsonb, 1, 'La conscience immédiate est le rapport spontané au monde ; la conscience réfléchie serait « je sais que je vois ».', 1),
    ('e5459737-998c-5326-bee1-2bf62c1d25c8'::uuid, 'philosophie', 'Tle', 'La conscience', 'Dans quelle œuvre Descartes écrit-il « Je pense, donc je suis » ?', 'mcq', '["Le Contrat social","Les Pensées","Le Discours de la méthode","La Critique de la raison pure"]'::jsonb, 2, 'La formule paraît dans le Discours de la méthode (1637) : c’est le point fixe que le doute ne peut entamer.', 2),
    ('84953fd6-573d-5c1e-97e7-2ab815fef92b'::uuid, 'philosophie', 'Tle', 'La conscience', 'Selon Freud, quelle place la conscience occupe-t-elle dans le psychisme ?', 'mcq', '["Elle en est la totalité","Elle en est la partie la plus décisive","Elle n’existe pas","Une petite partie, et pas la plus décisive"]'::jsonb, 3, 'Freud fait partie des « soupçons » contre le « je pense » : l’essentiel de la vie psychique se joue hors de la conscience.', 3),
    ('37a75caa-9fc2-50e6-a06e-492dbe8046e0'::uuid, 'philosophie', 'Tle', 'La conscience', 'Pourquoi être conscient, c’est « ne plus coïncider avec soi » ?', 'mcq', '["Parce que je peux me juger, me projeter, me regretter","Parce que je perds la mémoire","Parce que mon corps m’échappe entièrement","Parce que je deviens une chose"]'::jsonb, 0, 'La conscience ouvre une distance avec soi : Pascal y voit à la fois notre inquiétude et notre grandeur.', 4),
    ('ff64a69d-e1d9-53db-9c83-029cb89e748c'::uuid, 'philosophie', 'Tle', 'L’inconscient', 'Pourquoi l’oubli banal n’est-il pas l’inconscient freudien ?', 'mcq', '["Parce qu’il est volontaire","Parce qu’il n’agit pas : il laisse un vide","Parce qu’il ne concerne que les enfants","Parce qu’il est biologique"]'::jsonb, 1, 'L’inconscient psychique est fait de représentations qui ont un sens et qui agissent ; l’oubli banal ne produit rien.', 1),
    ('95e590a4-130b-577d-a3b8-6781b0e5f08c'::uuid, 'philosophie', 'Tle', 'L’inconscient', 'Quel phénomène Freud appelle-t-il la « voie royale » vers l’inconscient ?', 'mcq', '["Le lapsus","Le symptôme","L’acte manqué","Le rêve"]'::jsonb, 3, 'Le rêve est le principal retour déguisé du refoulé, et donc la meilleure porte d’accès à l’inconscient.', 2),
    ('7d4f9bd3-22db-5aff-a384-baa600cbec59'::uuid, 'philosophie', 'Tle', 'L’inconscient', 'Qu’est-ce que le symptôme, pour Freud ?', 'mcq', '["Un compromis entre le désir et l’interdit","Une maladie purement organique","Un simple hasard","Un souvenir conscient"]'::jsonb, 0, 'Le symptôme satisfait en partie le désir refoulé tout en respectant la censure : il se laisse donc interpréter.', 3),
    ('3c6bca12-d1f8-54e8-9572-5b076896f2ce'::uuid, 'philosophie', 'Tle', 'L’inconscient', 'Quel est l’argument de Sartre contre l’idée de refoulement ?', 'mcq', '["Le désir n’existe pas","Les rêves n’ont pas de sens","Pour censurer un désir, la censure devrait déjà le connaître","La conscience est une chose"]'::jsonb, 2, 'Une censure qui trie doit savoir ce qu’elle écarte : elle est donc consciente. Sartre parle alors de mauvaise foi, dont on reste responsable.', 4),
    ('b69f0cf0-0472-5bba-a48e-88c238e8bcd6'::uuid, 'philosophie', 'Tle', 'La nature', 'Dans « la nature du triangle », que désigne le mot « nature » ?', 'mcq', '["Le paysage","L’essence de la chose","Ce qui existe sans l’homme","Ce qui est normal"]'::jsonb, 1, 'Le mot a deux sens à distinguer : l’essence (ce qu’une chose est) et l’ensemble de ce qui existe sans l’homme.', 1),
    ('628ce816-d3a7-5dfb-a668-7ddaa1834cc6'::uuid, 'philosophie', 'Tle', 'La nature', 'Quelle formule résume l’idée qu’Aristote se fait de la nature ?', 'mcq', '["« La nature ne fait rien en vain »","« L’existence précède l’essence »","« La guerre de tous contre tous »","« Maîtres et possesseurs de la nature »"]'::jsonb, 0, 'Pour Aristote, chaque être naturel tend vers sa fin : la nature est finalisée.', 2),
    ('9b3b1466-29e5-5a89-a220-a7b4d419439a'::uuid, 'philosophie', 'Tle', 'La nature', 'Selon le cours, quel critère distingue le culturel du naturel ?', 'mcq', '["Le culturel est universel et spontané","Le culturel est plus ancien","Le culturel varie d’une société à l’autre et relève de la norme","Le culturel ne concerne que l’art"]'::jsonb, 2, 'Le naturel est universel et relève du fait ; le culturel varie selon les sociétés et relève de la norme.', 3),
    ('d7adabd1-63cb-581e-b01a-8c13ca6a4818'::uuid, 'philosophie', 'Tle', 'La nature', 'Selon Rousseau, qu’a apporté la société à l’homme de l’état de nature ?', 'mcq', '["La paix et la sécurité","La pitié","L’amour de soi","La propriété, l’inégalité et la corruption"]'::jsonb, 3, 'Pour Rousseau, l’état de nature était paisible ; c’est la société qui introduit la propriété et les inégalités. Hobbes pense l’inverse.', 4),
    ('96df2a28-04f7-5a38-aa42-139204689279'::uuid, 'philosophie', 'Tle', 'Le bonheur', 'Qu’est-ce qui distingue le bonheur du plaisir ?', 'mcq', '["Le bonheur est ponctuel et sensible","Le bonheur est un état durable et global","Le bonheur est une émotion passagère","Rien, ce sont des synonymes"]'::jsonb, 1, 'Le plaisir est une satisfaction sensible et fugitive ; le bonheur, une satisfaction complète et durable.', 1),
    ('cedf70d6-abb0-5bd1-ae1c-3e9ca3bf2cf3'::uuid, 'philosophie', 'Tle', 'Le bonheur', 'Chez Épicure, le désir de gloire ou de richesse est…', 'mcq', '["Naturel et nécessaire","Naturel et non nécessaire","Ni naturel ni nécessaire","Le seul désir légitime"]'::jsonb, 2, 'Ces désirs sont vains : ils ne connaissent pas de limite et troublent l’âme, à l’opposé de l’ataraxie.', 2),
    ('07c74849-0de4-52bc-a729-12a046b6bd65'::uuid, 'philosophie', 'Tle', 'Le bonheur', 'Que dit Schopenhauer de la vie humaine ?', 'mcq', '["Elle oscille entre la souffrance du manque et l’ennui de la satisfaction","Elle tend naturellement vers le bonheur","Elle est heureuse dès qu’on est vertueux","Elle se résume au divertissement"]'::jsonb, 0, 'Désirer, c’est manquer, donc souffrir ; une fois satisfait, le désir laisse place à l’ennui.', 3),
    ('bdc1b1cb-7d3f-521b-9382-1ef966a6e767'::uuid, 'philosophie', 'Tle', 'Le bonheur', 'Pour Aristote, la vertu suffit-elle au bonheur ?', 'mcq', '["Oui, la vertu seule suffit","Non, il faut seulement de la richesse","Non, le bonheur est impossible","Non, il y faut aussi des amis et un minimum de biens"]'::jsonb, 3, 'Le bonheur est une activité conforme à la vertu, mais dans une vie accomplie, qui suppose des amis et quelques biens.', 4),
    ('f7bb96f3-6c6d-52b6-a64b-8ea25dbe4d05'::uuid, 'philosophie', 'Tle', 'Le travail', 'De quel mot grec, désignant le loisir des citoyens libres, vient notre mot « école » ?', 'mcq', '["Technè","Skholè","Phusis","Polis"]'::jsonb, 1, 'Les Grecs réservaient le travail aux esclaves ; le loisir (skholè) était le temps libre de l’étude et de la cité.', 1),
    ('0cb31d3f-c7d9-5455-8f2b-9a868e777644'::uuid, 'philosophie', 'Tle', 'Le travail', 'Dans la dialectique hégélienne, pourquoi le maître ne se reconnaît-il dans rien ?', 'mcq', '["Parce qu’il travaille trop","Parce qu’il ne fait que consommer, sans rien produire","Parce qu’il est esclave de la nature","Parce qu’il n’a pas de désirs"]'::jsonb, 1, 'Seul l’esclave, en formant la chose, se forme lui-même ; le maître jouit sans produire.', 2),
    ('55c07c8c-2d39-5157-a8f2-f3dadb923d0a'::uuid, 'philosophie', 'Tle', 'Le travail', 'Quelle forme d’aliénation correspond à la parcellisation des tâches ?', 'mcq', '["Le travailleur vend son temps de vie","Il ne possède pas ce qu’il produit","Il ne voit plus le tout auquel il contribue","Il travaille pour lui-même"]'::jsonb, 2, 'Réduit à un geste, le travailleur perd de vue l’ensemble : c’est le prix humain de la division du travail décrite par Adam Smith.', 3),
    ('53423672-76b2-5902-9ab6-445f4c7c8e96'::uuid, 'philosophie', 'Tle', 'Le travail', 'Chez Hannah Arendt, quelle activité produit un monde durable qui laisse une trace ?', 'mcq', '["L’œuvre","Le travail","L’action","Le loisir"]'::jsonb, 0, 'Le travail produit du consommable qui recommence sans fin ; l’œuvre fabrique des objets durables ; l’action ouvre du nouveau.', 4),
    ('4bb0f9e0-6058-5dc0-81ec-e71ff578f860'::uuid, 'philosophie', 'Tle', 'L’État', 'Chez Hobbes, quelle limite est posée au pouvoir du souverain ?', 'mcq', '["Le respect des droits naturels","La volonté générale","Aucune, ou presque","La séparation des pouvoirs"]'::jsonb, 2, 'Pour garantir la sécurité, le Léviathan reçoit un pouvoir quasi absolu ; c’est Locke qui pose des droits que l’État ne peut violer.', 1),
    ('e8032b78-0442-5d81-90ef-7671c2e606b5'::uuid, 'philosophie', 'Tle', 'L’État', 'Selon Locke, que se passe-t-il si l’État viole les droits naturels ?', 'mcq', '["Il perd sa légitimité","Il devient plus fort","Rien, il reste souverain","Il devient une démocratie"]'::jsonb, 0, 'L’État a pour fin de garantir la vie, la liberté et la propriété : s’il les viole, il trahit sa raison d’être.', 2),
    ('713b75f1-8511-53ee-94d1-d49b8569ff30'::uuid, 'philosophie', 'Tle', 'L’État', 'Chez Rousseau, pourquoi obéir à la loi n’est-il pas une servitude ?', 'mcq', '["Parce que la loi est peu contraignante","Parce que le prince est éclairé","Parce que la loi est ancienne","Parce qu’obéir à la loi, c’est n’obéir qu’à soi"]'::jsonb, 3, 'Le peuple étant souverain, la loi exprime la volonté générale : le citoyen obéit à ce qu’il a lui-même voulu.', 3),
    ('ce85cbda-5bae-5b99-ba79-2a9be3227321'::uuid, 'philosophie', 'Tle', 'L’État', 'Selon le cours, où commence la tyrannie ?', 'mcq', '["Là où l’État fait beaucoup","Là où l’État n’est plus contrôlable","Là où il y a des impôts","Là où l’État réduit les inégalités"]'::jsonb, 1, 'Le critère n’est pas l’étendue des fonctions de l’État, mais la possibilité de le contrôler.', 4),
    ('3fe5d074-88da-5d7e-a262-c8e95076cda5'::uuid, 'philosophie', 'Tle', 'La justice et le droit', 'Quelle est la fonction du droit naturel selon le cours ?', 'mcq', '["Régler le stationnement","Permettre de juger les lois","Remplacer les tribunaux","Fixer les peines"]'::jsonb, 1, 'Le droit positif règle la vie commune ; le droit naturel fournit des principes pour juger si une loi est juste.', 1),
    ('f6aa9ed4-bcbe-51fd-8452-f7831a812882'::uuid, 'philosophie', 'Tle', 'La justice et le droit', 'Quelle justice rétablit l’équilibre rompu par un tort, selon une égalité arithmétique ?', 'mcq', '["La justice corrective","La justice distributive","La justice divine","La justice sociale"]'::jsonb, 0, 'La justice corrective répare sans regarder qui sont les personnes ; la distributive répartit selon le mérite.', 2),
    ('9b1aff77-6696-52f4-8922-f52fff025b83'::uuid, 'philosophie', 'Tle', 'La justice et le droit', 'Que constate Pascal sur le rapport entre la force et la justice ?', 'mcq', '["La justice finit toujours par l’emporter","La force est toujours injuste","Ne pouvant faire que le juste soit fort, on a fait que le fort soit juste","La force et la justice sont sans rapport"]'::jsonb, 2, 'Pascal constate froidement que l’ordre établi se donne pour juste parce qu’il est fort.', 3),
    ('dd395788-c15d-5fb9-b903-48b7f1c9cfd5'::uuid, 'philosophie', 'Tle', 'La justice et le droit', 'Sous le voile d’ignorance, quelles inégalités les personnes accepteraient-elles selon Rawls ?', 'mcq', '["Aucune","Celles qui favorisent les plus talentueux","Celles fixées par la naissance","Celles qui profitent aux plus défavorisés"]'::jsonb, 3, 'Ne sachant pas quelle place elles occuperont, elles se protègent du pire : une inégalité n’est acceptable que si elle profite aux plus défavorisés.', 4),
    ('38de413d-8529-5256-9743-525abe7d3dfd'::uuid, 'philosophie', 'Tle', 'Le devoir', 'Qu’est-ce qui distingue l’obligation morale de la contrainte ?', 'mcq', '["La contrainte est intérieure","L’obligation me lie de l’intérieur, et je peux y désobéir","L’obligation est imposée par la police","Il n’y a aucune différence"]'::jsonb, 1, 'La contrainte force de l’extérieur ; l’obligation n’a de sens que parce que je reste capable de désobéir.', 1),
    ('49da7c8c-110e-502d-aba9-fa4dd158cfde'::uuid, 'philosophie', 'Tle', 'Le devoir', '« Si tu veux être estimé, sois honnête » est un impératif…', 'mcq', '["Hypothétique","Catégorique","Universel","Moral au sens de Kant"]'::jsonb, 0, 'Il commande sous condition d’un but visé ; l’impératif catégorique, lui, dirait simplement « sois honnête ».', 2),
    ('27d6597d-9b5a-5b52-bdb7-9410553b801b'::uuid, 'philosophie', 'Tle', 'Le devoir', 'Selon Kant, qu’est-ce qui seul peut être tenu pour bon sans restriction ?', 'mcq', '["Le bonheur","L’intelligence","La richesse","Une bonne volonté"]'::jsonb, 3, 'Talents et biens peuvent servir le mal ; seule la bonne volonté est bonne en elle-même.', 3),
    ('7f06312d-b48a-5c7e-bfef-c3b21689a8be'::uuid, 'philosophie', 'Tle', 'Le devoir', 'Selon Weber, que risque celui qui ignore les conséquences de ses actes ?', 'mcq', '["Le cynisme","La mauvaise foi","L’irresponsabilité","Le ressentiment"]'::jsonb, 2, 'Renoncer à la conviction mène au cynisme ; ignorer les conséquences, à l’irresponsabilité. L’homme d’action tient les deux.', 4),
    ('328a79cb-37e1-587c-9791-351525990ddd'::uuid, 'philosophie', 'Tle', 'La raison', 'Quels sont les deux sens du mot « raison » ?', 'mcq', '["La faculté de penser et la cause d’une chose","La logique et les mathématiques","Le cœur et l’esprit","La loi et la morale"]'::jsonb, 0, 'La raison est la faculté de juger et aussi la cause (« la raison de ce phénomène ») : rendre raison, c’est expliquer.', 1),
    ('58cd6505-d370-5d44-8f2e-b8cb8de721d7'::uuid, 'philosophie', 'Tle', 'La raison', 'Quel modèle du savoir le rationalisme de Descartes privilégie-t-il ?', 'mcq', '["L’observation","Les mathématiques","La tradition","Le témoignage"]'::jsonb, 1, 'Le rationalisme fait venir le savoir de la raison seule, par idées claires et distinctes ; l’empirisme prend l’observation pour modèle.', 2),
    ('83acafd8-5c41-5c1e-97b6-67d291e42305'::uuid, 'philosophie', 'Tle', 'La raison', 'Selon Kant, que produit la raison quand elle veut connaître Dieu, l’âme ou le monde comme totalité ?', 'mcq', '["Des connaissances certaines","Des expériences nouvelles","Rien du tout","Des raisonnements également démontrables et contradictoires"]'::jsonb, 3, 'Hors de toute expérience possible, la raison s’égare : elle démontre aussi bien une thèse que son contraire.', 3),
    ('9ad678ff-b6d8-5438-bd3d-6fab3c7c5a39'::uuid, 'philosophie', 'Tle', 'La raison', 'Qu’a permis le principe de raison selon le cours ?', 'mcq', '["De revenir au merveilleux","De faire sortir la pensée du mythe","De se passer d’explication","De prouver le hasard"]'::jsonb, 1, 'Au lieu de raconter comment le monde est né, on cherche par quoi il s’explique : c’est la rupture avec le mythe.', 4),
    ('ae536437-cdd1-5312-9f40-394e696f3094'::uuid, 'philosophie', 'Tle', 'La liberté de faire ce qui me plaît', 'Quel penseur en reste à la liberté comme mouvement sans entrave ?', 'mcq', '["Rousseau","Spinoza","Hobbes","Épicure"]'::jsonb, 2, 'Pour Hobbes, être libre, c’est ne rencontrer aucun obstacle ; reste à savoir d’où viennent les désirs qu’on suit.', 1),
    ('28732670-5c23-506d-b3fb-38682a1e2351'::uuid, 'philosophie', 'Tle', 'La liberté de faire ce qui me plaît', 'Que montre l’ivrogne de Spinoza ?', 'mcq', '["Qu’il croit parler librement alors que son désir lui est venu sans qu’il le décide","Que l’alcool rend libre","Que la volonté est toute-puissante","Que la loi supprime la liberté"]'::jsonb, 0, 'Il croit parler par un libre décret de son esprit, mais regrette à jeun : avoir conscience d’agir ne prouve pas qu’on est libre.', 2),
    ('ce37381b-5fd3-57ec-b0c3-21e7458f10ac'::uuid, 'philosophie', 'Tle', 'La liberté de faire ce qui me plaît', 'Selon le cours, que produit la licence, liberté sans limite ?', 'mcq', '["Une coexistence paisible","Le règne des lois","L’égalité de tous","La victoire du plus fort, et elle se détruit elle-même"]'::jsonb, 3, 'Sans borne posée par la liberté d’autrui, chacun empiète sur l’autre et le plus fort l’emporte.', 3),
    ('7a2f9851-f258-5e76-aa59-afdd76311c0d'::uuid, 'philosophie', 'Tle', 'La liberté de faire ce qui me plaît', 'Que conseillent les stoïciens pour devenir libre ?', 'mcq', '["Satisfaire chaque désir","S’attacher à ce qui dépend de nous","Changer l’ordre du monde","Fuir toute loi"]'::jsonb, 1, 'La liberté devient une conquête : ne vouloir que ce qui dépend de nous, nos jugements, et non le reste.', 4),
    ('1f535062-3c8d-5d37-a0e0-6723ee77a515'::uuid, 'philosophie', 'Tle', 'Le libre arbitre', 'Pourquoi le libre arbitre fonde-t-il la responsabilité ?', 'mcq', '["Parce qu’il suppose qu’on aurait pu faire autrement","Parce qu’il supprime les causes","Parce qu’il rend tout prévisible","Parce qu’il vient de la loi"]'::jsonb, 0, 'On ne juge pas une pierre qui tombe : blâmer ou louer suppose qu’on aurait pu agir autrement.', 1),
    ('f84872ee-aae2-553a-b2bc-950a935810bc'::uuid, 'philosophie', 'Tle', 'Le libre arbitre', 'Selon Descartes, quand suis-je le plus libre ?', 'mcq', '["Quand je choisis au hasard","Quand j’hésite longtemps","Quand je choisis en connaissance de cause","Quand je ne choisis pas"]'::jsonb, 2, 'Plus les raisons de choisir sont fortes, plus je suis libre : l’indifférence est le plus bas degré de la liberté.', 2),
    ('ba0757d9-53b7-50fe-8ae5-106870331c3c'::uuid, 'philosophie', 'Tle', 'Le libre arbitre', 'Qu’affirme le fatalisme, à la différence du déterminisme ?', 'mcq', '["Que mes actes ont des causes","Que l’avenir arrivera quoi que je fasse","Que mes actes sont des causes à leur tour","Que la science peut tout prévoir"]'::jsonb, 1, 'Pour le déterministe, mes actes comptent comme causes ; pour le fataliste, ils ne changent rien. Confondre les deux est l’erreur la plus coûteuse.', 3),
    ('68af59e6-0099-53b1-8564-d6688f9f4212'::uuid, 'philosophie', 'Tle', 'Le libre arbitre', 'Comment Kant sauve-t-il la liberté face au déterminisme ?', 'mcq', '["En niant les lois de la nature","En faisant de la liberté un fait observable","En s’en remettant au hasard","En séparant le plan des phénomènes et celui du sujet moral"]'::jsonb, 3, 'Comme phénomène, je suis soumis aux lois de la nature ; comme sujet moral, je dois me penser libre, sinon le devoir n’a pas de sens.', 4),
    ('51bd3865-a0dc-58d4-a631-5ac4d26dc45f'::uuid, 'philosophie', 'Tle', 'La liberté politique', 'Pour Rousseau, qu’est-ce qui compte dans les lois pour que l’on reste libre ?', 'mcq', '["Leur quantité","Leur origine","Leur ancienneté","Leur douceur"]'::jsonb, 1, 'Ce n’est pas le nombre de lois mais leur source : une loi voulue par le peuple souverain ne l’asservit pas.', 1),
    ('9c82d5bb-7988-5942-8d59-c745efb6ca7f'::uuid, 'philosophie', 'Tle', 'La liberté politique', 'Quel est le risque de la liberté des Modernes, selon Benjamin Constant ?', 'mcq', '["L’individu est entièrement soumis à la cité","Le citoyen se désintéresse des affaires publiques","Les droits disparaissent","L’assemblée décide de tout"]'::jsonb, 1, 'Absorbé par son indépendance privée, le citoyen moderne risque de laisser la chose publique à d’autres.', 2),
    ('e28a7ebc-e3d1-5954-a886-346bf0a493e7'::uuid, 'philosophie', 'Tle', 'La liberté politique', 'Quelle garantie empêche que l’abus de pouvoir reste invisible ?', 'mcq', '["La séparation des pouvoirs","L’État de droit","La liberté de la presse","La justice indépendante"]'::jsonb, 2, 'Chaque garantie a sa fonction : la presse libre rend l’abus public, la justice indépendante protège les verdicts.', 3),
    ('74b25672-22aa-5653-bda1-901d8d0d883a'::uuid, 'philosophie', 'Tle', 'La liberté politique', 'La désobéissance civile se fait au nom de…', 'mcq', '["L’intérêt personnel","La violence révolutionnaire","La majorité","Du droit lui-même"]'::jsonb, 3, 'Publique et non violente, elle assume la sanction et invoque des principes de droit contre une loi jugée injuste.', 4),
    ('188ead74-ae4a-51cb-aad2-4a4b31576f9c'::uuid, 'philosophie', 'Tle', 'Le langage', 'Le français, l’anglais ou le japonais sont…', 'mcq', '["Des langues","Des langages","Des paroles","Des signifiés"]'::jsonb, 0, 'Le langage est la faculté de communiquer par signes ; une langue, le système particulier d’une communauté ; la parole, son usage individuel.', 1),
    ('f43457dc-e3ad-5cc0-8b22-cbd25f8ad85b'::uuid, 'philosophie', 'Tle', 'Le langage', 'Chez Saussure, le signifiant est…', 'mcq', '["Le concept","L’objet réel","L’image sonore","Le sens de la phrase"]'::jsonb, 2, 'Le signe unit un signifiant (l’image sonore) et un signifié (le concept) ; la chose elle-même n’en fait pas partie.', 2),
    ('4aaa2566-c26e-5d71-bf0d-6d439354c854'::uuid, 'philosophie', 'Tle', 'Le langage', '« La séance dure une heure » est un énoncé…', 'mcq', '["Performatif","Constatif","Impératif","Ni vrai ni faux"]'::jsonb, 1, 'Il décrit un fait et peut être vrai ou faux ; « la séance est ouverte », lui, accomplit ce qu’il dit.', 3),
    ('55baa3ea-fd94-5b0e-93e9-03bda74f769f'::uuid, 'philosophie', 'Tle', 'Le langage', 'Selon Descartes, que manque-t-il aux animaux pour parler vraiment ?', 'mcq', '["La voix","Des organes adaptés","Des émotions","Le pouvoir d’arranger des mots pour répondre à toute situation nouvelle"]'::jsonb, 3, 'Ce n’est pas une affaire d’organe : le propre de la parole humaine est de combiner librement les signes.', 4),
    ('d4ede067-ee07-5794-b3f4-7fa0ba032f4d'::uuid, 'philosophie', 'Tle', 'La vérité', 'Quelle limite le cours reconnaît-il au critère de cohérence ?', 'mcq', '["Un système faux peut être cohérent","Il exige de sortir de la pensée","Il ne conclut jamais","Il dépend de l’évidence"]'::jsonb, 0, 'L’absence de contradiction ne garantit pas l’accord avec le réel : un récit inventé peut être parfaitement cohérent.', 1),
    ('04eacb6a-ea8a-53c2-8bf3-0d400efa06c3'::uuid, 'philosophie', 'Tle', 'La vérité', 'Qu’est-ce qui manque à une opinion juste « par accident » ?', 'mcq', '["L’accord de la majorité","De savoir pourquoi elle est juste","Une formulation claire","L’ancienneté"]'::jsonb, 1, 'La doxa peut tomber juste, mais sans raisons : elle ne se distingue pas de l’erreur par elle-même.', 2),
    ('c3dbed1b-f589-521f-98e9-7ae3b79e506a'::uuid, 'philosophie', 'Tle', 'La vérité', 'Quelle difficulté rencontre la vérité-correspondance ?', 'mcq', '["Elle ne vaut qu’en mathématiques","Elle confond le vrai et le réel","Pour comparer l’idée à la chose, il faudrait sortir de sa pensée","Elle dépend du vote"]'::jsonb, 2, 'On ne peut confronter ses idées qu’au réel tel qu’on le pense : d’où la recherche d’autres critères.', 3),
    ('c587e5c0-ce2d-5f03-ad09-38f2147b5e3f'::uuid, 'philosophie', 'Tle', 'La vérité', 'Selon le cours, de quoi la vérité a-t-elle besoin pour ne pas rester une opinion parmi d’autres ?', 'mcq', '["D’un chef","De la force","Du consensus spontané","D’institutions : écoles, sciences, presse libre"]'::jsonb, 3, 'Chercher la vérité dérange des intérêts, comme le rappellent les procès de Socrate et de Galilée : elle doit être protégée.', 4),
    ('6a00dc3c-9423-56d4-b9b7-27e70c5697fb'::uuid, 'philosophie', 'Tle', 'La science', 'Selon le cours, qu’est-ce qui définit la science ?', 'mcq', '["Son objet","Sa méthode","Ses instruments","Son ancienneté"]'::jsonb, 1, 'La science explique au lieu de raconter, démontre au lieu d’affirmer, et accepte d’avoir tort.', 1),
    ('89963ab2-83b1-5b64-9d6c-6280b159422b'::uuid, 'philosophie', 'Tle', 'La science', 'Que fait le mythe face à une objection, à la différence de la science ?', 'mcq', '["Il l’absorbe","Il se corrige","Il tombe","Il la teste par expérience"]'::jsonb, 0, 'La science se corrige ou abandonne une théorie démentie ; le mythe intègre l’objection sans être mis en danger.', 2),
    ('9cd8aeec-6b80-5ac7-99ae-cea9f11296b6'::uuid, 'philosophie', 'Tle', 'La science', 'Que signifie idéaliser, comme le plan sans frottement de Galilée ?', 'mcq', '["Décrire le monde tel qu’il apparaît","Rêver un monde meilleur","Construire un modèle du réel","Renoncer à mesurer"]'::jsonb, 2, 'La science ne copie pas l’apparence : elle simplifie et mathématise pour construire un modèle.', 3),
    ('f93c5762-bab3-5b63-8cb0-62503f4ee121'::uuid, 'philosophie', 'Tle', 'La science', 'Selon Popper, que suffit-il pour démentir « tous les cygnes sont blancs » ?', 'mcq', '["Mille cygnes blancs","L’accord des savants","Une démonstration mathématique","Un seul cygne noir"]'::jsonb, 3, 'Aucune accumulation d’exemples ne prouve une loi, mais un seul contre-exemple la réfute : c’est l’asymétrie de la réfutation.', 4),
    ('16928848-1a35-5de5-874c-b3d73fa24574'::uuid, 'philosophie', 'Tle', 'La technique', 'Quel outil prolonge la mémoire et le calcul ?', 'mcq', '["Le marteau","La roue","Le télescope","L’ordinateur"]'::jsonb, 3, 'Chaque outil prolonge un organe ou une faculté : le marteau le poing, la roue la marche, le télescope l’œil.', 1),
    ('6f0d450c-a058-570f-9060-5544a20dbc38'::uuid, 'philosophie', 'Tle', 'La technique', 'Dans quel dialogue de Platon le mythe de Prométhée est-il raconté par Protagoras ?', 'mcq', '["La République","Le Protagoras","Le Phédon","Le Banquet"]'::jsonb, 1, 'Dans le dialogue qui porte son nom, Protagoras raconte comment l’homme, né nu, reçoit le feu et les techniques.', 2),
    ('85d43b54-5cef-5a85-be56-ffd760d4f7b0'::uuid, 'philosophie', 'Tle', 'La technique', 'Selon Heidegger, comment la technique moderne fait-elle voir la forêt, le fleuve ou l’homme ?', 'mcq', '["Comme un stock disponible","Comme des œuvres d’art","Comme du sacré","Comme des obstacles"]'::jsonb, 0, 'La technique n’est pas neutre : elle impose un regard qui réduit tout ce qui existe à une ressource utilisable.', 3),
    ('619df175-ebf6-5e55-87ba-1ed36cffb67e'::uuid, 'philosophie', 'Tle', 'La technique', 'Selon le cours, quelle est désormais la question décisive posée à la technique ?', 'mcq', '["Est-elle utile ?","Est-elle scientifique ?","Qui commande ?","Est-elle ancienne ?"]'::jsonb, 2, 'Quand le moyen devient une fin, la question n’est plus l’utilité mais la maîtrise : qui décide de son orientation ?', 4),
    ('f8a320d7-72f6-5a84-87e4-c950a12d296e'::uuid, 'philosophie', 'Tle', 'L’art', 'De quand date l’idée d’art au sens des beaux-arts ?', 'mcq', '["De l’Antiquité grecque","Du Moyen Âge","Du XVIIIe siècle","Du XXe siècle"]'::jsonb, 2, '« Art » a d’abord voulu dire savoir-faire (l’ars latine traduit la technè) ; les beaux-arts comme activité désintéressée sont une idée récente.', 1),
    ('8d67bd32-62d0-5d97-a080-66267cc59428'::uuid, 'philosophie', 'Tle', 'L’art', 'Chez Kant, qu’est-ce qui plaît « par le concept qu’on en a » ?', 'mcq', '["L’agréable","Le beau","Le sublime","Le bon"]'::jsonb, 3, 'L’agréable plaît aux sens, le bon par son concept, le beau universellement sans concept.', 2),
    ('1d5622ef-20b3-543a-a124-c8503bc19f5f'::uuid, 'philosophie', 'Tle', 'L’art', 'Selon Hegel, qu’est-ce que l’art ?', 'mcq', '["Une présentation sensible de la vérité","Un simple divertissement","Une copie de copie","Un marché"]'::jsonb, 0, 'L’art est pour Hegel une manière de penser autrement que par concepts, en rendant le vrai sensible.', 3),
    ('bb1d692f-3eb6-55e0-9bf3-f705d01c464d'::uuid, 'philosophie', 'Tle', 'L’art', 'Que cherche l’art moderne selon le cours ?', 'mcq', '["Imiter fidèlement la nature","Rendre visible plutôt que reproduire le visible","Plaire à tout prix","Appliquer des règles connues"]'::jsonb, 1, 'En rompant avec la ressemblance, l’art moderne ne reproduit plus ce qu’on voit : il fait voir autrement.', 4),
    ('e3de7192-52fa-5e4d-9b71-1919ee06057c'::uuid, 'philosophie', 'Tle', 'La religion', 'Que souligne l’étymologie « relegere » ?', 'mcq', '["Relier les hommes au divin","Recueillir avec scrupule ce qui a été transmis","Obéir à un livre saint","Sacrifier aux dieux"]'::jsonb, 1, 'Religare insiste sur le lien, relegere sur la transmission recueillie avec soin : les deux disent quelque chose du phénomène.', 1),
    ('61064757-d303-5f6d-9195-9d7cb16b549e'::uuid, 'philosophie', 'Tle', 'La religion', 'Selon Durkheim, que célèbre aussi la société à travers la religion ?', 'mcq', '["Sa propre unité","La puissance des prêtres","Le progrès scientifique","L’individu isolé"]'::jsonb, 0, 'En partageant le sacré et le profane, la communauté se célèbre elle-même, sans le savoir.', 2),
    ('820a1e11-dcba-5957-b6f3-f08acf989b92'::uuid, 'philosophie', 'Tle', 'La religion', 'Pour Freud, qu’est-ce que la religion ?', 'mcq', '["Une projection des qualités humaines","L’opium du peuple","Une illusion née du désir infantile de protection","Une connaissance démontrée"]'::jsonb, 2, 'La projection est la thèse de Feuerbach, l’opium celle de Marx ; Freud y voit une illusion issue du besoin d’un père protecteur.', 3),
    ('a0a85602-25b4-596e-a022-4a74d403aaac'::uuid, 'philosophie', 'Tle', 'La religion', 'Quelle distinction Spinoza et Locke posent-ils ?', 'mcq', '["Entre foi et raison","Entre sacré et profane","Entre riches et pauvres","Le salut relève de la conscience, l’ordre public de l’État"]'::jsonb, 3, 'Cette séparation fonde la tolérance, et plus tard la laïcité : l’État n’a pas à décider du salut des âmes.', 4),
    ('ae631f45-6e54-50e8-aa0a-17ec8eef1840'::uuid, 'philosophie', 'Tle', 'Le temps', 'Comment Newton conçoit-il le temps ?', 'mcq', '["Comme la forme de notre sensibilité","Comme un cadre absolu qui s’écoule uniformément","Comme le nombre du mouvement","Comme une illusion"]'::jsonb, 1, 'Pour Newton, le temps s’écoule indépendamment de ce qui s’y produit ; Kant en fait une forme de la sensibilité.', 1),
    ('2dbede4a-4a4e-5566-bab9-bf02e59c91ae'::uuid, 'philosophie', 'Tle', 'Le temps', 'Chez Augustin, à quoi correspond le « présent de l’avenir » ?', 'mcq', '["À la mémoire","À l’attention","À l’attente","À l’éternité"]'::jsonb, 2, 'Le passé est présent comme mémoire, le présent comme attention, l’avenir comme attente.', 2),
    ('28fc1805-ca0e-5d0d-b241-1fc0e6f5c547'::uuid, 'philosophie', 'Tle', 'Le temps', 'Que signifie « Carpe diem », formule d’Horace ?', 'mcq', '["Cueille le jour","Souviens-toi que tu vas mourir","Le temps fuit","Connais-toi toi-même"]'::jsonb, 0, 'Horace invite à saisir le présent plutôt qu’à se perdre dans l’attente d’un avenir incertain.', 3),
    ('631b37f1-0edd-5f3c-8405-0d05030f956d'::uuid, 'philosophie', 'Tle', 'Le temps', 'Selon le cours, que rend possible l’irréversibilité du temps ?', 'mcq', '["L’éternité","L’oubli de nos actes","L’absence de conséquences","Le projet, la promesse et l’histoire"]'::jsonb, 3, 'Parce que le temps passe, nos actes engagent quelque chose : une existence sans temps serait sans conséquence.', 4),
    ('c40fd9ca-9fae-5fa4-a98b-c97902acc53c'::uuid, 'emc', 'Tle', 'Histoire de la démocratie', 'Comment s’appelle l’assemblée où les citoyens athéniens votaient eux-mêmes les lois ?', 'mcq', '["Le Sénat","L’agora","L’ecclésia","L’aréopage"]'::jsonb, 2, 'L’ecclésia réunit les citoyens, qui votent directement les lois : c’est le cœur de la démocratie directe athénienne.', 1),
    ('91b95094-1f83-56ef-8d09-00844dd355fd'::uuid, 'emc', 'Tle', 'Histoire de la démocratie', 'Pourquoi Aristote jugeait-il l’élection plutôt « aristocratique » ?', 'mcq', '["Parce qu’elle désigne les meilleurs","Parce que seuls les riches pouvaient voter","Parce qu’elle était réservée aux nobles","Parce qu’elle se faisait à main levée"]'::jsonb, 0, 'Élire, c’est choisir les meilleurs (aristoi) ; le tirage au sort, lui, donne à chacun la même chance d’exercer une charge.', 2),
    ('a54e681d-4376-5f25-8e6a-aa42ad351974'::uuid, 'emc', 'Tle', 'Histoire de la démocratie', 'Depuis quand la majorité électorale est-elle fixée à 18 ans en France ?', 'mcq', '["1945","1958","1968","1974"]'::jsonb, 3, 'La loi de 1974 abaisse la majorité de 21 à 18 ans, dernière grande extension du corps électoral.', 3),
    ('5d7462b1-0091-5505-8d75-c5db0e3b4532'::uuid, 'emc', 'Tle', 'Histoire de la démocratie', 'Selon Samuel Huntington, quand commence la troisième vague de démocratisation ?', 'mcq', '["En 1945, avec la Libération","En 1974, avec la révolution des Œillets au Portugal","En 1989, avec la chute du mur de Berlin","En 1918, après la Grande Guerre"]'::jsonb, 1, 'La troisième vague part du Portugal en 1974, puis gagne l’Espagne, la Grèce, l’Amérique latine et l’Europe de l’Est après 1989.', 4),
    ('9cbff733-0617-55da-81a8-a25b879261b3'::uuid, 'emc', 'Tle', 'La démocratie et le peuple souverain', 'Quel article de la Constitution de 1958 reprend la formule de Lincoln « gouvernement du peuple, par le peuple et pour le peuple » ?', 'mcq', '["L’article 1er","L’article 2","L’article 3","L’article 16"]'::jsonb, 1, 'L’article 2 en fait le principe de la République ; l’article 3 traite ensuite de la souveraineté nationale.', 1),
    ('87d6a49d-15e9-5eac-ad40-59300f64fcb6'::uuid, 'emc', 'Tle', 'La démocratie et le peuple souverain', 'Avec la souveraineté populaire de Rousseau, quel mandat lie l’élu à ses électeurs ?', 'mcq', '["Un mandat représentatif","Un mandat libre","Un mandat impératif","Aucun mandat"]'::jsonb, 2, 'Si chaque citoyen détient une part de la souveraineté, l’élu doit obéir à ses électeurs : c’est le mandat impératif.', 2),
    ('90147a50-0ee1-5227-9bf2-42d2bf0aaf97'::uuid, 'emc', 'Tle', 'La démocratie et le peuple souverain', 'Les votations suisses relèvent de quelle forme de démocratie ?', 'mcq', '["Représentative","Participative","Directe","Délibérative"]'::jsonb, 2, 'Dans une votation, le peuple tranche lui-même la question posée : c’est de la démocratie directe.', 3),
    ('ef3d3014-f459-5dd5-b1c0-4605bbe4c4a3'::uuid, 'emc', 'Tle', 'La démocratie et le peuple souverain', 'Selon Sieyès, quelle part de la souveraineté chaque citoyen détient-il ?', 'mcq', '["Aucune : elle appartient à la Nation, indivisible","Une part égale","Une part proportionnelle à l’impôt payé","Une part s’il est élu"]'::jsonb, 0, 'Pour Sieyès, la Nation est une entité abstraite qui ne s’exprime que par ses représentants, d’où le mandat représentatif.', 4),
    ('d6fc30bf-6d6a-5331-bf16-c0d60a98f7c5'::uuid, 'emc', 'Tle', 'Les élections, outils de la démocratie', 'Parmi ces pays, lequel impose le vote obligatoire ?', 'mcq', '["La France","La Belgique","Le Royaume-Uni","L’Allemagne"]'::jsonb, 1, 'La Belgique, comme l’Australie, rend le vote obligatoire ; en France il reste libre.', 1),
    ('32ac387c-f85f-555f-9412-3e7d0a5f520c'::uuid, 'emc', 'Tle', 'Les élections, outils de la démocratie', 'Quel principe du vote l’isoloir garantit-il ?', 'mcq', '["L’universalité","L’égalité","Le secret","Le caractère direct"]'::jsonb, 2, 'L’isoloir, obligatoire, protège le secret du vote : personne ne peut savoir ni contrôler ce que chacun a choisi.', 2),
    ('4c9904a8-3e09-5fc8-bf35-0dbbd69dbbd2'::uuid, 'emc', 'Tle', 'Les élections, outils de la démocratie', 'Qu’est-ce qu’un scrutin mixte ?', 'mcq', '["Un scrutin qui ajoute une prime majoritaire à la proportionnelle","Un scrutin où hommes et femmes votent séparément","Un scrutin à un seul tour","Un scrutin réservé aux grands électeurs"]'::jsonb, 0, 'Le scrutin mixte cherche un compromis entre représentativité et gouvernabilité, sans jamais être parfait.', 3),
    ('e4d9c781-48cd-5e4b-a617-2e1b27407d05'::uuid, 'emc', 'Tle', 'Les élections, outils de la démocratie', 'Quel organisme veille à l’égalité du temps de parole des candidats ?', 'mcq', '["La CNCCFP","La HATVP","La CNIL","L’Arcom"]'::jsonb, 3, 'L’Arcom contrôle les temps de parole dans l’audiovisuel ; la CNCCFP, elle, vérifie les comptes de campagne.', 4),
    ('0f368083-f262-5223-924e-ff7b5455bbbf'::uuid, 'emc', 'Tle', 'Laïcité et démocratie', 'Que dit l’article 2 de la loi de 1905 ?', 'mcq', '["La République ne reconnaît, ne salarie ni ne subventionne aucun culte","La République assure la liberté de conscience","Les religions sont interdites dans l’espace public","Chaque culte doit être déclaré en préfecture"]'::jsonb, 0, 'L’article 1er pose la liberté, l’article 2 la neutralité : l’État ne finance ni ne reconnaît aucun culte.', 1),
    ('1cc10584-1f3e-58a8-955d-dc3f911f95b3'::uuid, 'emc', 'Tle', 'Laïcité et démocratie', 'Sur quel motif repose la loi de 2010 interdisant la dissimulation du visage dans l’espace public ?', 'mcq', '["La neutralité de l’État","L’ordre public et la sécurité","La lutte contre le blasphème","La protection des mineurs à l’école"]'::jsonb, 1, 'La loi de 2010 s’applique à tous, dans l’espace public, au nom de l’ordre public et de la sécurité, et non de la laïcité.', 2),
    ('7c29b5f0-6690-5e23-8566-3aa3ca2eeedd'::uuid, 'emc', 'Tle', 'Laïcité et démocratie', 'Selon le cours, qu’est-ce que le droit français punit ?', 'mcq', '["La critique d’un dogme religieux","La caricature d’une religion","L’incitation à la haine visant des personnes en raison de leur religion","Le fait de ne pas croire"]'::jsonb, 2, 'Les idées sont critiquables, y compris durement ; ce sont les personnes qui sont protégées contre l’injure et la haine.', 3),
    ('df75fadc-75be-5d86-8d65-fb70a3b19dc4'::uuid, 'emc', 'Tle', 'Laïcité et démocratie', 'Pourquoi l’Alsace-Moselle n’a-t-elle pas reçu la loi de 1905 ?', 'mcq', '["Elle l’a refusée par référendum","Elle était alors annexée à l’Empire allemand","Elle était sous administration de l’Église","La loi ne s’appliquait qu’à Paris"]'::jsonb, 1, 'Annexée depuis 1871, elle était allemande en 1905 ; revenue française, elle a gardé le régime concordataire.', 4),
    ('95a25e9a-f36f-5cd3-b32d-2aa155954f58'::uuid, 'emc', 'Tle', 'Contestation de la démocratie et transformations des régimes politiques', 'Que devient la société civile dans un régime totalitaire ?', 'mcq', '["Elle garde des espaces d’autonomie","Elle ne garde aucun espace d’autonomie","Elle contrôle l’État","Elle choisit le parti unique"]'::jsonb, 1, 'Le totalitarisme prétend tout encadrer : parti unique, idéologie officielle, terreur organisée ; un régime autoritaire, lui, laisse des espaces.', 1),
    ('b1a299b8-de4c-5e6b-bfd4-853573669d26'::uuid, 'emc', 'Tle', 'Contestation de la démocratie et transformations des régimes politiques', 'Dans une démocratie illibérale, que devient souvent la presse ?', 'mcq', '["Elle est interdite par la loi","Elle est nationalisée officiellement","Elle est étouffée économiquement","Elle devient entièrement libre"]'::jsonb, 2, 'La presse n’est pas interdite, mais rachetée ou asphyxiée : les formes restent, la substance est vidée.', 2),
    ('bcf37ca6-e28b-5dc6-b718-daf5066477ab'::uuid, 'emc', 'Tle', 'Contestation de la démocratie et transformations des régimes politiques', 'Pourquoi le recul démocratique est-il difficile à contester ?', 'mcq', '["Parce qu’il passe toujours par un coup d’État","Parce que chaque étape est légale","Parce que les élections sont supprimées","Parce qu’il est imposé par l’étranger"]'::jsonb, 1, 'Le pouvoir vide la démocratie de l’intérieur en respectant les formes, ce qui rend chaque étape difficile à dater et à dénoncer.', 3),
    ('2dee2d9c-161a-56bb-bd49-d74c20aa9b98'::uuid, 'emc', 'Tle', 'Contestation de la démocratie et transformations des régimes politiques', 'Lequel de ces indices mesure l’état des démocraties dans le monde ?', 'mcq', '["L’indice de développement humain","Le coefficient de Gini","Le PIB par habitant","V-Dem"]'::jsonb, 3, 'V-Dem, Freedom House et le Democracy Index constatent tous un recul du nombre de démocraties depuis une quinzaine d’années.', 4),
    ('e9b3e1dd-91b0-548a-a721-5c62b01cf064'::uuid, 'emc', 'Tle', 'La protection des démocraties : les enjeux de sécurité', 'Quelle autorité contrôle les techniques de renseignement depuis la loi de 2015 ?', 'mcq', '["La CNCTR","La CNIL","L’Arcom","La HATVP"]'::jsonb, 0, 'La Commission nationale de contrôle des techniques de renseignement vérifie l’usage des techniques de surveillance.', 1),
    ('2b179505-8290-51d2-9889-8b504c7d8fc0'::uuid, 'emc', 'Tle', 'La protection des démocraties : les enjeux de sécurité', 'Où siège la Cour européenne des droits de l’homme ?', 'mcq', '["À Bruxelles","À Luxembourg","À Strasbourg","À La Haye"]'::jsonb, 2, 'La CEDH siège à Strasbourg : elle offre un recours extérieur contre un État qui porterait atteinte aux libertés.', 2),
    ('2de5d830-cc73-5be8-82a3-29c35285e16a'::uuid, 'emc', 'Tle', 'La protection des démocraties : les enjeux de sécurité', 'Sous l’état d’urgence, qui décide des assignations à résidence ?', 'mcq', '["Un juge d’instruction","L’administration","Le Parlement","Le Conseil constitutionnel"]'::jsonb, 1, 'C’est la spécificité de l’état d’urgence : l’administration décide, sans autorisation préalable d’un juge.', 3),
    ('d659ccfb-06c8-5720-a6f7-d4ba025b33ba'::uuid, 'emc', 'Tle', 'La protection des démocraties : les enjeux de sécurité', 'Une mesure est « proportionnée » quand…', 'mcq', '["Elle répond à une menace établie","Un juge peut la censurer","Elle est votée à une large majorité","Il n’existe pas de moyen moins attentatoire aux libertés pour atteindre le même but"]'::jsonb, 3, 'La proportionnalité est l’un des trois critères avec la nécessité et le contrôle : il faut poser les trois dans une copie.', 4),
    ('563a7ba3-a96a-5eb5-80ca-d5e3195d40a8'::uuid, 'emc', 'Tle', 'La construction européenne et la démocratie', 'Pourquoi l’article 7 du TUE est-il presque inapplicable ?', 'mcq', '["Il exige l’unanimité","Il n’a jamais été ratifié","Il ne concerne que la zone euro","Il dépend de la CEDH"]'::jsonb, 0, 'L’unanimité requise permet à un État de protéger un autre ; la conditionnalité budgétaire de 2020, elle, a été utilisée.', 1),
    ('29848c56-67d3-5385-9eb6-a8c7008a180c'::uuid, 'emc', 'Tle', 'La construction européenne et la démocratie', 'Que permet la conditionnalité budgétaire adoptée en 2020 ?', 'mcq', '["Exclure un État de l’Union","Suspendre les fonds européens en cas d’atteinte à l’État de droit","Supprimer le droit de vote au Parlement européen","Imposer une amende à un gouvernement"]'::jsonb, 1, 'Elle lie le versement des fonds au respect de l’État de droit, et elle a été effectivement appliquée.', 2),
    ('abca9914-3715-5919-a62d-7be46045b64a'::uuid, 'emc', 'Tle', 'La construction européenne et la démocratie', 'Qu’exige l’initiative citoyenne européenne, en plus du million de signatures ?', 'mcq', '["Qu’elles viennent d’au moins sept États","L’accord du Parlement européen","Un vote de chaque parlement national","La signature d’un chef d’État"]'::jsonb, 0, 'Le million de signatures doit être réparti sur au moins sept États membres pour que la Commission soit saisie.', 3),
    ('ab5a9192-1728-5aae-b4ba-f2b33aa5d118'::uuid, 'emc', 'Tle', 'La construction européenne et la démocratie', 'Selon le cours, qu’est-ce qui pose surtout problème dans le système européen ?', 'mcq', '["L’absence totale d’élections","L’absence de droits fondamentaux","Sa lisibilité, plus que sa légitimité formelle","Le refus de tout nouvel adhérent"]'::jsonb, 2, 'Chaque décision passe par des élus ou des gouvernements responsables, mais la machine est lointaine et la responsabilité s’y dilue.', 4),
    ('1be7dc3e-7fe8-55ea-ac96-828f7983fb79'::uuid, 'emc', 'Tle', 'Faire vivre le débat dans une démocratie', 'Dans un débat, qu’attaque-t-on, contrairement à une dispute ?', 'mcq', '["La personne","L’idée","Le public","Le modérateur"]'::jsonb, 1, 'Débattre, c’est discuter l’idée avec des raisons ; s’en prendre à la personne relève de la dispute ou du sophisme.', 1),
    ('0e15d6b3-52c9-5a86-babf-da03f84a2fbd'::uuid, 'emc', 'Tle', 'Faire vivre le débat dans une démocratie', '« Soit tu es avec nous, soit tu es contre nous » : de quel sophisme s’agit-il ?', 'mcq', '["L’attaque personnelle","La généralisation abusive","Le faux dilemme","L’argument d’autorité"]'::jsonb, 2, 'Le faux dilemme réduit la question à deux options alors qu’il en existe d’autres.', 2),
    ('32355999-13b2-5112-b930-3b9794be8b5e'::uuid, 'emc', 'Tle', 'Faire vivre le débat dans une démocratie', 'Que produisent les algorithmes de recommandation selon le cours ?', 'mcq', '["Des chambres d’écho qui montrent ce qui confirme et ce qui indigne","Une information plus pluraliste","Un débat plus lent et plus réfléchi","La disparition de la désinformation"]'::jsonb, 0, 'En privilégiant ce qui retient l’attention, ils enferment dans des bulles de filtre et favorisent l’indignation.', 3),
    ('8e1e2642-227e-59df-9b8a-36f32b84067b'::uuid, 'emc', 'Tle', 'Faire vivre le débat dans une démocratie', 'Avant de discuter la position adverse, que faut-il faire ?', 'mcq', '["La résumer en une caricature","L’ignorer si elle est minoritaire","Vérifier qui la défend","L’exposer honnêtement"]'::jsonb, 3, 'Exposer honnêtement la thèse adverse avant de la discuter est l’une des quatre compétences attendues.', 4),
    ('2c1a5cb5-c557-586c-b764-7a95e7ac654a'::uuid, 'emc', 'Tle', 'Le modèle démocratique en question : exemplarité et transparence', 'Quelle affaire provoque en 2013 la création de la HATVP ?', 'mcq', '["L’affaire Cahuzac","L’affaire Dreyfus","L’affaire des emplois fictifs de la Ville de Paris","L’affaire Bettencourt"]'::jsonb, 0, 'Le ministre du Budget avait menti sur un compte détenu à l’étranger, ce qui a déclenché la réforme de la transparence.', 1),
    ('5c032200-586d-5a33-9d46-af3b702ab784'::uuid, 'emc', 'Tle', 'Le modèle démocratique en question : exemplarité et transparence', 'Que doit faire un responsable public placé en situation de conflit d’intérêts ?', 'mcq', '["Démissionner de tous ses mandats","Le déclarer et se déporter","Demander l’avis de la Cour des comptes","Rien, s’il est de bonne foi"]'::jsonb, 1, 'Se déporter, c’est ne pas participer à la décision où son intérêt privé est en jeu.', 2),
    ('86593be9-b9fe-505a-a812-ffeaed726422'::uuid, 'emc', 'Tle', 'Le modèle démocratique en question : exemplarité et transparence', 'Qu’ont supprimé les lois de 2017 pour la confiance dans la vie politique ?', 'mcq', '["Le financement public des partis","Le statut des lanceurs d’alerte","La réserve parlementaire","Les déclarations de patrimoine"]'::jsonb, 2, 'La réserve parlementaire, enveloppe distribuée par les parlementaires, est supprimée en même temps que sont interdits les emplois familiaux.', 3),
    ('ce914845-c8b2-53ab-be35-c8dd17a1d351'::uuid, 'emc', 'Tle', 'Le modèle démocratique en question : exemplarité et transparence', 'Qu’apporte la loi de 2022 sur les lanceurs d’alerte ?', 'mcq', '["Le premier statut du lanceur d’alerte","L’obligation de passer par la presse","La suppression de toute procédure de signalement","Une protection renforcée contre les représailles, en transposant une directive européenne"]'::jsonb, 3, 'Sapin II (2016) crée le statut ; la loi de 2022 transpose la directive de 2019 et clarifie la procédure.', 4),
    ('2d85f7c9-192f-50e5-9b76-251b0077b729'::uuid, 'emc', 'Tle', 'S’engager dans la démocratie au XXIe siècle', 'Environ combien de bénévoles compte la France ?', 'mcq', '["2 millions","5 millions","20 millions","50 millions"]'::jsonb, 2, 'Environ 20 millions de bénévoles dans plus d’un million d’associations : c’est la première forme d’engagement du pays.', 1),
    ('7983f516-977b-51cf-b4e7-9a8870cb4f51'::uuid, 'emc', 'Tle', 'S’engager dans la démocratie au XXIe siècle', 'Quel paradoxe caractérise le syndicalisme français ?', 'mcq', '["Beaucoup d’adhérents mais peu d’accords","Un faible taux de syndicalisation mais une couverture des accords collectifs très élevée","Des syndicats interdits dans le privé","Une adhésion obligatoire mais peu de grèves"]'::jsonb, 1, 'Autour de 10 % de syndiqués, mais la plupart des salariés sont couverts par des accords collectifs.', 2),
    ('a9306a6e-fb1a-5db9-8297-86e89ec98300'::uuid, 'emc', 'Tle', 'S’engager dans la démocratie au XXIe siècle', 'À qui est ouvert le service civique ?', 'mcq', '["Aux 16-25 ans","Aux seuls étudiants","Aux retraités","Aux 18-30 ans"]'::jsonb, 0, 'Créé en 2010, le service civique propose des missions d’intérêt général aux jeunes de 16 à 25 ans.', 3),
    ('52615ff0-b0cc-5cbe-a0b0-3b312900c75f'::uuid, 'emc', 'Tle', 'S’engager dans la démocratie au XXIe siècle', 'Qu’est-ce qui distingue un engagement d’un geste isolé, selon le cours ?', 'mcq', '["Son caractère spectaculaire","Le nombre de personnes qui le voient","Son coût financier","La continuité de l’action et son ancrage dans une organisation"]'::jsonb, 3, 'Un clic sincère n’est pas un engagement : il faut une action qui dure et qui s’inscrit dans un collectif.', 4),
    ('62d27195-7e7a-58ca-95ee-d81523e98282'::uuid, 'emc', 'Tle', 'Nouvelles aspirations démocratiques', 'Combien de propositions a formulées la Convention citoyenne pour le climat ?', 'mcq', '["49","149","250","1 000"]'::jsonb, 1, 'Elle a produit 149 propositions, reprises très partiellement : d’où la question de ce qu’on fait des propositions.', 1),
    ('6f198bff-ba08-5725-950f-9fbffdda03bf'::uuid, 'emc', 'Tle', 'Nouvelles aspirations démocratiques', 'Que manque-t-il aux citoyens tirés au sort, par rapport aux élus ?', 'mcq', '["La diversité sociale","L’information","Un mandat","Le temps de délibérer"]'::jsonb, 2, 'Personne n’a voté pour eux : ils apportent la diversité, mais pas la légitimité d’un mandat.', 2),
    ('e402f3d2-c351-5a82-be85-a62a17264e77'::uuid, 'emc', 'Tle', 'Nouvelles aspirations démocratiques', 'Combien d’électeurs doivent soutenir un référendum d’initiative partagée ?', 'mcq', '["Un dixième du corps électoral, environ 4,8 millions","500 000","Un million","La moitié des inscrits"]'::jsonb, 0, 'Il faut aussi un cinquième des parlementaires ; la procédure n’est jamais allée à son terme.', 3),
    ('b5925e87-5683-53d3-96d7-768cf5a5354b'::uuid, 'emc', 'Tle', 'Nouvelles aspirations démocratiques', 'Qu’a rendu la Convention citoyenne sur la fin de vie en 2023 ?', 'mcq', '["Un avis défavorable à toute évolution","Un projet de loi adopté tel quel","Aucun avis","Un avis favorable à une aide active à mourir"]'::jsonb, 3, 'Réunie en 2022-2023, elle s’est prononcée en faveur d’une aide active à mourir, sous conditions.', 4),
    ('b028fd9e-afbb-565e-b6d6-9df13802bdeb'::uuid, 'emc', 'Tle', 'Conscience démocratique et relations internationales', 'Quelle force contraignante a la Déclaration universelle des droits de l’homme ?', 'mcq', '["Aucune, mais c’est une référence morale et juridique universelle","Elle est appliquée par la CEDH","Elle s’impose à tous les tribunaux nationaux","Elle est sanctionnée par le Conseil de sécurité"]'::jsonb, 0, 'La DUDH de 1948 n’est pas un traité contraignant ; la Convention européenne de 1950, elle, l’est.', 1),
    ('48ddb1c7-6dbd-5f04-b0ca-1942519b4356'::uuid, 'emc', 'Tle', 'Conscience démocratique et relations internationales', 'Depuis quand la Cour pénale internationale fonctionne-t-elle ?', 'mcq', '["1948","1998","2002","2010"]'::jsonb, 2, 'Le statut de Rome est signé en 1998 et entre en vigueur en 2002.', 2),
    ('7200fbb5-6632-5c7a-8c8f-b8c95a566484'::uuid, 'emc', 'Tle', 'Conscience démocratique et relations internationales', 'Pourquoi la CPI dépend-elle des États ?', 'mcq', '["Ils nomment ses accusés","Elle n’a pas de police : ils doivent arrêter les personnes recherchées","Ils votent chacun de ses jugements","Elle ne juge que des chefs d’État consentants"]'::jsonb, 1, 'Sans force propre, la Cour a besoin des États pour exécuter ses mandats d’arrêt.', 3),
    ('a56bf570-4789-5e38-b07e-308f583eb720'::uuid, 'emc', 'Tle', 'Conscience démocratique et relations internationales', 'Quel reproche est souvent adressé aux puissances occidentales qui promeuvent la démocratie ?', 'mcq', '["L’isolationnisme","Le pacifisme","Le refus de toute intervention","Le « deux poids, deux mesures »"]'::jsonb, 3, 'On leur reproche d’appliquer leurs exigences selon leurs intérêts, sévères avec certains régimes, indulgentes avec d’autres.', 4),
    ('03c8db8e-902a-599e-8135-3c136f33fc85'::uuid, 'maths', 'Tle', 'Factorielle, k-uplet, permutation et combinaison', 'Combien de codes à 4 chiffres (de 0 à 9) peut-on former ?', 'mcq', '["4 000","10 000","5 040","210"]'::jsonb, 1, 'L’ordre compte et les chiffres peuvent se répéter : c’est un 4-uplet, soit 10⁴ = 10 000 codes.', 1),
    ('9b3f5f37-9675-54da-87c9-7d1050cc8b27'::uuid, 'maths', 'Tle', 'Factorielle, k-uplet, permutation et combinaison', 'Combien de podiums de 3 places peut-on former avec 8 coureurs ?', 'mcq', '["56","512","336","24"]'::jsonb, 2, 'L’ordre compte et un coureur n’occupe qu’une place : c’est un arrangement, 8 × 7 × 6 = 336.', 2),
    ('9252e54f-5d0a-5a3f-b6b1-38012d3e18a8'::uuid, 'maths', 'Tle', 'Factorielle, k-uplet, permutation et combinaison', 'De combien de façons peut-on ranger 5 objets distincts en ligne ?', 'mcq', '["120","25","3 125","60"]'::jsonb, 0, 'Ordonner n objets distincts, c’est une permutation : 5! = 5 × 4 × 3 × 2 × 1 = 120.', 3),
    ('8eaeade3-5349-52d6-92a3-47d7377d9f1d'::uuid, 'maths', 'Tle', 'Factorielle, k-uplet, permutation et combinaison', 'Pourquoi divise-t-on par k! dans la formule de C(n,k) ?', 'mcq', '["Pour autoriser les répétitions","Pour exclure les éléments non choisis","Pour obtenir un nombre pair","Pour effacer l’ordre des k éléments choisis"]'::jsonb, 3, 'On part des arrangements n!/(n−k)!, puis on divise par les k! façons d’ordonner les éléments choisis : il ne reste que la partie, sans ordre.', 4),
    ('33861028-a551-58f5-b197-5ffebf7bb4ed'::uuid, 'maths', 'Tle', 'Droites, plans et vecteurs de l’espace', 'Quelles sont les coordonnées du vecteur AB pour A(1 ; 2 ; 3) et B(4 ; 0 ; 5) ?', 'mcq', '["(5 ; 2 ; 8)","(−3 ; 2 ; −2)","(3 ; −2 ; 2)","(3 ; 2 ; 2)"]'::jsonb, 2, 'On calcule « arrivée moins départ » coordonnée par coordonnée : (4 − 1 ; 0 − 2 ; 5 − 3) = (3 ; −2 ; 2).', 1),
    ('c51400cd-4224-572f-8d73-3ab653d1ef3c'::uuid, 'maths', 'Tle', 'Droites, plans et vecteurs de l’espace', 'Comment obtient-on les coordonnées du milieu de [AB] dans l’espace ?', 'mcq', '["En faisant la moyenne des coordonnées de A et de B","En soustrayant les coordonnées de A à celles de B","En additionnant les coordonnées de A et de B","En multipliant les coordonnées de A et de B"]'::jsonb, 0, 'Comme dans le plan, avec une coordonnée de plus : chaque coordonnée du milieu est la moyenne de celles de A et de B.', 2),
    ('0ad0a7a7-7a32-5a78-b719-175b236b2bcd'::uuid, 'maths', 'Tle', 'Droites, plans et vecteurs de l’espace', 'Deux plans parallèles coupés par un troisième plan déterminent deux droites…', 'mcq', '["Sécantes","Non coplanaires","Orthogonales","Parallèles"]'::jsonb, 3, 'C’est l’un des théorèmes du chapitre : les deux droites d’intersection sont parallèles.', 3),
    ('60935798-9551-570c-88ec-e070377b08bd'::uuid, 'maths', 'Tle', 'Droites, plans et vecteurs de l’espace', 'Parmi ces données, laquelle suffit à définir un plan ?', 'mcq', '["Deux points distincts","Trois points non alignés","Un point et un seul vecteur directeur","Trois points alignés"]'::jsonb, 1, 'Trois points non alignés fournissent un point et deux vecteurs directeurs non colinéaires ; alignés, ils ne définissent qu’une droite.', 4),
    ('cc7096ce-34db-5944-ab30-188916ecabf6'::uuid, 'maths', 'Tle', 'Positions relatives de droites et de plans de l’espace', 'Combien de points communs une droite sécante à un plan a-t-elle avec lui ?', 'mcq', '["Aucun","Deux","Un seul","Une infinité"]'::jsonb, 2, 'Une droite sécante coupe le plan en un unique point ; une infinité signifie qu’elle y est incluse, aucun qu’elle lui est strictement parallèle.', 1),
    ('bda3406c-f868-58a2-85e3-efac1c69b06f'::uuid, 'maths', 'Tle', 'Positions relatives de droites et de plans de l’espace', 'Deux droites ont des vecteurs directeurs colinéaires et un point commun. Elles sont…', 'mcq', '["Confondues","Sécantes","Non coplanaires","Strictement parallèles"]'::jsonb, 0, 'Directeurs colinéaires : les droites sont parallèles ; si un point de l’une appartient à l’autre, elles sont confondues.', 2),
    ('e1ad9aa5-87ec-57f1-bc52-91e58a83f6e8'::uuid, 'maths', 'Tle', 'Positions relatives de droites et de plans de l’espace', 'Quand trois plans ont-ils un unique point commun ?', 'mcq', '["Quand leurs vecteurs normaux sont colinéaires","Quand deux d’entre eux sont parallèles","Quand ils passent tous par l’origine","Quand leurs trois vecteurs normaux sont non coplanaires"]'::jsonb, 3, 'Des vecteurs normaux non coplanaires garantissent que le système des trois équations a une solution unique : un point.', 3),
    ('294ff200-025b-599f-884b-1ddc5ccc255c'::uuid, 'maths', 'Tle', 'Positions relatives de droites et de plans de l’espace', 'Qu’appelle-t-on la configuration « en prisme » de trois plans ?', 'mcq', '["Trois plans qui se coupent en un point","Trois plans sécants deux à deux selon trois droites parallèles distinctes","Trois plans confondus","Trois plans parallèles entre eux"]'::jsonb, 1, 'Chaque paire de plans se coupe selon une droite, mais les trois droites sont parallèles : les trois plans n’ont aucun point commun.', 4),
    ('93fba3f3-5449-596b-a1a3-a883deadc260'::uuid, 'maths', 'Tle', 'Produit scalaire, orthogonalité et distances dans l’espace', 'Que vaut ‖u + v‖² ?', 'mcq', '["‖u‖² + ‖v‖²","‖u‖² − 2 u · v + ‖v‖²","(‖u‖ + ‖v‖)²","‖u‖² + 2 u · v + ‖v‖²"]'::jsonb, 3, 'Les identités remarquables s’appliquent aux vecteurs : le terme 2 u · v disparaît seulement si u et v sont orthogonaux.', 1),
    ('b845bb02-5b1f-575c-b334-04e96e463417'::uuid, 'maths', 'Tle', 'Produit scalaire, orthogonalité et distances dans l’espace', 'Que vaut u · v pour u(1 ; 2 ; −1) et v(3 ; −1 ; 1) ?', 'mcq', '["2","0","4","−2"]'::jsonb, 1, '1 × 3 + 2 × (−1) + (−1) × 1 = 3 − 2 − 1 = 0 : les deux vecteurs sont orthogonaux.', 2),
    ('5d3e2de6-41b5-594f-a5ff-8f93cc405ad4'::uuid, 'maths', 'Tle', 'Produit scalaire, orthogonalité et distances dans l’espace', 'Quel vecteur est normal au plan d’équation 2x − y + 3z + 4 = 0 ?', 'mcq', '["n(2 ; −1 ; 3)","n(2 ; 1 ; 3)","n(−1 ; 3 ; 4)","n(2 ; −1 ; 4)"]'::jsonb, 0, 'Les coefficients de x, y et z sont exactement les coordonnées d’un vecteur normal ; le terme constant d n’y entre pas.', 3),
    ('38b889df-0638-5ec9-a347-fb221e3883db'::uuid, 'maths', 'Tle', 'Produit scalaire, orthogonalité et distances dans l’espace', 'Quelle est la distance de l’origine O au plan d’équation x + 2y + 2z − 6 = 0 ?', 'mcq', '["6","3","2","6/5"]'::jsonb, 2, 'On divise |0 + 0 + 0 − 6| = 6 par √(1² + 2² + 2²) = √9 = 3 : la distance vaut 2.', 4),
    ('92f7da79-2a1b-5578-a1cb-b1f357360757'::uuid, 'maths', 'Tle', 'Représentations paramétriques de droites et équations cartésiennes de plans de l’espace', 'Quel point de la droite x = 1 + 2t, y = −t, z = 3 + t obtient-on pour t = 1 ?', 'mcq', '["(1 ; 0 ; 3)","(3 ; 1 ; 4)","(2 ; −1 ; 1)","(3 ; −1 ; 4)"]'::jsonb, 3, 'On remplace t par 1 : x = 1 + 2 = 3, y = −1, z = 3 + 1 = 4.', 1),
    ('be1c5ba1-440c-5c6a-8dde-e6dde229df56'::uuid, 'maths', 'Tle', 'Représentations paramétriques de droites et équations cartésiennes de plans de l’espace', 'Quel est un vecteur directeur de la droite x = 2 + 3t, y = 1 − t, z = 4 ?', 'mcq', '["(3 ; −1 ; 0)","(2 ; 1 ; 4)","(3 ; −1 ; 4)","(3 ; 1 ; 0)"]'::jsonb, 0, 'Le vecteur directeur se lit sur les coefficients de t ; z ne dépend pas de t, sa coordonnée est donc 0.', 2),
    ('4994f2b0-8324-554c-8eee-8dea51641bf0'::uuid, 'maths', 'Tle', 'Représentations paramétriques de droites et équations cartésiennes de plans de l’espace', 'Que décrit l’équation obtenue en multipliant 2x − y + z − 1 = 0 par 3 ?', 'mcq', '["Un plan parallèle distinct","Le même plan","Un plan orthogonal","Un plan passant par l’origine"]'::jsonb, 1, 'Multiplier toute l’équation par un réel non nul ne change pas l’ensemble des points : l’équation cartésienne d’un plan n’est pas unique.', 3),
    ('5990b838-bdce-5130-a11a-01400c330a8c'::uuid, 'maths', 'Tle', 'Représentations paramétriques de droites et équations cartésiennes de plans de l’espace', 'Comment vérifier que deux représentations paramétriques décrivent la même droite ?', 'mcq', '["En comparant leurs constantes","En comparant leurs paramètres","En testant la colinéarité des directeurs, puis l’appartenance d’un point de l’une à l’autre","En calculant le produit scalaire des directeurs"]'::jsonb, 2, 'Des directeurs colinéaires donnent des droites parallèles ; un point commun les rend confondues.', 4),
    ('1a401fb0-0085-5e4a-a468-c65f73d72f32'::uuid, 'maths', 'Tle', 'Raisonnement par récurrence', 'Dans l’image de l’échelle, à quoi correspond l’initialisation ?', 'mcq', '["Passer d’un barreau au suivant","Atteindre le sommet","Monter sur le premier barreau","Choisir la hauteur de l’échelle"]'::jsonb, 2, 'L’initialisation met le pied sur le premier barreau ; l’hérédité permet de passer de chaque barreau au suivant.', 1),
    ('5b5d0b99-4832-588e-9b68-4f31c7a63ca7'::uuid, 'maths', 'Tle', 'Raisonnement par récurrence', 'La propriété « 2ⁿ > n² » est-elle vraie pour n = 3 ?', 'mcq', '["Oui, car 8 > 6","Non, car 8 < 9","Oui, car 9 > 8","On ne peut pas le savoir"]'::jsonb, 1, '2³ = 8 et 3² = 9 : elle est fausse. Elle est pourtant héréditaire à partir d’un rang, preuve que l’hérédité seule ne démontre rien.', 2),
    ('e5a879c0-0154-5cba-854b-f8483c117679'::uuid, 'maths', 'Tle', 'Raisonnement par récurrence', 'Pourquoi est-ce une faute d’utiliser P(n+1) pour démontrer l’hérédité ?', 'mcq', '["Parce que P(n+1) est toujours fausse","Parce que cela allonge la démonstration","Parce que P(n+1) ne dépend pas de n","Parce que c’est supposer ce qu’on veut démontrer"]'::jsonb, 3, 'L’hypothèse de récurrence est P(n) ; P(n+1) est la conclusion à atteindre.', 3),
    ('44709dbb-ec66-5fee-9c11-9c6dbc43ec0d'::uuid, 'maths', 'Tle', 'Raisonnement par récurrence', 'Qu’attend-on dans la rédaction de l’initialisation ?', 'mcq', '["La vérification de P(n₀) par le calcul, en écrivant les deux membres","La supposition que P(n) est vraie","Le calcul de P(n+1)","La phrase de conclusion"]'::jsonb, 0, 'On vérifie P(n₀) par un calcul explicite de chaque membre : la rigueur de la rédaction fait partie de la note.', 4),
    ('130f9fcd-4abd-51f3-a052-7c5fee055d5c'::uuid, 'maths', 'Tle', 'Limites de suites', 'Quel est le comportement de la suite (−2)ⁿ ?', 'mcq', '["Elle tend vers +∞","Elle tend vers 0","Elle tend vers −∞","Elle n’a pas de limite"]'::jsonb, 3, 'Pour q inférieur ou égal à −1, qⁿ n’a pas de limite : ici les termes changent de signe en grandissant en valeur absolue.', 1),
    ('a220c873-896c-5935-a01b-e47d5b67b91f'::uuid, 'maths', 'Tle', 'Limites de suites', 'Comment lever l’indétermination de n² − n en +∞ ?', 'mcq', '["En factorisant par n², le terme dominant","En multipliant par l’expression conjuguée","En appliquant le théorème des gendarmes","En passant au logarithme"]'::jsonb, 0, 'n² − n = n²(1 − 1/n) : le premier facteur tend vers +∞, le second vers 1, donc la limite est +∞.', 2),
    ('b7ddff21-277a-5be2-af20-3a380ca643ad'::uuid, 'maths', 'Tle', 'Limites de suites', 'Quel outil démontre que qⁿ tend vers +∞ lorsque q > 1 ?', 'mcq', '["Le théorème des gendarmes","L’inégalité de Bernoulli","La relation de Pascal","Le théorème de la limite monotone"]'::jsonb, 1, 'En écrivant q = 1 + a avec a > 0, on a qⁿ supérieur ou égal à 1 + n a, qui tend vers +∞ : on conclut par minoration.', 3),
    ('8bcf5b36-d29a-5ed9-b547-14203a9ac28c'::uuid, 'maths', 'Tle', 'Limites de suites', 'Quelle est la limite de cos(n)/n ?', 'mcq', '["1","Elle n’existe pas","0","+∞"]'::jsonb, 2, 'cos(n) est compris entre −1 et 1, donc cos(n)/n est encadré par −1/n et 1/n, qui tendent vers 0 : c’est le théorème des gendarmes.', 4),
    ('612669b1-b528-50db-b9e1-e42e6d2d85d5'::uuid, 'maths', 'Tle', 'Limites de fonctions', 'Quelle est la limite de 1/√x quand x tend vers 0 par valeurs positives ?', 'mcq', '["0","+∞","1","−∞"]'::jsonb, 1, 'Le dénominateur √x tend vers 0 en restant positif : le quotient tend vers +∞.', 1),
    ('d3a6061c-0ba7-58c3-a41b-099816c4fac0'::uuid, 'maths', 'Tle', 'Limites de fonctions', 'Quelle est la limite de (3x² + 1)/(x² − 5) en +∞ ?', 'mcq', '["+∞","0","−1/5","3"]'::jsonb, 3, 'En +∞, une fraction rationnelle a la limite du quotient de ses termes de plus haut degré : 3x²/x² = 3.', 2),
    ('798f6b4b-e065-5811-b728-ffef1e63144d'::uuid, 'maths', 'Tle', 'Limites de fonctions', 'Quand la droite x = a est-elle asymptote verticale à la courbe de f ?', 'mcq', '["Quand f(x) tend vers ±∞ quand x tend vers a","Quand f(a) = 0","Quand f(x) tend vers a en l’infini","Quand f n’est pas dérivable en a"]'::jsonb, 0, 'Une asymptote verticale traduit une limite infinie en un réel, souvent une valeur interdite.', 3),
    ('6792e7bf-dc3c-549d-a97d-47a057994abf'::uuid, 'maths', 'Tle', 'Limites de fonctions', 'Quelle technique lève en général une forme 0/0 en un point ?', 'mcq', '["Factoriser par le terme de plus haut degré","Multiplier par x","Reconnaître un taux d’accroissement","Remplacer x par sa valeur"]'::jsonb, 2, 'Une forme 0/0 en a cache souvent (f(x) − f(a))/(x − a), dont la limite est le nombre dérivé f′(a).', 4),
    ('4820e7f3-41fd-506c-ba76-41a50071f490'::uuid, 'maths', 'Tle', 'Dérivée de 2 fonctions composées', 'Quelle est la dérivée de 1/u, pour u non nulle ?', 'mcq', '["1/u′","−u′/u²","−1/u²","u′/u²"]'::jsonb, 1, 'C’est la dérivée de la fonction inverse (−1/y²) prise en u, multipliée par u′.', 1),
    ('3e4aab69-b33e-542d-9f24-3c771edae43a'::uuid, 'maths', 'Tle', 'Dérivée de 2 fonctions composées', 'Quelle est la dérivée de e^(3x² + 1) ?', 'mcq', '["e^(3x² + 1)","6x","(3x² + 1) e^(3x²)","6x e^(3x² + 1)"]'::jsonb, 3, 'Avec u = 3x² + 1 et u′ = 6x, la formule (e^u)′ = u′ e^u donne 6x e^(3x² + 1).', 2),
    ('e94a4aed-b1e7-575a-b947-71b282e61b2c'::uuid, 'maths', 'Tle', 'Dérivée de 2 fonctions composées', 'Quelle est la dérivée de ln(x² + 1) ?', 'mcq', '["2x / (x² + 1)","1 / (x² + 1)","2x ln(x² + 1)","1 / (2x)"]'::jsonb, 0, 'x² + 1 est toujours strictement positif ; (ln u)′ = u′/u avec u′ = 2x.', 3),
    ('2cd81f91-ea64-55b1-99d9-7d69fc2da801'::uuid, 'maths', 'Tle', 'Dérivée de 2 fonctions composées', 'Pourquoi √u n’est-elle dérivable que là où u est strictement positive ?', 'mcq', '["Parce que √u n’est pas définie en 0","Parce que u′ s’annule en 0","Parce que la racine carrée n’est pas dérivable en 0, bien qu’elle y soit définie","Parce que √u est décroissante"]'::jsonb, 2, 'La dérivée u′/(2√u) exige √u non nulle : la racine est définie en 0 mais pas dérivable.', 4),
    ('cafa0365-8d38-50a9-9b9c-35ccff31ebbb'::uuid, 'maths', 'Tle', 'Fonctions convexes', 'Où se place la courbe d’une fonction convexe par rapport à ses cordes ?', 'mcq', '["Au-dessus","Confondue avec elles","Elle les traverse toujours","Au-dessous"]'::jsonb, 3, 'Convexe : au-dessus des tangentes, mais au-dessous des cordes entre deux de ses points.', 1),
    ('6b05d3b7-5f6b-5fd7-a2d5-4569ccd10c17'::uuid, 'maths', 'Tle', 'Fonctions convexes', 'Pour f dérivable, f est convexe sur un intervalle si et seulement si…', 'mcq', '["f′ est croissante","f′ est positive","f est croissante","f′ est nulle"]'::jsonb, 0, 'La convexité se lit sur la croissance de f′, c’est-à-dire sur le signe positif de f″ ; pas sur le signe de f′.', 2),
    ('2e17c708-c0a8-5f77-bdae-6a6212c3078a'::uuid, 'maths', 'Tle', 'Fonctions convexes', 'En quel point la fonction cube change-t-elle de convexité ?', 'mcq', '["En 1","En 0","En −1","Elle n’en change jamais"]'::jsonb, 1, 'Sa dérivée seconde 6x change de signe en 0 : x³ est concave sur les négatifs, convexe sur les positifs.', 3),
    ('911c6151-65ea-5143-8595-4d55ccd9d08c'::uuid, 'maths', 'Tle', 'Fonctions convexes', 'Sur une courbe, f′ > 0 et f″ > 0 se lisent comme…', 'mcq', '["« ça augmente de moins en moins vite »","« ça diminue de plus en plus vite »","« ça augmente de plus en plus vite »","« ça stagne »"]'::jsonb, 2, 'f′ > 0 : la fonction croît ; f″ > 0 : sa pente elle-même augmente, la croissance accélère.', 4),
    ('afc00d0e-d95f-5d59-8095-6453b8fa513e'::uuid, 'maths', 'Tle', 'Continuité des fonctions d’une variable réelle', 'Quel exemple montre qu’une fonction continue n’est pas forcément dérivable ?', 'mcq', '["L’exponentielle en 0","La valeur absolue en 0","Le cosinus en 0","Un polynôme en 0"]'::jsonb, 1, 'La valeur absolue est continue en 0, mais sa courbe y présente un point anguleux : elle n’y est pas dérivable.', 1),
    ('cfbb1550-5388-5026-9ae1-090ba1e6992f'::uuid, 'maths', 'Tle', 'Continuité des fonctions d’une variable réelle', 'Pour appliquer le théorème des valeurs intermédiaires à f(x) = k sur [a ; b], que faut-il vérifier sur k ?', 'mcq', '["Qu’il est positif","Qu’il est entier","Qu’il vaut f((a + b)/2)","Qu’il est compris entre f(a) et f(b)"]'::jsonb, 3, 'Continuité et encadrement de k entre les valeurs aux bornes : ce sont les deux hypothèses du théorème.', 2),
    ('7d8016f2-0553-54d1-a020-3843d7dceb27'::uuid, 'maths', 'Tle', 'Continuité des fonctions d’une variable réelle', 'Environ combien d’étapes de dichotomie faut-il pour gagner trois décimales ?', 'mcq', '["Dix","Trois","Cent","Mille"]'::jsonb, 0, 'Chaque étape divise l’amplitude par deux ; après dix étapes, elle est divisée par 2¹⁰ = 1 024, soit environ mille.', 3),
    ('3d2bb326-f527-51cf-af23-5f78a52ae735'::uuid, 'maths', 'Tle', 'Continuité des fonctions d’une variable réelle', 'La fonction x ↦ e^(sin x) est-elle continue sur ℝ ?', 'mcq', '["Non, car sin s’annule","Seulement sur [0 ; π]","Oui, comme composée de fonctions continues","Non, car elle est périodique"]'::jsonb, 2, 'Sinus et exponentielle sont continues sur ℝ ; une composée de fonctions continues est continue.', 4),
    ('4c02e574-ff8f-575d-b716-70b09cd33c41'::uuid, 'maths', 'Tle', 'Fonction logarithme népérien (ln)', 'Que vaut ln(a/b) pour a et b strictement positifs ?', 'mcq', '["ln a / ln b","ln(a − b)","ln a − ln b","ln b − ln a"]'::jsonb, 2, 'Le logarithme transforme un quotient en différence, comme il transforme un produit en somme.', 1),
    ('6278acc0-ab9e-5cd9-a542-3515e59e89b0'::uuid, 'maths', 'Tle', 'Fonction logarithme népérien (ln)', 'Quel est le signe de ln(x) pour x strictement compris entre 0 et 1 ?', 'mcq', '["Positif","Négatif","Nul","Il n’est pas défini"]'::jsonb, 1, 'ln(1) = 0 et ln est strictement croissante : avant 1, ln(x) est négatif.', 2),
    ('3874f767-d0aa-5cfc-8c97-e101e5f3b464'::uuid, 'maths', 'Tle', 'Fonction logarithme népérien (ln)', 'Quelle formule donne la demi-vie d’un noyau radioactif de constante λ ?', 'mcq', '["ln(2)/λ","λ/ln(2)","2λ","e^(−λ)"]'::jsonb, 0, 'On cherche t tel que e^(−λt) = 1/2, soit −λt = −ln 2, donc t = ln(2)/λ.', 3),
    ('66fd06a9-c220-51fa-8872-7ffbe82584e7'::uuid, 'maths', 'Tle', 'Fonction logarithme népérien (ln)', 'Comment se placent les courbes de ln et de l’exponentielle l’une par rapport à l’autre ?', 'mcq', '["Elles sont confondues","Elles sont symétriques par rapport à l’axe des abscisses","Elles sont parallèles","Elles sont symétriques par rapport à la droite y = x"]'::jsonb, 3, 'Les deux fonctions sont réciproques l’une de l’autre : leurs courbes sont symétriques par rapport à la droite y = x.', 4),
    ('9ba43d4b-69a4-565d-82e0-6f2f4674efe6'::uuid, 'maths', 'Tle', 'Fonction ln (logarithme népérien) : continuité, limites et dérivabilité', 'Que vaut la dérivée seconde de ln ?', 'mcq', '["1/x²","−1/x","−1/x²","ln(x)"]'::jsonb, 2, 'On dérive 1/x : on obtient −1/x², strictement négatif, d’où la concavité de ln.', 1),
    ('89891a40-1096-5c21-8b47-d018f293f125'::uuid, 'maths', 'Tle', 'Fonction ln (logarithme népérien) : continuité, limites et dérivabilité', 'Quelle est la limite de ln(1 + x)/x quand x tend vers 0 ?', 'mcq', '["0","1","+∞","e"]'::jsonb, 1, 'C’est un taux d’accroissement de ln en 1 : sa limite est ln′(1) = 1.', 2),
    ('3b28307f-60b3-56d3-8e3e-f8bb847da30a'::uuid, 'maths', 'Tle', 'Fonction ln (logarithme népérien) : continuité, limites et dérivabilité', 'Quelle est la limite de e^x/x² en +∞ ?', 'mcq', '["+∞","0","1","Elle n’existe pas"]'::jsonb, 0, 'Croissance comparée : l’exponentielle l’emporte sur toute puissance de x.', 3),
    ('127d505e-a905-5a31-b7d8-77a40aee6aa7'::uuid, 'maths', 'Tle', 'Fonction ln (logarithme népérien) : continuité, limites et dérivabilité', 'Sur quel ensemble étudie-t-on la fonction x ↦ ln(x − 2) ?', 'mcq', '["ℝ","[2 ; +∞[","]0 ; +∞[","]2 ; +∞["]'::jsonb, 3, 'L’argument doit être strictement positif : x − 2 > 0, soit x > 2.', 4),
    ('fe662fea-2c1b-5e4b-b788-ce0035438130'::uuid, 'maths', 'Tle', 'Fonctions cosinus et sinus', 'Que vaut cos(x + π) ?', 'mcq', '["cos x","−cos x","sin x","−sin x"]'::jsonb, 1, 'Ajouter π fait un demi-tour sur le cercle trigonométrique : cosinus et sinus changent de signe.', 1),
    ('518cd2ee-c379-504a-a6f2-56a6d7b2f5fc'::uuid, 'maths', 'Tle', 'Fonctions cosinus et sinus', 'Que vaut cos(π/2 − x) ?', 'mcq', '["cos x","−sin x","−cos x","sin x"]'::jsonb, 3, 'Le passage à l’angle complémentaire échange les deux fonctions : cos(π/2 − x) = sin x.', 2),
    ('e372c9fc-3544-59aa-aaa4-575e5a6c4a3a'::uuid, 'maths', 'Tle', 'Fonctions cosinus et sinus', 'Quelles sont les solutions de sin(x) = sin(a) ?', 'mcq', '["x = a + 2kπ ou x = π − a + 2kπ","x = a + 2kπ seulement","x = a + 2kπ ou x = −a + 2kπ","x = a + kπ"]'::jsonb, 0, 'Deux familles de solutions : la seconde est π − a pour le sinus (et −a pour le cosinus). L’oublier est l’erreur classique.', 3),
    ('96904a0c-63e5-5d88-a0d2-70adf7b84078'::uuid, 'maths', 'Tle', 'Fonctions cosinus et sinus', 'Quelle est la limite de (cos(x) − 1)/x quand x tend vers 0 ?', 'mcq', '["1","−1","0","Elle n’existe pas"]'::jsonb, 2, 'C’est le taux d’accroissement du cosinus en 0 : sa limite est cos′(0) = −sin(0) = 0.', 4),
    ('81092961-9818-53ab-a6b2-ecbc1a263f83'::uuid, 'maths', 'Tle', 'Primitives et équations différentielles', 'Quelle est une primitive de sin x ?', 'mcq', '["cos x","sin x","−sin x","−cos x"]'::jsonb, 3, 'La dérivée de −cos x est sin x. Le signe moins est l’oubli classique.', 1),
    ('9f71b776-a249-53e5-bfd2-bf156aa3e56d'::uuid, 'maths', 'Tle', 'Primitives et équations différentielles', 'Quelle est une primitive de x e^(x² + 1) ?', 'mcq', '["(1/2) e^(x² + 1)","e^(x² + 1)","2x e^(x² + 1)","x² e^(x² + 1)"]'::jsonb, 0, 'Avec u = x² + 1, u′ = 2x : il manque un facteur 2, d’où le coefficient 1/2 devant e^u.', 2),
    ('3d4600fc-912f-5a6e-8683-072d7942d0a9'::uuid, 'maths', 'Tle', 'Primitives et équations différentielles', 'Quelles sont les solutions de y′ = 2y + 6 ?', 'mcq', '["x ↦ C e^(2x) + 3","x ↦ C e^(2x) − 3","x ↦ C e^(6x) + 2","x ↦ C e^(2x) − 6"]'::jsonb, 1, 'La solution constante vérifie 0 = 2y + 6, soit y = −3 ; on y ajoute les solutions C e^(2x) de y′ = 2y.', 3),
    ('d30bb626-cddb-5021-8458-4a4d1698d59b'::uuid, 'maths', 'Tle', 'Primitives et équations différentielles', 'Quelle est une primitive de 1/√x sur ]0 ; +∞[ ?', 'mcq', '["√x","1/(2√x)","2√x","−2/√x"]'::jsonb, 2, 'La dérivée de √x est 1/(2√x) : celle de 2√x est donc 1/√x.', 4),
    ('5b0223f7-16dd-5cc8-a10b-528a9efae373'::uuid, 'maths', 'Tle', 'Calcul intégral', 'Que vaut l’intégrale de 0 à 1 de 2x dx ?', 'mcq', '["2","1","1/2","0"]'::jsonb, 1, 'Une primitive de 2x est x² : 1² − 0² = 1, l’aire du triangle de base 1 et de hauteur 2.', 1),
    ('5a432239-b7cd-5d4a-984d-35cf6a4fac02'::uuid, 'maths', 'Tle', 'Calcul intégral', 'Quelle est la valeur moyenne de f(x) = 2x sur [0 ; 2] ?', 'mcq', '["4","1","8","2"]'::jsonb, 3, 'L’intégrale de 0 à 2 de 2x vaut 2² = 4 ; on la divise par la longueur de l’intervalle, 2.', 2),
    ('869c183c-4263-5395-8862-ce27c80f8bd4'::uuid, 'maths', 'Tle', 'Calcul intégral', 'Pour intégrer ln x par parties, que pose-t-on ?', 'mcq', '["v = ln x et u′ = 1","u = ln x et v′ = ln x","u′ = ln x et v = x","v = 1/x et u′ = x"]'::jsonb, 0, 'ln x n’a pas de primitive simple mais se dérive en 1/x : on le choisit comme facteur à dériver, avec u′ = 1.', 3),
    ('497c2e55-dc77-5f30-b2ef-2b16fc57d0bf'::uuid, 'maths', 'Tle', 'Calcul intégral', 'Quelle propriété permet d’encadrer une intégrale ?', 'mcq', '["La relation de Chasles","L’inversion des bornes","La croissance : si f est inférieure à g, son intégrale l’est aussi","La linéarité"]'::jsonb, 2, 'Pour a inférieur à b, encadrer f entre deux fonctions encadre son intégrale entre les leurs.', 4),
    ('cfd57478-73cc-51a1-abd4-6cadf5ee6f0b'::uuid, 'maths', 'Tle', 'Succession d’épreuves indépendantes, lois de Bernoulli et binomiale', 'Quelle est la variance d’une variable de Bernoulli de paramètre p ?', 'mcq', '["p","p²","p(1 − p)","1 − p"]'::jsonb, 2, 'E(X) = p et V(X) = p(1 − p) : la loi binomiale multiplie ces valeurs par n.', 1),
    ('1d14a037-2e56-55c8-9064-fdcd56aa27e1'::uuid, 'maths', 'Tle', 'Succession d’épreuves indépendantes, lois de Bernoulli et binomiale', 'X suit la loi B(3 ; 0,5). Que vaut P(X = 2) ?', 'mcq', '["0,375","0,25","0,125","0,5"]'::jsonb, 0, 'C(3,2) × 0,5² × 0,5 = 3 × 0,125 = 0,375 : trois chemins réalisent exactement deux succès.', 2),
    ('9ce51d4d-11d5-593c-b040-efcb317c8b3d'::uuid, 'maths', 'Tle', 'Succession d’épreuves indépendantes, lois de Bernoulli et binomiale', 'Sur 100 lancers d’une pièce équilibrée, combien de piles attend-on en moyenne ?', 'mcq', '["25","100","10","50"]'::jsonb, 3, 'X suit B(100 ; 0,5), d’espérance n p = 100 × 0,5 = 50.', 3),
    ('e36ce779-6861-5ec2-8030-4aa72c47878a'::uuid, 'maths', 'Tle', 'Succession d’épreuves indépendantes, lois de Bernoulli et binomiale', 'Pour une loi binomiale, les épreuves doivent être identiques, indépendantes et…', 'mcq', '["Sans remise","À deux issues seulement","Au nombre de deux","De même durée"]'::jsonb, 1, 'Chaque épreuve n’a que deux issues, succès ou échec : ce sont les trois conditions à vérifier.', 4),
    ('d4ce6824-94f1-5015-88cd-3dc3db35e858'::uuid, 'maths', 'Tle', 'Sommes de variables aléatoires', 'Que vaut E(aX + b) ?', 'mcq', '["a E(X) + b","a² E(X)","a E(X)","a² E(X) + b"]'::jsonb, 0, 'L’espérance est linéaire : la constante b se retrouve dans l’espérance, alors qu’elle disparaît de la variance.', 1),
    ('b231d7ed-c8bb-52c6-bf46-9c9ef28472a7'::uuid, 'maths', 'Tle', 'Sommes de variables aléatoires', 'X et Y sont indépendantes, avec V(X) = 4 et V(Y) = 9. Que vaut V(X + Y) ?', 'mcq', '["5","25","36","13"]'::jsonb, 3, 'Sous indépendance, les variances s’additionnent : 4 + 9 = 13. Ce sont les variances qui s’ajoutent, pas les écarts-types.', 2),
    ('de5f7578-6029-5df1-9bfa-970bd69c4314'::uuid, 'maths', 'Tle', 'Sommes de variables aléatoires', 'Quel est l’écart-type de la somme S de n variables indépendantes de même écart-type σ ?', 'mcq', '["n σ","σ √n","σ/√n","σ"]'::jsonb, 1, 'V(S) = n σ² par additivité sous indépendance, donc σ(S) = σ √n.', 3),
    ('f5d9c9a0-71f6-5619-8d18-73f83ee3f599'::uuid, 'maths', 'Tle', 'Sommes de variables aléatoires', 'Quelle formule donne la variance à partir d’espérances ?', 'mcq', '["V(X) = E(X)² − E(X²)","V(X) = E(X²)","V(X) = E(X²) − E(X)²","V(X) = √E(X)"]'::jsonb, 2, 'La variance est l’espérance du carré moins le carré de l’espérance ; elle est toujours positive.', 4),
    ('5a628672-b8dd-5df0-911a-0a0f934bfe8b'::uuid, 'maths', 'Tle', 'Loi des grands nombres et concentration', 'X a pour espérance 10 et pour variance 4. Quel majorant Bienaymé-Tchebychev donne-t-il pour P(|X − 10| ≥ 4) ?', 'mcq', '["1","0,25","0,4","0,0625"]'::jsonb, 1, 'Le majorant vaut V/δ² = 4/4² = 4/16 = 0,25.', 1),
    ('50ab2e82-4280-5c09-abb4-d984331c54f5'::uuid, 'maths', 'Tle', 'Loi des grands nombres et concentration', 'X est positive d’espérance 2. Que donne l’inégalité de Markov pour P(X ≥ 10) ?', 'mcq', '["Elle est au plus 0,2","Elle vaut 0,2","Elle est au moins 0,2","Elle est au plus 0,02"]'::jsonb, 0, 'P(X ≥ a) est majorée par E(X)/a = 2/10 = 0,2 : c’est une borne, pas une valeur exacte.', 2),
    ('ae1ea587-5bbc-5e55-b24f-78689f2ab595'::uuid, 'maths', 'Tle', 'Loi des grands nombres et concentration', 'Quel majorant l’inégalité de concentration donne-t-elle pour P(|M − μ| ≥ δ) ?', 'mcq', '["σ/(n δ)","σ² / δ²","n σ² / δ²","σ² / (n δ²)"]'::jsonb, 3, 'C’est Bienaymé-Tchebychev appliquée à M, dont la variance est σ²/n.', 3),
    ('cee2cdb2-f03b-5d24-a5cf-06e8333b42b7'::uuid, 'maths', 'Tle', 'Loi des grands nombres et concentration', 'Quelle est la faiblesse de l’inégalité de Bienaymé-Tchebychev ?', 'mcq', '["Elle ne vaut que pour la loi binomiale","Elle exige de connaître la loi exacte","Elle est grossière : son majorant dépasse souvent de loin la probabilité réelle","Elle n’utilise pas la variance"]'::jsonb, 2, 'Valable pour toute loi, elle sert à garantir une précision, pas à estimer finement une probabilité.', 4),
    ('28d0eef3-f797-52de-90d5-a4f0e6a518ac'::uuid, 'maths-complementaires', 'Tle', 'Suites et modèles d’évolution', 'Une hausse de 10 % suivie d’une baisse de 10 % donne au total…', 'mcq', '["Une baisse de 1 %","Aucune variation","Une hausse de 1 %","Une baisse de 10 %"]'::jsonb, 0, 'On multiplie les coefficients : 1,1 × 0,9 = 0,99, soit −1 % : on ne revient pas au point de départ.', 1),
    ('c5333695-7c80-51fe-bd79-3087a182b019'::uuid, 'maths-complementaires', 'Tle', 'Suites et modèles d’évolution', 'Un versement fixe de 50 € chaque mois sur un compte sans intérêts se modélise par…', 'mcq', '["Une suite géométrique de raison 50","Une suite arithmétique de raison 50","Une suite géométrique de raison 1,5","Une suite constante"]'::jsonb, 1, 'On ajoute toujours la même quantité : c’est le cas typique d’une suite arithmétique.', 2),
    ('84c66580-9513-59e0-8dff-94b4e2461c5e'::uuid, 'maths-complementaires', 'Tle', 'Suites et modèles d’évolution', 'Que se passe-t-il pour une suite géométrique de raison q = 1 ?', 'mcq', '["Elle tend vers 0","Elle croît sans limite","Elle est constante","Elle alterne de signe"]'::jsonb, 2, 'Multiplier par 1 à chaque étape ne change rien : tous les termes sont égaux au premier.', 3),
    ('deebe061-c74a-5516-b553-9d44ce95320e'::uuid, 'maths-complementaires', 'Tle', 'Suites et modèles d’évolution', 'Pour u(n+1) = 0,5 u(n) + 10, quel est le point fixe L ?', 'mcq', '["10","5","40","20"]'::jsonb, 3, 'L = 0,5 L + 10 donne 0,5 L = 10, soit L = 20.', 4),
    ('a4bf21b8-6ca4-5533-81ab-6b54ae9e3662'::uuid, 'maths-complementaires', 'Tle', 'Suites numériques, modèles discrets et limites', 'Quel type de croissance décrit une suite arithmétique de raison positive ?', 'mcq', '["Exponentielle","Linéaire","Logarithmique","Oscillante"]'::jsonb, 1, 'On ajoute la même quantité à chaque étape : la croissance est linéaire, contrairement à la géométrique, exponentielle.', 1),
    ('fa750713-f191-5e33-acd6-4749f6281f51'::uuid, 'maths-complementaires', 'Tle', 'Suites numériques, modèles discrets et limites', 'Quelle est la limite d’une suite géométrique de raison q = −2 ?', 'mcq', '["+∞","0","−∞","Elle n’a pas de limite"]'::jsonb, 3, 'Pour q inférieur ou égal à −1, les termes changent de signe à chaque étape en grossissant : la suite n’a pas de limite.', 2),
    ('a54c089b-5a3b-5e9c-8fbb-f6a1e20562f4'::uuid, 'maths-complementaires', 'Tle', 'Suites numériques, modèles discrets et limites', 'Que garantit le théorème de la limite monotone pour une suite croissante et majorée ?', 'mcq', '["L’existence de la limite, pas sa valeur","Que la limite vaut le majorant","Que la suite est géométrique","Que la suite est constante à partir d’un rang"]'::jsonb, 0, 'Le théorème affirme que la suite converge, mais la limite peut être strictement inférieure au majorant donné.', 3),
    ('455734a3-6815-5671-9fa1-379d6425aec1'::uuid, 'maths-complementaires', 'Tle', 'Suites numériques, modèles discrets et limites', 'Pour u(n+1) = a u(n) + b et v(n) = u(n) − c (c point fixe), quelle est la forme de u(n) ?', 'mcq', '["u(n) = u(0) × aⁿ + c","u(n) = (u(0) − c) × aⁿ + c","u(n) = u(0) + n b","u(n) = c × aⁿ"]'::jsonb, 1, 'v est géométrique de raison a, donc v(n) = (u(0) − c) aⁿ, et on ajoute c pour revenir à u.', 4),
    ('625b4cc9-819a-523c-843e-df87ce30b52e'::uuid, 'maths-complementaires', 'Tle', 'Limites de fonctions', 'Quelle est la limite de ln(x) quand x tend vers 0 par valeurs positives ?', 'mcq', '["0","+∞","−∞","1"]'::jsonb, 2, 'Le logarithme plonge vers −∞ au voisinage de 0 : l’axe des ordonnées est une asymptote verticale.', 1),
    ('fc84a1b5-9847-58c5-9dc8-08426a12953c'::uuid, 'maths-complementaires', 'Tle', 'Limites de fonctions', 'Quelle est la limite de e^(−x) en +∞ ?', 'mcq', '["0","+∞","1","−∞"]'::jsonb, 0, 'e^(−x) = 1/e^x, et e^x tend vers +∞ : le quotient tend vers 0.', 2),
    ('f4d6e414-6f5e-5016-ae07-29728535c403'::uuid, 'maths-complementaires', 'Tle', 'Limites de fonctions', 'Quelle est la limite en +∞ de (3x² + 1)/(x² − 5) ?', 'mcq', '["+∞","0","1","3"]'::jsonb, 3, 'Une fraction rationnelle se comporte en +∞ comme le quotient de ses termes de plus haut degré : 3x²/x² = 3.', 3),
    ('95354d9b-4ef5-50a5-b0f3-2e96748f92be'::uuid, 'maths-complementaires', 'Tle', 'Limites de fonctions', 'Obtenir une forme indéterminée signifie que la limite n’existe pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une forme indéterminée signale seulement qu’il faut transformer l’écriture (factoriser, croissances comparées) pour conclure.', 4),
    ('8b3a8c4a-b29c-5a80-b453-0c665fb2e31e'::uuid, 'maths-complementaires', 'Tle', 'Fonctions, dérivées et optimisation', 'Quelle est la dérivée d’un quotient u/v ?', 'mcq', '["(u′v − uv′)/v²","(u′v + uv′)/v²","u′/v′","(uv′ − u′v)/v²"]'::jsonb, 0, 'Au numérateur, l’ordre compte : u′v moins uv′, le tout divisé par v².', 1),
    ('23ff8106-4081-5d82-b361-53765d8997f1'::uuid, 'maths-complementaires', 'Tle', 'Fonctions, dérivées et optimisation', 'Que mesure le nombre dérivé f′(a) dans un modèle ?', 'mcq', '["La valeur de la grandeur en a","La vitesse de variation instantanée en a","La moyenne de la grandeur","La valeur maximale de la grandeur"]'::jsonb, 1, 'f′(a) est la vitesse de variation instantanée : combien la grandeur change par unité de x au voisinage de a.', 2),
    ('f316e6a4-01a6-59e2-8edd-a33740c92c06'::uuid, 'maths-complementaires', 'Tle', 'Fonctions, dérivées et optimisation', 'On cherche les dimensions d’un enclos ; le calcul donne un optimum pour une longueur négative. Que conclure ?', 'mcq', '["On garde cette valeur","On prend sa valeur absolue","La solution n’est pas acceptable : il faut revenir à l’intervalle où le problème a un sens","On change la fonction à optimiser"]'::jsonb, 2, 'Une longueur est positive : un optimum hors de l’intervalle de sens ne vaut rien concrètement.', 3),
    ('cff1631f-8251-5e3d-be56-eddcdfc730c9'::uuid, 'maths-complementaires', 'Tle', 'Fonctions, dérivées et optimisation', 'Pour f(x) = x³, que se passe-t-il en 0 ?', 'mcq', '["f admet un maximum local","f admet un minimum local","f n’est pas dérivable","f′(0) = 0 mais f reste croissante"]'::jsonb, 3, 'La dérivée 3x² s’annule en 0 sans changer de signe : pas d’extremum, seulement un point d’inflexion.', 4),
    ('f1a14778-f405-5d50-a579-84077c569fed'::uuid, 'maths-complementaires', 'Tle', 'Probabilités conditionnelles', 'Que vaut la somme des probabilités des branches issues d’un même nœud d’un arbre ?', 'mcq', '["0","1","La probabilité du nœud","Elle dépend de l’arbre"]'::jsonb, 1, 'Les branches d’un nœud décrivent toutes les issues possibles à partir de lui : leurs probabilités totalisent 1.', 1),
    ('cc90b33f-6c73-52b5-a71b-179b7ffc71fb'::uuid, 'maths-complementaires', 'Tle', 'Probabilités conditionnelles', 'Deux événements A et B sont indépendants si et seulement si…', 'mcq', '["P_B(A) = P(A)","P_B(A) = P(B)","P(A) = P(B)","P_B(A) = 1"]'::jsonb, 0, 'L’indépendance signifie que savoir que B s’est produit ne change rien à la probabilité de A.', 2),
    ('ffa4d1ed-79a5-54c7-ad23-6ab4f1b1504e'::uuid, 'maths-complementaires', 'Tle', 'Probabilités conditionnelles', 'P(B) = 0,4 et P_B(A) = 0,5. Que vaut P(A inter B) ?', 'mcq', '["0,9","0,1","0,2","0,8"]'::jsonb, 2, 'Formule des probabilités composées : P(A inter B) = P(B) × P_B(A) = 0,4 × 0,5 = 0,2.', 3),
    ('be93ae0e-406d-59ff-9e4f-74fc4ba97b9b'::uuid, 'maths-complementaires', 'Tle', 'Probabilités conditionnelles', 'Dans l’exemple du cours (maladie touchant 1 personne sur 10 000, test fiable à 99 %), quelle est environ la probabilité d’être malade sachant que le test est positif ?', 'mcq', '["99 %","50 %","10 %","1 %"]'::jsonb, 3, 'Environ 100 faux positifs pour 1 vrai malade : un positif a environ 1 chance sur 100 d’être un vrai malade.', 4),
    ('d74c9659-0336-52c6-9b32-aaa5fdc23745'::uuid, 'maths-complementaires', 'Tle', 'Continuité de fonctions', 'Quelle image intuitive traduit la continuité d’une fonction sur un intervalle ?', 'mcq', '["La courbe se trace sans lever le crayon","La courbe est une droite","La courbe est toujours croissante","La courbe passe par l’origine"]'::jsonb, 0, 'Une fonction continue ne fait pas de saut : on trace sa courbe d’un seul trait.', 1),
    ('9b5c48e1-445d-55a3-b434-3683bde08d4a'::uuid, 'maths-complementaires', 'Tle', 'Continuité de fonctions', 'Une fonction continue est-elle toujours dérivable ?', 'mcq', '["Oui, toujours","Non, la réciproque de « dérivable implique continue » est fausse","Oui, sur un intervalle fermé","Oui, si elle est croissante"]'::jsonb, 1, 'Dérivable entraîne continue, mais pas l’inverse : une fonction peut être continue avec un point anguleux.', 2),
    ('c3dc12ce-193b-54a7-9118-d84ba6087093'::uuid, 'maths-complementaires', 'Tle', 'Continuité de fonctions', 'Pourquoi ne peut-on pas appliquer le théorème des valeurs intermédiaires à un nombre d’individus ?', 'mcq', '["Parce qu’il est toujours positif","Parce qu’il est trop grand","Parce que c’est un modèle discret, qui avance par sauts","Parce qu’il est décroissant"]'::jsonb, 2, 'Un nombre d’individus ne prend que des valeurs entières : le modèle est discret, les théorèmes de continuité ne s’y appliquent pas.', 3),
    ('0626b0d7-1a52-55ca-ba9c-58ac5fc5ee29'::uuid, 'maths-complementaires', 'Tle', 'Continuité de fonctions', 'À chaque étape de la dichotomie, la précision de l’encadrement…', 'mcq', '["Reste la même","Est multipliée par 10","Diminue","Double"]'::jsonb, 3, 'On garde la moitié de l’intervalle où le signe change : sa longueur est divisée par 2, la précision double.', 4),
    ('c68e459b-0d01-593f-afe7-77ec8b0354a0'::uuid, 'maths-complementaires', 'Tle', 'Statistiques et échantillonnage', 'Quelle est la variance d’une loi binomiale de paramètres n et p ?', 'mcq', '["n × p × (1 − p)","n × p","p × (1 − p)","√(n × p)"]'::jsonb, 0, 'La variance vaut n p (1 − p) ; l’espérance, elle, vaut n p.', 1),
    ('a4907d4a-ff87-52fa-b4bc-4f37c756458a'::uuid, 'maths-complementaires', 'Tle', 'Statistiques et échantillonnage', 'Quel intervalle de confiance au niveau 95 % le cours donne-t-il pour une fréquence f observée sur n personnes ?', 'mcq', '["[f − 1/n ; f + 1/n]","[f − 1/√n ; f + 1/√n]","[f − √n ; f + √n]","[f − 2/n ; f + 2/n]"]'::jsonb, 1, 'La marge est 1/√n : pour n = 1 000, environ 0,03, soit ± 3 points.', 2),
    ('415df9bb-9901-5b3d-80e4-60c4bc4c654c'::uuid, 'maths-complementaires', 'Tle', 'Statistiques et échantillonnage', 'Par combien faut-il multiplier la taille d’un échantillon pour diviser la marge d’erreur par 2 ?', 'mcq', '["Par 2","Par 8","Par 4","Par 10"]'::jsonb, 2, 'La marge décroît en 1/√n : quadrupler n divise la marge par √4 = 2.', 3),
    ('66ae9024-4d65-5e90-a209-3b4e75160ae4'::uuid, 'maths-complementaires', 'Tle', 'Statistiques et échantillonnage', 'Quelle est la principale faiblesse de la médiane comme indicateur de centre ?', 'mcq', '["Elle est très sensible aux valeurs extrêmes","Elle ne se calcule que sur des effectifs pairs","Elle mesure la dispersion","Elle ignore l’ampleur des écarts"]'::jsonb, 3, 'La médiane repose sur le rang : elle résiste aux valeurs extrêmes, mais ne dit rien de l’ampleur des écarts.', 4),
    ('b4b166dc-98dd-57ca-ab14-8aca5a15df59'::uuid, 'maths-complementaires', 'Tle', 'Fonction logarithme népérien (ln)', 'Que vaut ln(e) ?', 'mcq', '["0","1","e","−1"]'::jsonb, 1, 'ln est la réciproque de l’exponentielle : ln(e) = ln(e¹) = 1, et ln(1) = 0.', 1),
    ('d9846738-b8c0-5374-bfdc-7e6b26c3590a'::uuid, 'maths-complementaires', 'Tle', 'Fonction logarithme népérien (ln)', 'Que vaut ln(a^n) pour a strictement positif ?', 'mcq', '["n ln(a)","(ln a)^n","ln(a) + n","ln(n) × a"]'::jsonb, 0, 'Le logarithme fait descendre l’exposant en facteur : c’est ce qui permet de résoudre une inconnue en exposant.', 2),
    ('7d539e56-dca2-5364-ac7e-1dd6944f580e'::uuid, 'maths-complementaires', 'Tle', 'Fonction logarithme népérien (ln)', 'Quelle est la dérivée de ln(u) pour u strictement positive ?', 'mcq', '["1/u","u′ ln(u)","u′/u","u/u′"]'::jsonb, 2, 'On n’oublie pas le facteur u′ : (ln u)′ = u′/u.', 3),
    ('06e6508a-5600-5737-923b-daa8406f4f8a'::uuid, 'maths-complementaires', 'Tle', 'Fonction logarithme népérien (ln)', 'Si u(n) est une suite géométrique de raison q, alors ln(u(n)) est…', 'mcq', '["Géométrique de raison ln(q)","Constante","Arithmétique de raison q","Arithmétique de raison ln(q)"]'::jsonb, 3, 'ln(u(n)) = ln(u(0)) + n ln(q) : le logarithme transforme une suite géométrique en suite arithmétique.', 4),
    ('6fcc83e4-505a-5bcf-ac2d-f777744ffbd4'::uuid, 'maths-complementaires', 'Tle', 'Compléments sur la dérivation', 'Quelle est la dérivée de √x ?', 'mcq', '["1/(2√x)","2√x","1/√x","√x/2"]'::jsonb, 0, 'La dérivée de √x est 1/(2√x), définie pour x strictement positif.', 1),
    ('e989e19f-cdc9-5344-84a3-6c0d1b3122a4'::uuid, 'maths-complementaires', 'Tle', 'Compléments sur la dérivation', 'Quelle est la dérivée de 1/x ?', 'mcq', '["1/x²","−1/x²","ln(x)","−1/x"]'::jsonb, 1, 'La dérivée de 1/x est −1/x² : la fonction est décroissante sur chaque intervalle où elle est définie.', 2),
    ('7e97251e-ce05-550a-96f9-e5bf32804d87'::uuid, 'maths-complementaires', 'Tle', 'Compléments sur la dérivation', 'Selon le cours, où le bénéfice est-il maximal ?', 'mcq', '["Là où le coût total est minimal","Là où la recette est maximale","Là où le coût marginal égale la recette marginale","Là où le coût moyen est nul"]'::jsonb, 2, 'Le bénéfice est recette moins coût ; sa dérivée s’annule quand recette marginale et coût marginal sont égaux.', 3),
    ('74ed8331-7ef8-5f9c-a2ed-14f2ba50674c'::uuid, 'maths-complementaires', 'Tle', 'Compléments sur la dérivation', 'Quelle est la dérivée de uⁿ ?', 'mcq', '["n uⁿ⁻¹","u′ⁿ","uⁿ⁺¹/(n+1)","n u′ uⁿ⁻¹"]'::jsonb, 3, 'Comme pour toute composée, on n’oublie pas le facteur u′ : (uⁿ)′ = n u′ uⁿ⁻¹.', 4),
    ('858da7e9-3165-569f-bf9f-5964973c62fd'::uuid, 'maths-complementaires', 'Tle', 'Fonctions convexes', 'Pour une fonction deux fois dérivable, être convexe équivaut à…', 'mcq', '["f′ décroissante","f′ croissante","f positive","f croissante"]'::jsonb, 1, 'f convexe, f′ croissante et f″ positive ou nulle sont trois propositions équivalentes.', 1),
    ('b555e9ea-d1a8-564e-b27f-b5a23cf0051a'::uuid, 'maths-complementaires', 'Tle', 'Fonctions convexes', 'Une fonction affine est…', 'mcq', '["Convexe et concave à la fois","Seulement convexe","Seulement concave","Ni convexe ni concave"]'::jsonb, 0, 'Sa dérivée seconde est nulle : elle est à la fois positive ou nulle et négative ou nulle.', 2),
    ('96c1af4f-8464-52bf-a692-fadaa2479d28'::uuid, 'maths-complementaires', 'Tle', 'Fonctions convexes', 'Où se situe le point d’inflexion d’une courbe logistique en S ?', 'mcq', '["Au démarrage","Au plafond","À mi-chemin du plafond","Il n’y en a pas"]'::jsonb, 2, 'La courbe passe de convexe à concave à mi-chemin du plafond : c’est là que la vitesse de croissance est maximale.', 3),
    ('88d75f37-8c64-5a08-a772-ed12ddee063f'::uuid, 'maths-complementaires', 'Tle', 'Fonctions convexes', 'Une grandeur décroissante et convexe…', 'mcq', '["Baisse en accélérant","Augmente de plus en plus vite","Est constante","Baisse en ralentissant"]'::jsonb, 3, 'f′ < 0 et f′ croissante : la pente négative se rapproche de 0, la baisse ralentit.', 4),
    ('7781963f-d1fb-594a-877d-f6b9a87332ff'::uuid, 'maths-complementaires', 'Tle', 'Primitives et équations différentielles', 'Deux primitives d’une même fonction continue sur un intervalle…', 'mcq', '["Diffèrent d’une constante","Sont égales","Sont opposées","Diffèrent d’un facteur multiplicatif"]'::jsonb, 0, 'Toutes les primitives diffèrent d’une constante ; une condition initiale en désigne une seule.', 1),
    ('218ed371-15ef-59e8-8e9d-f670f2d17261'::uuid, 'maths-complementaires', 'Tle', 'Primitives et équations différentielles', 'Quelle est une primitive de x² ?', 'mcq', '["2x","x³/3","x³","3x²"]'::jsonb, 1, 'Pour xⁿ avec n différent de −1, une primitive est x^(n+1)/(n+1) : ici x³/3.', 2),
    ('ab35514d-6aee-5538-99a5-d4ff6d5eade8'::uuid, 'maths-complementaires', 'Tle', 'Primitives et équations différentielles', 'Quelle est une primitive de 2x e^(x²) ?', 'mcq', '["e^(2x)","2 e^(x²)","e^(x²)","x² e^(x²)"]'::jsonb, 2, 'On reconnaît u′ e^u avec u = x² et u′ = 2x : une primitive est e^u = e^(x²).', 3),
    ('61b8fe64-2584-5510-92b6-70d390214a97'::uuid, 'maths-complementaires', 'Tle', 'Primitives et équations différentielles', 'Quel phénomène est décrit par une vitesse d’évolution proportionnelle à la quantité présente ?', 'mcq', '["Une évolution linéaire","Une oscillation","Une évolution constante","L’équation y′ = a y"]'::jsonb, 3, 'Vitesse proportionnelle à la quantité : c’est l’équation y′ = a y, dont les solutions sont x ↦ C e^(a x).', 4),
    ('1fe07123-d449-5353-b42a-b61b9f2d3998'::uuid, 'maths-complementaires', 'Tle', 'Intégration', 'La valeur moyenne d’une fonction sur [a ; b] est-elle toujours égale à (f(a) + f(b))/2 ?', 'mcq', '["Oui, toujours","Non, seulement si la fonction est affine","Oui, si f est positive","Non, jamais"]'::jsonb, 1, 'La demi-somme des bornes ne coïncide avec la valeur moyenne que pour une fonction affine : piège fréquent.', 1),
    ('fd5161bd-58a1-5793-90e5-da7869cae8fd'::uuid, 'maths-complementaires', 'Tle', 'Intégration', 'Un débit en L/min intégré sur des minutes donne…', 'mcq', '["Un volume en litres","Un débit moyen en L/min","Une durée en minutes","Une vitesse en L/min²"]'::jsonb, 0, 'L’unité du résultat est le produit des unités des deux axes : L/min × min = L.', 2),
    ('080739da-7032-5723-a70c-19b78cf0907b'::uuid, 'maths-complementaires', 'Tle', 'Intégration', 'Si f est inférieure à g sur [a ; b], alors…', 'mcq', '["L’intégrale de f vaut celle de g","L’intégrale de f est positive","L’intégrale de f est inférieure ou égale à celle de g","L’intégrale de g est nulle"]'::jsonb, 2, 'C’est la croissance de l’intégrale : l’inégalité entre fonctions se conserve en intégrant.', 3),
    ('b6f9fcd3-b8a4-54e6-aa9d-f3749e6194b7'::uuid, 'maths-complementaires', 'Tle', 'Intégration', 'Pour f supérieure à g sur [a ; b], l’aire entre les deux courbes vaut…', 'mcq', '["L’intégrale de f × g","L’intégrale de f plus celle de g","L’intégrale de (g − f)","L’intégrale de (f − g)"]'::jsonb, 3, 'On intègre la différence « au-dessus moins au-dessous », f − g, positive sur l’intervalle.', 4),
    ('f5d3523a-6422-59f1-b9fa-8aae81957429'::uuid, 'maths-complementaires', 'Tle', 'Lois discrètes', 'Quelle formule donne la variance d’une variable aléatoire X ?', 'mcq', '["E(X)² − E(X²)","E(X²) − E(X)²","E(X) − E(X)²","E(X²)"]'::jsonb, 1, 'V(X) = E(X²) − E(X)² : la moyenne des carrés moins le carré de la moyenne.', 1),
    ('7e21f526-671e-501e-8889-990f2274ba23'::uuid, 'maths-complementaires', 'Tle', 'Lois discrètes', 'Pourquoi préfère-t-on souvent l’écart-type à la variance ?', 'mcq', '["Il est dans la même unité que X","Il est toujours plus grand","Il peut être négatif","Il ne dépend pas de la loi"]'::jsonb, 0, 'L’écart-type est la racine de la variance : il s’exprime dans l’unité de X, donc se lit plus facilement.', 2),
    ('71fcbee9-6784-5460-8497-5f9c0ab7ffbb'::uuid, 'maths-complementaires', 'Tle', 'Lois discrètes', 'Que vaut E(aX + b) ?', 'mcq', '["a² E(X)","a E(X)","a E(X) + b","E(X) + b"]'::jsonb, 2, 'L’espérance est linéaire : E(aX + b) = a E(X) + b ; c’est la variance qui prend a² et perd b.', 3),
    ('5f383cd2-51f8-5fe6-bd38-1f4d791d8c06'::uuid, 'maths-complementaires', 'Tle', 'Lois discrètes', 'Quelle condition de la loi binomiale un tirage sans remise dans une petite population viole-t-il ?', 'mcq', '["Les deux issues","Le nombre d’épreuves","L’identité des épreuves seulement","L’indépendance des épreuves"]'::jsonb, 3, 'Sans remise, chaque tirage modifie la composition de la population : les épreuves ne sont plus indépendantes.', 4),
    ('9845f234-b1f7-54c4-9ad4-dd98055b0f9c'::uuid, 'maths-complementaires', 'Tle', 'Lois à densité', 'Que vaut l’intégrale d’une densité de probabilité sur tout son intervalle de définition ?', 'mcq', '["0","Son maximum","1","Son espérance"]'::jsonb, 2, 'Une densité est continue, positive et d’intégrale totale 1 : la probabilité de l’univers entier.', 1),
    ('f77d4463-8bf2-5963-bc47-2ff58e5e9b87'::uuid, 'maths-complementaires', 'Tle', 'Lois à densité', 'Quelle est l’espérance d’une loi uniforme sur [a ; b] ?', 'mcq', '["(a + b)/2","b − a","1/(b − a)","(b − a)/2"]'::jsonb, 0, 'Toutes les valeurs de l’intervalle se valent : la moyenne est le milieu, (a + b)/2.', 2),
    ('0533655e-a3be-5055-a0dc-1d459096e11f'::uuid, 'maths-complementaires', 'Tle', 'Lois à densité', 'Pour une loi exponentielle de paramètre λ, que vaut P(X > t) ?', 'mcq', '["1 − e^(−λt)","e^(−λt)","λ e^(−λt)","e^(λt)"]'::jsonb, 1, 'P(X > t) = e^(−λt) : la probabilité de dépasser t décroît exponentiellement.', 3),
    ('126a0d64-7066-5f42-bc8d-fb25fcf5d290'::uuid, 'maths-complementaires', 'Tle', 'Lois à densité', 'X suit une loi uniforme sur [0 ; 10]. Que vaut P(2 ≤ X ≤ 5) ?', 'mcq', '["0,5","0,2","0,7","0,3"]'::jsonb, 3, 'P = (5 − 2)/(10 − 0) = 3/10 = 0,3 : seule la longueur de l’intervalle compte.', 4),
    ('85e0703f-98f7-5fca-a08b-9e2c56b9301b'::uuid, 'maths-complementaires', 'Tle', 'Statistique à deux variables', 'Quelles sont les coordonnées du point moyen G d’un nuage ?', 'mcq', '["Le premier et le dernier point","La moyenne des x et la moyenne des y","La médiane des x et la médiane des y","Le maximum des x et le maximum des y"]'::jsonb, 1, 'G a pour abscisse la moyenne des x et pour ordonnée la moyenne des y ; la droite de régression y passe toujours.', 1),
    ('bdb0c060-3646-5a90-b6d7-b70799e2c659'::uuid, 'maths-complementaires', 'Tle', 'Statistique à deux variables', 'Que faut-il faire avant tout calcul d’ajustement ?', 'mcq', '["Calculer r","Extrapoler","Regarder le nuage de points","Passer au logarithme"]'::jsonb, 2, 'La lecture du nuage dit si un ajustement affine a un sens et signale les points aberrants.', 2),
    ('22ac58bb-e65b-56f7-aa29-def93aa95f39'::uuid, 'maths-complementaires', 'Tle', 'Statistique à deux variables', 'Selon le cours, qu’est-ce qui seul permet d’établir une causalité ?', 'mcq', '["Une expérimentation contrôlée","Un coefficient r proche de 1","Un très grand échantillon","Une droite de régression"]'::jsonb, 0, 'Un coefficient de corrélation ne prouve jamais une causalité ; seule une expérience contrôlée le peut.', 3),
    ('de6a0983-1660-5ff9-b0ca-5c210cbaf9f2'::uuid, 'maths-complementaires', 'Tle', 'Statistique à deux variables', 'Quel changement de variable linéarise un modèle logarithmique ?', 'mcq', '["Poser z = ln(y)","Poser z = y²","Poser z = e^x","Poser z = ln(x)"]'::jsonb, 3, 'Pour un modèle y = a ln(x) + b, poser z = ln(x) donne une relation affine entre z et y.', 4),
    ('300d3383-5a97-50b2-b39a-2d8dabcaab6d'::uuid, 'maths-expertes', 'Tle', 'Les nombres complexes d’un point de vue algébrique', 'Que vaut (1 + i)(2 − i) ?', 'mcq', '["3 + i","1 + i","3 − i","2 + i"]'::jsonb, 0, 'On développe : 2 − i + 2i − i² = 2 + i + 1 = 3 + i, en remplaçant i² par −1.', 1),
    ('9687e50b-5e62-59fa-837b-6a838654e89f'::uuid, 'maths-expertes', 'Tle', 'Les nombres complexes d’un point de vue algébrique', 'Si z = −z̄, alors z est…', 'mcq', '["réel","imaginaire pur","de module 1","forcément nul"]'::jsonb, 1, 'z = −z̄ impose une partie réelle nulle : z est imaginaire pur. C’est z = z̄ qui caractérise un réel.', 2),
    ('e8d9507f-cf43-52dd-81ff-7aed528c83fd'::uuid, 'maths-expertes', 'Tle', 'Les nombres complexes d’un point de vue algébrique', 'Que vaut z + z̄ ?', 'mcq', '["2i Im(z)","|z|²","0","2 Re(z)"]'::jsonb, 3, '(a + ib) + (a − ib) = 2a : la somme d’un complexe et de son conjugué est toujours réelle. C’est la différence qui vaut 2i Im(z).', 3),
    ('357607b5-f6b4-555a-b0cb-58c091813a08'::uuid, 'maths-expertes', 'Tle', 'Les nombres complexes d’un point de vue algébrique', 'Quel est le module de 3 + 4i ?', 'mcq', '["7","25","5","√7"]'::jsonb, 2, 'Le module vaut √(a² + b²) = √(9 + 16) = √25 = 5 ; 25 est son carré, égal à z × z̄.', 4),
    ('9166e892-57a3-5f85-82eb-68f4adf2ac6f'::uuid, 'maths-expertes', 'Tle', 'Le point de vue géométrique des nombres complexes', 'Quelle est l’affixe du milieu de [AB] ?', 'mcq', '["z(B) − z(A)","(z(A) + z(B))/2","(z(B) − z(A))/2","z(A) × z(B)"]'::jsonb, 1, 'Comme pour les coordonnées, le milieu a pour affixe la demi-somme des affixes. z(B) − z(A) est l’affixe du vecteur AB.', 1),
    ('e3f68a5d-9998-54ba-8b0a-e3fa74fee5a8'::uuid, 'maths-expertes', 'Tle', 'Le point de vue géométrique des nombres complexes', 'Quelle est l’image du point d’affixe −z ?', 'mcq', '["Le symétrique de M par rapport à l’axe des ordonnées","Le symétrique de M par rapport à l’axe des abscisses","L’image de M par la rotation d’angle π/2","Le symétrique de M par rapport à l’origine"]'::jsonb, 3, 'Changer z en −z change le signe des deux coordonnées : c’est la symétrie centrale de centre O. L’axe des abscisses correspond au conjugué.', 2),
    ('71ef3c2b-4686-55a0-9f76-360e0b72cee7'::uuid, 'maths-expertes', 'Tle', 'Le point de vue géométrique des nombres complexes', 'Avec Z = (z(C) − z(A))/(z(B) − z(A)), que dit un Z imaginaire pur ?', 'mcq', '["A, B et C sont alignés","AB = AC","Les droites (AB) et (AC) sont perpendiculaires","Le triangle ABC est équilatéral"]'::jsonb, 2, 'Un imaginaire pur a pour argument ±π/2 : l’angle entre les vecteurs AB et AC est droit. Un Z réel, lui, traduit l’alignement.', 3),
    ('1a4c364f-fed2-5717-9dbb-fc590f0a0f16'::uuid, 'maths-expertes', 'Tle', 'Le point de vue géométrique des nombres complexes', 'Pour trouver l’argument θ de a + ib, pourquoi résoudre cos θ = a/r ET sin θ = b/r ?', 'mcq', '["Parce que le cosinus seul laisse deux angles possibles","Parce que le sinus est plus précis","Parce que r peut être négatif","Ce n’est pas nécessaire, une seule équation suffit"]'::jsonb, 0, 'Deux angles opposés ont le même cosinus : c’est le signe du sinus qui les départage.', 4),
    ('60601d4e-ea23-5a1d-b135-4a555ca13395'::uuid, 'maths-expertes', 'Tle', 'Nombres complexes et trigonométrie', 'Que vaut e^(iπ/2) ?', 'mcq', '["1","−i","i","−1"]'::jsonb, 2, 'e^(iπ/2) = cos(π/2) + i sin(π/2) = 0 + i × 1 = i.', 1),
    ('44945eea-52a9-5c06-9975-b843f05df259'::uuid, 'maths-expertes', 'Tle', 'Nombres complexes et trigonométrie', 'Quelle est la forme exponentielle de l’inverse de r e^(iθ) ?', 'mcq', '["r e^(−iθ)","(1/r) e^(−iθ)","(1/r) e^(iθ)","−r e^(iθ)"]'::jsonb, 1, 'On inverse le module et on change l’argument de signe. r e^(−iθ) est le conjugué, pas l’inverse.', 2),
    ('5a0f038a-3cf7-58a3-8b34-bbc7f2a954fd'::uuid, 'maths-expertes', 'Tle', 'Nombres complexes et trigonométrie', 'Que forment les images des n racines n-ièmes de l’unité ?', 'mcq', '["Une droite passant par l’origine","Un cercle de rayon n","Une spirale","Un polygone régulier à n côtés inscrit dans le cercle unité"]'::jsonb, 3, 'Les racines e^(2ikπ/n) sont de module 1 et régulièrement espacées de 2π/n : elles sont les sommets d’un polygone régulier.', 3),
    ('a5d4b8c0-0b31-511f-a71e-e0dd5da4af41'::uuid, 'maths-expertes', 'Tle', 'Nombres complexes et trigonométrie', 'Pour factoriser e^(ia) + e^(ib), que met-on en facteur ?', 'mcq', '["L’exponentielle de l’angle moyen, e^(i(a+b)/2)","e^(ia) seulement","e^(i(a+b))","Le cosinus de a"]'::jsonb, 0, 'On obtient e^(i(a+b)/2) × (e^(i(a−b)/2) + e^(−i(a−b)/2)), et la parenthèse vaut 2 cos((a − b)/2) par Euler.', 4),
    ('32eb6d7d-842b-5d22-bf14-0f0b10344150'::uuid, 'maths-expertes', 'Tle', 'Équations polynomiales et nombres complexes', 'Quelles sont les solutions de z² + 4 = 0 dans ℂ ?', 'mcq', '["2i et −2i","2 et −2","Il n’y en a aucune","4i et −4i"]'::jsonb, 0, 'z² = −4 = (2i)² : les solutions sont 2i et −2i, conjuguées l’une de l’autre comme l’annonce Δ = −16 < 0.', 1),
    ('4e2eeb3b-94c5-557b-af60-dd449c17b7ff'::uuid, 'maths-expertes', 'Tle', 'Équations polynomiales et nombres complexes', 'Combien de racines, comptées avec leur multiplicité, a un polynôme de degré n dans ℂ ?', 'mcq', '["Au plus deux","Exactement n","n − 1","Une seule"]'::jsonb, 1, 'Par récurrence sur le théorème fondamental de l’algèbre, un polynôme de degré n se factorise en n facteurs du premier degré.', 2),
    ('d7ec0316-5575-515b-ace6-bafb27bf5c21'::uuid, 'maths-expertes', 'Tle', 'Équations polynomiales et nombres complexes', 'On connaît une racine z₀ d’un polynôme de degré 3. Quelle est la méthode attendue pour trouver le quotient ?', 'mcq', '["Calculer un discriminant de degré 3","Passer en forme exponentielle","Factoriser par (z − z₀) et identifier les coefficients","Dériver le polynôme"]'::jsonb, 2, 'On pose le quotient avec des coefficients inconnus, on développe et on identifie : il reste alors un trinôme à résoudre.', 3),
    ('2c354f7c-d788-5882-aaff-1adcf870710f'::uuid, 'maths-expertes', 'Tle', 'Équations polynomiales et nombres complexes', 'Parmi ces nombres, lequel est une solution de z³ = 8 ?', 'mcq', '["−2","8","2i","2"]'::jsonb, 3, '2³ = 8. Les deux autres solutions, 2e^(2iπ/3) et 2e^(−2iπ/3), ne sont pas réelles : il y en a trois en tout.', 4),
    ('fcd64233-45fb-57f9-8600-36b324995521'::uuid, 'maths-expertes', 'Tle', 'Utilisation des nombres complexes en géométrie', 'Quelle écriture décrit l’homothétie de centre Ω (affixe ω) et de rapport k réel ?', 'mcq', '["z′ = k z + ω","z′ − ω = k (z − ω)","z′ = z + k","z′ − ω = e^(ik) (z − ω)"]'::jsonb, 1, 'Une homothétie multiplie par un réel à partir de son centre ; multiplier par e^(iθ), de module 1, donnerait une rotation.', 1),
    ('fd8bf253-5b30-5ca2-846a-136ea5214170'::uuid, 'maths-expertes', 'Tle', 'Utilisation des nombres complexes en géométrie', 'Que produit la multiplication par −1 ?', 'mcq', '["Une rotation d’angle π/2 autour de l’origine","La symétrie par rapport à l’axe des abscisses","Une rotation d’angle π autour de l’origine","Une homothétie de rapport 1"]'::jsonb, 2, '−1 = e^(iπ) : multiplier par −1, c’est tourner d’un demi-tour autour de O, ce qui est la symétrie centrale.', 2),
    ('ed0d307d-3c7d-5a0f-aa20-eb9cf964050f'::uuid, 'maths-expertes', 'Tle', 'Utilisation des nombres complexes en géométrie', 'Si Z = (z(C) − z(A))/(z(B) − z(A)) vaut e^(iπ/3), le triangle ABC est…', 'mcq', '["rectangle en A","aplati, les points étant alignés","rectangle isocèle en A","équilatéral"]'::jsonb, 3, 'Module 1 donne AB = AC, argument π/3 donne un angle de 60° en A : le triangle est équilatéral (direct).', 3),
    ('5b255ea1-ede9-5291-a656-1e5ed5f6483e'::uuid, 'maths-expertes', 'Tle', 'Utilisation des nombres complexes en géométrie', 'Quel ensemble de points décrit l’équation Re(z) = 3 ?', 'mcq', '["Une droite parallèle à l’axe des ordonnées","Une droite parallèle à l’axe des abscisses","Le cercle de centre O et de rayon 3","Une demi-droite d’origine O"]'::jsonb, 0, 'Re(z) = 3 fixe l’abscisse x = 3 : c’est une droite verticale, parallèle à l’axe des ordonnées.', 4),
    ('ec2dec62-fee9-5b1c-bfe3-9c9b45070978'::uuid, 'maths-expertes', 'Tle', 'Divisibilité et congruences dans Z', 'Si b divise a et a divise c, que peut-on affirmer ?', 'mcq', '["b divise c","c divise b","a = c","b = a"]'::jsonb, 0, 'C’est la transitivité : a = bk et c = ak′ donnent c = b(kk′).', 1),
    ('99e84d6c-8e60-545b-9068-c42648fc6806'::uuid, 'maths-expertes', 'Tle', 'Divisibilité et congruences dans Z', 'Si a ≡ 2 [5], à quoi a² est-il congru modulo 5 ?', 'mcq', '["2","4","1","0"]'::jsonb, 1, 'Les congruences sont compatibles avec les puissances : a² ≡ 2² = 4 [5].', 2),
    ('af8242e8-b6fc-59b9-b7c7-7fbbeec089c2'::uuid, 'maths-expertes', 'Tle', 'Divisibilité et congruences dans Z', 'Quelle est la période des puissances de 3 modulo 7 ?', 'mcq', '["3","7","6","2"]'::jsonb, 2, 'Les restes successifs sont 3, 2, 6, 4, 5, 1, puis le cycle recommence : la période est 6.', 3),
    ('5d44e6aa-841f-5ad2-b536-cc83f37880e9'::uuid, 'maths-expertes', 'Tle', 'Divisibilité et congruences dans Z', 'Sur quelle congruence repose le critère de divisibilité par 11 en somme alternée des chiffres ?', 'mcq', '["10 ≡ 1 [11]","11 ≡ 0 [10]","100 ≡ 0 [11]","10 ≡ −1 [11]"]'::jsonb, 3, 'Comme 10 ≡ −1 [11], les puissances de 10 valent alternativement 1 et −1 modulo 11 : les chiffres comptent avec des signes alternés.', 4),
    ('1fea81bc-fefb-50ad-afdd-42681f22e310'::uuid, 'maths-expertes', 'Tle', 'PGCD, théorèmes de Bézout et de Gauss', 'Quel est le PPCM de 12 et 18, sachant que leur PGCD vaut 6 ?', 'mcq', '["36","216","72","6"]'::jsonb, 0, 'PGCD × PPCM = 12 × 18 = 216, donc PPCM = 216 / 6 = 36.', 1),
    ('08667a93-539b-5381-bd0d-94a9b17bdafd'::uuid, 'maths-expertes', 'Tle', 'PGCD, théorèmes de Bézout et de Gauss', '6 divise 4 × 3 sans diviser ni 4 ni 3. Quelle hypothèse du théorème de Gauss manque ?', 'mcq', '["6 devrait être premier","6 devrait être premier avec 4 (ou avec 3)","Le produit devrait être impair","4 et 3 devraient être premiers entre eux"]'::jsonb, 1, 'Gauss exige que a soit premier avec b ; or PGCD(6 ; 4) = 2 et PGCD(6 ; 3) = 3. Sans cette hypothèse, la conclusion tombe.', 2),
    ('baeef65d-62a9-5d5a-82ab-3be2f3bc11ee'::uuid, 'maths-expertes', 'Tle', 'PGCD, théorèmes de Bézout et de Gauss', 'Dans l’algorithme d’Euclide, le PGCD est…', 'mcq', '["le premier reste obtenu","le dernier quotient","le dernier reste non nul","le plus petit des deux nombres"]'::jsonb, 2, 'On remplace (a ; b) par (b ; r) jusqu’à un reste nul : le dernier reste non nul est le PGCD (21 pour 1071 et 462).', 3),
    ('b0e1c9c2-6c65-5eb2-b5b5-54fba31f35c0'::uuid, 'maths-expertes', 'Tle', 'PGCD, théorèmes de Bézout et de Gauss', 'Que suffit-il de faire pour prouver que a et b sont premiers entre eux ?', 'mcq', '["Montrer qu’ils sont tous deux impairs","Montrer que l’un est premier","Calculer leur PPCM","Exhiber un couple d’entiers (u ; v) tel que a u + b v = 1"]'::jsonb, 3, 'C’est le sens utile du théorème de Bézout : un seul couple suffit, et le PGCD vaut alors 1.', 4),
    ('ac3fc722-6d5f-5ab2-855a-fc19a71cae04'::uuid, 'maths-expertes', 'Tle', 'Nombres premiers et petit théorème de Fermat', 'Combien 72 = 2³ × 3² a-t-il de diviseurs positifs ?', 'mcq', '["12","6","5","72"]'::jsonb, 0, 'On multiplie les exposants augmentés de 1 : (3 + 1)(2 + 1) = 12.', 1),
    ('38edc188-74c2-586a-b0a1-fcf15226c99b'::uuid, 'maths-expertes', 'Tle', 'Nombres premiers et petit théorème de Fermat', 'Si a^(n−1) ≡ 1 [n], que permet de conclure le petit théorème de Fermat ?', 'mcq', '["Que n est premier","Rien de sûr : certains nombres composés passent ce test","Que n est composé","Que n est pair"]'::jsonb, 1, 'Le théorème ne s’utilise qu’en contraposée : il prouve qu’un nombre n’est pas premier, jamais qu’il l’est.', 2),
    ('8d8590c6-fd43-583a-b01b-ed2c605c66e2'::uuid, 'maths-expertes', 'Tle', 'Nombres premiers et petit théorème de Fermat', 'Comment lit-on le PGCD sur les décompositions en facteurs premiers ?', 'mcq', '["Tous les facteurs, aux plus grands exposants","La somme des exposants","Les facteurs communs, aux plus petits exposants","Les facteurs communs, aux plus grands exposants"]'::jsonb, 2, 'Le PGCD garde les facteurs communs aux plus petits exposants ; le PPCM prend tous les facteurs aux plus grands exposants.', 3),
    ('7ca2240a-f3a7-5e2d-aa24-c45b6fd2886b'::uuid, 'maths-expertes', 'Tle', 'Nombres premiers et petit théorème de Fermat', 'Quel est le reste de 2^100 dans la division par 7 ?', 'mcq', '["1","4","0","2"]'::jsonb, 3, 'Fermat donne 2⁶ ≡ 1 [7] ; 100 = 6 × 16 + 4, donc 2^100 ≡ 2⁴ = 16 ≡ 2 [7].', 4),
    ('3ae97332-cfdb-5cf3-867d-9d1560f8e182'::uuid, 'maths-expertes', 'Tle', 'Calcul matriciel', 'A est de taille 2 × 3 et B de taille 3 × 4. Quelle est la taille de A × B ?', 'mcq', '["2 × 4","3 × 3","4 × 2","Le produit n’est pas défini"]'::jsonb, 0, 'Un produit n × p par p × q donne n × q : les 3 colonnes de A correspondent aux 3 lignes de B.', 1),
    ('dd561774-fdc5-5c1d-821e-ae34ea7687aa'::uuid, 'maths-expertes', 'Tle', 'Calcul matriciel', 'Quel est le déterminant de la matrice de lignes (2 ; 1) et (4 ; 3) ?', 'mcq', '["10","2","−2","6"]'::jsonb, 1, 'ad − bc = 2 × 3 − 1 × 4 = 2 : non nul, la matrice est inversible.', 2),
    ('3761b965-401f-52be-a7f7-5432d0c2c90e'::uuid, 'maths-expertes', 'Tle', 'Calcul matriciel', 'Si A n’est pas inversible, combien le système A X = B a-t-il de solutions ?', 'mcq', '["Une solution unique","Toujours aucune","Aucune ou une infinité","Exactement deux"]'::jsonb, 2, 'La solution unique X = A⁻¹B n’existe que si A est inversible ; sinon le système est soit impossible, soit indéterminé.', 3),
    ('a28e2f5e-5420-57d5-9c63-f8b541937812'::uuid, 'maths-expertes', 'Tle', 'Calcul matriciel', 'Comment calcule-t-on Dⁿ pour une matrice D diagonale ?', 'mcq', '["En multipliant chaque coefficient par n","En élevant tous les coefficients, même nuls, à la puissance n puis en additionnant","Dⁿ = D pour toute diagonale","En élevant chaque coefficient diagonal à la puissance n"]'::jsonb, 3, 'Le produit de deux matrices diagonales se fait terme à terme sur la diagonale : c’est ce qui rend la diagonalisation si utile.', 4),
    ('01f8dc65-bf3a-5766-a203-67c06eafb9ed'::uuid, 'maths-expertes', 'Tle', 'Graphes et matrices', 'Quel est le majorant du nombre chromatique donné par le cours ?', 'mcq', '["Le nombre de sommets au carré","Le degré maximal, plus 1","Le nombre d’arêtes","Le degré minimal"]'::jsonb, 1, 'Chaque sommet a au plus « degré maximal » voisins : avec une couleur de plus, on en trouve toujours une libre.', 1),
    ('d18c5a2d-5cfe-5734-9347-7341c74d3c68'::uuid, 'maths-expertes', 'Tle', 'Graphes et matrices', 'Quel minorant du nombre chromatique le cours donne-t-il ?', 'mcq', '["Le degré minimal","Le nombre de sommets","Le nombre de cycles","La taille du plus grand sous-graphe complet"]'::jsonb, 3, 'Dans un sous-graphe complet, tous les sommets sont voisins deux à deux : il faut autant de couleurs que de sommets.', 2),
    ('9898810a-18c6-5fe5-b8f2-48349e018c72'::uuid, 'maths-expertes', 'Tle', 'Graphes et matrices', 'Un graphe connexe dont tous les sommets sont de degré pair possède un cycle eulérien.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec 0 sommet de degré impair, le théorème d’Euler garantit même un cycle eulérien ; avec 2, seulement une chaîne.', 3),
    ('b4b539bc-1abd-539a-92b7-ffe4b17b0c3b'::uuid, 'maths-expertes', 'Tle', 'Graphes et matrices', 'Pourquoi le problème du voyageur de commerce est-il difficile ?', 'mcq', '["Parce que les graphes y sont orientés","Parce que sa matrice n’est pas symétrique","Parce qu’il n’existe aucun critère simple pour les chaînes hamiltoniennes","Parce que son nombre chromatique est trop grand"]'::jsonb, 2, 'Passer une fois par chaque sommet n’a pas d’équivalent au critère d’Euler sur les degrés : il faut chercher.', 4),
    ('ca6e2ac1-6082-57ee-8108-251c6b31a9bc'::uuid, 'maths-expertes', 'Tle', 'Suites de matrices colonnes', 'Dans le cas affine U(n+1) = A U(n) + B, quelle est la forme explicite de U(n) ?', 'mcq', '["Aⁿ U(0) + C","Aⁿ (U(0) − C) + C","Aⁿ U(0) + B","Aⁿ U(0) − C"]'::jsonb, 1, 'V(n) = U(n) − C vérifie V(n) = Aⁿ V(0) ; on rajoute C pour revenir à U(n).', 1),
    ('002c1368-b3b4-5938-b615-afd9b433fd6d'::uuid, 'maths-expertes', 'Tle', 'Suites de matrices colonnes', 'Si Aⁿ converge vers une matrice L, vers quoi converge U(n) = Aⁿ U(0) ?', 'mcq', '["L","U(0)","L U(0)","La matrice nulle"]'::jsonb, 2, 'On passe à la limite dans Aⁿ U(0) : la limite est L U(0), une matrice colonne.', 2),
    ('cd7d108f-918a-5059-8746-31fe72881c4c'::uuid, 'maths-expertes', 'Tle', 'Suites de matrices colonnes', 'On pose V(n) = U(n) − C, C étant l’état stable. Quelle relation vérifie V ?', 'mcq', '["V(n+1) = A V(n) + B","V(n+1) = V(n) + C","V(n+1) = B V(n)","V(n+1) = A V(n)"]'::jsonb, 3, 'En soustrayant C = AC + B à U(n+1) = A U(n) + B, le terme constant disparaît : la suite V est « géométrique ».', 3),
    ('14fd8cb5-8175-5940-bf04-111fd37c989b'::uuid, 'maths-expertes', 'Tle', 'Suites de matrices colonnes', 'u(n+1) = 2u(n) + v(n) et v(n+1) = u(n) + 3v(n). Quelle est la matrice A ?', 'mcq', '["Lignes (2 ; 1) et (1 ; 3)","Lignes (2 ; 1) et (3 ; 1)","Lignes (1 ; 2) et (3 ; 1)","Lignes (2 ; 3) et (1 ; 1)"]'::jsonb, 0, 'Chaque ligne de A porte les coefficients d’une équation, dans l’ordre des composantes u puis v.', 4),
    ('7d642964-0ac2-5619-b8cb-581099a7255a'::uuid, 'maths-expertes', 'Tle', 'Chaînes de Markov', 'Dans quelle situation l’hypothèse « sans mémoire » est-elle la plus discutable ?', 'mcq', '["La fidélité d’un client, où l’ancienneté compte","Le déplacement aléatoire d’un pion sur un graphe","Une météo modélisée à deux états","Le tirage d’une boule avec remise"]'::jsonb, 0, 'Si l’ancienneté d’un client pèse sur son choix, l’avenir dépend de l’historique : la propriété de Markov doit alors être discutée.', 1),
    ('a3ca64e3-2b7f-523b-8ff8-5847c71e34c5'::uuid, 'maths-expertes', 'Tle', 'Chaînes de Markov', 'Avec les distributions écrites en ligne, comment passe-t-on de P(n) à P(n+1) ?', 'mcq', '["P(n+1) = T × P(n)","P(n+1) = P(n) × T","P(n+1) = P(n) + T","P(n+1) = Tⁿ"]'::jsonb, 1, 'En ligne, on multiplie à droite par T ; d’où P(n) = P(0) × Tⁿ. En colonne, ce serait à gauche : la convention doit être tenue.', 2),
    ('32943e79-5ee1-52d2-8a7a-1c1dfc8ba007'::uuid, 'maths-expertes', 'Tle', 'Chaînes de Markov', 'T a pour lignes (0,8 ; 0,2) et (0,4 ; 0,6). Quel est son état stable ?', 'mcq', '["(1/2 ; 1/2)","(0,8 ; 0,2)","(2/3 ; 1/3)","(1/3 ; 2/3)"]'::jsonb, 2, 'π = (a ; b) avec a = 0,8a + 0,4b donne a = 2b ; avec a + b = 1, on trouve a = 2/3 et b = 1/3.', 3),
    ('bf59b2a6-8c7e-5987-ba3f-833f2d0e03a3'::uuid, 'maths-expertes', 'Tle', 'Chaînes de Markov', 'Sans la condition « somme des composantes égale à 1 », combien de solutions le système π × T = π admet-il ?', 'mcq', '["Aucune solution","Une seule solution","Exactement deux solutions","Une infinité de solutions proportionnelles"]'::jsonb, 3, 'Si π est solution, tout multiple de π l’est aussi : c’est la condition de somme 1 qui fixe l’unique distribution stable.', 4),
    ('2cbf5734-4a47-53a0-a64d-17750c90a525'::uuid, 'physique-chimie', 'Tle', 'Acides et bases selon Brönsted', 'Selon Brönsted, une base est une espèce qui…', 'mcq', '["Cède un proton H⁺","Libère un électron","Capte un proton H⁺","Cède un ion HO⁻"]'::jsonb, 2, 'Une base capte un proton ; l’acide, lui, le cède. Aucune espèce n’est acide ou basique dans l’absolu : elle l’est face à une autre.', 1),
    ('99009f8b-1dbe-5ca3-8380-32fb238d2dce'::uuid, 'physique-chimie', 'Tle', 'Acides et bases selon Brönsted', 'Dans le couple H₂O / HO⁻, quel rôle joue l’eau ?', 'mcq', '["La base","L’acide","Aucun, elle est spectatrice","Le catalyseur"]'::jsonb, 1, 'H₂O perd un proton pour donner HO⁻ : elle est l’acide de ce couple. Dans H₃O⁺ / H₂O, elle en est la base.', 2),
    ('ecaf127f-cdb1-5dc8-b5d4-b7f2b852d9b2'::uuid, 'physique-chimie', 'Tle', 'Acides et bases selon Brönsted', 'Quelle est la base conjuguée de l’ion ammonium NH₄⁺ ?', 'mcq', '["NH₂⁻","NH₄OH","N₂","NH₃"]'::jsonb, 3, 'En perdant un proton, NH₄⁺ devient l’ammoniac NH₃ : le couple NH₄⁺ / NH₃.', 3),
    ('3564d377-b3a3-5f5e-8847-157b10799b88'::uuid, 'physique-chimie', 'Tle', 'Acides et bases selon Brönsted', 'Pourquoi l’eau pure conduit-elle faiblement le courant ?', 'mcq', '["Parce que l’autoprotolyse y produit un peu d’ions H₃O⁺ et HO⁻","Parce qu’elle contient toujours du sel","Parce que les molécules d’eau sont chargées","Parce que les électrons y circulent librement"]'::jsonb, 0, 'L’autoprotolyse, très limitée, crée quelques ions H₃O⁺ et HO⁻, toujours présents ensemble : juste assez pour une faible conduction.', 4),
    ('244dd23a-62e8-5950-9d11-df94defd11f6'::uuid, 'physique-chimie', 'Tle', 'Le pH des solutions', 'Quelle est la définition du pH ?', 'mcq', '["pH = log([H₃O⁺]/c°)","pH = −log([H₃O⁺]/c°)","pH = −ln([H₃O⁺]/c°)","pH = [H₃O⁺] × 14"]'::jsonb, 1, 'pH = −log([H₃O⁺]/c°), avec c° = 1 mol·L⁻¹ qui rend l’argument du logarithme sans dimension.', 1),
    ('e19ed826-92e8-5c25-b31d-4309781d2c42'::uuid, 'physique-chimie', 'Tle', 'Le pH des solutions', 'Que vaut [H₃O⁺] dans une solution neutre à 25 °C ?', 'mcq', '["1,0 × 10⁻¹⁴ mol·L⁻¹","7,0 mol·L⁻¹","1,0 × 10⁻⁷ mol·L⁻¹","0 mol·L⁻¹"]'::jsonb, 2, 'À la neutralité, [H₃O⁺] = [HO⁻] et leur produit vaut 10⁻¹⁴ : chacune vaut donc 10⁻⁷ mol·L⁻¹, soit pH 7,0.', 2),
    ('ca3a488a-e9b8-5846-81c2-ad90e8e2d35a'::uuid, 'physique-chimie', 'Tle', 'Le pH des solutions', 'On dilue dix fois une solution de base forte de pH 12. Le nouveau pH vaut environ…', 'mcq', '["13","12","10","11"]'::jsonb, 3, 'Diluer dix fois une base forte fait baisser le pH d’une unité : il se rapproche de 7 sans jamais le franchir.', 3),
    ('40f63a9b-532d-57aa-9ad9-9d37627b930c'::uuid, 'physique-chimie', 'Tle', 'Le pH des solutions', 'Une solution acide, diluée autant qu’on veut, peut devenir basique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La dilution rapproche le pH de 7 sans jamais le franchir : une solution acide diluée reste acide.', 4),
    ('5a199475-403d-52f4-ba20-f7827559722c'::uuid, 'physique-chimie', 'Tle', 'Propriétés électriques des solutions', 'Comment la conductance G est-elle reliée à la conductivité σ ?', 'mcq', '["G = σ × S / L","G = σ × L / S","G = σ / (S × L)","G = σ × S × L"]'::jsonb, 0, 'G = σ × S/L, où S est la surface des électrodes et L leur distance : c’est pourquoi G dépend de la cellule et σ non.', 1),
    ('8fe507ba-b058-521f-acf5-9d9bd0e0742d'::uuid, 'physique-chimie', 'Tle', 'Propriétés électriques des solutions', 'Combien valent 0,010 mol·L⁻¹ en mol·m⁻³ ?', 'mcq', '["0,010 mol·m⁻³","10 mol·m⁻³","1,0 × 10⁻⁵ mol·m⁻³","100 mol·m⁻³"]'::jsonb, 1, '1 mol·L⁻¹ = 10³ mol·m⁻³ : 0,010 mol·L⁻¹ font donc 10 mol·m⁻³. C’est cette conversion qu’exige la loi de Kohlrausch.', 2),
    ('5b659a03-92fc-5ca8-b2a2-0f9f9ff2d777'::uuid, 'physique-chimie', 'Tle', 'Propriétés électriques des solutions', 'Pourquoi H₃O⁺ et HO⁻ conduisent-ils environ cinq fois mieux que les autres ions ?', 'mcq', '["Ils sont plus petits que tous les autres ions","Ils portent une charge double","Ils se déplacent par relais de proton d’une molécule d’eau à l’autre","Ils sont attirés plus fort par les électrodes"]'::jsonb, 2, 'Le proton passe de molécule d’eau en molécule d’eau : l’ion n’a pas à parcourir lui-même toute la distance.', 3),
    ('f01c018d-f3ce-5f32-891a-0caf91e3dfc6'::uuid, 'physique-chimie', 'Tle', 'Propriétés électriques des solutions', 'Avant de mesurer une conductivité avec un conductimètre, il faut…', 'mcq', '["Le rincer à l’acide chlorhydrique","Chauffer la solution","Ajouter un indicateur coloré","L’étalonner avec une solution de conductivité connue"]'::jsonb, 3, 'Le conductimètre s’étalonne sur une solution de conductivité connue : c’est ce qui permet de passer de G à σ.', 4),
    ('3f45c4d3-2494-5d77-bfbb-fa683c4ddcb8'::uuid, 'physique-chimie', 'Tle', 'Propriétés spectrales des substances chimiques et solutions', 'Quelle est l’unité de l’absorbance A ?', 'mcq', '["Elle est sans unité","L·mol⁻¹·cm⁻¹","mol·L⁻¹","cm"]'::jsonb, 0, 'A = ε × ℓ × c est un nombre sans unité : les unités de ε, ℓ et c se compensent.', 1),
    ('8a29f35e-20b3-5f18-b705-47daadffd857'::uuid, 'physique-chimie', 'Tle', 'Propriétés spectrales des substances chimiques et solutions', 'À quoi sert le « blanc » avant un dosage par étalonnage ?', 'mcq', '["À mesurer λ_max","À fixer le zéro d’absorbance avec le solvant seul","À nettoyer la cuve","À tracer la droite d’étalonnage"]'::jsonb, 1, 'Le solvant seul fixe le zéro : on ne mesure ensuite que ce qu’absorbe l’espèce dissoute.', 2),
    ('8f82fa7f-57a0-5e98-980f-04747b52bb9e'::uuid, 'physique-chimie', 'Tle', 'Propriétés spectrales des substances chimiques et solutions', 'Une bande fine et intense vers 1700 cm⁻¹ sur un spectre IR signale une liaison…', 'mcq', '["O—H d’alcool","N—H","C=O","C—H"]'::jsonb, 2, 'La liaison C=O donne une bande fine et intense vers 1700 cm⁻¹ ; le O—H d’alcool donne une bande large vers 3300 cm⁻¹.', 3),
    ('07698515-4d88-534f-8b6a-7162aa3a0077'::uuid, 'physique-chimie', 'Tle', 'Propriétés spectrales des substances chimiques et solutions', 'Quelle spectroscopie sert à quantifier une concentration ?', 'mcq', '["L’infrarouge","La RMN du proton","Aucune des trois","L’UV-visible"]'::jsonb, 3, 'L’UV-visible quantifie grâce à la loi de Beer-Lambert ; l’IR reconnaît les groupes et la RMN reconstruit le squelette.', 4),
    ('ffbd0309-2084-5a3f-9ac5-9397017fdc23'::uuid, 'physique-chimie', 'Tle', 'Suivi temporel d’une réaction chimique : modèle macroscopique', 'Au bout de combien de temps de demi-réaction une transformation est-elle pratiquement terminée ?', 'mcq', '["2 fois t₁/₂","5 à 7 fois t₁/₂","Exactement 1 fois t₁/₂","100 fois t₁/₂"]'::jsonb, 1, 'Le temps de demi-réaction donne l’ordre de grandeur de la durée totale : 5 à 7 fois t₁/₂ suffisent en pratique.', 1),
    ('d872e374-fe63-535e-94d2-c8c07e770dbc'::uuid, 'physique-chimie', 'Tle', 'Suivi temporel d’une réaction chimique : modèle macroscopique', 'Pour une réaction d’ordre 1 de constante k, que vaut t₁/₂ ?', 'mcq', '["ln2 / k","k / ln2","1 / (2k)","2k"]'::jsonb, 0, 'Avec [A](t) = [A]₀ × e^(−kt), on trouve t₁/₂ = ln2 / k, indépendant de la concentration initiale.', 2),
    ('71d9e685-8b9a-5c4d-b44f-12041bacd6c6'::uuid, 'physique-chimie', 'Tle', 'Suivi temporel d’une réaction chimique : modèle macroscopique', 'Quelle méthode de suivi choisir si un gaz se forme au cours de la réaction ?', 'mcq', '["La spectrophotométrie","La pH-métrie","La mesure de pression","La conductimétrie"]'::jsonb, 2, 'Un gaz formé fait monter la pression dans une enceinte fermée : on suit la réaction au capteur de pression.', 3),
    ('a8319890-d6c1-5181-aef0-70cbf8a6a15b'::uuid, 'physique-chimie', 'Tle', 'Suivi temporel d’une réaction chimique : modèle macroscopique', 'Pourquoi une poudre réagit-elle plus vite qu’un bloc du même solide ?', 'mcq', '["Elle est plus concentrée","Elle est plus chaude","Elle joue le rôle de catalyseur","Elle offre une plus grande surface de contact"]'::jsonb, 3, 'L’état de division est un facteur cinétique : plus le solide est fin, plus la surface de contact avec les réactifs est grande.', 4),
    ('ee08a81a-5cd2-57ac-ba16-a89501b70dfb'::uuid, 'physique-chimie', 'Tle', 'Étapes d’une transformation chimique : modèle microscopique', 'Pourquoi un acte élémentaire met-il en jeu au plus deux entités ?', 'mcq', '["Parce que les chocs à trois entités sont trop improbables","Parce que trois molécules se repoussent","Par convention d’écriture","Parce que les catalyseurs l’imposent"]'::jsonb, 0, 'Une rencontre simultanée de trois entités au même endroit, au même instant, est trop improbable pour compter.', 1),
    ('85932496-f6b6-5edb-ac27-f64788252f77'::uuid, 'physique-chimie', 'Tle', 'Étapes d’une transformation chimique : modèle microscopique', 'Qu’est-ce qu’un catalyseur ne modifie pas ?', 'mcq', '["La durée de la transformation","Le chemin réactionnel","L’état final et la constante d’équilibre","L’énergie demandée par les étapes"]'::jsonb, 2, 'Le catalyseur ouvre un chemin plus rapide, mais l’état final et K restent les mêmes.', 2),
    ('2561dc78-e021-5bf7-a1b6-aa7a3510fa5a'::uuid, 'physique-chimie', 'Tle', 'Étapes d’une transformation chimique : modèle microscopique', 'Quel facteur augmente la PART des chocs assez énergétiques pour être efficaces ?', 'mcq', '["La concentration","La température","Le volume du récipient","La couleur de la solution"]'::jsonb, 1, 'La concentration augmente le nombre de chocs ; la température augmente la part de ceux qui sont assez énergétiques.', 3),
    ('53d09e9f-6a15-5fb2-9b49-ac01cc1d157b'::uuid, 'physique-chimie', 'Tle', 'Étapes d’une transformation chimique : modèle microscopique', 'Peut-on déduire le mécanisme d’une réaction de son équation de bilan ?', 'mcq', '["Oui, il suffit de lire les coefficients","Oui, si la réaction est totale","Oui, quand il n’y a pas de catalyseur","Non, il s’établit expérimentalement"]'::jsonb, 3, 'Deux réactions au bilan identique peuvent suivre des chemins très différents : le mécanisme ne se devine pas.', 4),
    ('a7bf6fc1-19e3-5839-9f20-f671c0938b85'::uuid, 'physique-chimie', 'Tle', 'La radioactivité naturelle', 'Deux isotopes d’un même élément ont…', 'mcq', '["Le même A et des Z différents","Le même Z et des A différents","Le même nombre de neutrons","Des propriétés chimiques différentes"]'::jsonb, 1, 'Même Z, donc même élément et même chimie ; A différent, donc un nombre de neutrons différent : carbone 12 et carbone 14.', 1),
    ('01eaac00-4770-556e-a747-01cc97395402'::uuid, 'physique-chimie', 'Tle', 'La radioactivité naturelle', 'Quelle particule est émise lors d’une désintégration β⁺ ?', 'mcq', '["Un positon","Un électron","Un noyau d’hélium","Un neutron"]'::jsonb, 0, 'En β⁺, un proton devient neutron et un positon ⁰₊₁e est émis ; cela concerne les noyaux trop riches en protons.', 2),
    ('57e55564-fce6-5ea0-ae82-f3d7a4e4dc9e'::uuid, 'physique-chimie', 'Tle', 'La radioactivité naturelle', 'Le carbone 14 (Z = 6) subit une désintégration β⁻. Quel noyau obtient-on ?', 'mcq', '["Le bore 14 (Z = 5)","Le carbone 13 (Z = 6)","L’oxygène 14 (Z = 8)","L’azote 14 (Z = 7)"]'::jsonb, 3, 'En β⁻, A se conserve et Z augmente de 1 : ¹⁴₆C donne ¹⁴₇N, l’azote 14.', 3),
    ('c2b549f1-39e8-5420-a130-64543a90edec'::uuid, 'physique-chimie', 'Tle', 'La radioactivité naturelle', 'Quels noyaux subissent surtout une désintégration α ?', 'mcq', '["Les noyaux trop riches en protons","Les noyaux légers","Les noyaux lourds","Les noyaux excités seulement"]'::jsonb, 2, 'L’émission α, qui retire quatre nucléons d’un coup, concerne les noyaux lourds comme l’uranium ou le radium.', 4),
    ('96e84991-5dad-591a-b86a-4dd94f540591'::uuid, 'physique-chimie', 'Tle', 'Évolution d’une population de noyaux radioactifs', 'Quelle est la demi-vie du carbone 14 ?', 'mcq', '["8 jours","5 730 ans","50 000 ans","4,5 milliards d’années"]'::jsonb, 1, 'Le carbone 14 a une demi-vie de 5 730 ans ; 8 jours est celle de l’iode 131, 4,5 milliards d’années celle de l’uranium 238.', 1),
    ('cefd883e-93f8-53f4-903f-67be6ca21ed9'::uuid, 'physique-chimie', 'Tle', 'Évolution d’une population de noyaux radioactifs', 'Quelle équation différentielle vérifie N(t) ?', 'mcq', '["dN/dt = λN","dN/dt = −λ","dN/dt = −λN","dN/dt = N/λ"]'::jsonb, 2, 'dN/dt = −λN : le nombre de désintégrations par unité de temps est proportionnel au nombre de noyaux restants.', 2),
    ('80097cc3-cb10-594f-9b36-04330e802e65'::uuid, 'physique-chimie', 'Tle', 'Évolution d’une population de noyaux radioactifs', 'Après 10 demi-vies, quelle part des noyaux initiaux reste-t-il ?', 'mcq', '["La moitié","Un dixième","Aucune","Moins d’un millième"]'::jsonb, 3, '(1/2)¹⁰ = 1/1024 : il reste moins d’un millième des noyaux. La décroissance est exponentielle, pas linéaire.', 3),
    ('329c37fb-aedc-55bc-9ede-79095e5a0916'::uuid, 'physique-chimie', 'Tle', 'Évolution d’une population de noyaux radioactifs', 'Que mesure-t-on au compteur Geiger ?', 'mcq', '["L’activité de l’échantillon","Le nombre de noyaux N","La constante radioactive λ","La masse de l’échantillon"]'::jsonb, 0, 'On mesure l’activité, en désintégrations par seconde ; N ne se mesure jamais directement, on le déduit de A = λN.', 4),
    ('5db65f37-a8b6-5cc1-82dd-dbafae01faae'::uuid, 'physique-chimie', 'Tle', 'L’équilibre chimique', 'Si Qr,i > K, dans quel sens le système évolue-t-il ?', 'mcq', '["Dans le sens direct","Dans le sens indirect","Il n’évolue pas","Il évolue jusqu’à Qr = 0"]'::jsonb, 1, 'Qr doit diminuer pour rejoindre K : le système consomme des produits, il évolue dans le sens indirect.', 1),
    ('a1c40e29-175b-5e44-8b23-e2b2dbcf5195'::uuid, 'physique-chimie', 'Tle', 'L’équilibre chimique', 'Comment se définit le taux d’avancement final τ ?', 'mcq', '["τ = x_max / x_f","τ = K / Qr","τ = x_f × x_max","τ = x_f / x_max"]'::jsonb, 3, 'τ = x_f / x_max mesure jusqu’où la transformation est allée : τ = 1 pour une transformation totale.', 2),
    ('edc99cd9-0f29-5411-82dc-a430455c5800'::uuid, 'physique-chimie', 'Tle', 'L’équilibre chimique', 'Dans une solution aqueuse diluée, l’eau solvant figure dans l’expression de Qr.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme les solides, le solvant n’apparaît pas dans Qr : sa concentration ne varie pratiquement pas.', 3),
    ('170b51a5-ee18-504c-91d8-6e1b2528e953'::uuid, 'physique-chimie', 'Tle', 'L’équilibre chimique', 'À l’équilibre chimique, qu’est-ce qui cesse de varier ?', 'mcq', '["Les concentrations, à l’échelle macroscopique","Les réactions à l’échelle microscopique","La température du milieu obligatoirement","La valeur de K"]'::jsonb, 0, 'L’équilibre est dynamique : les réactions directe et inverse continuent, à la même vitesse, et seules les concentrations se figent.', 4),
    ('f32574c5-252b-5a57-a152-496cd9a3152a'::uuid, 'physique-chimie', 'Tle', 'Les piles : générateurs électrochimiques', 'Dans une pile, qu’est-ce qui circule dans le pont salin ?', 'mcq', '["Des électrons","Des protons seulement","Des ions","Des molécules d’eau"]'::jsonb, 2, 'Les électrons circulent dans le fil extérieur ; dans le pont salin, ce sont des ions qui ferment le circuit.', 1),
    ('49b21060-5448-51b8-8d78-2f671366c843'::uuid, 'physique-chimie', 'Tle', 'Les piles : générateurs électrochimiques', 'Que se passe-t-il à la cathode d’une pile ?', 'mcq', '["Une réduction, au pôle positif","Une oxydation, au pôle positif","Une réduction, au pôle négatif","Une oxydation, au pôle négatif"]'::jsonb, 0, 'Cathode = réduction (deux consonnes) ; dans une pile, c’est le pôle positif.', 2),
    ('cde0fec2-7aeb-5c4a-a22a-a5cb0289e6b2'::uuid, 'physique-chimie', 'Tle', 'Les piles : générateurs électrochimiques', 'Dans le circuit extérieur d’une pile, le courant conventionnel circule…', 'mcq', '["De l’anode vers la cathode","De la cathode vers l’anode","Dans le pont salin uniquement","Dans les deux sens alternativement"]'::jsonb, 1, 'Les électrons vont de l’anode vers la cathode ; le courant conventionnel, en sens inverse, sort par le pôle positif.', 3),
    ('e54d6d2e-266a-5aa4-9595-12c3163c4394'::uuid, 'physique-chimie', 'Tle', 'Les piles : générateurs électrochimiques', 'Quel réactif limite le plus souvent la durée de vie d’une pile ?', 'mcq', '["Le sel du pont salin","L’eau des solutions","Le fil de connexion","Le métal de l’anode, qui se dissout"]'::jsonb, 3, 'L’anode est oxydée et se dissout peu à peu : c’est presque toujours elle le réactif limitant.', 4),
    ('b35f66e7-3266-5e11-bca4-785728d1a9c1'::uuid, 'physique-chimie', 'Tle', 'Électrolyse et générateurs électrochimiques', 'Lors d’une électrolyse, la cathode est reliée à…', 'mcq', '["La borne + du générateur","La borne − du générateur","La terre","Aucune borne"]'::jsonb, 1, 'La cathode, siège de la réduction, reçoit les électrons : elle est reliée à la borne − du générateur.', 1),
    ('ba8cdf15-45b5-551e-aa3b-9e3fb51bbe01'::uuid, 'physique-chimie', 'Tle', 'Électrolyse et générateurs électrochimiques', 'En galvanoplastie, où place-t-on la pièce à recouvrir de métal ?', 'mcq', '["À la cathode","À l’anode","Dans le pont salin","Hors de la solution"]'::jsonb, 0, 'Les ions métalliques sont réduits à la cathode et s’y déposent : c’est donc là qu’on place la pièce.', 2),
    ('dd809bd1-2177-5b62-bd2a-f18ecee4dd6c'::uuid, 'physique-chimie', 'Tle', 'Électrolyse et générateurs électrochimiques', 'Quelle conversion d’énergie réalise une électrolyse ?', 'mcq', '["Chimique vers électrique","Thermique vers électrique","Électrique vers chimique","Lumineuse vers chimique"]'::jsonb, 2, 'Le générateur fournit de l’énergie électrique qui force une réaction non spontanée : elle est stockée sous forme chimique.', 3),
    ('8b42fb41-8412-54b9-bc0e-d0596b239822'::uuid, 'physique-chimie', 'Tle', 'Électrolyse et générateurs électrochimiques', 'Que doit fournir le générateur d’une électrolyse ?', 'mcq', '["Une tension nulle","Un courant alternatif","Une tension égale à celle de la pile correspondante","Une tension supérieure à celle que délivrerait la pile correspondante"]'::jsonb, 3, 'Pour forcer le système contre son sens spontané, il faut dépasser la tension que la pile correspondante délivrerait.', 4),
    ('460402d4-46d8-57cc-ad08-4cca7a2aeac1'::uuid, 'physique-chimie', 'Tle', 'Force des acides et des bases', 'Parmi ces acides, lequel est un acide fort ?', 'mcq', '["L’acide éthanoïque","L’acide fluorhydrique HF","L’acide nitrique HNO₃","L’ion ammonium"]'::jsonb, 2, 'HCl, HNO₃ et H₂SO₄ réagissent totalement avec l’eau ; CH₃COOH, HF et NH₄⁺ sont des acides faibles.', 1),
    ('ee3ac4de-d834-5700-adfc-f67e98844b80'::uuid, 'physique-chimie', 'Tle', 'Force des acides et des bases', 'Quelle relation relie pH et pKa d’un couple ?', 'mcq', '["pH = pKa + log([A⁻]/[AH])","pH = pKa + log([AH]/[A⁻])","pH = pKa × [A⁻]/[AH]","pH = pKa − Ke"]'::jsonb, 0, 'C’est la relation de Henderson, obtenue en prenant le logarithme de l’expression de Ka.', 2),
    ('c2c18167-d360-5e51-bae2-ac8bdd2f1286'::uuid, 'physique-chimie', 'Tle', 'Force des acides et des bases', 'Combien de domaines de prédominance compte un diacide ?', 'mcq', '["Deux","Trois","Quatre","Un seul"]'::jsonb, 1, 'Ses deux pKa coupent l’axe de pH en trois domaines : le diacide, l’espèce intermédiaire et la dibase.', 3),
    ('8207d3fc-a14e-5ad1-ba4b-481122d202e5'::uuid, 'physique-chimie', 'Tle', 'Force des acides et des bases', 'L’ammoniac NH₃ est une base…', 'mcq', '["Forte, comme HO⁻","Qui n’existe pas en solution","Amphotère seulement","Faible, de pKa 9,2 pour son couple"]'::jsonb, 3, 'NH₃ réagit de façon limitée avec l’eau : c’est une base faible, et le couple NH₄⁺/NH₃ a un pKa de 9,2.', 4),
    ('ea8329ba-ba69-5884-b933-0587e3f49bb0'::uuid, 'physique-chimie', 'Tle', 'Équilibre chimique et calcul du pH d’une solution', 'Quel est le pH d’une solution de base forte de concentration 1,0 × 10⁻² mol·L⁻¹ à 25 °C ?', 'mcq', '["2,0","12,0","7,0","10,0"]'::jsonb, 1, 'pH = 14,0 + log(c/c°) = 14,0 − 2,0 = 12,0 : on passe par [HO⁻] puis par Ke.', 1),
    ('682edc24-54ac-518d-a700-a9eb020bbae5'::uuid, 'physique-chimie', 'Tle', 'Équilibre chimique et calcul du pH d’une solution', 'Comment évolue le taux d’avancement d’un acide faible quand on le dilue ?', 'mcq', '["Il augmente","Il diminue","Il reste constant","Il devient nul"]'::jsonb, 0, 'Diluer augmente τ : un acide faible très dilué se comporte presque comme un acide fort.', 2),
    ('87c291b8-c484-5ae9-b080-c1e8516f29f8'::uuid, 'physique-chimie', 'Tle', 'Équilibre chimique et calcul du pH d’une solution', 'Comment repère-t-on l’équivalence sur une courbe de titrage pH-métrique ?', 'mcq', '["Au point où pH = 7 toujours","Au point où pH = pKa","Par la méthode des tangentes ou le maximum de la dérivée","Au début de la courbe"]'::jsonb, 2, 'L’équivalence est le point d’inflexion du saut de pH : méthode des tangentes ou maximum de dpH/dV.', 3),
    ('7df56d8c-0447-5de9-b28f-ed1a2b90cace'::uuid, 'physique-chimie', 'Tle', 'Équilibre chimique et calcul du pH d’une solution', 'Quel couple tamponne le sang autour de pH 7,4 ?', 'mcq', '["NH₄⁺ / NH₃","H₃O⁺ / H₂O","CH₃COOH / CH₃COO⁻","CO₂,H₂O / HCO₃⁻"]'::jsonb, 3, 'Le sang est tamponné par le couple CO₂,H₂O / HCO₃⁻, qui limite les variations de pH autour de 7,4.', 4),
    ('9746e8ae-710a-5c14-8cf9-b5fbe9740a8b'::uuid, 'physique-chimie', 'Tle', 'Structure des molécules organiques', 'Où se trouve toujours le groupe d’un aldéhyde, —CHO ?', 'mcq', '["En milieu de chaîne","En bout de chaîne","Sur un cycle obligatoirement","Sur un carbone tertiaire"]'::jsonb, 1, 'Le groupe —CHO est toujours en bout de chaîne ; le groupe cétone —CO— est toujours en milieu de chaîne.', 1),
    ('d4bf6fb9-d3a4-5489-b046-204f4d7e544b'::uuid, 'physique-chimie', 'Tle', 'Structure des molécules organiques', 'Quel groupe caractéristique définit un ester ?', 'mcq', '["—COO—","—CONH—","—COOH","—CHO"]'::jsonb, 0, 'L’ester porte —COO— ; —CONH— est l’amide, —COOH l’acide carboxylique, —CHO l’aldéhyde.', 2),
    ('1b865318-6e53-5367-93ed-aef2dd309f87'::uuid, 'physique-chimie', 'Tle', 'Structure des molécules organiques', 'Quelle formule ne permet pas de distinguer deux isomères ?', 'mcq', '["La formule topologique","La formule semi-développée","La formule brute","La formule développée"]'::jsonb, 2, 'La formule brute ne donne que le nombre d’atomes : C₂H₆O est aussi bien l’éthanol que le méthoxyméthane.', 3),
    ('1c62f619-8069-5ce6-b661-28b1b579cd5a'::uuid, 'physique-chimie', 'Tle', 'Structure des molécules organiques', 'Pourquoi deux énantiomères peuvent-ils avoir des effets biologiques très différents ?', 'mcq', '["Parce que leurs masses molaires diffèrent","Parce que l’un est toujours toxique","Parce qu’ils n’ont pas la même formule brute","Parce que les récepteurs biologiques sont eux-mêmes chiraux"]'::jsonb, 3, 'Un récepteur chiral ne reconnaît qu’une des deux formes, alors que leurs propriétés physiques sont identiques.', 4),
    ('8d28b191-cabb-5f75-949a-b6548e43e36e'::uuid, 'physique-chimie', 'Tle', 'Stratégie et sélectivité en chimie organique', 'Comment reconnaît-on une réaction d’élimination ?', 'mcq', '["Une insaturation disparaît","Une liaison multiple se crée","Un groupe en remplace un autre","La chaîne s’allonge"]'::jsonb, 1, 'Dans une élimination, une liaison multiple apparaît ; dans une addition, elle disparaît.', 1),
    ('80d98fcf-74d6-5ab5-808f-ac17ce078b8e'::uuid, 'physique-chimie', 'Tle', 'Stratégie et sélectivité en chimie organique', 'Qu’appelle-t-on régiosélectivité ?', 'mcq', '["Une seule position réagit parmi plusieurs possibles","Un seul type de groupe réagit","Un seul stéréo-isomère se forme","La réaction se fait sans solvant"]'::jsonb, 0, 'La régiosélectivité porte sur la position ; la chimiosélectivité sur le type de groupe ; la stéréosélectivité sur le stéréo-isomère.', 2),
    ('67083b02-2e8f-5d53-9ffb-fe034d768feb'::uuid, 'physique-chimie', 'Tle', 'Stratégie et sélectivité en chimie organique', 'Combien d’étapes une protection de fonction ajoute-t-elle à une synthèse ?', 'mcq', '["Aucune","Une","Deux","Trois"]'::jsonb, 2, 'Protéger puis déprotéger : deux étapes de plus, donc un coût et une perte de rendement, mais souvent le seul chemin possible.', 3),
    ('832563d9-d3bb-50f1-a7ca-3f8503789bc3'::uuid, 'physique-chimie', 'Tle', 'Stratégie et sélectivité en chimie organique', 'Parmi ces choix, lequel relève de la chimie verte ?', 'mcq', '["Multiplier les solvants","Employer des réactifs en quantité stœchiométrique plutôt qu’un catalyseur","Prolonger le chauffage à reflux","Préférer la catalyse et les matières premières renouvelables"]'::jsonb, 3, 'La chimie verte limite les solvants, préfère la catalyse aux réactifs stœchiométriques et les ressources renouvelables.', 4),
    ('db3b303f-8dcf-5036-a08c-b5263313bd70'::uuid, 'physique-chimie', 'Tle', 'Modélisation d’un mouvement', 'Quel référentiel choisit-on pour étudier le mouvement d’un satellite de la Terre ?', 'mcq', '["Le référentiel héliocentrique","Le référentiel géocentrique","Le référentiel terrestre","Le référentiel du satellite"]'::jsonb, 1, 'Le référentiel géocentrique, centré sur la Terre, sert pour les satellites ; l’héliocentrique pour les planètes.', 1),
    ('f4d68e8d-4b81-5048-98ba-4deb0c2da17a'::uuid, 'physique-chimie', 'Tle', 'Modélisation d’un mouvement', 'Que traduit la composante tangentielle de l’accélération aₜ = dv/dt ?', 'mcq', '["La variation de la valeur de la vitesse","La variation de la direction de la vitesse","La courbure de la trajectoire","La distance parcourue"]'::jsonb, 0, 'aₜ traduit la variation de la valeur de la vitesse ; aₙ = v²/R, celle de sa direction.', 2),
    ('8ced78c0-ce1e-50d8-ab48-6e8451f855a8'::uuid, 'physique-chimie', 'Tle', 'Modélisation d’un mouvement', 'Vers où le vecteur accélération est-il toujours orienté sur une trajectoire courbe ?', 'mcq', '["Vers l’extérieur de la courbure","Tangent à la trajectoire","Vers l’intérieur de la courbure","Vers le haut"]'::jsonb, 2, 'Pour qu’une trajectoire tourne, l’accélération doit pointer vers l’intérieur de la courbure.', 3),
    ('304db386-ad89-537f-b1db-e61e3e0a50cb'::uuid, 'physique-chimie', 'Tle', 'Modélisation d’un mouvement', 'Sur un pointage vidéo, que se passe-t-il si l’on réduit trop l’intervalle τ entre deux images ?', 'mcq', '["La dérivée devient exacte","La vitesse calculée double","Les positions deviennent inutiles","L’incertitude de pointage pèse davantage"]'::jsonb, 3, 'Un petit τ approche mieux la dérivée, mais l’erreur de pointage devient relativement plus grande : c’est un compromis.', 4),
    ('3d01e5c5-3c4e-594d-ab77-156f2974f75a'::uuid, 'physique-chimie', 'Tle', 'Appliquer la deuxième loi de Newton', 'Comment s’écrit la quantité de mouvement p d’un système ?', 'mcq', '["p = m a","p = ½ m v²","p = m v","p = m g"]'::jsonb, 2, 'p = m v ; la deuxième loi de Newton s’écrit ΣF = dp/dt, soit ΣF = m a si la masse est constante.', 1),
    ('5a92f27d-af53-5433-9dbd-93c78dc34cfe'::uuid, 'physique-chimie', 'Tle', 'Appliquer la deuxième loi de Newton', 'D’après la deuxième loi de Newton, une force donne…', 'mcq', '["La vitesse du système","La variation de la vitesse","La position du système","La masse du système"]'::jsonb, 1, 'Une force ne donne pas la vitesse, mais sa variation : on peut avancer vite sans aucune force, par inertie.', 2),
    ('f58f3eb4-941c-5913-8f61-eb344ee17934'::uuid, 'physique-chimie', 'Tle', 'Appliquer la deuxième loi de Newton', 'Où viennent les constantes d’intégration quand on intègre deux fois ΣF = m a ?', 'mcq', '["Des conditions initiales","De la masse du système","Du référentiel choisi","De la troisième loi de Newton"]'::jsonb, 0, 'Position et vitesse à t = 0 fixent les constantes : ce sont les conditions initiales.', 3),
    ('3a6d6918-5015-579f-8dca-9681d528014e'::uuid, 'physique-chimie', 'Tle', 'Appliquer la deuxième loi de Newton', 'Dans la méthode d’Euler, comment améliorer la fidélité de la solution approchée ?', 'mcq', '["En augmentant Δt","En supprimant les frottements","En changeant de référentiel","En diminuant le pas Δt"]'::jsonb, 3, 'Plus le pas Δt est petit, plus la solution pas à pas colle à la solution exacte.', 4),
    ('df9d2082-deef-56b3-b600-50636738e4fa'::uuid, 'physique-chimie', 'Tle', 'Mouvement dans un champ uniforme', 'Comment est orienté le champ électrique entre deux plaques chargées ?', 'mcq', '["De la plaque + vers la plaque −","De la plaque − vers la plaque +","Parallèlement aux plaques","Il n’a pas de sens défini"]'::jsonb, 0, 'E est dirigé du + vers le − ; une charge positive est poussée dans le sens de E, une charge négative en sens inverse.', 1),
    ('65dce3dd-093d-500c-9e65-6936285189a3'::uuid, 'physique-chimie', 'Tle', 'Mouvement dans un champ uniforme', 'Dans un tir sans frottement, quel est le mouvement selon l’axe horizontal ?', 'mcq', '["Uniformément accéléré","Uniforme","Circulaire","Uniformément ralenti jusqu’à l’arrêt"]'::jsonb, 1, 'a_x = 0 : la composante horizontale de la vitesse reste v₀ cos α, le mouvement horizontal est uniforme.', 2),
    ('08c9cd54-ffe1-55f9-83cd-43c632e94785'::uuid, 'physique-chimie', 'Tle', 'Mouvement dans un champ uniforme', 'Pourquoi néglige-t-on le poids d’un électron entre deux plaques chargées ?', 'mcq', '["Parce qu’un électron n’a pas de masse","Parce que g est nul entre les plaques","Parce qu’il est totalement négligeable devant la force électrique","Parce que le poids est compensé par la poussée d’Archimède"]'::jsonb, 2, 'La masse de l’électron est si faible que son poids est négligeable devant qE : on ne le fait pas figurer au bilan.', 3),
    ('eb5aac6a-a22b-56ca-a97b-d4d96c751bf4'::uuid, 'physique-chimie', 'Tle', 'Mouvement dans un champ uniforme', 'Quelle méthode donne le plus vite la vitesse d’un projectile en un point, sans frottement ?', 'mcq', '["Intégrer deux fois les équations","Tracer la parabole point par point","Calculer la portée d’abord","Utiliser la conservation de l’énergie mécanique"]'::jsonb, 3, '½mv² + mgz = constante donne la vitesse en un point sans passer par les équations horaires.', 4),
    ('dc04792e-1145-5b5c-8e43-0ff215566b6b'::uuid, 'physique-chimie', 'Tle', 'Mouvement dans un champ de gravitation', 'La vitesse d’un satellite en orbite circulaire dépend de sa masse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'v = √(G M / r) : seule la masse M de l’astre attracteur intervient, celle du satellite disparaît de l’équation.', 1),
    ('5463916e-f61c-53ec-a384-8628e8ba4750'::uuid, 'physique-chimie', 'Tle', 'Mouvement dans un champ de gravitation', 'Selon la deuxième loi de Kepler, une planète va plus vite…', 'mcq', '["Au périhélie, au plus près du Soleil","À l’aphélie, au plus loin du Soleil","Toujours à la même vitesse","Seulement quand elle est alignée avec la Terre"]'::jsonb, 0, 'Des aires égales en des durées égales : près du Soleil, le rayon est court, la planète doit donc parcourir plus d’arc, elle va plus vite.', 2),
    ('6a95ffd0-60d6-50e6-9eee-0d948e409841'::uuid, 'physique-chimie', 'Tle', 'Mouvement dans un champ de gravitation', 'À quelle altitude se trouve un satellite géostationnaire ?', 'mcq', '["Environ 400 km","Environ 6 400 km","Environ 36 000 km","Environ 384 000 km"]'::jsonb, 2, 'La troisième loi de Kepler impose un rayon de 42 200 km depuis le centre de la Terre, soit environ 36 000 km d’altitude.', 3),
    ('4611cc4f-dda2-5158-a008-3a532822ca57'::uuid, 'physique-chimie', 'Tle', 'Mouvement dans un champ de gravitation', 'À quoi sert la troisième loi de Kepler T²/r³ = 4π²/(G M) ?', 'mcq', '["À calculer la masse du satellite","À mesurer la forme des orbites","À prouver que les orbites sont circulaires","À peser l’astre attracteur à partir d’une seule orbite"]'::jsonb, 3, 'Connaissant T et r d’un seul satellite, on en déduit M : c’est ainsi qu’on pèse un astre.', 4),
    ('5bbd5a80-ff19-542c-9807-76c33782ade1'::uuid, 'physique-chimie', 'Tle', 'Écoulement d’un fluide incompressible', 'Une canalisation passe d’une section S à une section S/2. La vitesse du fluide…', 'mcq', '["Est divisée par 2","Double","Reste la même","Est multipliée par 4"]'::jsonb, 1, 'Le débit S × v se conserve : si la section est divisée par deux, la vitesse double.', 1),
    ('40f3fece-a3d4-5138-8cf9-468de9c3a8d6'::uuid, 'physique-chimie', 'Tle', 'Écoulement d’un fluide incompressible', 'Dans la relation de Bernoulli, comment s’appelle le terme ½ρv² ?', 'mcq', '["La pression dynamique","La pression statique","Le terme de hauteur","La viscosité"]'::jsonb, 0, 'P est la pression statique, ½ρv² la pression dynamique, ρgz le terme de hauteur : tous homogènes à une pression.', 2),
    ('637e8eff-3108-51e5-b794-34aea33b166e'::uuid, 'physique-chimie', 'Tle', 'Écoulement d’un fluide incompressible', 'Dans une conduite réelle, pourquoi faut-il une pompe pour entretenir la pression ?', 'mcq', '["Parce que le fluide est compressible","Parce que le débit augmente","Parce que les frottements dus à la viscosité font chuter la pression","Parce que Bernoulli l’interdit"]'::jsonb, 2, 'Bernoulli suppose un fluide sans viscosité ; dans le réel, les frottements font baisser la pression le long du trajet.', 3),
    ('ab29aeb1-3069-54ac-aea1-13be839ba680'::uuid, 'physique-chimie', 'Tle', 'Écoulement d’un fluide incompressible', 'Quelle est l’unité du débit volumique ?', 'mcq', '["m·s⁻¹","kg·s⁻¹","Pa","m³·s⁻¹"]'::jsonb, 3, 'Dv = V / Δt = S × v s’exprime en m³·s⁻¹ ; le débit massique, lui, serait en kg·s⁻¹.', 4),
    ('c3ecc585-6255-59b1-8a83-1010a1739044'::uuid, 'physique-chimie', 'Tle', 'Description d’un système thermodynamique', 'Un calorimètre idéal est un système…', 'mcq', '["Ouvert","Fermé","Isolé","Qui échange seulement de la matière"]'::jsonb, 2, 'Un système isolé n’échange ni matière ni énergie : c’est ce qu’approche un calorimètre idéal.', 1),
    ('b60cb142-3195-5814-8122-043fdce44b47'::uuid, 'physique-chimie', 'Tle', 'Description d’un système thermodynamique', 'À combien de degrés Celsius correspond le zéro absolu ?', 'mcq', '["−273,15 °C","0 °C","−100 °C","−373,15 °C"]'::jsonb, 0, '0 K = −273,15 °C : c’est l’agitation minimale des entités.', 2),
    ('3129626c-cd89-5977-839c-5baf73917042'::uuid, 'physique-chimie', 'Tle', 'Description d’un système thermodynamique', 'Pourquoi peut-on écrire un écart de température ΔT en °C ?', 'mcq', '["Parce que le kelvin est interdit","Parce qu’un écart de 1 °C vaut exactement un écart de 1 K","Parce que les deux échelles ont le même zéro","On ne le peut jamais"]'::jsonb, 1, 'Les deux échelles ne diffèrent que par leur zéro : un écart de 1 °C est un écart de 1 K.', 3),
    ('121f4840-a921-514d-bc17-be7509cc51e3'::uuid, 'physique-chimie', 'Tle', 'Description d’un système thermodynamique', 'Pourquoi l’eau est-elle un bon fluide caloporteur ?', 'mcq', '["Parce qu’elle bout à 100 °C","Parce qu’elle est incompressible","Parce qu’elle conduit le courant","Parce que sa capacité thermique massique est remarquablement élevée"]'::jsonb, 3, 'Avec c = 4185 J·kg⁻¹·K⁻¹, l’eau stocke beaucoup d’énergie pour un faible échauffement : elle adoucit aussi les climats côtiers.', 4),
    ('524dcd84-7796-5cfb-bb3d-36b30ab6ff92'::uuid, 'physique-chimie', 'Tle', 'Variation de l’énergie interne d’un système', 'Pendant la fusion d’un corps pur, à quoi sert l’énergie reçue ?', 'mcq', '["À augmenter l’agitation des entités","À rompre les interactions entre entités","À augmenter la masse","À élever la température"]'::jsonb, 1, 'L’énergie sert à rompre des interactions, pas à agiter davantage les entités : la température reste constante.', 1),
    ('4d133fca-65c4-5bec-a1ed-ee0dcdc38b39'::uuid, 'physique-chimie', 'Tle', 'Variation de l’énergie interne d’un système', 'Quelle est la nature d’un transfert thermique Q ?', 'mcq', '["Un transfert désordonné d’énergie","Un transfert ordonné par une force","Un transfert de matière","Un transfert électrique"]'::jsonb, 0, 'Le transfert thermique est désordonné, de proche en proche ; le travail est un transfert ordonné, par une force.', 2),
    ('6aa531aa-5356-5fe9-a9cc-98b81deb6ffc'::uuid, 'physique-chimie', 'Tle', 'Variation de l’énergie interne d’un système', 'Dans un calorimètre, on mélange deux corps. Quelle relation écrit-on ?', 'mcq', '["Q₁ = Q₂","Q₁ = 2 × Q₂","Q₁ + Q₂ = 0","Q₁ × Q₂ = 1"]'::jsonb, 2, 'Le calorimètre approche un système isolé : les transferts s’annulent, ce que l’un cède, l’autre le reçoit.', 3),
    ('5ea618e8-e0e1-55f1-95ac-8c58d5e3f1e2'::uuid, 'physique-chimie', 'Tle', 'Variation de l’énergie interne d’un système', 'Pourquoi la transpiration rafraîchit-elle le corps ?', 'mcq', '["La sueur est plus froide que la peau","La sueur isole la peau","La sueur réfléchit le rayonnement","L’eau qui s’évapore prélève son énergie de vaporisation sur la peau"]'::jsonb, 3, 'La vaporisation coûte beaucoup d’énergie (2,26 × 10⁶ J·kg⁻¹), prélevée sur la peau qui se refroidit.', 4),
    ('002540c1-ba59-536e-b433-a7f8851f5522'::uuid, 'physique-chimie', 'Tle', 'Le premier principe de la thermodynamique', 'Pour une phase condensée subissant une transformation isotherme, que vaut ΔU ?', 'mcq', '["ΔU = W","ΔU = 0, donc W = −Q","ΔU = Q","ΔU = W + 2Q"]'::jsonb, 1, 'Pour une phase condensée, la température fixe U : à T constante ΔU = 0, et le travail reçu est intégralement cédé en chaleur.', 1),
    ('b05f35d1-9053-5a4f-8d13-9f84f779fbc5'::uuid, 'physique-chimie', 'Tle', 'Le premier principe de la thermodynamique', 'Qu’a établi l’expérience de Joule ?', 'mcq', '["L’équivalence entre travail et chaleur","L’existence du zéro absolu","La conservation de la masse","La loi de refroidissement"]'::jsonb, 0, 'Agiter de l’eau dans une enceinte calorifugée la réchauffe sans la chauffer : le travail produit le même effet qu’un transfert thermique.', 2),
    ('12fa9d80-e99a-586d-86dc-5be6d9a6df87'::uuid, 'physique-chimie', 'Tle', 'Le premier principe de la thermodynamique', 'Quel principe interdit à la chaleur de passer spontanément du froid vers le chaud ?', 'mcq', '["Le premier principe","Le principe d’inertie","Le second principe","Le principe des actions réciproques"]'::jsonb, 2, 'Le premier principe ne dit rien sur le sens des échanges ; c’est le second principe qui l’impose.', 3),
    ('02f46436-a75d-50db-b504-655653923675'::uuid, 'physique-chimie', 'Tle', 'Le premier principe de la thermodynamique', 'Un moteur reçoit 1000 J et fournit 350 J d’énergie utile. Que vaut son rendement ?', 'mcq', '["2,86","0,65","350","0,35"]'::jsonb, 3, 'η = E_utile / E_fournie = 350 / 1000 = 0,35 ; les 650 J restants partent en pertes, surtout en chaleur.', 4),
    ('77678462-b6b3-55a9-b3c9-2e7cbc116cd8'::uuid, 'physique-chimie', 'Tle', 'Transferts thermiques', 'Par quel mode la chaleur d’un radiateur se répartit-elle dans une pièce, l’air chaud montant ?', 'mcq', '["La conduction","La convection","Le rayonnement seul","L’électrolyse"]'::jsonb, 1, 'La convection transporte l’énergie par déplacement d’un fluide : l’air chaud, moins dense, monte.', 1),
    ('7c97da55-5206-5793-90b3-841e39eadf86'::uuid, 'physique-chimie', 'Tle', 'Transferts thermiques', 'Qu’est-ce qui isole vraiment dans une laine de verre ou un pull ?', 'mcq', '["L’air immobile emprisonné","Les fibres elles-mêmes","La couleur du matériau","L’humidité contenue"]'::jsonb, 0, 'L’air immobile a une conductivité de 0,026 W·m⁻¹·K⁻¹ : c’est lui qui isole, d’où l’inefficacité d’un isolant mouillé ou tassé.', 2),
    ('1dfbda26-d70f-54a8-a622-d48bc85a9c7b'::uuid, 'physique-chimie', 'Tle', 'Transferts thermiques', 'Dans l’analogie électrique, à quoi correspond l’écart de température ΔT ?', 'mcq', '["À l’intensité I","À la résistance R","À la tension U","À la charge q"]'::jsonb, 2, 'ΔT joue le rôle de la tension U, le flux Φ celui de l’intensité, R_th celui de la résistance : Φ = ΔT / R_th.', 3),
    ('f496f186-34d0-5866-b61e-0335ea672b99'::uuid, 'physique-chimie', 'Tle', 'Transferts thermiques', 'Que fait réellement un manteau ?', 'mcq', '["Il produit de la chaleur","Il absorbe le froid","Il augmente la température du corps","Il freine le flux thermique qui sort"]'::jsonb, 3, 'Un manteau n’est pas une source : c’est une résistance thermique qui freine le flux sortant.', 4),
    ('7b5a8d5b-1e9e-5cbe-be73-5db1620670ff'::uuid, 'physique-chimie', 'Tle', 'L’intensité sonore', 'Quel niveau sonore correspond au seuil de douleur ?', 'mcq', '["60 dB","120 dB","85 dB","0 dB"]'::jsonb, 1, 'Le seuil de douleur est à 120 dB, soit une intensité de 1 W·m⁻² ; le seuil d’audibilité est à 0 dB.', 1),
    ('fdafec45-a2d1-5980-9a3a-79989c4b1900'::uuid, 'physique-chimie', 'Tle', 'L’intensité sonore', 'Que vaut l’intensité de référence I₀ ?', 'mcq', '["1,0 × 10⁻¹² W·m⁻²","1,0 W·m⁻²","1,0 × 10⁻⁶ W·m⁻²","1,0 × 10¹² W·m⁻²"]'::jsonb, 0, 'I₀ = 10⁻¹² W·m⁻² est le seuil d’audibilité : à cette intensité, L = 0 dB.', 2),
    ('660d4916-61b5-590e-82aa-ac37dc1b71a8'::uuid, 'physique-chimie', 'Tle', 'L’intensité sonore', 'Entre quelles fréquences l’oreille humaine est-elle la plus sensible ?', 'mcq', '["Entre 20 et 100 Hz","Au-delà de 15 kHz","Entre 1 et 4 kHz","Elle est également sensible partout"]'::jsonb, 2, 'L’oreille est plus sensible entre 1 et 4 kHz, d’où la pondération dB(A) de l’acoustique réglementaire.', 3),
    ('bd11c30d-fdd6-5872-a1cd-115f1fdb5afe'::uuid, 'physique-chimie', 'Tle', 'L’intensité sonore', 'Que devient l’énergie sonore perdue par absorption dans un milieu ?', 'mcq', '["Elle s’étale sur une sphère plus grande","Elle est détruite","Elle est réfléchie vers la source","Elle est convertie en énergie interne du milieu"]'::jsonb, 3, 'L’absorption convertit réellement l’énergie ; l’atténuation géométrique, elle, ne fait que la répartir.', 4),
    ('6355c152-1c1d-5a93-b570-3f6f0136447f'::uuid, 'physique-chimie', 'Tle', 'L’effet Doppler', 'Quelle relation donne la fréquence reçue quand la source s’éloigne à la vitesse v ?', 'mcq', '["f_r = f_e × c / (c − v)","f_r = f_e × c / (c + v)","f_r = f_e × v / c","f_r = f_e × (c + v) / c²"]'::jsonb, 1, 'Quand la source s’éloigne, le dénominateur c + v est plus grand que c : la fréquence reçue diminue.', 1),
    ('28caf5a2-82cd-5b52-97d2-6b1e6760d88c'::uuid, 'physique-chimie', 'Tle', 'L’effet Doppler', 'Quelle découverte le décalage vers le rouge des galaxies a-t-il permise ?', 'mcq', '["L’expansion de l’Univers","L’existence des photons","La vitesse du son","Les lois de Kepler"]'::jsonb, 0, 'Les galaxies lointaines s’éloignent de nous, et d’autant plus vite qu’elles sont loin : l’Univers est en expansion.', 2),
    ('00c2a75e-0e95-52ca-8e81-25442f78da72'::uuid, 'physique-chimie', 'Tle', 'L’effet Doppler', 'Comment l’effet Doppler permet-il de détecter une exoplanète ?', 'mcq', '["La planète émet un son","La planète cache l’étoile","Le spectre de l’étoile oscille au rythme de la planète","La planète réfléchit un radar"]'::jsonb, 2, 'La planète fait osciller son étoile : ses raies se décalent tantôt vers le bleu, tantôt vers le rouge.', 3),
    ('40bda4ff-b27e-5ec9-8510-2b17fd8cc8d5'::uuid, 'physique-chimie', 'Tle', 'L’effet Doppler', 'Que se passe-t-il quand la vitesse de la source atteint la célérité du son ?', 'mcq', '["Le son disparaît","La fréquence émise double","La célérité du son augmente","Les fronts d’onde s’accumulent en une onde de choc : le mur du son"]'::jsonb, 3, 'Les fronts d’onde s’accumulent en une seule surface ; la formule f_e × c / (c − v) diverge et annonce le phénomène.', 4),
    ('5909980b-4a50-5df2-8fbd-96b102aa2c5f'::uuid, 'physique-chimie', 'Tle', 'Diffraction d’une onde', 'En quelle unité s’exprime θ dans la relation θ = λ / a ?', 'mcq', '["En degrés","En radians","En mètres","En hertz"]'::jsonb, 1, 'θ = λ / a est un rapport de deux longueurs qui donne un angle en radians.', 1),
    ('7692b238-3a8f-518d-a041-b2a9abd48946'::uuid, 'physique-chimie', 'Tle', 'Diffraction d’une onde', 'Pourquoi la lumière semble-t-elle aller tout droit au quotidien ?', 'mcq', '["Sa longueur d’onde, quelques centaines de nm, est minuscule devant les ouvertures courantes","Elle ne se diffracte jamais","Elle va plus vite que le son","Elle est absorbée par l’air"]'::jsonb, 0, 'Les ouvertures courantes sont immenses devant λ ≈ 500 nm : l’étalement est trop faible pour être remarqué.', 2),
    ('944bed2e-7978-5485-9e81-db1c601db7ad'::uuid, 'physique-chimie', 'Tle', 'Diffraction d’une onde', 'Qu’est-ce qui pousse surtout à construire de grands télescopes ?', 'mcq', '["Un grossissement plus fort","Un tube plus long","Une résolution moins limitée par la diffraction","Un poids plus stable"]'::jsonb, 2, 'Plus l’ouverture est grande, moins la diffraction étale l’image : deux étoiles proches sont mieux séparées.', 3),
    ('26dcc677-5769-5024-ad51-3bff3af241d7'::uuid, 'physique-chimie', 'Tle', 'Diffraction d’une onde', 'Comment peut-on mesurer le diamètre d’un cheveu au laboratoire ?', 'mcq', '["À la règle graduée","Par effet Doppler","Par conductimétrie","En mesurant la tache centrale de diffraction qu’il produit"]'::jsonb, 3, 'Le cheveu diffracte comme une fente de même largeur : de L = 2λD/a on tire a, connaissant λ et D.', 4),
    ('33aaf1a5-7827-54b7-9c2a-233a3a8c3498'::uuid, 'physique-chimie', 'Tle', 'Interférences de deux ondes', 'Quelle est la condition d’interférences constructives ?', 'mcq', '["δ = (k + ½) λ","δ = k λ","δ = λ / 4","δ = 2k + 1"]'::jsonb, 1, 'Une différence de marche multiple entière de λ met les ondes en phase : frange brillante.', 1),
    ('02dd9d38-244d-59c4-ac85-fb8097a7435e'::uuid, 'physique-chimie', 'Tle', 'Interférences de deux ondes', 'Deux lampes distinctes de même couleur donnent-elles des interférences visibles ?', 'mcq', '["Non, elles ne sont pas cohérentes","Oui, si elles ont la même intensité","Oui, toujours","Oui, si elles sont proches"]'::jsonb, 0, 'Leur déphasage varie sans cesse : on n’obtient d’interférences stables qu’en dédoublant une même source.', 2),
    ('bb8551a0-1193-5ff9-bb70-aa4d4a7fbd0e'::uuid, 'physique-chimie', 'Tle', 'Interférences de deux ondes', 'Comment évolue l’interfrange si l’on écarte davantage les deux fentes d’Young ?', 'mcq', '["Il augmente","Il ne change pas","Il diminue","Il s’annule"]'::jsonb, 2, 'i = λD / b : l’interfrange est inversement proportionnel à l’écart b entre les fentes.', 3),
    ('1330bba3-8f08-50f6-bd2f-a48d20d01320'::uuid, 'physique-chimie', 'Tle', 'Interférences de deux ondes', 'Comment distinguer une couleur interférentielle d’une couleur de pigment ?', 'mcq', '["Elle est toujours bleue","Elle disparaît dans le noir","Elle ne se voit qu’au microscope","Elle change avec l’angle de vue"]'::jsonb, 3, 'Les couleurs d’une bulle ou d’une plume de paon changent avec l’angle : aucun pigment ne fait cela.', 4),
    ('5e41df9e-ff88-5b71-8b84-47778b685660'::uuid, 'physique-chimie', 'Tle', 'Système optique et formation d’images : la lunette astronomique', 'Quelle est la vergence d’une lentille de focale f′ = 0,50 m ?', 'mcq', '["0,50 δ","2,0 δ","5,0 δ","50 δ"]'::jsonb, 1, 'V = 1/f′ = 1/0,50 = 2,0 dioptries : la vergence s’exprime en m⁻¹.', 1),
    ('438308a5-e0d1-5a1a-a715-d42b5b5a00be'::uuid, 'physique-chimie', 'Tle', 'Système optique et formation d’images : la lunette astronomique', 'Un rayon incident passant par le foyer objet F d’une lentille convergente…', 'mcq', '["Ressort parallèle à l’axe","N’est pas dévié","Passe par le foyer image","Est réfléchi"]'::jsonb, 0, 'C’est l’une des trois constructions de base : passant par F, le rayon émerge parallèle à l’axe optique.', 2),
    ('9cbb7fda-69bc-5d80-a1f9-f5028e46beac'::uuid, 'physique-chimie', 'Tle', 'Système optique et formation d’images : la lunette astronomique', 'Pourquoi l’image finale d’une lunette afocale est-elle rejetée à l’infini ?', 'mcq', '["Pour agrandir le tube","Pour redresser l’image","Pour que l’œil observe sans accommoder","Pour augmenter la lumière collectée"]'::jsonb, 2, 'Une image à l’infini s’observe œil au repos : c’est la condition d’un confort d’observation sur plusieurs heures.', 3),
    ('fbe901e0-8e20-514a-a3ec-bbea00889bc9'::uuid, 'physique-chimie', 'Tle', 'Système optique et formation d’images : la lunette astronomique', 'Une lunette a un objectif de focale 900 mm et un oculaire de 10 mm. Son grossissement vaut…', 'mcq', '["9","0,011","910","90"]'::jsonb, 3, 'G = f′₁ / f′₂ = 900 / 10 = 90. On change de grossissement en changeant d’oculaire.', 4),
    ('ec66ff24-e832-51af-aae5-bf862edfd817'::uuid, 'physique-chimie', 'Tle', 'Modèle corpusculaire de la lumière : le photon', 'À combien de joules correspond un électronvolt ?', 'mcq', '["6,63 × 10⁻³⁴ J","1,60 × 10⁻¹⁹ J","3,00 × 10⁸ J","9,11 × 10⁻³¹ J"]'::jsonb, 1, '1 eV = 1,60 × 10⁻¹⁹ J : c’est l’unité commode pour l’énergie d’un photon.', 1),
    ('6ba6229e-9f27-5fff-a863-b82c2b2d0ee0'::uuid, 'physique-chimie', 'Tle', 'Modèle corpusculaire de la lumière : le photon', 'Lequel de ces photons transporte le plus d’énergie ?', 'mcq', '["Un photon bleu à 450 nm","Un photon rouge à 700 nm","Un photon infrarouge à 1000 nm","Ils ont tous la même énergie"]'::jsonb, 0, 'E = hc/λ : plus la longueur d’onde est courte, plus le photon est énergétique (environ 2,8 eV pour le bleu contre 1,8 eV pour le rouge).', 2),
    ('d5b46c3e-8541-556e-b810-463e19d9767c'::uuid, 'physique-chimie', 'Tle', 'Modèle corpusculaire de la lumière : le photon', 'Quelle est la condition pour qu’un photon arrache un électron à un métal ?', 'mcq', '["Que la lumière soit très intense","Que l’éclairement dure longtemps","Que hν soit supérieur au travail d’extraction W₀","Que le métal soit chauffé"]'::jsonb, 2, 'Un électron reçoit un photon entier ou rien : il faut hν > W₀, quelle que soit l’intensité.', 3),
    ('0df446ac-bf69-552b-9d47-872edec195c4'::uuid, 'physique-chimie', 'Tle', 'Modèle corpusculaire de la lumière : le photon', 'Que montre l’expérience des fentes d’Young photon par photon ?', 'mcq', '["Que la lumière n’est qu’une onde","Que les photons n’existent pas","Que les franges apparaissent dès le premier photon","Que chaque photon arrive en un point, mais que leur accumulation dessine des franges"]'::jsonb, 3, 'Impacts ponctuels (corpuscule), figure de franges à l’accumulation (onde) : c’est la dualité onde-corpuscule.', 4),
    ('20d86fce-226c-578a-ba9f-25549a60273e'::uuid, 'physique-chimie', 'Tle', 'Dynamique d’un circuit électrique et capteurs capacitifs', 'Quelle relation lie l’intensité traversant un condensateur à la tension à ses bornes ?', 'mcq', '["i = C × u","i = C × du/dt","i = u / C","i = ½ C u²"]'::jsonb, 1, 'i = C × du/dt : l’intensité est le débit de charge, nulle quand la tension ne varie plus.', 1),
    ('fd2fee95-8f75-562f-a219-8d8317116d6e'::uuid, 'physique-chimie', 'Tle', 'Dynamique d’un circuit électrique et capteurs capacitifs', 'Lors de la décharge d’un condensateur, quel pourcentage de la tension initiale reste-t-il à t = τ ?', 'mcq', '["37 %","63 %","50 %","5 %"]'::jsonb, 0, 'u(t) = E × e^(−t/τ) : à t = τ, il reste e⁻¹ ≈ 37 % de la tension initiale.', 2),
    ('6f29ea0f-c50f-5872-94d6-6faee1575f6d'::uuid, 'physique-chimie', 'Tle', 'Dynamique d’un circuit électrique et capteurs capacitifs', 'Où la tangente à l’origine de la courbe de charge coupe-t-elle l’asymptote u = E ?', 'mcq', '["À t = 5τ","À t = 0","À t = τ","À t = τ/2"]'::jsonb, 2, 'La tangente à l’origine coupe l’asymptote à t = τ : c’est une seconde méthode de lecture de la constante de temps.', 3),
    ('4a37fb2f-818e-5cf2-96c5-d03d494351a9'::uuid, 'physique-chimie', 'Tle', 'Dynamique d’un circuit électrique et capteurs capacitifs', 'Sur quoi repose un capteur capacitif de niveau de liquide ?', 'mcq', '["Le liquide chauffe les armatures","Le liquide ferme un circuit","Le liquide réfléchit la lumière","Le liquide remplace l’air entre les armatures, ce qui change C"]'::jsonb, 3, 'Changer l’isolant entre les armatures change la capacité, donc τ : une durée mesurable qui renseigne sur le niveau.', 4),
    ('d879b6d7-f440-5faa-9c0a-61b71bdd1e91'::uuid, 'svt', 'Tle', 'La conservation des génomes : stabilité génétique et évolution clonale', 'Quelle enzyme assemble le nouveau brin d’ADN lors de la réplication ?', 'mcq', '["L’ARN polymérase","La ligase seule","L’ADN polymérase","L’hélicase"]'::jsonb, 2, 'L’ADN polymérase place en face de chaque nucléotide du brin matrice son complémentaire : A face à T, G face à C.', 1),
    ('c6343489-62a5-51ef-a200-d85bf0bca408'::uuid, 'svt', 'Tle', 'La conservation des génomes : stabilité génétique et évolution clonale', 'Un brin matrice porte la séquence ATGC. Quelle séquence porte le brin neuf formé en face ?', 'mcq', '["TACG","ATGC","UACG","GCAT"]'::jsonb, 0, 'La complémentarité impose A-T et G-C : face à ATGC, la polymérase place TACG (l’uracile n’existe que dans l’ARN).', 2),
    ('b694ffba-89a0-53e6-8568-708666cd7185'::uuid, 'svt', 'Tle', 'La conservation des génomes : stabilité génétique et évolution clonale', 'Quel est l’ordre de grandeur du taux d’erreur de l’ADN polymérase seule, AVANT relecture ?', 'mcq', '["1 sur 10","1 sur 10¹²","1 sur 10⁹","1 sur 10⁵"]'::jsonb, 3, 'Seule, la polymérase se trompe environ une fois sur 10⁵ ; relecture et réparation ramènent ce taux vers 1 sur 10⁹.', 3),
    ('e167829e-7e71-5d0f-8ad9-64a8029ad52a'::uuid, 'svt', 'Tle', 'La conservation des génomes : stabilité génétique et évolution clonale', 'Par quel mécanisme le puceron se reproduit-il sans fécondation ?', 'mcq', '["La scissiparité","La parthénogenèse","Le bouturage","Le marcottage"]'::jsonb, 1, 'La parthénogenèse produit un descendant à partir d’un ovule non fécondé ; la scissiparité est le mode des bactéries.', 4),
    ('53abef55-3067-529c-929d-67a489c01137'::uuid, 'svt', 'Tle', 'Le brassage des génomes à chaque génération : la reproduction sexuée des eucaryotes', 'Que se sépare-t-il lors de la division II de la méiose ?', 'mcq', '["Les chromosomes homologues","Les chromatides sœurs","Les deux lots de gamètes","Les brins d’ADN"]'::jsonb, 1, 'La division II est équationnelle, comme une mitose : ce sont les chromatides sœurs qui se séparent ; les homologues se sont séparés en division I.', 1),
    ('da32beba-f193-5656-9d35-3fba9bf36d15'::uuid, 'svt', 'Tle', 'Le brassage des génomes à chaque génération : la reproduction sexuée des eucaryotes', 'Pourquoi la division I de méiose est-elle dite réductionnelle ?', 'mcq', '["Elle réduit la taille des chromosomes","Elle supprime les crossing-over","Elle réduit le nombre de cellules","Elle fait passer la cellule de 2n à n chromosomes"]'::jsonb, 3, 'En séparant les homologues, la division I fait passer de 2n à n : chez l’humain, de 46 à 23 chromosomes.', 2),
    ('5f0de973-4b12-5445-9f7d-62c889cd1017'::uuid, 'svt', 'Tle', 'Le brassage des génomes à chaque génération : la reproduction sexuée des eucaryotes', 'Dans un croisement-test, des recombinés très rares indiquent que les deux gènes sont…', 'mcq', '["Proches sur le même chromosome","Situés sur des chromosomes différents","Très éloignés sur le même chromosome","Récessifs tous les deux"]'::jsonb, 0, 'Plus deux gènes liés sont proches, plus un crossing-over entre eux est rare, donc moins il y a de recombinés.', 3),
    ('c0c16dd4-555c-5bdd-bcec-cc1569a424ef'::uuid, 'svt', 'Tle', 'Le brassage des génomes à chaque génération : la reproduction sexuée des eucaryotes', 'Que deviennent les copies d’un gène dupliqué au fil des générations ?', 'mcq', '["Elles restent identiques pour toujours","Elles fusionnent en un seul gène","Elles mutent indépendamment et forment une famille multigénique","Elles sont éliminées à la méiose suivante"]'::jsonb, 2, 'Chaque copie accumule ses propres mutations : c’est ainsi que s’est formée la famille des gènes des globines.', 4),
    ('e54b7a78-856e-50e8-84f2-263edd160eeb'::uuid, 'svt', 'Tle', 'Mécanismes de diversification des êtres vivants', 'Quel exemple illustre un transfert horizontal de gènes chez les bactéries ?', 'mcq', '["La pêche aux termites","La formation d’un lichen","La diffusion de la résistance aux antibiotiques","Le chant des oiseaux"]'::jsonb, 2, 'Par conjugaison, transformation ou transduction, un gène de résistance passe d’une bactérie à une autre sans reproduction.', 1),
    ('83ec5d6d-afd6-5cd5-bfcd-8d8bc1621420'::uuid, 'svt', 'Tle', 'Mécanismes de diversification des êtres vivants', 'Pourquoi un mulet est-il en général stérile ?', 'mcq', '["Il est né d’une hybridation entre deux espèces","Il est polyploïde","Il est issu d’un transfert viral","Il n’a pas de microbiote"]'::jsonb, 0, 'L’hybride du cheval et de l’âne a des chromosomes mal appariés : sa méiose échoue. Seul un doublement du stock chromosomique peut la rétablir.', 2),
    ('83023770-8784-5041-bf0d-5681149be187'::uuid, 'svt', 'Tle', 'Mécanismes de diversification des êtres vivants', 'Quelle proportion des plantes dépendent des mycorhizes ?', 'mcq', '["Moins de 5 %","Environ 20 %","Aucune, c’est rare","Plus de 80 %"]'::jsonb, 3, 'Plus de 80 % des plantes s’associent à un champignon au niveau des racines, ce qui décuple leur surface d’absorption.', 3),
    ('c11b1c63-1919-5c54-8848-3738d1435cf7'::uuid, 'svt', 'Tle', 'Mécanismes de diversification des êtres vivants', 'Comment une transmission culturelle peut-elle influencer l’évolution génétique ?', 'mcq', '["Elle modifie directement l’ADN","Elle modifie la pression de sélection qui s’exerce ensuite sur les gènes","Elle provoque des mutations","Elle n’a aucun effet possible"]'::jsonb, 1, 'Un comportement appris change le milieu ou les ressources exploitées, donc les allèles avantagés par la sélection.', 4),
    ('10f7b872-140b-5300-bb4b-e5fa3039a9c3'::uuid, 'svt', 'Tle', 'De la diversification des êtres vivants à l’évolution de la biodiversité', 'Une population respecte Hardy-Weinberg avec p = 0,7. Quelle est la fréquence attendue des homozygotes aa ?', 'mcq', '["0,49","0,09","0,42","0,3"]'::jsonb, 1, 'q = 1 − p = 0,3, et la fréquence des aa vaut q² = 0,09 ; 0,49 correspond à AA et 0,42 aux hétérozygotes (2pq).', 1),
    ('e30c3b6b-2eaa-51cf-a6a1-d022bc0c86b5'::uuid, 'svt', 'Tle', 'De la diversification des êtres vivants à l’évolution de la biodiversité', 'Laquelle de ces conditions N’EST PAS une hypothèse du modèle de Hardy-Weinberg ?', 'mcq', '["Une population de grand effectif","L’absence de migration","Des croisements au hasard","Une sélection naturelle forte"]'::jsonb, 3, 'Le modèle suppose au contraire l’absence de sélection, de mutation et de migration, dans une grande population panmictique.', 2),
    ('2345e8e6-af67-5b3a-a7f0-374aa458af22'::uuid, 'svt', 'Tle', 'De la diversification des êtres vivants à l’évolution de la biodiversité', 'Dans quel cas la dérive génétique a-t-elle le plus d’effet ?', 'mcq', '["Dans une population de petit effectif","Dans une population très nombreuse","Quand la sélection est forte","Quand l’allèle est avantageux"]'::jsonb, 0, 'La dérive vient du hasard de l’échantillonnage des gamètes : plus la population est petite, plus ce hasard pèse.', 3),
    ('0f3575a9-ded0-5c3c-b8f7-74f386deebcd'::uuid, 'svt', 'Tle', 'De la diversification des êtres vivants à l’évolution de la biodiversité', 'Pourquoi le critère d’interfécondité ne s’applique-t-il pas aux fossiles ?', 'mcq', '["Ils sont trop anciens pour être classés","Ils se reproduisaient tous de façon asexuée","On ne peut pas les croiser","Leur ADN est toujours intact"]'::jsonb, 2, 'L’interfécondité se teste par croisement ; pour les fossiles, on recourt aux critères morphologique et phylogénétique.', 4),
    ('d657c3aa-2c8f-5a67-a0b4-fe290a8b558f'::uuid, 'svt', 'Tle', 'La chronologie relative : décrypter le temps des roches par l’observation', 'Un filon de basalte traverse trois couches sédimentaires. Que conclut-on ?', 'mcq', '["Le filon est plus ancien que les couches","Le filon et les couches ont le même âge","Le filon est plus récent que les couches qu’il recoupe","On ne peut rien conclure"]'::jsonb, 2, 'Principe de recoupement : ce qui recoupe est postérieur à ce qui est recoupé.', 1),
    ('fdf03f4c-c13b-5232-bd99-209cb77bfd41'::uuid, 'svt', 'Tle', 'La chronologie relative : décrypter le temps des roches par l’observation', 'Une couche change de faciès, de sable à argile, sur son extension. Que dit le principe de continuité ?', 'mcq', '["Elle a le même âge sur toute son extension","Elle a deux âges différents","La partie sableuse est plus ancienne","Elle a été renversée"]'::jsonb, 0, 'Une même couche garde le même âge partout, même si les conditions de dépôt, donc son faciès, varient latéralement.', 2),
    ('23c120f1-b1c7-5f09-9d22-4ef32862eba4'::uuid, 'svt', 'Tle', 'La chronologie relative : décrypter le temps des roches par l’observation', 'Pourquoi le cœlacanthe est-il un mauvais fossile stratigraphique ?', 'mcq', '["Il est trop petit","Il est trop abondant","Il vivait partout sur Terre","Il a existé pendant une très longue durée"]'::jsonb, 3, 'Une espèce qui a vécu des centaines de millions d’années ne permet pas de découper finement le temps.', 3),
    ('67437255-7620-575d-a8b5-bdc2ff123aff'::uuid, 'svt', 'Tle', 'La chronologie relative : décrypter le temps des roches par l’observation', 'Qu’a apporté la radiochronologie à l’échelle stratigraphique ?', 'mcq', '["Elle l’a entièrement remplacée","Elle l’a calibrée en millions d’années","Elle a inversé l’ordre des ères","Elle a supprimé les étages"]'::jsonb, 1, 'L’échelle ères-périodes-étages existait déjà grâce à la chronologie relative ; la radiochronologie y a ajouté des dates.', 4),
    ('82791f5e-f6ea-5efc-97c5-77535109d4fc'::uuid, 'svt', 'Tle', 'La chronologie absolue : décrypter le temps des roches par des mesures', 'Au bout de deux demi-vies, quelle fraction des atomes pères reste-t-il ?', 'mcq', '["La moitié","Le quart","Le tiers","Aucun"]'::jsonb, 1, 'Chaque demi-vie divise le nombre de pères par deux : 1/2 puis 1/4.', 1),
    ('3f65cdb8-50f2-5e47-bab4-1367498605eb'::uuid, 'svt', 'Tle', 'La chronologie absolue : décrypter le temps des roches par des mesures', 'Quelle méthode permet de s’affranchir de la quantité initiale d’isotope fils inconnue ?', 'mcq', '["Le principe de superposition","Le granoclassement","La demi-vie seule","La droite isochrone"]'::jsonb, 3, 'La droite isochrone, construite sur plusieurs minéraux d’une même roche, donne l’âge par sa pente sans connaître la quantité initiale de fils.', 2),
    ('79c20b98-6d99-5313-a70e-f9e56e74a2f3'::uuid, 'svt', 'Tle', 'La chronologie absolue : décrypter le temps des roches par des mesures', 'Quel couple choisir pour dater une coulée volcanique de quelques millions d’années ?', 'mcq', '["Potassium 40 / argon 40","Carbone 14 / azote 14","Aucun, c’est impossible","Le carbone 14 corrigé"]'::jsonb, 0, 'Le couple K/Ar, de demi-vie 1,3 milliard d’années, convient aux roches volcaniques ; le carbone 14 ne dépasse pas 50 000 ans.', 3),
    ('320b2c73-8de7-5fc9-8c97-311acfd6caa7'::uuid, 'svt', 'Tle', 'La chronologie absolue : décrypter le temps des roches par des mesures', 'Que date le carbone 14 dans un reste organique ?', 'mcq', '["La naissance de l’organisme","La formation de la roche qui l’entoure","La mort de l’organisme","La fossilisation complète"]'::jsonb, 2, 'À sa mort, l’organisme cesse d’échanger du carbone : son stock de carbone 14 décroît sans être renouvelé.', 4),
    ('5a8b6b07-72dc-5d9f-80af-4564dd8fb9de'::uuid, 'svt', 'Tle', 'Formation et disparition des océans : témoins d’un passé mouvementé de la Terre', 'Dans une ophiolite, quelle roche trouve-t-on tout en bas de la séquence ?', 'mcq', '["Les radiolarites","Les basaltes en coussins","Les péridotites","Les gabbros"]'::jsonb, 2, 'De bas en haut : péridotites (le manteau), gabbros, basaltes en coussins, radiolarites (sédiments profonds).', 1),
    ('993e50e5-0864-5162-aff3-765a4f68014a'::uuid, 'svt', 'Tle', 'Formation et disparition des océans : témoins d’un passé mouvementé de la Terre', 'Quel exemple actuel illustre la phase de rifting ?', 'mcq', '["Le rift est-africain","La chaîne des Alpes","La fosse des Mariannes","L’Himalaya"]'::jsonb, 0, 'Le rift est-africain et le fossé rhénan montrent une lithosphère continentale qui s’amincit et se casse en failles normales.', 2),
    ('1eec6fcd-be39-5744-b1eb-a47930e6a2ec'::uuid, 'svt', 'Tle', 'Formation et disparition des océans : témoins d’un passé mouvementé de la Terre', 'Quels minéraux caractérisent une éclogite ?', 'mcq', '["Le quartz et la calcite","L’olivine seule","Le feldspath et le mica","Le grenat et la jadéite"]'::jsonb, 3, 'L’éclogite, à grenat et jadéite, se forme à plus grande profondeur que le faciès à glaucophane, lors de la subduction.', 3),
    ('20848c96-8b37-5f54-936f-5b5ef50700af'::uuid, 'svt', 'Tle', 'Formation et disparition des océans : témoins d’un passé mouvementé de la Terre', 'Jusqu’à quelle profondeur peut descendre la racine crustale d’une chaîne de collision ?', 'mcq', '["Environ 5 km","Environ 70 km","Environ 700 km","Elle n’a pas de racine"]'::jsonb, 1, 'L’épaississement crustal enfonce la croûte comme un iceberg, jusqu’à environ 70 km sous la chaîne.', 4),
    ('db82adc7-04d4-51a9-9e24-01be0164e205'::uuid, 'svt', 'Tle', 'Organisation fonctionnelle des plantes à fleurs et adaptation à leurs milieux de vie', 'Quel tissu permet à une plante de croître toute sa vie ?', 'mcq', '["Le xylème","Les méristèmes","Le phloème","La cuticule"]'::jsonb, 1, 'Les méristèmes produisent sans cesse de nouvelles cellules : la croissance d’une plante est modulaire et continue.', 1),
    ('2b01daa7-ee52-52ec-9c5d-07ba619bd3b1'::uuid, 'svt', 'Tle', 'Organisation fonctionnelle des plantes à fleurs et adaptation à leurs milieux de vie', 'Quelle adaptation limite la perte d’eau chez une plante de milieu sec ?', 'mcq', '["Des feuilles larges et minces","Des stomates nombreux sur la face supérieure","Des racines très courtes","Une cuticule cireuse épaisse"]'::jsonb, 3, 'Cuticule cireuse, feuilles en épines et stomates enfoncés réduisent la transpiration en milieu sec.', 2),
    ('54abc382-3188-564b-bd90-bec23d180407'::uuid, 'svt', 'Tle', 'Organisation fonctionnelle des plantes à fleurs et adaptation à leurs milieux de vie', 'Qu’est-ce qui maintient la colonne d’eau continue dans le xylème ?', 'mcq', '["La cohésion des molécules d’eau","Une pompe racinaire","La pression du phloème","La photosynthèse"]'::jsonb, 0, 'L’évaporation au sommet tire l’eau et la cohésion entre molécules empêche la colonne de se rompre.', 3),
    ('4c05b212-68bc-5024-8421-1b014c7289da'::uuid, 'svt', 'Tle', 'Organisation fonctionnelle des plantes à fleurs et adaptation à leurs milieux de vie', 'Une plante attaquée par un herbivore peut émettre des composés volatils. Que peuvent-ils faire ?', 'mcq', '["Faire fuir la plante","Accélérer la photosynthèse","Alerter les plantes voisines et attirer des prédateurs de l’herbivore","Fermer définitivement les stomates"]'::jsonb, 2, 'Même fixée, la plante communique : ses signaux volatils préparent ses voisines et recrutent parfois des alliés.', 4),
    ('b6904b64-9cbc-54da-ae6c-0ebc79cd8cad'::uuid, 'svt', 'Tle', 'La plante, productrice de la matière organique grâce à la photosynthèse', 'Quelles couleurs de la lumière les chlorophylles absorbent-elles surtout ?', 'mcq', '["Le vert et le jaune","Seulement l’infrarouge","Le bleu et le rouge","Seulement le vert"]'::jsonb, 2, 'Les chlorophylles absorbent le bleu et le rouge ; le vert, réfléchi, donne leur couleur aux feuilles.', 1),
    ('0f4aacd5-0477-526d-9cf6-03e38a8822f1'::uuid, 'svt', 'Tle', 'La plante, productrice de la matière organique grâce à la photosynthèse', 'Que se passe-t-il pour le cycle de Calvin quand on plonge une plante dans le noir ?', 'mcq', '["Il s’arrête en quelques secondes, faute d’ATP et de RH₂","Il continue des heures sans changement","Il accélère","Il produit du dioxygène"]'::jsonb, 0, 'Les deux phases sont couplées : sans lumière, la phase photochimique ne fournit plus l’ATP et les RH₂ dont le cycle de Calvin a besoin.', 2),
    ('5505169d-ef5c-5f17-b718-8abf294eb5fa'::uuid, 'svt', 'Tle', 'La plante, productrice de la matière organique grâce à la photosynthèse', 'Sous quelle forme les sucres sont-ils exportés des feuilles vers les organes non chlorophylliens ?', 'mcq', '["En amidon, par le xylème","En cellulose","En glucose, par les stomates","En saccharose, par le phloème"]'::jsonb, 3, 'Le saccharose circule dans la sève élaborée du phloème ; l’amidon est une forme de réserve, la cellulose une forme de structure.', 3),
    ('7fc361f6-16c2-545a-b567-911cc43dd981'::uuid, 'svt', 'Tle', 'La plante, productrice de la matière organique grâce à la photosynthèse', 'Quelle molécule forme la paroi des cellules végétales et donc la charpente de la plante ?', 'mcq', '["L’amidon","La cellulose","La chlorophylle","La RuBisCO"]'::jsonb, 1, 'Le glucose produit par la photosynthèse est assemblé en cellulose, polymère de structure de la paroi.', 4),
    ('9d4007f6-65ad-59a1-ad57-bc3c20b71a5b'::uuid, 'svt', 'Tle', 'Reproduction de la plante entre vie fixée et mobilité', 'Que devient l’ovaire de la fleur après la fécondation ?', 'mcq', '["La graine","Le fruit","L’embryon","Le pollen"]'::jsonb, 1, 'L’ovaire devient le fruit, tandis que chaque ovule qu’il contient devient une graine.', 1),
    ('921e6acb-8f31-52ba-abc8-a5da717aeaad'::uuid, 'svt', 'Tle', 'Reproduction de la plante entre vie fixée et mobilité', 'Comment se disperse l’akène plumeux du pissenlit ?', 'mcq', '["Par zoochorie","Par hydrochorie","Par épizoochorie","Par anémochorie"]'::jsonb, 3, 'Le fruit plumeux est emporté par le vent : c’est l’anémochorie, comme pour la samare ailée de l’érable.', 2),
    ('40bd2e80-72f5-54f1-8b35-acaa0d6a4273'::uuid, 'svt', 'Tle', 'Reproduction de la plante entre vie fixée et mobilité', 'Quel dispositif empêche l’autofécondation en faisant rejeter par le stigmate le pollen de la même plante ?', 'mcq', '["L’incompatibilité biochimique","La dioécie","La maturation décalée","La multiplication végétative"]'::jsonb, 0, 'L’incompatibilité biochimique fait que le stigmate reconnaît et rejette le pollen de la plante elle-même.', 3),
    ('322cefcc-3b67-5fbe-b088-af3d8a5e52c5'::uuid, 'svt', 'Tle', 'Reproduction de la plante entre vie fixée et mobilité', 'Quel organe permet au fraisier de se multiplier de façon végétative ?', 'mcq', '["Le tubercule","Le rhizome","Le stolon","Le drageon"]'::jsonb, 2, 'Le fraisier émet des stolons qui s’enracinent plus loin ; le tubercule est celui de la pomme de terre, le rhizome celui du bambou.', 4),
    ('fa7956eb-2bcc-539a-9fc0-08954fce68bf'::uuid, 'svt', 'Tle', 'La domestication des plantes', 'Pourquoi la germination simultanée a-t-elle été sélectionnée chez les plantes cultivées ?', 'mcq', '["Elle protège des parasites","Elle augmente la taille des grains","Elle permet une récolte unique","Elle supprime l’amertume"]'::jsonb, 2, 'Des graines qui germent en même temps donnent des plantes mûres en même temps, récoltables en une seule fois.', 1),
    ('8f50f41f-19e1-5c75-99f9-a13c7fc22214'::uuid, 'svt', 'Tle', 'La domestication des plantes', 'Pourquoi un agriculteur qui cultive un hybride F1 rachète-t-il ses semences chaque année ?', 'mcq', '["La F2 perd l’homogénéité et la vigueur de la F1","La F1 est stérile","La loi interdit de ressemer","Les graines F1 ne germent pas"]'::jsonb, 0, 'Les descendants d’un hybride F1 ne sont plus homogènes : il faut recroiser les lignées pures, donc racheter.', 2),
    ('bbab4b3c-cf45-546b-a4f1-6d1416f55882'::uuid, 'svt', 'Tle', 'La domestication des plantes', 'Quelle technique consiste à provoquer des mutations au hasard puis à trier les plantes obtenues ?', 'mcq', '["La transgenèse","La sélection massale","L’hybridation F1","La mutagenèse"]'::jsonb, 3, 'La mutagenèse est aveugle : elle crée des mutations au hasard, que le sélectionneur trie ensuite.', 3),
    ('9103cdf5-30db-53d9-8b26-059f664345fb'::uuid, 'svt', 'Tle', 'La domestication des plantes', 'Quel événement historique illustre la vulnérabilité d’une culture génétiquement uniforme ?', 'mcq', '["La domestication du maïs","Le mildiou de la pomme de terre en Irlande en 1845","La création du Svalbard","L’invention de la sélection massale"]'::jsonb, 1, 'Des pommes de terre presque toutes identiques ont été ravagées par un même parasite, provoquant une grande famine.', 4),
    ('f07e13dc-b860-5632-81e6-e1037b5c277e'::uuid, 'svt', 'Tle', 'Comprendre les variations climatiques', 'Quelle puissance solaire moyenne la Terre reçoit-elle par mètre carré ?', 'mcq', '["Environ 34 W/m²","Environ 340 W/m²","Environ 3 400 W/m²","Environ 34 000 W/m²"]'::jsonb, 1, 'La Terre reçoit en moyenne environ 340 W/m², dont environ 30 % est renvoyé directement par l’albédo.', 1),
    ('f5a49e17-1f5a-5853-afab-e1f1a2a3026d'::uuid, 'svt', 'Tle', 'Comprendre les variations climatiques', 'Entre quelles valeurs varie l’obliquité de l’axe terrestre, et sur quelle période ?', 'mcq', '["Entre 0° et 90°, en 100 000 ans","Entre 10° et 15°, en 21 000 ans","Elle ne varie pas","Entre 22° et 24,5°, en environ 41 000 ans"]'::jsonb, 3, 'L’obliquité oscille entre 22° et 24,5° avec une période d’environ 41 000 ans, modifiant le contraste des saisons.', 2),
    ('0597eb98-f464-593c-a181-b4da1194927e'::uuid, 'svt', 'Tle', 'Comprendre les variations climatiques', 'Pourquoi la vapeur d’eau constitue-t-elle une rétroaction positive ?', 'mcq', '["Plus il fait chaud, plus l’air en contient, et elle renforce l’effet de serre","Elle augmente l’albédo en permanence","Elle consomme du CO₂","Elle refroidit toujours la surface"]'::jsonb, 0, 'Un air plus chaud contient plus de vapeur d’eau, gaz à effet de serre, ce qui amplifie le réchauffement initial.', 3),
    ('59b6bfab-3ae5-5dbb-b0aa-5ca1f4195c0f'::uuid, 'svt', 'Tle', 'Comprendre les variations climatiques', 'Quel forçage a contribué au refroidissement du Cénozoïque ?', 'mcq', '["Un volcanisme intense","La combustion des énergies fossiles","La surrection de l’Himalaya et l’altération de ses silicates","L’augmentation de la constante solaire"]'::jsonb, 2, 'L’altération des silicates d’une chaîne jeune consomme du CO₂ atmosphérique, ce qui affaiblit l’effet de serre.', 4),
    ('ec11d398-192f-5c26-8aae-91fcff52ac6d'::uuid, 'svt', 'Tle', 'Les méthodes d’observation du climat passé', 'Pourquoi le δ18O des foraminifères augmente-t-il en période glaciaire ?', 'mcq', '["Les foraminifères grandissent plus","L’océan se réchauffe","Les glaces piègent l’isotope léger et enrichissent l’océan en isotope lourd","La salinité baisse"]'::jsonb, 2, 'L’isotope léger part dans les calottes ; l’océan s’enrichit en ¹⁸O, et l’eau plus froide renforce encore cette signature.', 1),
    ('53201f7c-0f94-53e5-91ad-5d23e1975103'::uuid, 'svt', 'Tle', 'Les méthodes d’observation du climat passé', 'Quelle archive renseigne sur l’extension passée des glaciers ?', 'mcq', '["Les moraines","Les cernes des arbres","Les bulles d’air","Les tests de foraminifères"]'::jsonb, 0, 'Les moraines marquent la position des anciens fronts glaciaires, avec une résolution temporelle grossière.', 2),
    ('db62f98f-7eb3-52c6-82cf-f3fb3e8fc1b1'::uuid, 'svt', 'Tle', 'Les méthodes d’observation du climat passé', 'Que montrent les carottes de glace sur 800 000 ans ?', 'mcq', '["Que le CO₂ est resté constant","Que la température n’a jamais varié","Que le méthane n’existe pas","Que le CO₂ et la température varient de concert"]'::jsonb, 3, 'C’est la seule archive donnant les deux grandeurs au même instant : elle montre leur variation conjointe.', 3),
    ('725d498e-9a94-5c3c-9fdc-a9dc65c978f9'::uuid, 'svt', 'Tle', 'Les méthodes d’observation du climat passé', 'Quelle archive permet de remonter des dizaines de millions d’années ?', 'mcq', '["Les carottes de glace","Les foraminifères marins","Les cernes des arbres","Les registres de vendanges"]'::jsonb, 1, 'Les sédiments marins et leurs foraminifères couvrent des dizaines de millions d’années, avec une résolution millénaire.', 4),
    ('f05e2014-42dd-5592-97cc-0ac420053c99'::uuid, 'svt', 'Tle', 'Comprendre les conséquences du réchauffement climatique et les possibilités d’actions', 'De combien le niveau marin est-il monté depuis 1900 ?', 'mcq', '["D’environ 2 cm","D’environ 20 cm","D’environ 2 m","Il a baissé"]'::jsonb, 1, 'Le niveau marin a monté d’environ 20 cm depuis 1900, et cette hausse s’accélère.', 1),
    ('b0032b17-6694-5c27-b98f-3a98383f4346'::uuid, 'svt', 'Tle', 'Comprendre les conséquences du réchauffement climatique et les possibilités d’actions', 'Quelle cause de montée des eaux ne fait intervenir aucune fonte de glace ?', 'mcq', '["La fonte du Groenland","La fonte des glaciers de montagne","La fonte de l’Antarctique","La dilatation thermique de l’eau de mer"]'::jsonb, 3, 'En se réchauffant, l’eau de mer occupe plus de volume : c’est la dilatation thermique.', 2),
    ('c50d6674-f1b9-5be9-aaeb-d660c25ae3a5'::uuid, 'svt', 'Tle', 'Comprendre les conséquences du réchauffement climatique et les possibilités d’actions', 'Quelle part de nos émissions de CO₂ les puits de carbone absorbent-ils aujourd’hui ?', 'mcq', '["Environ la moitié","Presque rien","Environ un dixième","La totalité"]'::jsonb, 0, 'Forêts, sols et océan absorbent environ la moitié de nos émissions, mais un puits saturé ne stocke plus.', 3),
    ('663dd9d4-2910-56af-914e-f4e9d6342608'::uuid, 'svt', 'Tle', 'Comprendre les conséquences du réchauffement climatique et les possibilités d’actions', 'Végétaliser une ville pour limiter les îlots de chaleur relève de…', 'mcq', '["L’atténuation","La compensation","L’adaptation","La géo-ingénierie"]'::jsonb, 2, 'Cette mesure limite les dommages d’un réchauffement déjà engagé : c’est de l’adaptation, pas une baisse des émissions.', 4),
    ('a99136e1-6636-535e-8472-5301206e23bd'::uuid, 'svt', 'Tle', 'Les réflexes', 'Quelle est la fonction réelle du réflexe myotatique au quotidien ?', 'mcq', '["Retirer la main d’une flamme","Déclencher la marche","Maintenir la posture","Réguler la glycémie"]'::jsonb, 2, 'Chaque étirement d’un muscle par le poids du corps provoque sa contraction ajustée : le réflexe maintient la posture.', 1),
    ('067cce20-9829-5f46-a408-c86b1220810b'::uuid, 'svt', 'Tle', 'Les réflexes', 'Que dit la loi du « tout ou rien » d’un potentiel d’action ?', 'mcq', '["Son amplitude ne varie pas","Sa fréquence est fixe","Il ne se propage jamais","Il n’existe qu’à la synapse"]'::jsonb, 0, 'Un potentiel d’action a toujours la même amplitude ; c’est leur fréquence qui code l’intensité du stimulus.', 2),
    ('ee9dbf1f-4285-5a8c-ab14-0aadee307bbc'::uuid, 'svt', 'Tle', 'Les réflexes', 'Quelle fibre nerveuse conduit le message du fuseau neuromusculaire vers la moelle ?', 'mcq', '["Le motoneurone","Le nerf optique","La fibre musculaire","La fibre Ia"]'::jsonb, 3, 'La fibre sensitive Ia relie le fuseau à la moelle épinière, où elle fait synapse directement avec le motoneurone.', 3),
    ('8f2615b3-876a-59cb-bb9b-c99d5bac56d5'::uuid, 'svt', 'Tle', 'Les réflexes', 'Comment le message nerveux est-il codé au niveau d’une synapse ?', 'mcq', '["Par l’amplitude des potentiels d’action","Par la concentration de neurotransmetteur libéré","Par la nature du neurotransmetteur, qui change","Par la longueur de l’axone"]'::jsonb, 1, 'À la synapse, le message est codé par la quantité de neurotransmetteur libéré, qui dépend de la fréquence des potentiels d’action.', 4),
    ('c8ff9cdc-51d7-51df-8e99-9ec083ffdc41'::uuid, 'svt', 'Tle', 'Cerveau et mouvement volontaire', 'Quelle structure assure la coordination, l’équilibre et la précision des gestes ?', 'mcq', '["Les noyaux gris centraux","Le cervelet","Les aires prémotrices","Le bulbe rachidien"]'::jsonb, 1, 'Une atteinte du cervelet rend les gestes imprécis et la démarche instable.', 1),
    ('2dadec74-0eb0-522b-bf3d-f23a4d674075'::uuid, 'svt', 'Tle', 'Cerveau et mouvement volontaire', 'Après une section de la moelle épinière, que peut-il persister sous le niveau lésé ?', 'mcq', '["La commande volontaire","La sensibilité consciente","Rien du tout","Les réflexes médullaires"]'::jsonb, 3, 'La commande volontaire ne descend plus, mais les arcs réflexes médullaires situés sous la lésion peuvent encore fonctionner.', 2),
    ('9007dfc6-753f-54d0-b80c-218851adc4ad'::uuid, 'svt', 'Tle', 'Cerveau et mouvement volontaire', 'Pourquoi dit-on que les motoneurones sont la « voie finale commune » ?', 'mcq', '["Réflexes et mouvements volontaires passent tous par eux","Ils meurent les premiers","Ils sont situés dans le cortex","Ils ne reçoivent qu’une seule synapse"]'::jsonb, 0, 'Qu’il vienne d’un arc réflexe ou du cortex moteur, tout ordre de contraction passe par le motoneurone.', 3),
    ('918843b5-66cc-548e-ba7b-6293435cf615'::uuid, 'svt', 'Tle', 'Cerveau et mouvement volontaire', 'Quel rôle jouent les aires prémotrices ?', 'mcq', '["Elles contractent directement le muscle","Elles détectent l’étirement","Elles planifient le geste","Elles produisent la dopamine"]'::jsonb, 2, 'Les aires prémotrices organisent la séquence du geste ; leur atteinte gêne la planification d’un mouvement.', 4),
    ('dd690c74-99c9-5614-837a-8fd208c68f3c'::uuid, 'svt', 'Tle', 'Le cerveau : un organe fragile à préserver', 'Pourquoi un AVC est-il une urgence absolue ?', 'mcq', '["Parce qu’il est toujours mortel","Parce qu’il est contagieux","Plus la prise en charge est rapide, plus la zone cérébrale sauvée est grande","Parce que les neurones se multiplient"]'::jsonb, 2, 'Chaque minute sans oxygène détruit des neurones qui ne se renouvellent presque pas.', 1),
    ('db2abeed-b653-5da9-959c-25239fedcec8'::uuid, 'svt', 'Tle', 'Le cerveau : un organe fragile à préserver', 'Qu’est-ce que la réserve cognitive ?', 'mcq', '["Une capacité, entretenue par l’activité, qui retarde les symptômes des maladies neurodégénératives","Un stock de neurones de rechange","Un médicament","Une zone du cervelet"]'::jsonb, 0, 'Activité physique, intellectuelle et sociale construisent une réserve qui retarde l’apparition des symptômes.', 2),
    ('9a5b18c5-ee1a-51f5-9003-a41fd8c6d083'::uuid, 'svt', 'Tle', 'Le cerveau : un organe fragile à préserver', 'Sur quels récepteurs agit le THC du cannabis ?', 'mcq', '["Les récepteurs à l’insuline","Les récepteurs à l’acétylcholine du muscle","Les fuseaux neuromusculaires","Les récepteurs endocannabinoïdes"]'::jsonb, 3, 'Le THC se fixe sur les récepteurs du système endocannabinoïde, impliqués notamment dans la mémoire et l’attention.', 3),
    ('bd76f12f-d7f4-5ed4-937a-9901eef75fa6'::uuid, 'svt', 'Tle', 'Le cerveau : un organe fragile à préserver', 'Parmi ces structures, laquelle appartient au système de récompense ?', 'mcq', '["Le cervelet","Le noyau accumbens","La moelle épinière","Le cortex visuel"]'::jsonb, 1, 'L’aire tegmentale ventrale, le noyau accumbens et le cortex préfrontal forment le système de récompense, qui utilise la dopamine.', 4),
    ('2bfa87f5-3663-5535-b4de-f95ffafa3107'::uuid, 'svt', 'Tle', 'La cellule musculaire : une structure spécialisée permettant son propre raccourcissement', 'Quelles structures délimitent un sarcomère ?', 'mcq', '["Deux noyaux","Deux stries Z","Deux mitochondries","Deux tendons"]'::jsonb, 1, 'Le sarcomère va d’une strie Z à la suivante ; les filaments d’actine y sont ancrés.', 1),
    ('f1116974-5261-57b5-8c53-644ca7fde97b'::uuid, 'svt', 'Tle', 'La cellule musculaire : une structure spécialisée permettant son propre raccourcissement', 'Qu’est-ce que la rigidité cadavérique ?', 'mcq', '["Un excès de calcium dans le sang","Un raccourcissement des filaments d’actine","Une contraction réflexe","Des têtes de myosine restées accrochées à l’actine faute d’ATP"]'::jsonb, 3, 'Sans ATP, la tête de myosine ne peut plus se détacher de l’actine : le muscle reste figé.', 2),
    ('ce07c0fe-d4f1-5de9-a62b-b39b962de387'::uuid, 'svt', 'Tle', 'La cellule musculaire : une structure spécialisée permettant son propre raccourcissement', 'Pourquoi le relâchement musculaire consomme-t-il de l’énergie ?', 'mcq', '["Le calcium est repompé activement dans le réticulum sarcoplasmique","Il faut allonger les filaments","Il faut détruire la myosine","Il ne consomme aucune énergie"]'::jsonb, 0, 'Le retour du Ca²⁺ dans le réticulum se fait contre son gradient, grâce à l’hydrolyse d’ATP.', 3),
    ('c8a2d241-31d0-5a58-9914-cdde5089719e'::uuid, 'svt', 'Tle', 'La cellule musculaire : une structure spécialisée permettant son propre raccourcissement', 'Pourquoi les muscles de l’œil ont-ils des unités motrices de quelques fibres seulement ?', 'mcq', '["Pour la puissance","Pour économiser le calcium","Pour la finesse du contrôle","Parce qu’ils n’ont pas de motoneurone"]'::jsonb, 2, 'Peu de fibres par motoneurone permettent des ajustements très fins ; le mollet, avec plus d’un millier de fibres par unité, vise la puissance.', 4),
    ('d0deec93-c393-52d4-9f04-e2607c3666ea'::uuid, 'svt', 'Tle', 'Origine de l’énergie (ATP) nécessaire à la contraction de la cellule musculaire', 'Quelle réaction régénère l’ATP à partir de la phosphocréatine ?', 'mcq', '["ATP + créatine donne ADP + phosphocréatine","Glucose donne 2 lactate","ADP + phosphocréatine donne ATP + créatine","Pyruvate donne CO₂ + eau"]'::jsonb, 2, 'La phosphocréatine cède son phosphate à l’ADP : direct, sans oxygène ni déchet, mais épuisé en une dizaine de secondes.', 1),
    ('472acd73-0d79-5e81-b925-264d18ae31fd'::uuid, 'svt', 'Tle', 'Origine de l’énergie (ATP) nécessaire à la contraction de la cellule musculaire', 'Quelle étape de la respiration cellulaire produit l’essentiel de l’ATP en réduisant le dioxygène en eau ?', 'mcq', '["La chaîne respiratoire","La glycolyse","Le cycle de Krebs","La fermentation"]'::jsonb, 0, 'La chaîne respiratoire de la membrane interne mitochondriale produit l’essentiel de l’ATP.', 2),
    ('4e37d692-3d33-5149-982b-c30699eed3e9'::uuid, 'svt', 'Tle', 'Origine de l’énergie (ATP) nécessaire à la contraction de la cellule musculaire', 'Qu’augmente un entraînement en endurance ?', 'mcq', '["La section des fibres uniquement","La réserve de lactate","La proportion de fibres blanches","Le nombre de mitochondries et la densité capillaire"]'::jsonb, 3, 'L’endurance développe mitochondries, capillaires et VO₂ max ; la musculation augmente surtout la section des fibres.', 3),
    ('97c97581-c842-5f83-a697-45a6edb52671'::uuid, 'svt', 'Tle', 'Origine de l’énergie (ATP) nécessaire à la contraction de la cellule musculaire', 'Pourquoi les fibres de type I sont-elles appelées fibres rouges ?', 'mcq', '["Elles contiennent de l’hémoglobine libre","Elles sont riches en myoglobine et très vascularisées","Elles accumulent du lactate","Elles n’ont pas de mitochondries"]'::jsonb, 1, 'La myoglobine, qui fixe le dioxygène, et une forte vascularisation leur donnent leur couleur rouge.', 4),
    ('36d161fc-164f-585e-bb13-667615d867b6'::uuid, 'svt', 'Tle', 'Le contrôle des flux de glucose, source essentielle d’énergie des cellules musculaires', 'Dans quelles structures du pancréas se trouvent les cellules α et β ?', 'mcq', '["Les acini digestifs","Les îlots de Langerhans","Les néphrons","Les hépatocytes"]'::jsonb, 1, 'Les îlots de Langerhans détectent la glycémie et sécrètent insuline (cellules β) et glucagon (cellules α).', 1),
    ('76768d19-69a2-5aa4-9d86-32d8187dcec3'::uuid, 'svt', 'Tle', 'Le contrôle des flux de glucose, source essentielle d’énergie des cellules musculaires', 'Quel est l’effet du glucagon sur le foie ?', 'mcq', '["Il y fait stocker du glycogène","Il y fait entrer les GLUT4","Il y fait détruire l’insuline","Il y fait hydrolyser le glycogène et fabriquer du glucose"]'::jsonb, 3, 'Hyperglycémiant, le glucagon fait libérer du glucose par le foie à partir du glycogène et par néoglucogenèse.', 2),
    ('9e56d54d-fc9a-5ce2-a144-0080e010dbc1'::uuid, 'svt', 'Tle', 'Le contrôle des flux de glucose, source essentielle d’énergie des cellules musculaires', 'Pendant un effort, comment les GLUT4 gagnent-ils la membrane de la fibre musculaire ?', 'mcq', '["Grâce à la contraction elle-même, même sans insuline","Seulement sous l’effet de l’insuline","Grâce au glucagon","Ils n’y vont jamais"]'::jsonb, 0, 'La contraction fait migrer les GLUT4 indépendamment de l’insuline : c’est pourquoi l’activité physique améliore le contrôle glycémique.', 3),
    ('7bca837b-16ea-54bb-826e-912bcd997cd8'::uuid, 'svt', 'Tle', 'Le contrôle des flux de glucose, source essentielle d’énergie des cellules musculaires', 'Pourquoi l’hyperglycémie chronique du diabète est-elle grave ?', 'mcq', '["Elle provoque des crampes","Elle empêche la digestion","Elle abîme les petits vaisseaux de la rétine, des reins, des nerfs et du cœur","Elle fait disparaître le glycogène musculaire"]'::jsonb, 2, 'Les complications vasculaires font la gravité de la maladie, bien plus que le symptôme immédiat.', 4),
    ('292c5f7b-807c-5bb7-a12b-80f1b8d5c67c'::uuid, 'svt', 'Tle', 'L’adaptabilité de l’organisme face aux perturbations de l’environnement', 'Quel système nerveux porte la phase rapide de la réponse au stress ?', 'mcq', '["Le système parasympathique","Le cervelet","Le système nerveux sympathique","L’axe corticotrope"]'::jsonb, 2, 'Le sympathique déclenche en quelques secondes la libération d’adrénaline par la médullosurrénale.', 1),
    ('1bce29c6-be73-5e3f-9fec-7d3076468f0b'::uuid, 'svt', 'Tle', 'L’adaptabilité de l’organisme face aux perturbations de l’environnement', 'Quelle glande libère le cortisol ?', 'mcq', '["La corticosurrénale","La médullosurrénale","L’hypophyse","L’hypothalamus"]'::jsonb, 0, 'La corticosurrénale libère le cortisol sous l’effet de l’ACTH ; la médullosurrénale libère l’adrénaline.', 2),
    ('51ee9743-ed0d-5be6-8373-1f5b212467e6'::uuid, 'svt', 'Tle', 'L’adaptabilité de l’organisme face aux perturbations de l’environnement', 'Pendant la phase d’alarme, vers où le sang est-il redistribué ?', 'mcq', '["Vers la digestion et la peau","Vers les reins uniquement","Il n’est pas redistribué","Vers les muscles et le cerveau"]'::jsonb, 3, 'Le sang afflue vers les muscles et le cerveau, au détriment de la digestion et de la peau.', 3),
    ('3928f1ae-ac40-5229-84b2-5e1024ff166e'::uuid, 'svt', 'Tle', 'L’adaptabilité de l’organisme face aux perturbations de l’environnement', 'Dans le syndrome général d’adaptation, quelle phase n’est plus bénéfique ?', 'mcq', '["L’alarme","L’épuisement","La résistance","Aucune"]'::jsonb, 1, 'À l’épuisement, les capacités d’adaptation sont dépassées : la réponse devient délétère.', 4),
    ('933781ea-2a5f-5001-ab4b-7b5f8409cff3'::uuid, 'svt', 'Tle', 'L’organisme débordé dans ses capacités d’adaptation', 'Quelles sont les trois dimensions du burn-out ?', 'mcq', '["Fièvre, douleurs, toux","Épuisement, détachement vis-à-vis du travail, sentiment de perte d’efficacité","Colère, joie, tristesse","Insomnie, hypoglycémie, hypertension"]'::jsonb, 1, 'Le burn-out associe épuisement émotionnel et physique, détachement et sentiment de perte d’efficacité.', 1),
    ('f973fec2-3008-559f-8471-398ae3bfc7ef'::uuid, 'svt', 'Tle', 'L’organisme débordé dans ses capacités d’adaptation', 'Quelle conséquence cardiovasculaire le stress chronique favorise-t-il ?', 'mcq', '["Une hypotension permanente","Un ralentissement du cœur","Aucune","Une hypertension durable et de l’athérosclérose"]'::jsonb, 3, 'L’activation prolongée entretient l’hypertension et l’athérosclérose, qui augmentent le risque d’infarctus et d’AVC.', 2),
    ('8cba8089-7a6f-5a81-bc48-1aa22567cbb2'::uuid, 'svt', 'Tle', 'L’organisme débordé dans ses capacités d’adaptation', 'Qu’arrive-t-il aux récepteurs au cortisol de l’hypothalamus sous stress prolongé ?', 'mcq', '["Ils se désensibilisent","Ils se multiplient","Ils disparaissent du jour au lendemain","Ils deviennent des récepteurs à l’adrénaline"]'::jsonb, 0, 'Désensibilisés, ils freinent mal l’axe corticotrope : le cortisol reste élevé.', 3),
    ('caa0d88d-2850-5411-b4cd-4bccdc8b1cda'::uuid, 'svt', 'Tle', 'L’organisme débordé dans ses capacités d’adaptation', 'Parmi ces facteurs, lequel est l’un des facteurs protecteurs les mieux établis face au stress ?', 'mcq', '["L’isolement","La caféine","Le soutien social","La privation de sommeil"]'::jsonb, 2, 'Le soutien social fait partie des leviers de résilience les mieux documentés, avec l’activité physique et le sommeil.', 4),
    ('75a2a81a-eab8-5c0a-ba17-9ef024cd70f9'::uuid, 'nsi', 'Tle', 'Matériels, systèmes et logiciels', 'Que devient le contenu de la mémoire vive quand on éteint l’appareil ?', 'mcq', '["Il est recopié automatiquement sur le stockage","Il disparaît","Il est compressé","Il reste intact jusqu’au prochain démarrage"]'::jsonb, 1, 'La mémoire vive contient ce qui est en cours d’exécution et s’efface à l’extinction ; seul le stockage conserve les données de façon persistante.', 1),
    ('5c603231-94a4-54df-a1ee-c01ef420e1e9'::uuid, 'nsi', 'Tle', 'Matériels, systèmes et logiciels', 'Quelle fonction du système d’exploitation donne à chaque processus son tour de processeur ?', 'mcq', '["La gestion des fichiers","La gestion des droits","L’ordonnancement","La gestion de la mémoire"]'::jsonb, 2, 'L’ordonnanceur alterne très vite entre les processus : c’est ce qui donne l’illusion qu’ils s’exécutent en parallèle.', 2),
    ('6cdad90c-6a7f-5530-a19f-dc89440ca1a8'::uuid, 'nsi', 'Tle', 'Matériels, systèmes et logiciels', 'À quelle couche du modèle TCP/IP appartient le protocole IP ?', 'mcq', '["Application","Transport","Accès réseau","Internet"]'::jsonb, 3, 'La couche Internet s’occupe de l’adressage et du routage : c’est le rôle d’IP. TCP et UDP sont au-dessus, dans la couche Transport.', 3),
    ('6f765c12-746c-5ed7-aeba-a27cde5f7d3a'::uuid, 'nsi', 'Tle', 'Matériels, systèmes et logiciels', 'Sur un objet connecté, processeur, mémoire et périphériques tiennent souvent dans…', 'mcq', '["un système sur puce","un disque dur","un routeur","une carte réseau"]'::jsonb, 0, 'Un système sur puce réunit sur un seul circuit les éléments d’un ordinateur : c’est ce qui permet des objets connectés minuscules.', 4),
    ('1453b3c0-bec8-586b-888c-dbb3494fe4a7'::uuid, 'nsi', 'Tle', 'Sécurité des réseaux', 'Quelle garantie le hachage assure-t-il ?', 'mcq', '["La confidentialité","L’intégrité","L’authenticité","L’anonymat"]'::jsonb, 1, 'Comparer deux empreintes permet de vérifier que rien n’a été modifié : c’est l’intégrité. La confidentialité relève du chiffrement.', 1),
    ('ef785c15-f2d8-5a01-b7c4-3bf648a0eb2a'::uuid, 'nsi', 'Tle', 'Sécurité des réseaux', 'Quel est le problème du chiffrement symétrique utilisé seul ?', 'mcq', '["Il est trop lent pour de gros volumes","Il n’utilise aucune clé","Il faut transmettre la clé commune sans qu’elle soit interceptée","Il ne protège que les images"]'::jsonb, 2, 'Symétrique veut dire une seule clé partagée : tout le problème est de la faire parvenir à l’autre. L’asymétrique résout ce point.', 2),
    ('25a4b86d-70f4-57a9-90b5-a46a7b12a181'::uuid, 'nsi', 'Tle', 'Sécurité des réseaux', 'Qu’appelle-t-on l’effet d’avalanche d’une fonction de hachage ?', 'mcq', '["L’empreinte grandit avec la taille du message","Le calcul ralentit quand le message s’allonge","Deux messages différents ont toujours la même empreinte","La moindre modification du message change entièrement l’empreinte"]'::jsonb, 3, 'Changer une seule lettre produit une empreinte méconnaissable : on ne peut donc pas deviner le message en tâtonnant autour d’une empreinte.', 3),
    ('a43a9c5d-0548-5671-a224-de413ac6b918'::uuid, 'nsi', 'Tle', 'Sécurité des réseaux', 'Quelle protection crée un tunnel chiffré entre un appareil et un réseau ?', 'mcq', '["Le VPN","Le pare-feu","La segmentation du réseau","La mise à jour du système"]'::jsonb, 0, 'Le VPN chiffre tout ce qui circule dans son tunnel ; le pare-feu, lui, filtre les ports sans chiffrer.', 4),
    ('abc05f02-1308-5d2e-84d5-232c28f1765f'::uuid, 'nsi', 'Tle', 'Conteneurs de données', 'Que coûte l’insertion d’un élément en tête d’un tableau (une liste Python) ?', 'mcq', '["Un temps constant","Un temps proportionnel à sa taille, car il faut tout décaler","Un temps logarithmique","Rien, l’opération est impossible"]'::jsonb, 1, 'Chaque élément doit reculer d’une case : c’est là que la liste chaînée, qui insère en tête en temps constant, prend l’avantage.', 1),
    ('c2095f22-9c4f-5b12-89f3-e1ed712e627b'::uuid, 'nsi', 'Tle', 'Conteneurs de données', 'Quelle structure permet de vérifier qu’une expression est bien parenthésée ?', 'mcq', '["Une file","Un dictionnaire","Une pile","Un tableau trié"]'::jsonb, 2, 'On empile chaque parenthèse ouvrante et on dépile à chaque fermante : la dernière ouverte doit être la première fermée.', 2),
    ('5dae0e0f-620d-5358-912f-f33d873a6d20'::uuid, 'nsi', 'Tle', 'Conteneurs de données', 'Quelle structure choisir pour représenter une relation hiérarchique, comme des dossiers et sous-dossiers ?', 'mcq', '["Un dictionnaire","Une file","Une pile","Un arbre"]'::jsonb, 3, 'Une hiérarchie se représente par un arbre ; une relation quelconque, avec des cycles, demanderait un graphe.', 3),
    ('ab104900-904f-5f19-a721-9728b2a7dbfb'::uuid, 'nsi', 'Tle', 'Conteneurs de données', 'Que contient chaque maillon d’une liste chaînée ?', 'mcq', '["Une valeur et une référence vers le maillon suivant","Une valeur et son indice","Une clé et une valeur","Deux valeurs et leur somme"]'::jsonb, 0, 'C’est la référence vers le suivant qui relie les maillons : pour atteindre le i-ième, il faut donc suivre la chaîne depuis le début.', 4),
    ('d99e5935-0b40-5fd4-8b3f-249a286c3e2f'::uuid, 'nsi', 'Tle', 'Programmation orientée objet', 'Dans une méthode, on écrit `total = 0` au lieu de `self.total = 0`. Que se passe-t-il ?', 'mcq', '["L’attribut total de l’objet est mis à zéro","On crée une variable locale qui disparaît à la fin de la méthode","Python lève une erreur de syntaxe","On crée un attribut de classe"]'::jsonb, 1, 'Sans self, la variable n’est pas rattachée à l’objet : l’attribut reste inchangé. C’est l’erreur la plus fréquente du chapitre.', 1),
    ('3f2aa2d8-6568-51c9-a225-34008c8a5f92'::uuid, 'nsi', 'Tle', 'Programmation orientée objet', 'Une voiture a un moteur. Quel mécanisme traduit cette relation ?', 'mcq', '["L’héritage","Le polymorphisme","La composition","L’encapsulation"]'::jsonb, 2, 'Une relation « a un » se traduit par un attribut qui est lui-même un objet : c’est la composition. L’héritage traduit « est un ».', 2),
    ('941cc95e-1e4b-57fe-b205-8419855236ce'::uuid, 'nsi', 'Tle', 'Programmation orientée objet', 'Pourquoi modifier un attribut par une méthode plutôt que de l’écrire directement ?', 'mcq', '["C’est plus rapide à l’exécution","Python interdit l’accès direct aux attributs","Cela évite d’écrire un constructeur","La méthode peut vérifier la validité de la valeur écrite"]'::jsonb, 3, 'Une méthode de modification peut refuser un solde négatif ou une note de 25 : c’est l’un des intérêts de l’encapsulation.', 3),
    ('2522cae8-9c32-512f-b4e1-5b2999123c66'::uuid, 'nsi', 'Tle', 'Programmation orientée objet', 'Avec `class Epargne(Compte):`, que reçoit la classe Epargne ?', 'mcq', '["Les attributs et méthodes de Compte, qu’elle peut compléter ou redéfinir","Un attribut qui contient un objet Compte","Une copie figée de Compte qu’elle ne peut pas modifier","Rien, les parenthèses ne servent qu’à la documentation"]'::jsonb, 0, 'C’est l’héritage : Epargne reprend tout ce que sait faire Compte, en ajoute et peut redéfinir certaines méthodes.', 4),
    ('4bbc68e7-65cd-523a-8360-85dee4544866'::uuid, 'nsi', 'Tle', 'Arbres et structure de données', 'Quelle est la hauteur d’un arbre réduit à sa seule racine ?', 'mcq', '["−1","0","1","2"]'::jsonb, 1, 'La hauteur compte les arêtes du plus long chemin racine-feuille : aucune ici, donc 0. L’arbre vide, lui, a pour hauteur −1.', 1),
    ('7f6dca44-0433-505e-bfa6-6d89fdfc59c9'::uuid, 'nsi', 'Tle', 'Arbres et structure de données', 'Dans quel ordre le parcours préfixe visite-t-il un arbre binaire ?', 'mcq', '["Gauche, nœud, droite","Gauche, droite, nœud","Nœud, gauche, droite","Niveau par niveau"]'::jsonb, 2, 'Le préfixe traite le nœud avant ses sous-arbres : c’est l’ordre utile pour copier ou sérialiser un arbre.', 2),
    ('e82b1bcc-461a-5086-a50a-3d153563058f'::uuid, 'nsi', 'Tle', 'Arbres et structure de données', 'Que désigne la taille d’un arbre ?', 'mcq', '["Son nombre de feuilles","Sa hauteur","Le nombre d’enfants de la racine","Son nombre de nœuds"]'::jsonb, 3, 'Taille et hauteur sont deux mesures différentes : la taille compte les nœuds, la hauteur mesure le plus long chemin depuis la racine.', 3),
    ('777c8b1e-be63-557f-8e30-44726eff9e48'::uuid, 'nsi', 'Tle', 'Arbres et structure de données', 'Quelle est la hauteur minimale d’un arbre binaire de 1 000 nœuds ?', 'mcq', '["9","31","99","999"]'::jsonb, 0, 'Un arbre de hauteur 9 contient au plus 2^10 − 1 = 1 023 nœuds, assez pour 1 000 ; une hauteur de 8 n’en permet que 511. D’où la recherche en log₂(n).', 4),
    ('73f0e736-d5f6-5ada-ad7a-b25796cb8830'::uuid, 'nsi', 'Tle', 'Graphes abstraits', 'Quelle mémoire occupe la matrice d’adjacence d’un graphe à n sommets ?', 'mcq', '["Proportionnelle au nombre d’arêtes","De l’ordre de n²","De l’ordre de n","De l’ordre de log n"]'::jsonb, 1, 'Le tableau n × n réserve une case pour chaque couple de sommets, qu’il y ait une arête ou non : c’est un gâchis sur un grand graphe creux.', 1),
    ('e31bef34-e4a5-5ee0-96ff-6163d2d0adf7'::uuid, 'nsi', 'Tle', 'Graphes abstraits', 'Quel parcours utilise-t-on pour détecter des cycles ou établir un tri topologique ?', 'mcq', '["Le parcours en largeur","L’algorithme de Dijkstra","Le parcours en profondeur","Le parcours infixe"]'::jsonb, 2, 'Le parcours en profondeur s’enfonce le plus loin possible puis revient : c’est lui qui révèle les cycles et les composantes connexes.', 2),
    ('35b76684-0b18-5ebc-9d71-63a83d7659d2'::uuid, 'nsi', 'Tle', 'Graphes abstraits', 'Qu’est-ce qu’un graphe pondéré ?', 'mcq', '["Un graphe dont les arêtes ont un sens","Un graphe sans cycle","Un graphe où tout sommet est relié à tous les autres","Un graphe dont chaque arête porte une valeur"]'::jsonb, 3, 'Distance, coût ou débit : la valeur portée par l’arête. C’est dès qu’il y a des poids que le parcours en largeur ne suffit plus et que Dijkstra prend le relais.', 3),
    ('54228a03-1bfe-5b3d-a565-e715237b55f8'::uuid, 'nsi', 'Tle', 'Graphes abstraits', 'Contrairement à un arbre, un graphe peut contenir des cycles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le graphe n’impose aucune hiérarchie : un chemin peut revenir à son point de départ. C’est pour cela qu’il faut marquer les sommets visités.', 4),
    ('333922f4-b424-5d0f-ac9b-103b2fcabf7a'::uuid, 'nsi', 'Tle', 'Modélisation d’une base de données', 'Dans le schéma eleve(id, nom, prenom, date_naissance, #classe_id), que signale le dièse ?', 'mcq', '["Une clé primaire","Un attribut obligatoire","Une clé étrangère","Un attribut indexé"]'::jsonb, 2, 'Le dièse marque une clé étrangère : classe_id référence la clé primaire de la table classe. La clé primaire, elle, est notée en gras.', 1),
    ('01790bf9-0bc8-5dfd-8376-361b7988948b'::uuid, 'nsi', 'Tle', 'Modélisation d’une base de données', 'Laquelle de ces situations est une anomalie d’insertion ?', 'mcq', '["Corriger une adresse oblige à la corriger sur plusieurs lignes","On ne peut pas enregistrer un professeur qui n’a pas encore de classe","Effacer un élève efface aussi les informations de sa classe","Deux élèves portent le même nom"]'::jsonb, 1, 'L’anomalie d’insertion empêche d’enregistrer une information tant qu’une autre manque. La première est une anomalie de mise à jour, la troisième de suppression.', 2),
    ('e50d86a0-fc3f-591e-b229-2e957236730c'::uuid, 'nsi', 'Tle', 'Modélisation d’une base de données', 'Dans le modèle relationnel, qu’est-ce qu’un enregistrement ?', 'mcq', '["Une colonne de la table","La table elle-même","Le domaine d’un attribut","Une ligne de la table"]'::jsonb, 3, 'Une relation (table) est faite d’attributs, les colonnes, et d’enregistrements, les lignes.', 3),
    ('fe99c915-69d7-59e2-9648-4c1270554da1'::uuid, 'nsi', 'Tle', 'Modélisation d’une base de données', 'Que dire d’une relation « un à un » entre deux tables ?', 'mcq', '["Elle est rare et souvent réductible à une seule table","Elle exige une table de jonction","Elle impose une clé étrangère dans chacune des deux tables","Elle est impossible dans le modèle relationnel"]'::jsonb, 0, 'Si chaque ligne de l’une correspond à exactement une ligne de l’autre, les deux tables décrivent souvent la même entité : on peut les fusionner.', 4),
    ('21b7f32f-4ca7-5270-b5e4-282cf80f10b0'::uuid, 'nsi', 'Tle', 'Structure de base de données', 'Que renvoie la comparaison NULL = NULL en SQL ?', 'mcq', '["Vrai","Faux","Inconnu","Zéro"]'::jsonb, 2, 'Toute comparaison avec NULL renvoie « inconnu », même avec un autre NULL : c’est pourquoi on teste avec IS NULL.', 1),
    ('25448bf2-83fd-5b50-b148-ddd031a08dfb'::uuid, 'nsi', 'Tle', 'Structure de base de données', 'Quelle commande SQL retire un droit à un utilisateur ?', 'mcq', '["DROP","REVOKE","DELETE","DENY"]'::jsonb, 1, 'GRANT attribue un droit, REVOKE le retire. DROP supprime une table entière, DELETE des lignes.', 2),
    ('77754db9-94bc-5a80-ba4e-c3eab84eabca'::uuid, 'nsi', 'Tle', 'Structure de base de données', 'Quel mot-clé fournit une valeur quand l’insertion n’en donne aucune ?', 'mcq', '["CHECK","UNIQUE","NOT NULL","DEFAULT"]'::jsonb, 3, 'DEFAULT fixe une valeur par défaut ; NOT NULL, lui, rendrait la valeur obligatoire et refuserait l’insertion.', 3),
    ('f397a9a7-05fb-57c5-b2c7-c5706cfa74e7'::uuid, 'nsi', 'Tle', 'Structure de base de données', 'Une application ne fait que lire la base. Selon le principe de moindre privilège, quels droits lui donner ?', 'mcq', '["Seulement le droit de lecture (SELECT)","Tous les droits, par précaution","SELECT et DELETE","Aucun droit"]'::jsonb, 0, 'On ne donne que ce qui est nécessaire : si l’application est piratée, l’attaquant ne pourra ni modifier ni effacer les données.', 4),
    ('11c4e568-3971-51ac-9289-204da947cc68'::uuid, 'nsi', 'Tle', 'Système de gestion de bases de données (SGBD)', 'Un virement débite un compte, puis une panne survient avant le crédit. Quelle propriété impose d’annuler le débit ?', 'mcq', '["L’isolation","La durabilité","L’atomicité","La concurrence"]'::jsonb, 2, 'L’atomicité, c’est tout ou rien : les deux opérations réussissent ensemble ou aucune n’est gardée.', 1),
    ('e760465f-c2a8-5911-9ac8-4423350383e5'::uuid, 'nsi', 'Tle', 'Système de gestion de bases de données (SGBD)', 'Quels mécanismes le SGBD emploie-t-il pour gérer les accès concurrents ?', 'mcq', '["Le chiffrement et le hachage","Des verrous ou des versions","Des index et des vues","Le tri et la pagination"]'::jsonb, 1, 'Verrous ou versions empêchent deux clients qui modifient la même ligne d’écraser mutuellement leur travail.', 2),
    ('4d837995-4093-5e30-809d-9df0a8e449da'::uuid, 'nsi', 'Tle', 'Système de gestion de bases de données (SGBD)', 'Comment un SGBD sort-il d’un interblocage entre deux transactions ?', 'mcq', '["Il attend indéfiniment","Il redémarre le serveur","Il valide les deux transactions","Il détecte l’interblocage et annule l’une des deux transactions"]'::jsonb, 3, 'Chacune attend la ressource de l’autre : le SGBD tranche en annulant l’une, qui pourra être relancée.', 3),
    ('05f82342-4cde-5ee8-853d-5dd843c44aa7'::uuid, 'nsi', 'Tle', 'Système de gestion de bases de données (SGBD)', 'Que font les bases NoSQL par rapport aux bases relationnelles ?', 'mcq', '["Elles renoncent à une partie du modèle relationnel pour gagner en volume et en répartition","Elles n’enregistrent aucune donnée durablement","Elles interdisent les requêtes","Elles sont toujours embarquées, sans serveur"]'::jsonb, 0, 'Elles sacrifient certaines garanties du relationnel pour répartir d’énormes volumes sur de nombreuses machines.', 4),
    ('c68e75f7-724c-5f91-b267-18f486011ac5'::uuid, 'nsi', 'Tle', 'Le langage SQL', 'À quelle famille de commandes appartient ALTER TABLE ?', 'mcq', '["La manipulation des données","La définition des données","La gestion des droits","Le contrôle des transactions"]'::jsonb, 1, 'CREATE, ALTER et DROP TABLE définissent la structure ; SELECT, INSERT, UPDATE et DELETE manipulent le contenu.', 1),
    ('0086a656-31ca-57f5-8956-e0ee62d61b3c'::uuid, 'nsi', 'Tle', 'Le langage SQL', 'Quelle condition sélectionne les noms qui commencent par D ?', 'mcq', '["nom = ''D%''","nom IN (''D'')","nom LIKE ''D%''","nom IS ''D''"]'::jsonb, 2, 'LIKE compare à un motif où le pour-cent remplace n’importe quelle suite de caractères ; l’égalité, elle, chercherait littéralement « D% ».', 2),
    ('126e9a5c-1c8a-5cb6-95d6-fbc5dfb284e6'::uuid, 'nsi', 'Tle', 'Le langage SQL', 'Que renvoie `SELECT COUNT(*) FROM eleve` ?', 'mcq', '["La liste de tous les élèves","La somme des moyennes","Le premier élève de la table","Le nombre de lignes de la table eleve"]'::jsonb, 3, 'COUNT est un agrégat : il résume l’ensemble des lignes en une seule valeur, leur nombre.', 3),
    ('33db97ac-b84b-533e-bb11-08a3933748d8'::uuid, 'nsi', 'Tle', 'Le langage SQL', 'Quel mot-clé élimine les doublons d’un résultat ?', 'mcq', '["DISTINCT","UNIQUE","LIMIT","HAVING"]'::jsonb, 0, 'SELECT DISTINCT ne garde qu’un exemplaire de chaque ligne ; UNIQUE est une contrainte posée à la création de la table.', 4),
    ('a5421e97-16da-5c90-93bb-05bf277218b9'::uuid, 'nsi', 'Tle', 'Tri de données avec le langage SQL', 'Après un ORDER BY, quelles lignes renvoie `LIMIT 10 OFFSET 20` ?', 'mcq', '["Les lignes 1 à 10","Les lignes 21 à 30","Les lignes 20 à 30","Les lignes 10 à 20"]'::jsonb, 1, 'OFFSET saute les 20 premières lignes, puis LIMIT en garde 10 : c’est la troisième page d’un affichage par dix.', 1),
    ('3f9b10d9-36a8-5486-892d-7db7d900431e'::uuid, 'nsi', 'Tle', 'Tri de données avec le langage SQL', 'Qu’est-ce que la collation d’une base ?', 'mcq', '["L’ordre de stockage des lignes","La liste des index","Les règles de tri des chaînes, notamment pour les majuscules et les accents","La taille maximale d’une table"]'::jsonb, 2, 'Selon la collation, « Élise » et « elise » ne se classent pas au même endroit.', 2),
    ('095d73f0-922f-53a3-abc2-ee3509edf7bd'::uuid, 'nsi', 'Tle', 'Tri de données avec le langage SQL', 'Pourquoi un tri sur une colonne indexée est-il plus rapide ?', 'mcq', '["Parce que la table est rangée sur le disque dans cet ordre","Parce que le SGBD ignore alors les lignes","Parce que l’index supprime les doublons","Parce que l’index fournit déjà l’ordre"]'::jsonb, 3, 'L’index est une structure auxiliaire déjà ordonnée : le SGBD n’a plus qu’à la suivre, sans trier le résultat.', 3),
    ('ad607d1c-43e0-5fdc-9f8d-733f389b78a2'::uuid, 'nsi', 'Tle', 'Tri de données avec le langage SQL', 'Sur un gros volume, quelle bonne pratique réduit le coût d’un tri ?', 'mcq', '["Filtrer avant de trier","Trier toutes les colonnes","Trier deux fois pour vérifier","Supprimer le LIMIT"]'::jsonb, 0, 'Un tri coûte de l’ordre de n log n : réduire n par un WHERE d’abord rend le tri bien moins cher.', 4),
    ('44b6e43a-36e7-5778-995c-36a73b025118'::uuid, 'nsi', 'Tle', 'Programmes et données', 'Que se passe-t-il en Python quand on évalue `1 + "2"` ?', 'mcq', '["On obtient le nombre 3","Une erreur de type est levée","On obtient la chaîne « 12 »","On obtient le nombre 12"]'::jsonb, 1, 'Le typage fort de Python refuse d’additionner un entier et une chaîne, sans tenter de conversion implicite.', 1),
    ('7fdca68e-a232-57c6-bddf-aa0a94c94c53'::uuid, 'nsi', 'Tle', 'Programmes et données', 'Qui a montré que le problème de l’arrêt est indécidable ?', 'mcq', '["Von Neumann","Codd","Turing","Dijkstra"]'::jsonb, 2, 'Alan Turing l’a démontré : aucun algorithme ne peut décider, pour tout programme, s’il s’arrête sur une entrée donnée.', 2),
    ('e3564ac7-f6db-5c5e-9c45-9cc56713013f'::uuid, 'nsi', 'Tle', 'Programmes et données', 'Comment fonctionne Java, cité comme solution mixte ?', 'mcq', '["Il est interprété ligne à ligne comme Python","Il est compilé directement pour un seul processeur","Il ne peut pas être exécuté sans navigateur","Il est compilé vers un code intermédiaire exécuté par une machine virtuelle"]'::jsonb, 3, 'Le code intermédiaire est portable ; la machine virtuelle de chaque système se charge de l’exécuter.', 3),
    ('e71f341c-2c6d-50cc-9e1c-91dde207544e'::uuid, 'nsi', 'Tle', 'Programmes et données', 'Dans `sorted(mots, key=len)`, que montre l’argument key ?', 'mcq', '["Qu’une fonction peut être passée en argument comme une donnée","Que len est une variable globale","Que sorted est une méthode de liste","Que les mots sont triés par ordre alphabétique"]'::jsonb, 0, 'La fonction len est transmise à sorted, qui l’applique à chaque mot : c’est la fonction « donnée de première classe ».', 4),
    ('06f4398b-e5b9-533f-ba47-35aaaee2210e'::uuid, 'nsi', 'Tle', 'Paradigmes de programmation', 'Que signifie l’immutabilité en programmation fonctionnelle ?', 'mcq', '["Les fonctions ne peuvent pas être appelées deux fois","On crée une nouvelle valeur au lieu de modifier l’ancienne","Les variables sont toutes globales","Le programme ne peut plus être modifié"]'::jsonb, 1, 'Ne jamais modifier une valeur existante évite qu’une autre partie du programme voie ses données changer sans prévenir.', 1),
    ('a9300bae-24e5-5f28-baea-ee566561bb2e'::uuid, 'nsi', 'Tle', 'Paradigmes de programmation', 'Quel est le point faible du paradigme impératif quand le programme grandit ?', 'mcq', '["Il ne sait pas faire de boucles","Il est trop lent","L’état partagé rend le raisonnement difficile","Il interdit les fonctions"]'::jsonb, 2, 'Quand de nombreuses instructions modifient le même état, il faut tout lire pour savoir ce que vaut une variable à un instant donné.', 2),
    ('5cfc35f9-df88-526a-be5a-70e98100c45f'::uuid, 'nsi', 'Tle', 'Paradigmes de programmation', 'Dans un programme événementiel, qu’est-ce qui décide du flot d’exécution ?', 'mcq', '["L’ordre des lignes du fichier","Le compilateur","Le programmeur, à l’avance","Les événements qui arrivent : clic, message réseau, minuteur"]'::jsonb, 3, 'Le programme attend et réagit : ses gestionnaires sont appelés au gré de ce qui se produit.', 3),
    ('cc5a9513-823e-5593-ba64-47fe4fd05724'::uuid, 'nsi', 'Tle', 'Paradigmes de programmation', 'Quel paradigme est le plus proche de l’exécution réelle de la machine ?', 'mcq', '["L’impératif","Le fonctionnel","L’événementiel","L’objet"]'::jsonb, 0, 'Affectations, boucles et conditions correspondent directement à ce que fait le processeur : d’où son usage quand la performance est critique.', 4),
    ('0aefe203-7a5d-508a-9f77-27024e084a16'::uuid, 'nsi', 'Tle', 'Modularité des programmes', 'Que signifie qu’un module a une forte cohésion ?', 'mcq', '["Il dépend de nombreux autres modules","Il contient beaucoup de fonctions","Tout ce qu’il contient concerne le même sujet","Il est écrit par une seule personne"]'::jsonb, 2, 'Forte cohésion à l’intérieur, faible couplage entre modules : ce sont les deux critères d’un bon découpage.', 1),
    ('891cb408-896a-59ac-8357-e1e0fc612487'::uuid, 'nsi', 'Tle', 'Modularité des programmes', 'Qui doit garantir la postcondition d’une fonction ?', 'mcq', '["L’appelant","La fonction elle-même","L’interpréteur","L’utilisateur final"]'::jsonb, 1, 'La postcondition est ce que la fonction promet en retour ; la précondition, ce que l’appelant doit garantir avant l’appel.', 2),
    ('628adc06-5a0e-5ff7-bc5b-668dbcaa585a'::uuid, 'nsi', 'Tle', 'Modularité des programmes', 'Quel avantage a `import math` suivi de `math.sqrt(2)` sur `from math import sqrt` ?', 'mcq', '["On sait toujours de quel module vient chaque fonction","Le programme s’exécute deux fois plus vite","sqrt serait inaccessible autrement","Il n’y a plus besoin d’installer le module"]'::jsonb, 0, 'Le préfixe math. rend l’origine visible à chaque appel : c’est la forme la plus lisible.', 3),
    ('06335a1a-a4b2-52a2-8e97-84f71f3dfdaf'::uuid, 'nsi', 'Tle', 'Modularité des programmes', 'Quel test simple révèle qu’un module est mal découpé ?', 'mcq', '["Il dépasse cent lignes","Il contient une classe","Il n’a pas de docstring","On ne peut pas expliquer ce qu’il fait en une phrase sans employer « et »"]'::jsonb, 3, 'S’il faut un « et » pour le décrire, le module fait deux choses et gagnerait à être scindé.', 4),
    ('83ff5983-156a-5e25-b689-478bb6257293'::uuid, 'nsi', 'Tle', 'Bonnes pratiques logicielles', 'Quelle règle guide le choix de la longueur d’un nom de variable ?', 'mcq', '["Un nom ne dépasse jamais trois lettres","Plus la portée est large, plus le nom doit être explicite","Tous les noms doivent être en majuscules","Le nom doit indiquer la valeur actuelle"]'::jsonb, 1, 'Un compteur de boucle courte peut s’appeler i ; une variable utilisée dans tout le programme mérite un nom comme nb_eleves_inscrits.', 1),
    ('a3e9087c-fe27-5016-b53b-808edf19af52'::uuid, 'nsi', 'Tle', 'Bonnes pratiques logicielles', 'Parmi ces entrées, laquelle est un cas limite à tester ?', 'mcq', '["Une liste de dix nombres ordinaires","Une chaîne à la place d’un nombre","Une liste vide","Un fichier bien formé"]'::jsonb, 2, 'Liste vide, un seul élément, borne exacte : ce sont les cas limites. Une chaîne à la place d’un nombre est un cas d’erreur.', 2),
    ('8ee99663-7331-582b-b2a4-79d7d871250a'::uuid, 'nsi', 'Tle', 'Bonnes pratiques logicielles', 'Que vaut un commentaire faux ?', 'mcq', '["Autant qu’un commentaire juste","Il est sans effet","Il vaut mieux qu’aucun commentaire","Il est pire que pas de commentaire"]'::jsonb, 3, 'Il induit en erreur celui qui lui fait confiance : il faut mettre à jour les commentaires avec le code.', 3),
    ('bdd472a2-8d35-56a8-bf84-e86fdc40a5e3'::uuid, 'nsi', 'Tle', 'Bonnes pratiques logicielles', 'Qu’attend-on d’un bon enregistrement dans git ?', 'mcq', '["Qu’il soit petit et que son message explique l’intention","Qu’il regroupe une semaine de travail","Que son message liste chaque ligne modifiée","Qu’il soit fait une fois le projet terminé"]'::jsonb, 0, 'Un petit enregistrement bien décrit permet de retrouver quand et pourquoi une ligne a changé, et de revenir en arrière proprement.', 4),
    ('5c9bfd1c-5710-525f-b7ea-e9d0bf706528'::uuid, 'nsi', 'Tle', 'Mise au point logicielle', 'Quelle est la première étape pour corriger un bug ?', 'mcq', '["Modifier le code au hasard","Reproduire l’erreur de façon fiable, avec le plus petit cas possible","Réécrire la fonction entière","Ajouter des commentaires"]'::jsonb, 1, 'Sans reproduction fiable, impossible de savoir si une correction marche ; un petit cas d’entrée rend la localisation bien plus simple.', 1),
    ('a6f36d38-21d5-5da2-a18c-2daf946cfa1f'::uuid, 'nsi', 'Tle', 'Mise au point logicielle', 'Une division par zéro arrête le programme en route. À quelle famille appartient cette erreur ?', 'mcq', '["Erreur de syntaxe","Erreur de logique","Erreur d’exécution","Erreur de compilation"]'::jsonb, 2, 'Le code est lisible, mais l’exécution échoue sur une opération impossible : c’est une erreur d’exécution, bruyante donc repérable.', 2),
    ('29c47776-305b-508e-a19b-89997dd9f8a8'::uuid, 'nsi', 'Tle', 'Mise au point logicielle', 'À quel niveau faut-il traiter une exception ?', 'mcq', '["Toujours dans la fonction où elle se produit","Jamais : il faut laisser le programme s’arrêter","Tout en haut du programme, en attrapant tout","Au niveau où l’on sait quoi faire"]'::jsonb, 3, 'Par exemple, là où l’on peut avertir l’utilisateur qu’un fichier est absent et lui proposer un autre chemin.', 3),
    ('890d5f4b-0d9e-5f2c-a78b-c59fb1877308'::uuid, 'nsi', 'Tle', 'Mise au point logicielle', 'Pourquoi ce code est-il risqué : `for x in L: if x < 0: L.remove(x)` ?', 'mcq', '["Il modifie la liste pendant qu’il la parcourt et peut sauter des éléments","remove n’existe pas en Python","La condition x < 0 est toujours fausse","Il provoque une erreur de syntaxe"]'::jsonb, 0, 'Supprimer un élément décale les suivants : la boucle en saute un. Deux négatifs consécutifs, et le second reste dans la liste.', 4),
    ('ce346272-3814-5b56-8189-fcdee90d8da4'::uuid, 'nsi', 'Tle', 'Algorithme récursif', 'Que manque-t-il à `def f(n): return n * f(n - 1)` ?', 'mcq', '["Un paramètre supplémentaire","Un cas de base","Une boucle","Une variable globale"]'::jsonb, 1, 'Sans cas de base (par exemple renvoyer 1 quand n vaut 0), les appels ne s’arrêtent jamais et la pile déborde.', 1),
    ('6c4ef38b-d975-573e-aba1-ff4694396b70'::uuid, 'nsi', 'Tle', 'Algorithme récursif', 'Que conserve la pile d’appels pour chaque appel en cours ?', 'mcq', '["Le code source de la fonction","Le résultat final du programme","Ses paramètres et l’endroit où reprendre","La liste de toutes les variables globales"]'::jsonb, 2, 'Chaque appel occupe une place en mémoire : c’est pour cela que la profondeur de récursion est limitée.', 2),
    ('0eba34e8-5102-532d-b5a8-ba5b7cc86b67'::uuid, 'nsi', 'Tle', 'Algorithme récursif', 'Avec `def s(L): return 0 if L == [] else L[0] + s(L[1:])`, que vaut `s([4, 5, 6])` ?', 'mcq', '["4","6","0","15"]'::jsonb, 3, 's([4, 5, 6]) = 4 + s([5, 6]) = 4 + 5 + s([6]) = 4 + 5 + 6 + s([]) = 15.', 3),
    ('b339e6b9-5485-5bf4-a10c-900eb2fb5f44'::uuid, 'nsi', 'Tle', 'Algorithme récursif', 'Quand préférer une version itérative à une version récursive ?', 'mcq', '["Quand la profondeur serait très grande ou la performance critique","Quand on parcourt un arbre","Quand le code doit être le plus court possible","Jamais : la récursivité est toujours meilleure"]'::jsonb, 0, 'Les deux ont la même puissance, mais la pile d’appels est bornée : sur une grande profondeur, la boucle passe là où la récursion échoue.', 4),
    ('8d30972d-43ef-56b1-844a-637008a0e6a4'::uuid, 'nsi', 'Tle', 'Diviser pour régner', 'Combien de comparaisons faut-il environ pour une recherche dichotomique dans un million d’éléments ?', 'mcq', '["1 000","20","500 000","2"]'::jsonb, 1, 'Chaque comparaison divise par deux la zone de recherche : 2^20 dépasse le million, donc une vingtaine suffit.', 1),
    ('68977f5c-547b-55da-bc0d-e12650211a3b'::uuid, 'nsi', 'Tle', 'Diviser pour régner', 'Dans le tri fusion, quelle étape concentre le travail ?', 'mcq', '["Diviser","Régner","Combiner, c’est-à-dire fusionner les deux moitiés triées","Aucune, elles se valent"]'::jsonb, 2, 'Couper en deux ne coûte rien ; c’est la fusion, qui prend à chaque étape le plus petit élément disponible, qui fait le travail.', 2),
    ('c17be083-dd70-5246-957d-ca56fc86395a'::uuid, 'nsi', 'Tle', 'Diviser pour régner', 'Quel est le principe de l’exponentiation rapide ?', 'mcq', '["Multiplier n fois le nombre par lui-même","Trier les exposants","Calculer la puissance au hasard puis corriger","Élever au carré plutôt que multiplier n fois"]'::jsonb, 3, 'x^16 = (((x²)²)²)² : quatre élévations au carré au lieu de quinze multiplications.', 3),
    ('22fb4614-ed55-57e3-8db6-a93647336213'::uuid, 'nsi', 'Tle', 'Diviser pour régner', 'Que se passe-t-il si l’on applique la recherche dichotomique à un tableau non trié ?', 'mcq', '["Elle peut renvoyer un résultat faux sans rien signaler","Elle trie d’abord le tableau","Elle lève une erreur","Elle devient simplement plus lente"]'::jsonb, 0, 'Rien ne prévient : la moitié écartée peut justement contenir la valeur. Le tri préalable est une condition absolue.', 4),
    ('a78d1602-1ff3-5e50-bc54-9e00cd3c8b88'::uuid, 'nsi', 'Tle', 'Programmation dynamique', 'Avec des pièces de 1, 3 et 4, combien de pièces faut-il au minimum pour rendre 6 ?', 'mcq', '["3","2","1","4"]'::jsonb, 1, '3 + 3 suffit. Le glouton, qui prend d’abord la plus grosse pièce, donne 4 + 1 + 1, soit trois pièces.', 1),
    ('6c96eeec-8ebb-576d-a3e5-71a25072db8a'::uuid, 'nsi', 'Tle', 'Programmation dynamique', 'Quel avantage a l’approche ascendante (tabulation) sur la mémoïsation ?', 'mcq', '["Le code reste identique à la version récursive","Elle n’utilise aucune mémoire","Aucun risque de dépassement de la pile d’appels","Elle ne demande aucun ordre de calcul"]'::jsonb, 2, 'Remplir un tableau par une boucle n’empile aucun appel ; en contrepartie, il faut trouver soi-même le bon ordre de remplissage.', 2),
    ('b037d329-19d4-57d4-8528-e447a70f34a6'::uuid, 'nsi', 'Tle', 'Programmation dynamique', 'Quel tableau utilise-t-on pour résoudre le problème du sac à dos ?', 'mcq', '["Aucun tableau","Un tableau trié","Un dictionnaire de listes chaînées","Un tableau à deux dimensions"]'::jsonb, 3, 'Une dimension pour les objets considérés, une pour la capacité : chaque case réutilise les cases déjà remplies.', 3),
    ('7f2f403b-29fe-585a-86e4-9d5030eb0bb0'::uuid, 'nsi', 'Tle', 'Programmation dynamique', 'Si les sous-problèmes sont indépendants et ne se recouvrent pas, quelle méthode suffit ?', 'mcq', '["Diviser pour régner","La programmation dynamique","L’algorithme glouton","La recherche séquentielle"]'::jsonb, 0, 'Sans chevauchement, rien n’est recalculé : mémoriser serait inutile. C’est le recouvrement qui justifie la programmation dynamique.', 4),
    ('5b308713-d1b6-5329-9c14-6b0d3d0aa408'::uuid, 'nsi', 'Tle', 'Recherche de sous-chaîne', 'En cas d’échec, de combien l’algorithme naïf décale-t-il le motif ?', 'mcq', '["De la longueur du motif","De la moitié du motif","D’un seul cran","Jusqu’à la fin du texte"]'::jsonb, 2, 'Il repart ensuite du début du motif : il oublie tout ce que les comparaisons précédentes lui ont appris.', 1),
    ('84892ce8-e5f7-5bed-8a7f-7ac559419a6d'::uuid, 'nsi', 'Tle', 'Recherche de sous-chaîne', 'Quand Boyer-Moore-Horspool est-il particulièrement rapide ?', 'mcq', '["Quand le motif est très court","Quand le texte est trié","Quand le texte ne contient qu’une seule lettre répétée","Quand le motif est long, sur du texte naturel"]'::jsonb, 3, 'Plus le motif est long, plus les sauts permis par la table de décalage sont grands : des positions sont écartées sans être examinées.', 2),
    ('8d3743e7-9f78-5ffc-a399-9e5574d1e3e0'::uuid, 'nsi', 'Tle', 'Recherche de sous-chaîne', 'Que coûte le prétraitement du motif dans les algorithmes efficaces ?', 'mcq', '["De l’ordre de m opérations","De l’ordre de n opérations","De l’ordre de m × n opérations","Rien du tout"]'::jsonb, 0, 'On investit un calcul sur le motif de longueur m pour économiser ensuite sur le texte, bien plus long.', 3),
    ('dfdcfc5c-eaf7-58bd-a03b-44fbc417caa0'::uuid, 'nsi', 'Tle', 'Recherche de sous-chaîne', 'Motif très répétitif et besoin d’une performance garantie : quel algorithme choisir ?', 'mcq', '["L’algorithme naïf","Knuth-Morris-Pratt","Boyer-Moore-Horspool","La recherche dichotomique"]'::jsonb, 1, 'KMP ne recule jamais dans le texte et garantit un coût n + m, alors que Boyer-Moore peut tomber à m × n dans le pire cas.', 4),
    ('c06b875d-bdc1-584f-9bd0-69790f7aa84f'::uuid, 'enseignement-scientifique', 'Tle', 'L’atmosphère terrestre : son rôle dans l’apparition et dans le maintien de la vie', 'Avant de s’accumuler dans l’atmosphère, le dioxygène produit par les cyanobactéries a d’abord été consommé par…', 'mcq', '["la respiration des premiers animaux","la formation de la couche d’ozone","l’oxydation du fer dissous dans l’océan","la dissolution dans les roches carbonatées"]'::jsonb, 2, 'Le fer dissous s’est oxydé et a précipité en couches : les fers rubanés. L’O₂ ne s’accumule dans l’air qu’ensuite, vers −2,4 milliards d’années.', 1),
    ('3f69582a-b3fd-57c7-aa73-2eb41792124a'::uuid, 'enseignement-scientifique', 'Tle', 'L’atmosphère terrestre : son rôle dans l’apparition et dans le maintien de la vie', 'D’où provient l’atmosphère primitive de la Terre ?', 'mcq', '["Du dégazage volcanique","De la photosynthèse des cyanobactéries","De l’évaporation des premiers océans","Des vents solaires"]'::jsonb, 0, 'Il y a environ 4,5 milliards d’années, les volcans libèrent vapeur d’eau, CO₂ et diazote : aucune trace de dioxygène.', 2),
    ('5a06ec97-2cbb-5916-92d9-188e104a2ef8'::uuid, 'enseignement-scientifique', 'Tle', 'L’atmosphère terrestre : son rôle dans l’apparition et dans le maintien de la vie', 'Pourquoi la détection de dioxygène dans l’atmosphère d’une exoplanète intéresse-t-elle les astronomes ?', 'mcq', '["Parce qu’il prouve la présence d’océans","Parce que c’est un indice possible de vie","Parce qu’il indique une activité volcanique","Parce qu’il signale une planète gazeuse"]'::jsonb, 1, 'Sur Terre, un taux élevé de O₂ est une signature du vivant : aucune planète voisine n’en a autant.', 3),
    ('8ec3127c-2841-55c7-bc70-eee235a32049'::uuid, 'enseignement-scientifique', 'Tle', 'L’atmosphère terrestre : son rôle dans l’apparition et dans le maintien de la vie', 'Quel rôle actuel de l’atmosphère permet une température compatible avec l’eau liquide ?', 'mcq', '["La filtration des UV","La fourniture de dioxygène","La dissolution du CO₂","Le maintien de l’effet de serre"]'::jsonb, 3, 'L’effet de serre naturel garde la surface autour de +15 °C ; la couche d’ozone, elle, filtre les UV.', 4),
    ('dde840f8-a72c-5323-89d2-44f6c8cb6dc0'::uuid, 'enseignement-scientifique', 'Tle', 'Le climat : un système complexe', 'Quelle part du rayonnement solaire reçu est réfléchie vers l’espace ?', 'mcq', '["Environ 30 %","Environ 5 %","Environ 70 %","Environ 90 %"]'::jsonb, 0, 'C’est l’albédo moyen de la Terre : nuages, glaces et surfaces claires renvoient environ 30 % de l’énergie reçue.', 1),
    ('b99014b6-755d-5954-8cdc-9e70b4c32594'::uuid, 'enseignement-scientifique', 'Tle', 'Le climat : un système complexe', 'Sous quelle forme la Terre réémet-elle vers l’espace l’énergie qu’elle a absorbée ?', 'mcq', '["En ultraviolets","En lumière visible","En infrarouge","En rayons X"]'::jsonb, 2, 'Le sol et l’atmosphère, bien plus froids que le Soleil, rayonnent dans l’infrarouge — que les gaz à effet de serre absorbent en partie.', 2),
    ('804c1ff3-a61c-5de7-bdbe-feaa5325b2e5'::uuid, 'enseignement-scientifique', 'Tle', 'Le climat : un système complexe', 'Un sol plus chaud qui rayonne davantage d’infrarouge et évacue plus d’énergie est un exemple de…', 'mcq', '["rétroaction positive","rétroaction négative","forçage radiatif positif","couplage océan-atmosphère"]'::jsonb, 1, 'Une rétroaction négative freine la perturbation qui l’a déclenchée : plus il fait chaud, plus la Terre perd d’énergie.', 3),
    ('4c5811fe-78d3-5982-a7be-619d0af06698'::uuid, 'enseignement-scientifique', 'Tle', 'Le climat : un système complexe', 'Pourquoi dit-on que la réponse du climat n’est ni linéaire ni immédiate ?', 'mcq', '["Parce que les mesures sont imprécises","Parce que le Soleil varie sans cesse","Parce que le climat se définit sur 30 ans","Parce que l’océan profond réagit en siècles et que des rétroactions entrent en jeu"]'::jsonb, 3, 'Les réservoirs ont des échelles de temps très différentes (jours pour l’atmosphère, siècles pour l’océan profond) et les rétroactions amplifient ou freinent la réponse.', 4),
    ('e27d743e-725f-5f90-8f26-9dc2e91f09b5'::uuid, 'enseignement-scientifique', 'Tle', 'Variations passées, récentes et futures du climat', 'Quel paramètre orbital varie selon une période d’environ 41 000 ans ?', 'mcq', '["L’excentricité","L’obliquité","La précession","La distance Terre-Soleil moyenne"]'::jsonb, 1, 'L’obliquité, c’est l’inclinaison de l’axe de rotation ; l’excentricité suit environ 100 000 ans et la précession environ 21 000 ans.', 1),
    ('15128328-6fe0-5115-b594-c274dfab0914'::uuid, 'enseignement-scientifique', 'Tle', 'Variations passées, récentes et futures du climat', 'Qu’est-ce qui permet d’attribuer le CO₂ ajouté depuis 1850 aux combustibles fossiles ?', 'mcq', '["Sa signature isotopique","Sa couleur dans les bulles de glace","Sa concentration dans les pollens","Sa présence dans les cernes des arbres"]'::jsonb, 0, 'Le carbone fossile a une composition isotopique particulière, que l’on retrouve dans le CO₂ atmosphérique récent.', 2),
    ('4b1f1557-946d-52c0-ad60-9e9a2d8fcfa9'::uuid, 'enseignement-scientifique', 'Tle', 'Variations passées, récentes et futures du climat', 'Quelle archive naturelle renseigne le climat année par année sur quelques milliers d’années ?', 'mcq', '["Les carottes de glace","Les pollens","Les coquilles marines","Les cernes des arbres"]'::jsonb, 3, 'Chaque cerne correspond à une année de croissance ; sa largeur dépend des conditions climatiques de cette année-là.', 3),
    ('fbc4bdb2-ecda-57c5-a2b6-5510162bb05a'::uuid, 'enseignement-scientifique', 'Tle', 'Variations passées, récentes et futures du climat', 'Dans un scénario où les émissions se poursuivent, quel réchauffement est attendu à la fin du siècle ?', 'mcq', '["+0,5 °C","+1,1 °C","+4 °C et au-delà","Aucun, le climat se stabilise"]'::jsonb, 2, 'Si les émissions continuent, le réchauffement dépasserait +4 °C ; une chute rapide le limiterait à +1,5 à +2 °C.', 4),
    ('dcf8f74c-a299-5ca1-b6b9-59ffa339dc98'::uuid, 'enseignement-scientifique', 'Tle', 'Modèles prédictifs du climat du futur', 'Parmi ces équations, lesquelles un modèle climatique résout-il dans chaque maille ?', 'mcq', '["Celles de la croissance démographique","Celles de la mécanique des fluides, du transfert radiatif et de la thermodynamique","Celles de l’économie des énergies","Celles de la génétique des populations"]'::jsonb, 1, 'Un modèle, c’est de la physique résolue numériquement : mouvements d’air et d’eau, échanges de rayonnement, changements d’état.', 1),
    ('47427ce8-3bc6-59c5-a7c5-ceaac41b2135'::uuid, 'enseignement-scientifique', 'Tle', 'Modèles prédictifs du climat du futur', 'Quel test permet de vérifier qu’un modèle réagit correctement à une perturbation brève ?', 'mcq', '["Rejouer le refroidissement qui suit une grande éruption volcanique","Prévoir la météo de la semaine suivante","Comparer deux scénarios d’émissions","Réduire la taille des mailles"]'::jsonb, 0, 'Une grande éruption injecte des aérosols qui refroidissent la planète : un bon modèle doit reproduire ce refroidissement observé.', 2),
    ('b735a3c7-3afe-540b-8ed8-73d01f864601'::uuid, 'enseignement-scientifique', 'Tle', 'Modèles prédictifs du climat du futur', 'Qu’est-ce qu’une projection climatique fournit, contrairement à une prévision météo ?', 'mcq', '["Le temps d’un jour précis","Une date exacte de canicule","La trajectoire d’une tempête","Des statistiques : moyennes et extrêmes"]'::jsonb, 3, 'Le climat se décrit par des statistiques ; la météo, chaotique, n’est prévisible qu’une dizaine de jours.', 3),
    ('66da9315-11da-5719-8b69-89344d42b502'::uuid, 'enseignement-scientifique', 'Tle', 'Modèles prédictifs du climat du futur', 'Quelle est la taille typique d’une maille dans un modèle climatique ?', 'mcq', '["Quelques mètres","Quelques centaines de mètres","Quelques dizaines de kilomètres","Plusieurs milliers de kilomètres"]'::jsonb, 2, 'Des mailles de quelques dizaines de kilomètres : c’est pourquoi un nuage ou un orage, plus petits, doivent être paramétrés.', 4),
    ('d8dc8a07-6670-5b33-8cae-5031a5473a3a'::uuid, 'enseignement-scientifique', 'Tle', 'L’énergie électrique au cours des deux derniers siècles : le XIXe siècle', 'Qu’observe Œrsted en 1820 ?', 'mcq', '["Un courant électrique dévie une aiguille aimantée","Une pile produit un courant continu","Un aimant qui tourne crée un courant","Un fil parcouru par un courant chauffe"]'::jsonb, 0, 'Œrsted montre que l’électricité et le magnétisme sont liés, ouvrant la voie à l’induction de Faraday.', 1),
    ('5e6ef8d8-f71d-5649-bd09-37330cdab702'::uuid, 'enseignement-scientifique', 'Tle', 'L’énergie électrique au cours des deux derniers siècles : le XIXe siècle', 'Qui construit en 1869 la dynamo produisant du courant en quantité industrielle ?', 'mcq', '["Edison","Volta","Zénobe Gramme","Faraday"]'::jsonb, 2, 'La dynamo de Gramme fait passer l’électricité du laboratoire à l’industrie.', 2),
    ('e7aaf858-ecf4-51b2-9ecb-395bdb6bbc2b'::uuid, 'enseignement-scientifique', 'Tle', 'L’énergie électrique au cours des deux derniers siècles : le XIXe siècle', 'Une machine électrique qui convertit l’énergie électrique en énergie mécanique fonctionne en…', 'mcq', '["générateur","moteur","alternateur","transformateur"]'::jsonb, 1, 'Le même dispositif est réversible : générateur dans un sens, moteur dans l’autre.', 3),
    ('9186acd4-a6d9-51c1-8dbf-f91bd1339056'::uuid, 'enseignement-scientifique', 'Tle', 'L’énergie électrique au cours des deux derniers siècles : le XIXe siècle', 'Une lampe de 60 W fonctionne pendant 2 heures. Quelle énergie consomme-t-elle ?', 'mcq', '["30 Wh","62 Wh","1 200 Wh","120 Wh"]'::jsonb, 3, 'E = P × t = 60 W × 2 h = 120 Wh, soit 0,12 kWh.', 4),
    ('e6b07a42-d55b-55a8-8528-bdffc7cab7e4'::uuid, 'enseignement-scientifique', 'Tle', 'L’énergie électrique au cours des deux derniers siècles : le XXe siècle', 'Quel plan lance en 1974 la construction du parc nucléaire français ?', 'mcq', '["Le plan Marshall","Le plan Messmer","Le plan Freycinet","Le plan Monnet"]'::jsonb, 1, 'Lancé juste après le choc pétrolier de 1973, le plan Messmer donne un parc construit pour l’essentiel entre 1975 et 1990.', 1),
    ('1dbb9c54-f907-54e0-82a9-5d6a5e3239d1'::uuid, 'enseignement-scientifique', 'Tle', 'L’énergie électrique au cours des deux derniers siècles : le XXe siècle', 'Dans une centrale thermique ou nucléaire, qu’est-ce qui entraîne directement l’alternateur ?', 'mcq', '["La turbine","Le transformateur","Le réacteur","La ligne haute tension"]'::jsonb, 0, 'La source chauffe l’eau, la vapeur fait tourner la turbine, la turbine entraîne l’alternateur qui produit le courant.', 2),
    ('ca97468b-355c-57db-ae32-988e82414411'::uuid, 'enseignement-scientifique', 'Tle', 'L’énergie électrique au cours des deux derniers siècles : le XXe siècle', 'Quelle filière, parmi celles-ci, ne repose PAS sur une turbine entraînant un alternateur ?', 'mcq', '["L’hydraulique","Le nucléaire","Le thermique au gaz","Le photovoltaïque"]'::jsonb, 3, 'Le panneau photovoltaïque convertit directement la lumière en courant, sans pièce tournante.', 3),
    ('6ed1e7ab-4509-5dda-a0d4-3187c8ea1087'::uuid, 'enseignement-scientifique', 'Tle', 'L’énergie électrique au cours des deux derniers siècles : le XXe siècle', 'Qu’apporte la création d’EDF en 1946 ?', 'mcq', '["La privatisation des barrages","La sortie du charbon","L’unification de la production, du transport et de la distribution","L’invention du transistor"]'::jsonb, 2, 'EDF naît d’une nationalisation qui réunit toute la chaîne électrique dans une seule entreprise.', 4),
    ('31a71e22-613d-501d-9de3-3569453454f1'::uuid, 'enseignement-scientifique', 'Tle', 'Le transport de l’électricité', 'Si l’intensité dans une ligne double, les pertes par effet Joule sont…', 'mcq', '["doublées","multipliées par 4","inchangées","divisées par 2"]'::jsonb, 1, 'Les pertes valent R × I² : le carré de l’intensité fait qu’un doublement de I quadruple les pertes.', 1),
    ('f1d330e3-f399-58ce-a878-57d32ce4901d'::uuid, 'enseignement-scientifique', 'Tle', 'Le transport de l’électricité', 'Quelle est l’ordre de grandeur des pertes sur le réseau de transport français ?', 'mcq', '["2 à 3 %","15 à 20 %","Environ 50 %","Moins de 0,01 %"]'::jsonb, 0, 'Grâce à la très haute tension, les pertes restent de l’ordre de 2 à 3 % seulement.', 2),
    ('56d156e0-9146-5376-9b58-e519e91ef073'::uuid, 'enseignement-scientifique', 'Tle', 'Le transport de l’électricité', 'Quelle est la tension délivrée aux logements après le transformateur de quartier ?', 'mcq', '["20 kV","400 kV","230 V","12 V"]'::jsonb, 2, 'La chaîne descend de 400 kV (THT) à 20 kV (distribution), puis à 230 V chez l’usager.', 3),
    ('44ea84f6-4a10-5390-9fa6-3187fc7a7896'::uuid, 'enseignement-scientifique', 'Tle', 'Le transport de l’électricité', 'Qui s’opposait à Edison dans la « guerre des courants » en défendant l’alternatif ?', 'mcq', '["Faraday et Volta","Ampère et Œrsted","Gramme et Pascal","Tesla et Westinghouse"]'::jsonb, 3, 'L’alternatif l’a emporté parce que le transformateur permet de le transporter en haute tension.', 4),
    ('9af75078-91fe-5c7a-a344-966483b5982c'::uuid, 'enseignement-scientifique', 'Tle', 'Les atouts de l’électricité et ses enjeux dans le développement durable', 'Quel est l’ordre de grandeur de l’intensité carbone de l’électricité produite au gaz ?', 'mcq', '["Environ 10 g de CO₂ par kWh","Environ 490 g de CO₂ par kWh","Environ 820 g de CO₂ par kWh","Environ 2 000 g de CO₂ par kWh"]'::jsonb, 1, 'Le gaz émet environ 490 g/kWh, le charbon environ 820, l’éolien, l’hydraulique et le nucléaire 5 à 15.', 1),
    ('904bd5b9-0c53-5fca-b86b-6aeb0fe148db'::uuid, 'enseignement-scientifique', 'Tle', 'Les atouts de l’électricité et ses enjeux dans le développement durable', 'Parmi ces ressources, laquelle fait partie des ressources critiques de l’électrification ?', 'mcq', '["Le lithium","Le sable","Le calcaire","L’argile"]'::jsonb, 0, 'Cuivre, lithium et terres rares sont indispensables aux batteries, moteurs et réseaux : leur approvisionnement est un enjeu.', 2),
    ('fdb773a1-67da-5f67-92ca-fd57a43502aa'::uuid, 'enseignement-scientifique', 'Tle', 'Les atouts de l’électricité et ses enjeux dans le développement durable', 'Pourquoi un panneau solaire n’est-il pas sans impact, bien qu’il n’émette rien en fonctionnant ?', 'mcq', '["Parce qu’il consomme de l’électricité la nuit","Parce qu’il rejette du CO₂ quand il chauffe","Parce qu’il produit des déchets radioactifs","Parce que sa fabrication a un coût énergétique et matériel"]'::jsonb, 3, 'L’analyse du cycle de vie compte aussi l’extraction, la fabrication, le transport et la fin de vie.', 3),
    ('a2482af6-857b-55af-acd9-31b4fd9c5f6f'::uuid, 'enseignement-scientifique', 'Tle', 'Les atouts de l’électricité et ses enjeux dans le développement durable', 'Parmi ces moyens, lequel ne sert PAS à gérer l’intermittence des renouvelables ?', 'mcq', '["Le stockage","Les interconnexions entre pays","L’augmentation de la tension domestique","Le pilotage de la demande"]'::jsonb, 2, 'Stocker, échanger avec les voisins et déplacer la consommation compensent les variations du vent et du soleil ; la tension domestique n’y change rien.', 4),
    ('4567787b-6273-5033-b5e7-4e29da245cce'::uuid, 'enseignement-scientifique', 'Tle', 'La nécessité d’une transition énergétique pour agir sur le futur climatique', 'Quel levier consiste à consommer mieux à service rendu égal, par exemple en isolant un logement ?', 'mcq', '["La sobriété","L’efficacité","La décarbonation","Le puits de carbone"]'::jsonb, 1, 'L’efficacité améliore le rendement ; la sobriété, elle, réduit l’usage lui-même.', 1),
    ('4180a9ca-8b56-5da9-a54b-cf000af4c2cb'::uuid, 'enseignement-scientifique', 'Tle', 'La nécessité d’une transition énergétique pour agir sur le futur climatique', 'En quelle année l’Union européenne vise-t-elle la neutralité carbone ?', 'mcq', '["2030","2040","2100","2050"]'::jsonb, 3, 'L’objectif européen est la neutralité carbone en 2050, dans la ligne de l’Accord de Paris.', 2),
    ('2cb13423-43c0-53b1-b32a-f8a91d5e535b'::uuid, 'enseignement-scientifique', 'Tle', 'La nécessité d’une transition énergétique pour agir sur le futur climatique', 'Pourquoi le carbone d’un arbre brûlé ne pose-t-il pas le même problème, à long terme, que le carbone fossile ?', 'mcq', '["Parce qu’il revient d’où il vient dans le cycle actuel du carbone","Parce qu’il ne produit pas de CO₂ en brûlant","Parce qu’il est absorbé par l’ozone","Parce qu’il est plus lourd que l’air"]'::jsonb, 0, 'L’arbre a capté ce carbone récemment ; le fossile réinjecte un carbone stocké depuis des millions d’années.', 3),
    ('37da1372-a4d1-5b9c-a7f9-c8d15b3fac51'::uuid, 'enseignement-scientifique', 'Tle', 'La nécessité d’une transition énergétique pour agir sur le futur climatique', 'À quel ordre de grandeur correspond le budget carbone restant pour +1,5 °C au rythme actuel ?', 'mcq', '["Plusieurs siècles","Environ un siècle","Une poignée d’années","Il est déjà négatif depuis 1900"]'::jsonb, 2, 'Il reste quelques centaines de milliards de tonnes de CO₂, soit une poignée d’années d’émissions au rythme actuel.', 4),
    ('3b393c0b-1100-5813-8970-01590c6537e0'::uuid, 'enseignement-scientifique', 'Tle', 'Le choix énergétique : une décision stratégique à fort impact sur les sociétés', 'Pourquoi la Norvège produit-elle surtout de l’électricité hydraulique ?', 'mcq', '["Par un choix politique de sortie du nucléaire","Grâce à son relief et à ses précipitations","Parce qu’elle n’a pas de pétrole","Parce que l’hydraulique est intermittent"]'::jsonb, 1, 'Le mix d’un pays reflète aussi sa géographie : relief et pluies abondantes font de la Norvège un pays hydraulique.', 1),
    ('030ecbed-1628-5a5a-ab35-a706436fed95'::uuid, 'enseignement-scientifique', 'Tle', 'Le choix énergétique : une décision stratégique à fort impact sur les sociétés', 'À quel rythme environ le parc de logements se renouvelle-t-il ?', 'mcq', '["Environ 1 % par an","Environ 10 % par an","Environ 25 % par an","Entièrement tous les 10 ans"]'::jsonb, 0, 'Ce renouvellement lent montre l’inertie des choix énergétiques : les bâtiments d’aujourd’hui seront encore là dans des décennies.', 2),
    ('9a4faaf0-fdf2-5220-a04f-eb41c9ef61a0'::uuid, 'enseignement-scientifique', 'Tle', 'Le choix énergétique : une décision stratégique à fort impact sur les sociétés', 'Parmi ces énoncés, lequel est un jugement de valeur et non un fait mesuré ?', 'mcq', '["Le charbon émet environ 820 g de CO₂ par kWh","Une centrale fonctionne 40 à 60 ans","Le nucléaire fournit 65 à 70 % de l’électricité française","Le nucléaire est une mauvaise solution"]'::jsonb, 3, 'Au bac, on distingue un fait chiffré, vérifiable, d’une appréciation personnelle qui n’est pas une donnée.', 3),
    ('51bc16fb-4ffb-5302-8aa7-96fdc628c9e4'::uuid, 'enseignement-scientifique', 'Tle', 'Le choix énergétique : une décision stratégique à fort impact sur les sociétés', 'Qu’attend-on quand on te demande d’énoncer les limites d’une donnée ?', 'mcq', '["Son prix d’achat","L’opinion de l’auteur","Son périmètre, son année et sa source","Sa couleur sur le graphique"]'::jsonb, 2, 'Une donnée vaut pour un périmètre, une date et une source précis : les préciser, c’est raisonner honnêtement.', 4),
    ('0c77c0e7-2619-5847-bec7-5409657a2944'::uuid, 'enseignement-scientifique', 'Tle', 'Origine et évolution de la biodiversité', 'On marque 50 poissons, puis on en capture 40, dont 10 marqués. Quelle est l’estimation de l’effectif ?', 'mcq', '["100","80","200","500"]'::jsonb, 2, 'N = (n₁ × n₂) / m = (50 × 40) / 10 = 200 poissons.', 1),
    ('889f8994-15f3-567a-9634-1665e8fe7860'::uuid, 'enseignement-scientifique', 'Tle', 'Origine et évolution de la biodiversité', 'Combien d’espèces estime-t-on exister, hors micro-organismes ?', 'mcq', '["Environ 2 millions","Environ 8 à 10 millions","Environ 500 000","Plus d’un milliard"]'::jsonb, 1, 'Seules environ 2 millions sont décrites : une part majeure de la biodiversité n’a jamais été inventoriée.', 2),
    ('2c014af9-1400-5ff3-b23c-e0e8cc32be50'::uuid, 'enseignement-scientifique', 'Tle', 'Origine et évolution de la biodiversité', 'Pourquoi la diversité génétique au sein d’une espèce est-elle importante ?', 'mcq', '["Une espèce uniforme est fragile face à une maladie","Elle augmente le nombre d’espèces d’un milieu","Elle empêche toute mutation","Elle garantit l’absence de prédateurs"]'::jsonb, 0, 'Si tous les individus portent les mêmes allèles, une maladie qui touche l’un peut toucher tous les autres.', 3),
    ('4af3a90e-cbcf-5cc0-92cd-c60d4a9dad11'::uuid, 'enseignement-scientifique', 'Tle', 'Origine et évolution de la biodiversité', 'Quel groupe doit son essor à la crise Crétacé-Paléogène ?', 'mcq', '["Les trilobites","Les dinosaures non aviens","Les cyanobactéries","Les mammifères"]'::jsonb, 3, 'La disparition des dinosaures non aviens a libéré des niches que les mammifères ont occupées en se diversifiant.', 4),
    ('b534f3af-403a-5f29-942c-144a5cbdc8f6'::uuid, 'enseignement-scientifique', 'Tle', 'Modèles démographiques : comprendre l’évolution quantitative des populations', 'Une population augmente de 500 individus chaque année. Quel modèle la décrit ?', 'mcq', '["Le modèle logistique","Le modèle exponentiel","Le modèle linéaire","Le modèle en cloche"]'::jsonb, 2, 'Un nombre constant ajouté chaque année donne N(t) = N₀ + a × t : une droite.', 1),
    ('f3e467ff-fd99-5c8a-ac6c-09c0014ef06d'::uuid, 'enseignement-scientifique', 'Tle', 'Modèles démographiques : comprendre l’évolution quantitative des populations', 'D’après la règle des 70, en combien de temps double une population qui croît de 1 % par an ?', 'mcq', '["Environ 70 ans","Environ 35 ans","Environ 7 ans","Environ 700 ans"]'::jsonb, 0, 'Temps de doublement ≈ 70 / taux en % = 70 / 1 = 70 ans.', 2),
    ('4c77ac42-e969-5acd-a836-fd5097d82a9e'::uuid, 'enseignement-scientifique', 'Tle', 'Modèles démographiques : comprendre l’évolution quantitative des populations', 'Vers quelle valeur la population mondiale pourrait-elle plafonner au XXIe siècle selon les projections ?', 'mcq', '["Environ 8 milliards","Environ 20 milliards","Environ 50 milliards","Environ 10 milliards"]'::jsonb, 3, 'Le taux d’accroissement diminuant depuis les années 1970, les projections envisagent un plafond d’environ 10 milliards.', 3),
    ('c7928cf3-f013-5aa4-a28e-c355ebf0618c'::uuid, 'enseignement-scientifique', 'Tle', 'Modèles démographiques : comprendre l’évolution quantitative des populations', 'Qu’est-ce qui fait passer une population d’une croissance exponentielle à une croissance logistique ?', 'mcq', '["Une hausse du taux de natalité","Les ressources deviennent limitantes","L’arrivée de migrants","Un changement de calcul"]'::jsonb, 1, 'Nourriture, espace, prédation, maladies : quand le milieu limite, la croissance ralentit vers la capacité K.', 4),
    ('20fe4f92-5c33-5d77-b237-811994e0991b'::uuid, 'enseignement-scientifique', 'Tle', 'L’évolution comme grille de lecture du monde', 'Dans quel type de population la dérive génétique a-t-elle les effets les plus marqués ?', 'mcq', '["Une petite population","Une très grande population","Une population soumise à une forte sélection","Une population sans mutation"]'::jsonb, 0, 'Dans une petite population, le hasard de l’échantillonnage peut fixer ou éliminer un allèle en quelques générations.', 1),
    ('d6a49006-d658-5aaf-bd1e-dd0f7b1535d6'::uuid, 'enseignement-scientifique', 'Tle', 'L’évolution comme grille de lecture du monde', 'Que remplace l’humain lors d’une sélection artificielle ?', 'mcq', '["L’hérédité des caractères","La variation entre individus","Le milieu comme facteur de tri","Les mutations"]'::jsonb, 2, 'Le mécanisme est le même que la sélection naturelle ; seul le tri est fait par l’éleveur ou l’agriculteur.', 2),
    ('73c4efd9-1642-55d4-ad2d-61f6d65128ba'::uuid, 'enseignement-scientifique', 'Tle', 'L’évolution comme grille de lecture du monde', 'Pourquoi l’usage répété d’un insecticide finit-il par le rendre inefficace ?', 'mcq', '["Les insectes s’y habituent au cours de leur vie","L’insecticide perd sa toxicité avec le temps","L’insecticide provoque les mutations de résistance","Il sélectionne les insectes déjà résistants, qui se multiplient"]'::jsonb, 3, 'Même mécanisme que l’antibiorésistance : la mutation précède la pression, qui ne fait que trier.', 3),
    ('eb8d2e06-c1ff-587e-907b-c278ff5ba411'::uuid, 'enseignement-scientifique', 'Tle', 'L’évolution comme grille de lecture du monde', 'Que signifie dire que l’évolution « bricole » ?', 'mcq', '["Elle agit au hasard, sans sélection","Elle modifie l’existant sans repartir de zéro","Elle vise des formes parfaites","Elle ne concerne que les bactéries"]'::jsonb, 1, 'L’évolution n’a ni but ni plan : elle ajuste des structures héritées à un milieu qui change.', 4),
    ('776b436e-976b-51c7-878c-7555d3679b0c'::uuid, 'enseignement-scientifique', 'Tle', 'Histoire évolutive de la lignée humaine', 'Il y a combien de temps vivait le dernier ancêtre commun des humains et des chimpanzés ?', 'mcq', '["7 à 10 millions d’années","300 000 ans","3,2 millions d’années","65 millions d’années"]'::jsonb, 0, 'Depuis cet ancêtre commun, les deux lignées ont évolué autant l’une que l’autre.', 1),
    ('165a580b-7c66-5e37-bac9-dc6e1ab82690'::uuid, 'enseignement-scientifique', 'Tle', 'Histoire évolutive de la lignée humaine', 'Quelle espèce est considérée comme la première à sortir d’Afrique ?', 'mcq', '["Homo habilis","Homo sapiens","Homo erectus","Australopithecus afarensis"]'::jsonb, 2, 'Homo erectus, vers 1,9 million d’années, est le premier Homo connu hors d’Afrique.', 2),
    ('184ca6fe-1b65-5dcb-9dd9-c93d70c4a8bf'::uuid, 'enseignement-scientifique', 'Tle', 'Histoire évolutive de la lignée humaine', 'Quelle part d’ADN néandertalien porte-t-on chez les non-Africains actuels ?', 'mcq', '["0 %","Environ 1 à 3 %","Environ 25 %","Environ 50 %"]'::jsonb, 1, 'Cette part d’ADN prouve que Homo sapiens s’est croisé avec Néandertal après sa sortie d’Afrique.', 3),
    ('226bd6e2-499f-5409-a80f-99085bc43831'::uuid, 'enseignement-scientifique', 'Tle', 'Histoire évolutive de la lignée humaine', 'Pourquoi le langage ou l’usage du feu sont-ils difficiles à dater ?', 'mcq', '["Parce qu’ils sont apparus avec Homo sapiens seulement","Parce que les fossiles de crânes sont rares","Parce que l’ADN ancien ne se conserve pas","Parce que les fossiles n’en gardent que des traces indirectes"]'::jsonb, 3, 'Outils, foyers ou art sont des indices ; un os ne garde pas la preuve directe d’un comportement.', 4),
    ('cd87e9ad-baa8-51a4-b0ad-844a1aff8066'::uuid, 'enseignement-scientifique', 'Tle', 'Automatisation du traitement de l’information : une évolution des capacités humaines', 'Qui conçoit au XIXe siècle la machine analytique, programmable mais jamais achevée ?', 'mcq', '["Blaise Pascal","Alan Turing","Gordon Moore","Charles Babbage"]'::jsonb, 3, 'Ada Lovelace écrit pour cette machine de Babbage le premier algorithme destiné à une machine.', 1),
    ('77c291c8-b6df-5a16-a7b9-b5f690637ddb'::uuid, 'enseignement-scientifique', 'Tle', 'Automatisation du traitement de l’information : une évolution des capacités humaines', 'Sous quelle forme les données doivent-elles être codées pour être traitées par une machine ?', 'mcq', '["En binaire","En chiffres romains","En base dix uniquement","En texte manuscrit"]'::jsonb, 0, 'Le traitement automatisé suppose des données codées en binaire, d’autant mieux traitées qu’elles sont bien structurées.', 2),
    ('94f698d5-90d2-595f-bfd8-4e19c92d0904'::uuid, 'enseignement-scientifique', 'Tle', 'Automatisation du traitement de l’information : une évolution des capacités humaines', 'Pourquoi certaines limites de l’automatisation ne seront-elles jamais repoussées par le progrès matériel ?', 'mcq', '["Parce que la loi de Moore s’arrêtera","Parce que les transistors sont trop petits","Parce que certains problèmes ne sont pas calculables, par nature","Parce que les programmes sont écrits par des humains"]'::jsonb, 2, 'Turing a montré que des problèmes sont non calculables quelle que soit la puissance de la machine : c’est une limite théorique.', 3),
    ('3e260147-e495-51ec-9102-657d95911aa2'::uuid, 'enseignement-scientifique', 'Tle', 'Automatisation du traitement de l’information : une évolution des capacités humaines', 'Parmi ces capacités, laquelle est le plus souvent déléguée à la machine plutôt qu’augmentée ?', 'mcq', '["L’accès à l’information","L’orientation dans l’espace","La vitesse de calcul","La capacité de mémoire"]'::jsonb, 1, 'Avec le GPS, on délègue l’orientation : se pose alors la question de ce qu’on sait encore faire soi-même.', 4),
    ('b344c581-c296-5f82-b1c2-5fdcb942e022'::uuid, 'enseignement-scientifique', 'Tle', 'L’intelligence artificielle : enjeux et débats', 'En quelle année apparaît l’expression « intelligence artificielle » ?', 'mcq', '["1936","1947","1956","2012"]'::jsonb, 2, 'Le mot date de 1956 ; ce qui est récent, ce sont les techniques d’apprentissage qui la font fonctionner.', 1),
    ('b3a24be3-1df1-53ee-818a-a7ac863a3ec0'::uuid, 'enseignement-scientifique', 'Tle', 'L’intelligence artificielle : enjeux et débats', 'Quelle architecture domine aujourd’hui l’apprentissage automatique ?', 'mcq', '["Les réseaux de neurones artificiels","Les tables de règles écrites à la main","Les machines à roues dentées","Les bases de données relationnelles"]'::jsonb, 0, 'Vaguement inspirés des neurones biologiques, ils n’en sont pas un modèle fidèle.', 2),
    ('3919f559-4f2e-5bf5-b51d-0c99b5873b92'::uuid, 'enseignement-scientifique', 'Tle', 'L’intelligence artificielle : enjeux et débats', 'Sur quoi porte surtout le débat sur l’IA et l’emploi ?', 'mcq', '["Sur la disparition totale du travail humain","Sur l’interdiction des machines","Sur le salaire des programmeurs","Sur le rythme des changements et sur qui en paie le coût"]'::jsonb, 3, 'Des tâches disparaissent, d’autres apparaissent : la question est la vitesse de la transition et sa répartition.', 3),
    ('a433eb56-a5dd-550e-9603-ac824382530e'::uuid, 'enseignement-scientifique', 'Tle', 'L’intelligence artificielle : enjeux et débats', 'Décider d’autoriser ou non la reconnaissance faciale dans l’espace public relève…', 'mcq', '["d’un fait technique","d’un choix de société","d’un biais des données","d’un problème d’explicabilité"]'::jsonb, 1, 'Le fait technique dit ce que la machine peut faire ; ce qu’on autorise, et sous quel contrôle, est un choix de société.', 4),
    ('081c78c3-2dc8-58b3-9f85-7185a1ea8dfc'::uuid, 'si', 'Tle', 'Systèmes asservis', 'Lequel de ces exemples fonctionne en boucle fermée ?', 'mcq', '["Un four réglé sur une durée","Un four réglé sur une température","Un grille-pain à minuterie","Un arrosage programmé à heure fixe"]'::jsonb, 1, 'Le four réglé sur une température mesure la sortie par un capteur et corrige l’écart : c’est une boucle fermée.', 1),
    ('08913659-5da8-56a0-83ed-5ed4f9074929'::uuid, 'si', 'Tle', 'Systèmes asservis', 'Comment se calcule l’erreur au comparateur ?', 'mcq', '["Mesure − consigne","Consigne × mesure","Consigne − mesure","Consigne + perturbation"]'::jsonb, 2, 'Le comparateur soustrait la mesure à la consigne ; le correcteur agit ensuite sur cette erreur.', 2),
    ('2c970a68-67eb-5d89-9f89-ce885f13f1bf'::uuid, 'si', 'Tle', 'Systèmes asservis', 'Sur une réponse indicielle, on observe une erreur statique persistante. Quel correcteur est probablement en cause ?', 'mcq', '["Un correcteur purement proportionnel","Un correcteur à action intégrale trop marquée","Un correcteur dérivé seul","Aucun : c’est impossible en boucle fermée"]'::jsonb, 0, 'L’action proportionnelle laisse une erreur statique ; seule l’action intégrale peut l’annuler.', 3),
    ('4dbbad2e-56db-5a7d-a21f-cd7ef11a56f1'::uuid, 'si', 'Tle', 'Systèmes asservis', 'Que mesure-t-on avec le « temps de réponse à 5 % » ?', 'mcq', '["La stabilité","La précision","Le dépassement","La rapidité"]'::jsonb, 3, 'C’est le temps au bout duquel la sortie reste à moins de 5 % de sa valeur finale : il mesure la rapidité.', 4),
    ('9baa1887-fe19-52a1-9554-78affce45d14'::uuid, 'si', 'Tle', 'Modélisation et simulation', 'Quel diagramme SysML décrit de quoi le système est fait ?', 'mcq', '["Le diagramme des exigences","Le diagramme de définition de blocs","Le diagramme de séquence","Le diagramme d’états"]'::jsonb, 1, 'Le diagramme de définition de blocs décrit la composition du système ; celui de blocs internes, les échanges entre ses blocs.', 1),
    ('dd52286f-337a-5742-a2f0-b1bcfa8c5c64'::uuid, 'si', 'Tle', 'Modélisation et simulation', 'La réponse mesurée est plus lente que la simulation. Quelle hypothèse interroger d’abord ?', 'mcq', '["Le temps de réponse du capteur uniquement","Une erreur de l’appareil de mesure","Une inertie ou un jeu mécanique négligés","Des frottements surestimés"]'::jsonb, 2, 'Une réponse plus lente que prévu signale souvent une inertie ou un jeu que le modèle avait écartés.', 2),
    ('7ed4a094-1972-5ff0-bf82-9bfdb3067bdb'::uuid, 'si', 'Tle', 'Modélisation et simulation', 'Face à un modèle, quelle est la première question à poser selon le cours ?', 'mcq', '["Pour quelle question a-t-il été construit ?","Est-il parfaitement juste ?","Combien de temps dure le calcul ?","Quel logiciel l’a produit ?"]'::jsonb, 0, 'Un modèle n’est jamais « vrai » : il est valide dans un domaine, celui de la question à laquelle il répond.', 3),
    ('1b4cd743-e030-502c-bcdd-4cb015e0e5de'::uuid, 'si', 'Tle', 'Modélisation et simulation', 'Dans un moteur, quel couplage relie les domaines thermique et mécanique ?', 'mcq', '["Le correcteur compense la dérive","Le courant absorbé fixe la tension","Le capteur retarde la mesure","L’échauffement dégrade le couple"]'::jsonb, 3, 'C’est ce couplage entre domaines qui produit les surprises, d’où l’intérêt d’une simulation multiphysique.', 4),
    ('c0ab2f66-ff89-58ba-8465-9dd54c285749'::uuid, 'si', 'Tle', 'Projet et démarche d’ingénieur', 'Dans un tableau de choix de solutions, comment sont les critères ?', 'mcq', '["Tirés au sort","Pondérés","Tous de même poids obligatoirement","Choisis après le résultat"]'::jsonb, 1, 'Les critères pondérés reflètent l’importance relative des exigences du cahier des charges.', 1),
    ('884e1fed-528e-554b-88be-37894b850dee'::uuid, 'si', 'Tle', 'Projet et démarche d’ingénieur', 'Une mesure donnée sans incertitude est…', 'mcq', '["Un chiffre, pas un résultat exploitable","Toujours exacte","Suffisante si l’appareil est neuf","Plus précise qu’une série de mesures"]'::jsonb, 0, 'Le moyen de mesure porte sa propre incertitude : sans elle, on ne peut rien conclure.', 2),
    ('5dea6d85-92c4-588d-ada0-d5c7b41bffc1'::uuid, 'si', 'Tle', 'Projet et démarche d’ingénieur', 'Combien de phases couvre l’analyse du cycle de vie dans le cours ?', 'mcq', '["Deux","Trois","Quatre","Cinq"]'::jsonb, 3, 'Extraction, fabrication, transport, usage et fin de vie : l’ingénieur raisonne sur tout le cycle.', 3),
    ('f1f38364-9ed2-5e9f-adaf-79fd3eaaf92c'::uuid, 'si', 'Tle', 'Projet et démarche d’ingénieur', 'Que doit produire chaque étape d’un projet ?', 'mcq', '["Un prototype","Un score","Un livrable","Une mesure"]'::jsonb, 2, 'Chaque étape laisse une trace écrite, ce qui rend la démarche évaluable et traçable.', 4)
  ) AS v(id, slug, level, chapter, question, kind, options, correct_index, explanation, rang)
  JOIN public.subjects s ON s.slug = v.slug
  JOIN public.chapters c ON c.subject_id = s.id AND c.level = v.level AND c.title = v.chapter
  JOIN LATERAL (
    SELECT qz.id FROM public.lessons l
      JOIN public.quizzes qz ON qz.lesson_id = l.id
     WHERE l.chapter_id = c.id
     ORDER BY l.position, qz.id
     LIMIT 1
  ) qz ON true
ON CONFLICT (id) DO NOTHING;

